window.CRT_EVENTS = {"events":[{"id":"cs-1999-old-economy-rotation","date":"1999-01-04","end_date":"2002-10-09","sector":"consumer_staples","subindustries":[],"direction":"mixed","magnitude":"major","driver_type":"positioning","title":"Staples dumped for internet stocks in 1999, then rebought as the 'old economy' refuge","summary":"In 1999 investors sold slower-growing companies to buy internet names, so staples fell even as the Nasdaq rose 85.6%; the reversal began in March 2000, when the Nasdaq fell 2.6% in a month in which the S&P 500 rose 2.4% as money moved back into established businesses. Through the 2000-2002 bear market food, household and tobacco stocks were among the few groups that held value, cementing staples' role as the defensive leg of every rotation since.","evidence":"Nasdaq +85.6% in 1999 while 'old economy' stocks were sold; March 2000 Nasdaq -2.6% vs S&P 500 +2.4% as the rotation reversed","sources":[{"title":"Wikipedia: Dot-com bubble","url":"https://en.wikipedia.org/wiki/Dot-com_bubble"}]},{"id":"tech-1999-dotcom-meltup","date":"1999-01-04","end_date":"2000-03-10","sector":"technology","subindustries":["internet_platforms","hardware","telecom","semiconductors","application_software"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Dot-com melt-up: Nasdaq nearly doubles in 1999","summary":"Capital poured into internet, telecom-equipment and software names in the final leg of the dot-com bubble. The Nasdaq Composite rose 85.6% in 1999 against a 21.0% total return for the S&P 500, and the index peaked at a 5,048.62 close on 10 March 2000 (5,132.52 intraday). The Fed was tightening into the top, raising rates again on 21 March 2000.","evidence":"Nasdaq Composite 1999 calendar-year return +85.59%; record close 5,048.62 on 2000-03-10.","sources":[{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"Dot-com bubble (Wikipedia)","url":"https://en.wikipedia.org/wiki/Dot-com_bubble"},{"title":"S&P 500 annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/S%26P_500"}]},{"id":"en-2000-old-economy-rotation","date":"2000-03-10","end_date":"2000-12-29","sector":"energy","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Dot-com peak: capital rotates into 'old economy' energy","summary":"As the Nasdaq topped in March 2000, value investors rotated into energy, which had been shunned at a 6% S&P weight; crude recovered from the 1998-99 lows above $30 and the sector delivered its first big relative year in a decade. XLE returned 24.4% in 2000 while the S&P 500 lost 9.7%, then gave ground in the 2001-02 recession as oil fell back below $20.","evidence":"XLE +24.4% in 2000 vs SPY -9.7%; XLE -18.1% in 2001 and -14.7% in 2002","sources":[{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"},{"title":"ChartRow SPY calendar-year returns","url":"https://chartrow.com/quote/spy/returns"}]},{"id":"re-2000-tech-bust-rotation","date":"2000-03-10","end_date":"2002-12-31","sector":"real_estate","subindustries":[],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Dot-com bust: REITs become the anti-Nasdaq","summary":"Ignored during the tech bubble (REITs lost 17.5% in 1998 and 4.6% in 1999), listed real estate absorbed the rotation out of growth: the FTSE Nareit All Equity REITs index returned 26.4% in 2000, 13.9% in 2001 and 3.8% in 2002 while the S&P 500 fell 9.7%, 11.8% and 21.6%. Mortgage REITs returned 77% in 2001 as the Fed slashed rates and the curve steepened.","evidence":"All Equity REITs +26.4% (2000), +13.9% (2001), +3.8% (2002) vs SPY -9.7%, -11.8%, -21.6%; Mortgage REITs +77.3% in 2001","sources":[{"title":"Nareit annual index values and returns (AnnualReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"ChartRow SPY calendar-year returns","url":"https://chartrow.com/quote/spy/returns"}]},{"id":"cd-2000-dotcom-bust","date":"2000-03-10","end_date":"2002-10-09","sector":"consumer_discretionary","subindustries":[],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Dot-com bust guts internet retail; capital rotates to 'old economy' consumer names","summary":"The Nasdaq Composite peaked at 5,048.62 on March 10 2000 and fell 78% to its October 2002 low, taking internet retailers (Amazon, eBay, Priceline, Webvan, Pets.com) down with it; in March 2000 alone the Nasdaq fell 2.6% while the S&P 500 rose 2.4% as money moved into established companies that had been dumped in 1999. For consumer discretionary this meant two and a half years in which homebuilders, auto parts and brick-and-mortar retailers outperformed online retail by a wide margin.","evidence":"Nasdaq Composite peak 5,048.62 on 2000-03-10, -78% to October 2002","sources":[{"title":"Wikipedia: Dot-com bubble","url":"https://en.wikipedia.org/wiki/Dot-com_bubble"}]},{"id":"tech-2000-dotcom-bust","date":"2000-03-10","end_date":"2002-10-09","sector":"technology","subindustries":["internet_platforms","hardware","telecom","semiconductors","application_software","it_services"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"Dot-com bust: tech falls 82% peak-to-trough","summary":"The Nasdaq fell roughly 78% from its March 2000 peak to October 2002, with the S&P 500 technology sector down 82.4% and telecom down 74.1% between 24 March 2000 and 9 October 2002 versus 49.2% for the S&P 500. Cisco, briefly the world's most valuable company at over $500 billion in late March 2000, lost about 80% of its value. The Fed began an emergency easing cycle with a 50 bp cut to 6% on 3 January 2001, but capital kept leaving tech for staples (+24% over the bear) and value.","evidence":"S&P 500 Information Technology sector -82.37% from 2000-03-24 to 2002-10-09 vs S&P 500 -49.15%.","sources":[{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"Cisco (Wikipedia)","url":"https://en.wikipedia.org/wiki/Cisco"},{"title":"FOMC statement, 3 January 2001","url":"https://www.federalreserve.gov/boarddocs/press/general/2001/20010103/default.htm"},{"title":"Dot-com bubble (Wikipedia)","url":"https://en.wikipedia.org/wiki/Dot-com_bubble"}]},{"id":"hc-2000-genome-bubble","date":"2000-03-14","end_date":null,"sector":"healthcare","subindustries":[],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Clinton-Blair genome statement pops the genomics bubble","summary":"The Nasdaq Biotech Index fell about 12.5% and the Amex Biotech Index 13.2% in a single day after a Clinton-Blair statement calling for open access to raw genome data was read as undermining gene patents. The sell-off came on top of a bubble that had already begun deflating in early March 2000; Celera fell from $276 at the start of March to $122.50 right after the announcement. Biotech then traded as a high-beta appendage of the Nasdaq through the 2000-2002 bear market.","evidence":"Nasdaq Biotech Index -12.5% on 2000-03-14; Celera from $276 (early March) to $122.50 after the statement","sources":[{"title":"BioCentury: $10.4B knocked off genomics stocks","url":"https://www.biocentury.com/article/57468/10-4b-knocked-off-genomics-stocks"},{"title":"CNN Money, March 14 2000: biotech sell-off","url":"https://money.cnn.com/2000/03/14/companies/biotech/"}]},{"id":"ind-2000-dotcom-bust","date":"2000-03-24","end_date":"2002-10-09","sector":"industrials","subindustries":[],"direction":"out","magnitude":"major","driver_type":"macro","title":"Dot-com bust drags industrials into a three-year bear market","summary":"The tech bust of 2000-2002 spilled into capital-goods and transport names as business investment collapsed after the telecom/IT overbuild. XLI lost 10.2% in 2001 and 24.6% in 2002, roughly matching the S&P 500, with airlines and conglomerates (GE, Tyco) the worst performers; the sector did not regain leadership until the 2003 China-driven capex cycle.","evidence":"XLI total return: +6.7% in 2000, -10.2% in 2001, -24.6% in 2002 (SPY -9.7%, -11.8%, -21.6%)","sources":[{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"},{"title":"ChartRow SPY calendar-year returns","url":"https://chartrow.com/quote/spy/returns"}]},{"id":"cs-2000-engle-verdict","date":"2000-07-14","end_date":"2000-07-14","sector":"consumer_staples","subindustries":[],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Engle jury awards $145 billion against tobacco","summary":"A Florida jury awarded roughly $145 billion in punitive damages to a class of up to 700,000 smokers, about $74 billion of it attributed to Philip Morris USA, the largest verdict in US history. Tobacco stocks had already been de-rated to all-time lows by the 1998 Master Settlement and litigation fears; the verdict kept the group a deep-value, high-yield outcast until the award was overturned on appeal, after which Altria became one of the best performers of the 2000s.","evidence":"Punitive award of ~$145B on 2000-07-14, $74B attributed to Philip Morris USA (Altria SEC filings)","sources":[{"title":"Wikipedia: Howard Engle","url":"https://en.wikipedia.org/wiki/Howard_Engle"},{"title":"Mother Jones: Big tobacco's big loss","url":"https://fullsite.motherjones.com/politics/2000/07/big-tobaccos-big-loss"},{"title":"Altria 10-K exhibit referencing Engle","url":"https://www.sec.gov/Archives/edgar/data/764180/000076418019000023/R109.htm"}]},{"id":"cd-2001-sept11","date":"2001-09-11","end_date":"2001-12-31","sector":"consumer_discretionary","subindustries":[],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"September 11 attacks shut markets and crush travel, hotels and leisure","summary":"US exchanges stayed closed until September 17 2001, and when they reopened travel and entertainment stocks fell hardest; Midway Airlines stopped flying immediately, Swissair was grounded on October 2, tens of thousands of airline workers were laid off within a week, New York hotel occupancy fell below 40% and Congress passed $15 billion of airline aid and guarantees. Online travel agencies were hit especially hard. Cruise lines, hotels and theme parks took several quarters to recover demand.","evidence":"NYC hotel occupancy below 40% in the week after the attacks; $10B loan guarantees plus $5B short-term airline assistance","sources":[{"title":"Wikipedia: Economic effects of the September 11 attacks","url":"https://en.wikipedia.org/wiki/Economic_effects_of_the_September_11_attacks"}]},{"id":"ind-2001-911-airlines","date":"2001-09-17","end_date":"2002-08-11","sector":"industrials","subindustries":[],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"9/11 shuts US airspace; airline equities collapse and bankruptcies follow","summary":"When markets reopened on September 17, 2001 UAL fell 42% and US Airways 52% in a single session, and the AMEX airline index dropped 40% in a week. The industry lost $13bn in 2001 and $11.3bn in 2002; US Airways filed Chapter 11 in August 2002 and United in December 2002, starting a wave of legacy-carrier restructurings that ran to 2005.","evidence":"AMEX Airline Index -40% in the week after 9/11 and -60% YTD by late Oct 2001 vs Dow -13%","sources":[{"title":"CS Monitor: Analysts suggest airline stocks have hit bottom (Oct 2001)","url":"https://www.csmonitor.com/layout/set/amphtml/2001/1029/p15s1-wmpi.html"},{"title":"NZ Herald: US airline industry in tailspin","url":"https://nzherald.co.nz/business/us-airline-industry-in-tailspin/DDBR3WFD2NWORLLBEAYIJUWRFM"}]},{"id":"tech-2003-recovery","date":"2003-01-02","end_date":"2003-12-31","sector":"technology","subindustries":["semiconductors","internet_platforms","application_software","hardware"],"direction":"in","magnitude":"major","driver_type":"rates","title":"2003 reflation: Nasdaq +50% on 1% Fed funds","summary":"With the fed funds rate at a four-decade low of 1% (the Fed only began raising it, to 1.25%, on 30 June 2004), beaten-down tech led the recovery. The Nasdaq Composite gained 50.0% in 2003 versus 28.7% for the S&P 500, the first year of a new cycle after three consecutive losing years (-39.3%, -21.1%, -31.5%).","evidence":"Nasdaq Composite 2003 return +50.01% vs S&P 500 total return +28.68%.","sources":[{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"FOMC statement, 30 June 2004","url":"https://www.federalreserve.gov/boarddocs/press/monetary/2004/20040630/default.htm"},{"title":"S&P 500 annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/S%26P_500"}]},{"id":"ind-2003-china-supercycle","date":"2003-03-12","end_date":"2007-12-31","sector":"industrials","subindustries":[],"direction":"in","magnitude":"major","driver_type":"commodity","title":"China commodity supercycle lifts machinery and capital goods","summary":"Chinese infrastructure and mining demand, plus a global capex rebound, made heavy machinery the leadership group of the 2003-2007 bull market. Caterpillar returned 86% in 2003 and Deere 99% in 2007, and XLI gained 31.9% in 2003 versus 28.2% for the S&P 500; mining-equipment and ag names rode commodity prices until the 2008 crash.","evidence":"CAT total return +86.1% in 2003 and DE +98.7% in 2007; XLI +31.9% in 2003 vs SPY +28.2%","sources":[{"title":"ChartRow CAT calendar-year returns","url":"https://chartrow.com/quote/cat/returns"},{"title":"ChartRow DE calendar-year returns","url":"https://chartrow.com/quote/de/returns"},{"title":"Cambridge: Twenty-first century supercycle","url":"https://www.cambridge.org/core/books/commodity-markets-and-the-global-economy/twentyfirstcentury-supercycle-longterm-trends-in-metal-and-energy-prices/6E93073217153ADEDA8E0629C3A32421"}]},{"id":"en-2003-commodity-supercycle","date":"2003-03-12","end_date":"2008-07-11","sector":"energy","subindustries":[],"direction":"in","magnitude":"major","driver_type":"commodity","title":"China supercycle: energy rises ~300% from the 2003 low to the 2008 peak","summary":"Chinese demand, OPEC discipline and under-investment took WTI from the $20s to $147, and energy became the market's leadership sector for five years. XLE returned 25.8%, 33.9%, 40.2%, 18.1% and 36.9% in 2003-2007, beating the S&P 500 every year, and the sector's S&P weight rose from about 6% to roughly 16% by mid-2008.","evidence":"XLE +40.2% in 2005 and +36.9% in 2007 vs SPY +4.8% and +5.1%; energy sector ~+300% from 2003 bottom to 2008 peak","sources":[{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"},{"title":"Investing Daily: The new super-cycle","url":"https://investingdaily.com/articles/2300/the-new-super-cycle"}]},{"id":"re-2003-reit-bull-market","date":"2003-03-12","end_date":"2007-02-07","sector":"real_estate","subindustries":[],"direction":"in","magnitude":"major","driver_type":"macro","title":"2003-2006 REIT bull market: seven straight years of beating every benchmark","summary":"Cheap debt, CMBS growth and private-equity takeovers (culminating in Blackstone's $39bn Equity Office buyout in February 2007) compressed cap rates and pushed REIT prices up 99% from Q4 2003 to Q4 2006. All Equity REITs returned 37.1% in 2003, 31.6% in 2004, 12.2% in 2005 and 35.1% in 2006, with office (+45.2%), health care (+44.6%), self storage (+40.9%) and apartments (+40.0%) leading 2006; Nareit noted REITs beat all major equity benchmarks for the seventh straight year.","evidence":"All Equity REITs +35.1% in 2006 vs S&P 500 +15.8%; office +45.2% and apartments +40.0% in 2006","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"Facilities Net: REIT 2006 returns (NAREIT)","url":"https://facilitiesnet.com/facilitiesmanagement/article.aspx?id=6024"}]},{"id":"hc-2003-mma-part-d","date":"2003-12-08","end_date":"2005-12-31","sector":"healthcare","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"Medicare Modernization Act creates Part D and Medicare Advantage","summary":"The MMA, signed December 8 2003, created the Part D drug benefit and the modern Medicare Advantage program, handing private insurers a large new government-funded market. Managed care stocks re-rated through 2004-2005: by February 2005 Humana's shares had rallied so far that analysts no longer saw a valuation case, and UnitedHealth and Humana took the largest Part D shares at the January 2006 launch. Exact index moves were not retrievable; the direction is well documented.","evidence":"UnitedHealth held 27% and Humana 18% of Part D enrollment at the 2006 launch (CMS count via FierceHealthcare); Motley Fool noted Humana's 'strong rally' following the MMA (Feb 2005)","sources":[{"title":"Motley Fool: Humana offers some reassurance (Feb 2005)","url":"https://www.fool.com/investing/high-growth/2005/02/07/humana-offers-some-reassurance.aspx"},{"title":"FierceHealthcare: UnitedHealth leads in Part D race","url":"https://www.fiercehealthcare.com/healthcare/unitedhealth-leads-part-d-race"}]},{"id":"en-2005-refining-golden-age","date":"2004-01-02","end_date":"2007-07-31","sector":"energy","subindustries":[],"direction":"in","magnitude":"major","driver_type":"commodity","title":"Refining's first golden age: tight capacity and Katrina","summary":"No new US refinery had been built since 1976, demand was growing and hurricanes Katrina and Rita (Aug-Sep 2005) knocked out Gulf Coast capacity, sending crack spreads to records. Valero returned 98% in 2004 and 128% in 2005, the best large-cap performance in the S&P 500, before margins normalized in 2006-07 and collapsed in 2008.","evidence":"VLO +97.6% in 2004 and +128.5% in 2005 vs SPY +10.7% and +4.8%","sources":[{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"}]},{"id":"tech-2004-2006-midcycle-lag","date":"2004-06-30","end_date":"2006-06-29","sector":"technology","subindustries":["semiconductors","hardware","application_software"],"direction":"out","magnitude":"moderate","driver_type":"rates","title":"Measured-pace hiking cycle: tech lags energy and value","summary":"The Fed raised rates 17 times from 1% to 5.25% between June 2004 and June 2006, and leadership passed to energy, materials, homebuilders and financials. The Nasdaq returned 8.6% in 2004, 1.4% in 2005 and 9.5% in 2006 against S&P 500 total returns of 10.9%, 4.9% and 15.8%, a persistent relative drag for growth-heavy tech during the commodity and credit boom.","evidence":"Fed funds target raised to 1.25% on 2004-06-30 and to 5.25% on 2006-06-29; Nasdaq 2005 return +1.37% vs S&P 500 +4.91%.","sources":[{"title":"FOMC statement, 30 June 2004","url":"https://www.federalreserve.gov/boarddocs/press/monetary/2004/20040630/default.htm"},{"title":"FOMC statement, 29 June 2006","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20060629a.htm"},{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"}]},{"id":"hc-2004-vioxx","date":"2004-09-30","end_date":null,"sector":"healthcare","subindustries":[],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Merck withdraws Vioxx; big pharma's safety discount deepens","summary":"Merck pulled its $2.5 billion-a-year painkiller Vioxx on cardiovascular safety data and the stock fell roughly 27% in one day, erasing about $25 billion of market value, with a further ~10% drop a month later on reports of what Merck knew. The episode extended a multi-year de-rating of large-cap pharma that began with the late-1990s patent-cliff worries and turned the group into a value/defensive trade for the rest of the decade.","evidence":"MRK fell $12.07 (-27%) to $33.00 on 2004-09-30, about $25B of market value","sources":[{"title":"CNN Money: Merck pulls Vioxx (Sept 30 2004)","url":"https://money.cnn.com/2004/09/30/news/fortune500/merck/"},{"title":"NPR: Merck stock dives on Vioxx news","url":"https://www.npr.org/2004/09/30/4055360/merck-stock-dives-on-vioxx-news"}]},{"id":"re-2005-mortgage-reit-flat-curve","date":"2005-01-03","end_date":"2005-12-30","sector":"real_estate","subindustries":[],"direction":"out","magnitude":"moderate","driver_type":"rates","title":"Fed hikes flatten the curve; mortgage REITs lose a quarter of their value","summary":"Seventeen consecutive Fed hikes from mid-2004 squeezed the repo-funded spread between short rates and MBS yields; the Nareit Mortgage REITs index lost 23.2% in 2005 (home financing -26%) and Annaly 41%, while equity REITs still gained 12%. The episode is the template for every later mortgage-REIT drawdown: the sub-sector trades on the yield curve, not on property.","evidence":"Nareit Mortgage REITs -23.2% and Home Financing -25.95% in 2005; NLY -40.6% in 2005","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"ChartRow NLY calendar-year returns","url":"https://chartrow.com/quote/nly/returns"}]},{"id":"cs-2005-pg-gillette","date":"2005-01-28","end_date":"2005-10-01","sector":"consumer_staples","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Procter & Gamble buys Gillette","summary":"P&G announced a stock deal for Gillette in late January 2005 worth more than $50 billion (reported at about $54-57 billion), the largest consumer-products merger to date, with FTC clearance on September 30 2005 and Berkshire Hathaway as the key endorsing shareholder. The deal set the template for scale-driven consolidation in household products and marked the peak of confidence in branded-goods pricing power before the private-label and retailer-consolidation pressures of the following decade.","evidence":"P&G-Gillette stock deal announced January 2005 (WSJ: $54B), FTC approval 2005-09-30","sources":[{"title":"Wikipedia: Gillette","url":"https://en.wikipedia.org/wiki/Gillette"}]},{"id":"cd-2005-gm-ford-junk","date":"2005-05-05","end_date":null,"sector":"consumer_discretionary","subindustries":[],"direction":"out","magnitude":"moderate","driver_type":"macro","title":"S&P cuts GM and Ford to junk","summary":"S&P downgraded GM two notches to BB and Ford to BB+ on May 5 2005, citing lost confidence in management, collapsing SUV sales and health-care costs. GM fell almost 6% to $30.86 and the downgrade of roughly $450 billion of combined debt rattled credit markets. It marked the start of the Detroit distress trade that ended in the 2009 bankruptcies and pushed capital toward foreign and parts makers.","evidence":"GM -6% to $30.86 on 2005-05-05 after the two-notch cut to BB","sources":[{"title":"NPR: Credit ratings for GM, Ford downgraded","url":"https://www.npr.org/2005/05/05/4632485/credit-ratings-for-gm-ford-downgraded"},{"title":"New York Sun: S&P cuts debt ratings of GM, Ford to junk","url":"https://www.nysun.com/article/business-s-p-cuts-debt-ratings-of-general-motors-ford"}]},{"id":"cd-2005-homebuilder-peak","date":"2005-07-20","end_date":"2005-11-15","sector":"consumer_discretionary","subindustries":[],"direction":"out","magnitude":"major","driver_type":"rates","title":"Homebuilder stocks peak in July 2005","summary":"After tripling during the 2003-2005 housing boom, homebuilder stocks topped in late July 2005 as the Fed's rate-hike cycle and stretched affordability bit: the group fell about 24% by mid-November 2005 and Toll Brothers, which cut its sales forecast in November, peaked at $58.25. It was the beginning of a drawdown that exceeded 70% for the group by 2008.","evidence":"Homebuilder index topped in July 2005 and fell ~24% by mid-November 2005; TOL peak $58.25","sources":[{"title":"Builder Online: Builder stocks slide (2005)","url":"https://builderonline.com/money/mortgage-finance/builder-stocks-slide_o"},{"title":"Kiplinger: Time to buy homebuilder stocks? (2008)","url":"https://kiplinger.com/article/investing/t038-c008-s001-time-to-buy-homebuilder-stocks.html"}]},{"id":"cd-2006-2008-housing-bust","date":"2006-01-03","end_date":"2008-11-20","sector":"consumer_discretionary","subindustries":["housing"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Housing bust: builders lose more than 70% from the 2005 peak","summary":"House prices peaked in July 2006 (Case-Shiller -21.8% by September 2008) and builder equities, which had already rolled over in 2005, kept falling as cancellations, land write-downs and the subprime collapse hit: by August 2008 Toll Brothers was down 62% from its peak and Pulte 73%, with the group down more than 70%. Home-improvement retailers and furniture makers fell in sympathy, and the sub-industry did not regain its 2005 high until 2020.","evidence":"TOL -62% and PHM -73% from July 2005 peak by late August 2008; Case-Shiller -21.8% from July 2006 peak by Sept 2008","sources":[{"title":"Kiplinger: Time to buy homebuilder stocks?","url":"https://kiplinger.com/article/investing/t038-c008-s001-time-to-buy-homebuilder-stocks.html"},{"title":"Motley Fool: A bigger housing knockdown in '09","url":"https://www.fool.com/investing/general/2008/12/22/a-bigger-housing-knockdown-in-09.aspx"}]},{"id":"media-2006-google-youtube","date":"2006-10-09","end_date":"2006-11-13","sector":"communication_media","subindustries":["media_entertainment","internet_platforms"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"Google buys YouTube for $1.65 billion","summary":"Google agreed on 9 October 2006 to acquire YouTube for $1.65 billion in stock, closing 13 November 2006. The deal marked the start of the shift of video advertising dollars from traditional media toward internet platforms, a theme that would weigh on legacy media valuations for the next two decades. YouTube was already serving roughly 100 million video views per day by mid-2006.","evidence":"Acquisition announced 2006-10-09 for $1.65 billion in Google stock; closed 2006-11-13.","sources":[{"title":"YouTube (Wikipedia)","url":"https://en.wikipedia.org/wiki/YouTube"}]},{"id":"re-2007-credit-crunch","date":"2007-02-08","end_date":"2007-12-31","sector":"real_estate","subindustries":["mortgage_reits","office_reits","residential_reits","retail_reits","lodging_reits","real_estate_services"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Subprime and the CMBS freeze: REITs peak and roll over in 2007","summary":"REIT prices peaked in February 2007 with the Equity Office buyout; subprime lender failures from February and the August 2007 money-market seizure then closed the CMBS market and REITs lost 15.7% for the year. Mortgage REITs collapsed 42% (commercial financing -49%), apartments fell 25% and office 19%, with SL Green down 28% and CBRE down 35%.","evidence":"All Equity REITs -15.7% in 2007; Mortgage REITs -42.4%; Residential -25.2%, Office -19.0%, Lodging -22.4%","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"Russell Investment Co. N-CSR FY2009 (CMBS lockdown and REIT solvency)","url":"https://www.sec.gov/Archives/edgar/data/0000351601/000119312510052773/dncsr.htm"}]},{"id":"apple-2007-iphone-launch","date":"2007-06-29","end_date":"2007-12-31","sector":"technology","subindustries":["apple","hardware","telecom","semiconductors"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"iPhone launch starts the smartphone supercycle","summary":"The iPhone went on sale on 29 June 2007 and Apple's shares rose from roughly $77 at the end of 2006 to about $200 by December 2007, a gain of around 160% in a year when the S&P 500 returned 5.5% and the Nasdaq 9.8%. The product reshaped the handset, component and wireless-carrier value chain (AT&T's exclusive), and the semiconductor content of phones became a decade-long demand driver.","evidence":"Apple closed 2007 at about $200.96 versus $76.77 a year earlier (pre-split prices).","sources":[{"title":"2007: A Heady Year for Apple","url":"https://infopackets.com/news/3030/2007-heady-year-apple"},{"title":"Apple share price flirts with $200 (Computerworld)","url":"https://www.computerworld.com/article/1571428/apple-share-price-flirts-with-200.html"},{"title":"This Day In Market History: Apple Introduces The iPhone","url":"https://www.benzinga.com/general/education/20/01/11007650/this-day-in-market-history-apple-introduces-the-iphone-1?mod=mw_quote_news"}]},{"id":"financials-2007-credit-crunch","date":"2007-09-18","end_date":"2008-03-14","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Credit crunch: Fed starts cutting, financial earnings collapse","summary":"The Fed cut 50 bp to 4.75% on 18 September 2007, warning that tightening credit could intensify the housing correction. By 15 February 2008 analysts expected S&P 500 financial-sector profits to fall 23% in Q1 2008 (versus +5% expected the prior October), with mortgage insurers and Countrywide down 35-67% over three months. Capital rotated out of banks and brokers and, by May 2008, technology had overtaken financials as the largest S&P 500 sector.","evidence":"Thomson Financial consensus on 2008-02-15: Q1 2008 financial-sector earnings -23%; ex-financials S&P 500 earnings +9%.","sources":[{"title":"FOMC statement, 18 September 2007","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20070918a.htm"},{"title":"Q1 earnings forecast goes negative (CNBC, 2008-02-15)","url":"https://www.cnbc.com/2008/02/15/q1-earnings-forecast-goes-negative.html"},{"title":"Odd data point: tech passes finance in SPX (Ritholtz, May 2008)","url":"https://ritholtz.com/2008/05/odd-data-point-tech-passes-finance-in-spx"}]},{"id":"ind-2008-gfc","date":"2007-10-09","end_date":"2009-03-09","sector":"industrials","subindustries":["transportation","machinery","industrial_distribution","building_products_construction","commercial_aerospace","electrical_equipment","professional_services"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Global financial crisis: industrials fall further than the market","summary":"Industrials were hit harder than the S&P 500 in the GFC because of leverage (GE Capital), collapsing freight and capex, and the housing bust. XLI lost 38.7% in 2008 and its peak-to-trough drawdown reached 62% versus 55% for SPY; United Rentals fell 50%, Deere 58%, Boeing 50% and staffing-sector stock indices fell 37.5% through November 2008 as unemployment surged.","evidence":"XLI max drawdown -62.3% (Oct 9, 2007 to Mar 9, 2009) vs SPY -55.2%; XLI -38.7% in 2008","sources":[{"title":"PortfoliosLab XLI drawdown statistics","url":"https://portfolioslab.com/symbol/XLI"},{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"},{"title":"ERE: Recruitment/HR stocks hit harder than market (2008)","url":"https://www.ere.net/recruitment-hr-stocks-hit-harder-than-market"}]},{"id":"utilities-2008-defensive-bear","date":"2007-10-09","end_date":"2009-03-09","sector":"utilities","subindustries":["regulated_utilities"],"direction":"mixed","magnitude":"major","driver_type":"macro","title":"Utilities outperform but still fall 46% in the GFC bear","summary":"Regulated utilities drew defensive flows during the financial crisis yet still lost 45.9% peak-to-trough versus 56.8% for the S&P 500, because credit-spread widening hit their leveraged balance sheets and merchant generators. The 0-0.25% fed funds rate set on 16 December 2008 and the start of asset purchases then turned utilities into the bond proxy of the next decade.","evidence":"S&P 500 Utilities -45.87% from 2007-10-09 to 2009-03-09 vs S&P 500 -56.78%.","sources":[{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"FOMC statement, 16 December 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081216b.htm"}]},{"id":"ind-2008-defensives-hold-up","date":"2008-01-02","end_date":"2008-12-31","sector":"industrials","subindustries":["waste","defense"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Waste and defense act as the sector's bunkers in 2008","summary":"Inside a sector that fell almost 40%, the non-cyclical sub-industries attracted relative capital. Waste Management posted a positive total return in 2008 on contracted, pricing-led revenue, and Lockheed Martin fell about half as much as the market because the defense budget was still growing through the Iraq/Afghanistan wars.","evidence":"WM +4.5% and LMT -18.6% in 2008 vs SPY -36.8% and XLI -38.7%","sources":[{"title":"ChartRow WM calendar-year returns","url":"https://chartrow.com/quote/wm/returns"},{"title":"ChartRow LMT calendar-year returns","url":"https://chartrow.com/quote/lmt/returns"}]},{"id":"re-2008-gfc-reit-crash","date":"2008-01-02","end_date":"2009-03-09","sector":"real_estate","subindustries":["industrial_logistics_reits","lodging_reits","retail_reits","office_reits","mortgage_reits","real_estate_services"],"direction":"out","magnitude":"major","driver_type":"macro","title":"GFC: REITs lose 38%, ProLogis and General Growth nearly fail","summary":"Lehman's bankruptcy raised solvency fears for leveraged landlords; All Equity REITs fell 37.7% in 2008 and another 23% to the March 9, 2009 low, with short interest peaking near 12% of shares. Industrial REITs lost 67% (ProLogis -58%, CEO ousted), lodging 60%, regional malls 61% (General Growth missed a $900m loan in November 2008 and filed the largest REIT bankruptcy on April 16, 2009 with $27.3bn of debt), commercial mortgage REITs 75%, and CBRE lost 80%.","evidence":"All Equity REITs -37.7% in 2008; Industrial REITs -67.5%, Lodging -59.7%, Regional Malls -60.6%, Commercial Financing mREITs -74.8% in 2008","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"NPR: Major shopping mall owner files for bankruptcy (Apr 2009)","url":"https://www.npr.org/2009/04/16/103166380/major-shopping-mall-owner-files-for-bankruptcy"},{"title":"ChartRow PLD calendar-year returns","url":"https://chartrow.com/quote/pld/returns"}]},{"id":"re-2008-storage-healthcare-defensive","date":"2008-01-02","end_date":"2008-12-31","sector":"real_estate","subindustries":["self_storage_reits","healthcare_reits"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Self storage and health care REITs hold up through the crash","summary":"Short leases, low leverage and need-based demand made self storage the only REIT sector with a positive 2008 (+5.1%, Public Storage +11.3%), and health care REITs fell only 12% (Welltower flat) on triple-net leases to senior-housing and skilled-nursing operators. Both sectors attracted the defensive capital that fled leveraged office, mall and hotel landlords.","evidence":"Self Storage REITs +5.05% and Health Care REITs -11.98% in 2008 vs All Equity REITs -37.7%; PSA +11.3%, WELL +0.2%","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"ChartRow PSA calendar-year returns","url":"https://chartrow.com/quote/psa/returns"}]},{"id":"cs-2008-defensive-outperformance","date":"2008-01-02","end_date":"2008-12-31","sector":"consumer_staples","subindustries":["staples_retail","food_beverage_tobacco","household_personal"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Staples are the 2008 sector outperformer; Walmart gains share in the crisis","summary":"In the 2008 crash XLP was the best-performing sector fund in both halves of the year, down only mid-single digits by October while the S&P 500 was down roughly 35-40%, as investors crowded into non-cyclical earnings and dividends. Walmart's revenue still climbed 7% to $401 billion as shoppers traded down, making it one of the few large-cap stocks to rise in 2008. The relative gain reversed in 2009 when staples lagged the risk rally (staples -9.7% vs S&P -8.9% by late March 2009).","evidence":"XLP was the sector outperformer in both halves of 2008 and down only ~5% YTD in October 2008 (TraderFeed); Walmart FY revenue +7% to $401.2B","sources":[{"title":"TraderFeed: A look at the rotating bear market (Oct 2008)","url":"https://traderfeed.blogspot.com/2008/10/look-at-rotating-bear-market.html"},{"title":"Motley Fool: Sector strategy, stick with consumer staples (March 2009)","url":"https://www.fool.com/investing/general/2009/03/24/sector-strategy-stick-with-consumer-staples.aspx"}]},{"id":"tech-2008-gfc-relative-resilience","date":"2008-01-02","end_date":"2009-03-09","sector":"technology","subindustries":["hardware","semiconductors","application_software","internet_platforms","apple"],"direction":"mixed","magnitude":"major","driver_type":"macro","title":"GFC: tech falls less than the market and becomes the largest sector","summary":"Technology fell about 43.7% in 2008 (Nasdaq -40.5%) and 53.0% peak-to-trough, less than the S&P 500's 56.8% and far less than financials' 82.6%, because balance sheets were cash-rich and had no credit exposure. In May 2008 tech overtook financials as the largest S&P 500 sector weight, a position it has not relinquished. The relative resilience set up tech's leadership in the 2009-2012 recovery.","evidence":"S&P 500 Information Technology -52.95% peak-to-trough (2007-10-09 to 2009-03-09) vs Financials -82.62%; Nasdaq 2008 return -40.54%.","sources":[{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"Odd data point: tech passes finance in SPX (Ritholtz)","url":"https://ritholtz.com/2008/05/odd-data-point-tech-passes-finance-in-spx"},{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"}]},{"id":"fintech-2008-visa-ipo","date":"2008-03-18","end_date":null,"sector":"technology","subindustries":["fintech_payments"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Visa prices the largest US IPO in history mid-crisis","summary":"Visa raised about $17.9 billion (US$19.1 billion with the overallotment) at $44 a share on 18 March 2008, then the largest IPO in US history, days after Bear Stearns was rescued. The listing created a liquid, asset-light payments bucket inside the IT sector that compounded through the financial crisis while bank balance sheets shrank; Mastercard had listed in 2006.","evidence":"406 million shares sold at $44 on 2008-03-18, raising about $17.9 billion.","sources":[{"title":"Visa Inc. (Wikipedia)","url":"https://en.wikipedia.org/wiki/Visa_Inc."}]},{"id":"ind-2008-airline-fuel-shock","date":"2008-04-14","end_date":"2008-07-11","sector":"industrials","subindustries":["transportation"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"$147 oil crushes airlines; Delta-Northwest merger as a survival move","summary":"Crude's run to a record $147 in July 2008 created a cash crunch for US carriers: AMR fell from $41 to $4 over 18 months, Aloha and other small carriers folded, and Delta and Northwest announced their merger on April 14, 2008. Even after the merger both stocks fell more than 40%; the group only rebounded when oil collapsed in the second half of 2008.","evidence":"AMR shares fell from $41 to $4 as crude went from $55 to $145 by mid-July 2008; Delta -47% and Northwest -44% after the Apr 14 merger announcement","sources":[{"title":"Honolulu Advertiser: airline stocks and oil (Jan 2009)","url":"https://archives-new.honoluluadvertiser.com/article/2009/Jan/04/bz/hawaii901040340.html"},{"title":"NBC News: 2008 a look back at one wacky year in travel","url":"https://www.nbcnews.com/id/wbna28355794"}]},{"id":"en-2008-solar-bust","date":"2008-05-15","end_date":"2009-03-09","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"macro","title":"First solar bust: polysilicon at $460/kg, then the credit crunch","summary":"Solar had been the hottest trade of 2007 (First Solar +795%) on German and Spanish feed-in tariffs, but polysilicon prices peaked near $460/kg in early 2008 and project finance vanished in the crisis. TAN lost three-quarters of its value over five months in late 2008 and First Solar fell 48% for the year, the first of three solar boom-bust cycles.","evidence":"TAN lost ~75% of its value in a five-month period in late 2008; FSLR +795.2% in 2007 then -48.4% in 2008","sources":[{"title":"24/7 Wall St: Solar stocks, does the punishment fit the crime? (Oct 2011)","url":"https://247wallst.com/energy-business/2011/10/06/solar-stocks-does-the-punishment-fit-the-crime-fslr-spwra-stp-jaso-tsl-ldk-tan/"},{"title":"ChartRow FSLR calendar-year returns","url":"https://chartrow.com/quote/fslr/returns"}]},{"id":"en-2008-oil-spike-and-crash","date":"2008-07-11","end_date":"2008-12-19","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services","refining","midstream"],"direction":"out","magnitude":"major","driver_type":"macro","title":"WTI $147 to $32: the 2008 energy crash","summary":"Crude peaked at $147 on July 11, 2008 and fell to about $32 by December as the financial crisis destroyed demand; XLE fell from near $90 to a $45 low. The ETF lost 39% in 2008, E&Ps (XOP -43%) and services (OIH -60%, SLB -56%) fell far more than the integrateds (XOM -13%), and refiners were crushed by the demand collapse (VLO -68.5%).","evidence":"WTI fell from $147 (Jul 11, 2008) to ~$32 (Dec 2008); XLE -39.0%, XOP -42.7%, OIH -60.2%, XOM -13.1% in 2008","sources":[{"title":"Convextrade: what happens to XLE when oil spikes","url":"https://convextrade.com/what-happens-when/oil-price-spikes/xle"},{"title":"ChartRow XOP calendar-year returns","url":"https://chartrow.com/quote/xop/returns"},{"title":"ChartRow OIH calendar-year returns","url":"https://chartrow.com/quote/oih/returns"}]},{"id":"materials-2008-commodity-peak-crash","date":"2008-07-11","end_date":"2008-12-23","sector":"materials","subindustries":["chemicals","metals_mining","gold_miners"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"Commodity supercycle peak and crash","summary":"Oil peaked at about $147 a barrel on 11 July 2008 and collapsed to $30.28 by 23 December 2008 as the credit crunch crushed demand expectations; nickel fell from about $51,000 to $11,550 a tonne and the Baltic Dry Index from 11,440 to 715. S&P 500 materials fell 59.6% peak-to-trough versus 56.8% for the index, with miners and chemical producers hit by destocking and the dollar squeeze.","evidence":"WTI/Brent peak about $147 on 2008-07-11; WTI spot $30.28 on 2008-12-23; Materials sector -59.55% from 2007-10-09 to 2009-03-09.","sources":[{"title":"Price of oil (Wikipedia)","url":"https://en.wikipedia.org/wiki/Price_of_oil"},{"title":"2000s commodities boom (Wikipedia)","url":"https://en.wikipedia.org/wiki/2000s_commodities_boom"},{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"}]},{"id":"financials-2008-lehman-gfc","date":"2008-09-15","end_date":"2009-03-09","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Lehman bankruptcy and the financials collapse","summary":"Lehman Brothers filed the largest bankruptcy in US history on 15 September 2008; the Dow fell 4.4% that day and AIG plunged 61%. S&P 500 financials lost about 57% in calendar 2008 and 82.6% from the 9 October 2007 peak to the 9 March 2009 low, versus 56.8% for the index. The Fed announced $600 billion of agency and MBS purchases on 25 November 2008 and cut to 0-0.25% on 16 December 2008.","evidence":"S&P 500 Financials -82.62% from 2007-10-09 to 2009-03-09 vs S&P 500 -56.78%.","sources":[{"title":"Bankruptcy of Lehman Brothers (Wikipedia)","url":"https://en.wikipedia.org/wiki/Bankruptcy_of_Lehman_Brothers"},{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"Don't trust the rally in financials (Motley Fool, 2009 sector table)","url":"https://www.fool.com/investing/general/2009/05/07/dont-trust-the-rally-in-financials.aspx"},{"title":"Fed announces agency debt and MBS purchases, 25 Nov 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081125b.htm"},{"title":"FOMC statement, 16 December 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081216b.htm"}]},{"id":"hc-2008-election-insurers","date":"2008-11-04","end_date":"2009-03-09","sector":"healthcare","subindustries":["managed_care","healthcare_facilities_services"],"direction":"out","magnitude":"major","driver_type":"election","title":"Obama win and reform debate hit managed care into the 2009 low","summary":"Health insurers sold off after the 2008 election as investors priced universal-coverage proposals, minimum medical-loss ratios and Medicare Advantage cuts on top of recession-driven enrollment losses. Within a month of the election UnitedHealth was down 11.7%, WellPoint 14.6% and Cigna 39.8%, and 2008 industry profits fell sharply (UNH net income -36%). Hospital operators were simultaneously squeezed by rising bad debt. Managed care only recovered once the final bill looked survivable in late 2009.","evidence":"Post-election declines to 2008-12-01: UNH -11.7%, WLP -14.6%, CI -39.8% (Capital IQ via Motley Fool)","sources":[{"title":"Motley Fool: Health insurers' universal uncertainty (Dec 2008)","url":"https://www.fool.com/investing/general/2008/12/01/health-insurers-universal-uncertainty.aspx"},{"title":"WellPoint FY2008 10-K","url":"https://www.sec.gov/Archives/edgar/data/0001156039/000119312509033022/d10k.htm"}]},{"id":"cd-2008-circuit-city","date":"2008-11-10","end_date":"2009-03-09","sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Circuit City files Chapter 11 and liquidates","summary":"The second-largest US electronics chain filed for bankruptcy on November 10 2008 citing the recession, collapsing consumer spending and competition from Best Buy, and announced full liquidation on January 16 2009, closing on March 8 and eliminating more than 30,000 jobs. It was the emblem of the 2008-2009 specialty-retail washout (Linens 'n Things, Mervyn's, Sharper Image also failed) that cleared capacity for survivors like Best Buy and the off-price chains.","evidence":"Chapter 11 filed 2008-11-10; liquidation of all stores announced 2009-01-16","sources":[{"title":"Wikipedia: Circuit City","url":"https://en.wikipedia.org/wiki/Circuit_City"}]},{"id":"cd-2009-gm-bankruptcy","date":"2008-12-19","end_date":"2009-07-10","sector":"consumer_discretionary","subindustries":["autos"],"direction":"mixed","magnitude":"major","driver_type":"macro","title":"Auto bailout, Chrysler and GM bankruptcies","summary":"GM and Chrysler took $17.4 billion of federal aid in December 2008; Chrysler filed on April 30 2009 and GM on June 1 2009 with $82.3 billion of assets against $172.8 billion of liabilities, its shares having fallen to 75 cents. Ford, which had mortgaged its assets in 2006, avoided bankruptcy and returned to profit by Q2 2009, and its stock became the vehicle for the 2009-2010 auto recovery trade while GM equity holders were wiped out.","evidence":"GM filed Chapter 11 on 2009-06-01 with $82.29B assets and $172.81B debt; shares had fallen to $0.75","sources":[{"title":"Patterson Belknap: GM files for bankruptcy","url":"https://www.pbwt.com/publications/gm-files-for-bankruptcy"},{"title":"History.com: Obama announces auto industry shakeup","url":"https://www.history.com/this-day-in-history/march-30/president-obama-announces-auto-industry-shakeup"},{"title":"Washington Times: GM bankruptcy spurs hope","url":"https://m.washingtontimes.com/news/2009/jun/2/gm-bankruptcy-spurs-hope-but-experts-expect-long-r/"}]},{"id":"cd-2009-homebuyer-credit","date":"2009-01-01","end_date":"2010-04-30","sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"minor","driver_type":"policy","title":"First-time homebuyer tax credit props up builders","summary":"The $8,000 first-time buyer credit ran from January 2009, was extended and widened in late October 2009, and required contracts by April 30 2010. It produced a sales spike that lifted builder stocks off their 2008-2009 lows, followed by a sharp drop in sales when it expired; analysts judged it had mostly pulled forward demand, and the sub-industry did not establish a durable recovery until 2012.","evidence":"Credit in effect January 2009 through April 30 2010 contracts; sales fell after expiry (Washington Times, Sept 2010)","sources":[{"title":"Calculated Risk: Tax credits, vehicle and existing home","url":"https://www.calculatedriskblog.com/2010/02/tax-credits-vehicle-and-existing-home.html"},{"title":"Washington Times: Charting the market, sales reflect tax credit expiration","url":"https://m.washingtontimes.com/news/2010/sep/23/charting-the-market-sales-reflect-tax-credit-expir/"}]},{"id":"memory-2009-qimonda-dram-bust","date":"2009-01-23","end_date":null,"sector":"technology","subindustries":["memory","semiconductors"],"direction":"out","magnitude":"moderate","driver_type":"tech_cycle","title":"DRAM oversupply bankrupts Qimonda","summary":"Commodity DRAM prices fell through 2008 on oversupply and Qimonda, Infineon's memory spin-off, filed for insolvency on 23 January 2009 after a German bailout fell apart; its NYSE shares had dropped to $0.05 by November 2008 and it sold its Inotera stake to Micron for about $400 million. The failure removed capacity from a sector that was consolidating toward three DRAM makers, the structure behind later memory price cycles.","evidence":"Qimonda AG filed for insolvency protection on 2009-01-23; net sales fell to EUR 1.79 billion from EUR 3.61 billion.","sources":[{"title":"Qimonda (Wikipedia)","url":"https://en.wikipedia.org/wiki/Qimonda"}]},{"id":"ind-2009-recovery-cyclicals","date":"2009-03-09","end_date":"2010-12-31","sector":"industrials","subindustries":["machinery","industrial_distribution","transportation","electrical_equipment","commercial_aerospace"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2009-2010 recovery: early-cycle industrials lead the rebound","summary":"Once credit markets reopened, capital rotated back into the most cyclical, most leveraged industrials. XLI returned 22% in 2009 and 27.8% in 2010 (vs SPY 26.4% and 15.1%), United Rentals rose 132% in 2010, Deere gained 45% and 56%, and Old Dominion 56% in 2010 as freight volumes recovered; Boeing added 33% in 2009 on the 787 program.","evidence":"XLI +27.8% in 2010 vs SPY +15.1%; URI +131.9% and DE +56.3% in 2010","sources":[{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"},{"title":"ChartRow URI calendar-year returns","url":"https://chartrow.com/quote/uri/returns"},{"title":"ChartRow ODFL calendar-year returns","url":"https://chartrow.com/quote/odfl/returns"}]},{"id":"en-2009-recovery-services-lead","date":"2009-03-09","end_date":"2010-12-31","sector":"energy","subindustries":["oilfield_services","exploration_production","integrated"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2009-10 recovery: oilfield services and shale E&Ps lead energy back","summary":"With China stimulus restoring oil to $80 and the shale gas/oil boom starting, high-beta services and E&Ps led the rebound: OIH returned 63.5% in 2009 and 20% in 2010, XOP 40% and 29%, while XLE gained 21.8% both years. The Macondo spill (April 2010) briefly hit offshore drillers but the land-rig count and pressure-pumping demand surged into 2011.","evidence":"OIH +63.5% in 2009; XOP +40.2% (2009) and +28.6% (2010); XLE +21.8% in both years","sources":[{"title":"ChartRow OIH calendar-year returns","url":"https://chartrow.com/quote/oih/returns"},{"title":"ChartRow XOP calendar-year returns","url":"https://chartrow.com/quote/xop/returns"}]},{"id":"re-2009-recapitalization-rally","date":"2009-03-09","end_date":"2009-12-31","sector":"real_estate","subindustries":["office_reits","lodging_reits","retail_reits","real_estate_services","mortgage_reits"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2009 REIT recapitalization: $37.5bn of equity raises end the solvency panic","summary":"Starting with Simon's March 2009 offering, REITs raised $37.5bn through 91 secondary offerings in 2009 and unsecured spreads narrowed from ~1,200bp to ~500bp; the capital came at dilutive prices but ended the bankruptcy scare. All Equity REITs returned 28% in 2009, with the most distressed groups leading: regional malls +63%, lodging +67%, SL Green +102% and CBRE +214% from the March low.","evidence":"REITs raised $37.5bn via 91 secondary offerings in 2009; All Equity REITs +28.0%, Lodging +67.2%, Regional Malls +63.0%, SLG +101.6% in 2009","sources":[{"title":"Nareit: 2009 REIT capital raising","url":"https://www.reit.com/node/120379"},{"title":"InvestmentNews: REITs took devastating early hit but finished on upswing","url":"https://investmentnews.com/alternatives/reits-took-devastating-early-hit-but-finished-on-upswing/24869"},{"title":"ChartRow SLG calendar-year returns","url":"https://chartrow.com/quote/slg/returns"}]},{"id":"tech-2009-2012-smartphone-cloud-buildout","date":"2009-03-10","end_date":"2012-12-31","sector":"technology","subindustries":["apple","semiconductors","hardware","internet_platforms","application_software","telecom"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Smartphone and cloud build-out leads the QE recovery","summary":"With the Fed at zero and buying bonds (QE2 of $600 billion announced 3 November 2010), capital rotated into the mobile and cloud build-out: the Nasdaq returned 43.9% in 2009, 16.9% in 2010 and 15.9% in 2012 versus 26.5%, 15.1% and 16.0% for the S&P 500. Global smartphone shipments reached 725 million units in 2012 and about 1 billion in 2013 (+38%), and Apple set a then-record $624 billion market capitalisation on 20 August 2012.","evidence":"Apple market capitalisation record of $624 billion on 2012-08-20; smartphone shipments about 1 billion in 2013, up 38% from 725 million in 2012.","sources":[{"title":"Apple Inc. (Wikipedia)","url":"https://en.wikipedia.org/wiki/Apple_Inc."},{"title":"Smartphone (Wikipedia)","url":"https://en.wikipedia.org/wiki/Smartphone"},{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"FOMC statement, 3 November 2010 (QE2)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20101103a.htm"}]},{"id":"financials-2009-stress-tests","date":"2009-05-07","end_date":"2009-12-31","sector":"financials","subindustries":["banks","capital_markets"],"direction":"in","magnitude":"major","driver_type":"regulatory","title":"Stress-test results end the bank panic","summary":"The Fed's Supervisory Capital Assessment Program results on 7 May 2009 found 10 of 19 large firms needed about $74.6 billion of capital (Bank of America $33.9 billion), a credible number that let banks raise equity and unlocked the rally in financials from the 9 March 2009 low. Combined with QE1 purchases, the result pulled capital back into banks and brokers through 2009, although the sector never regained its pre-crisis index weight.","evidence":"SCAP results released 2009-05-07: 10 of 19 banks required additional capital totalling about $74.6 billion.","sources":[{"title":"Supervisory Capital Assessment Program (Wikipedia)","url":"https://en.wikipedia.org/wiki/Supervisory_Capital_Assessment_Program"},{"title":"Fed announces agency debt and MBS purchases, 25 Nov 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081125b.htm"}]},{"id":"cd-2009-cash-for-clunkers","date":"2009-07-24","end_date":"2009-08-24","sector":"consumer_discretionary","subindustries":["autos"],"direction":"in","magnitude":"minor","driver_type":"policy","title":"Cash for Clunkers pulls auto demand forward","summary":"The Car Allowance Rebate System ran in practice from late July to August 24 2009 and pushed July auto sales to their highest level of the year; dealer stocks such as AutoNation jumped (with executives selling into the rally) and parts suppliers followed. Economists later concluded it mostly pulled sales forward, but it anchored the bottom in auto equities alongside the GM restructuring.","evidence":"July 2009 US auto sales were the highest of the year; AutoNation shares jumped on the program","sources":[{"title":"CS Monitor: Auto sales revive amid Cash for Clunkers","url":"https://www.csmonitor.com/Business/2009/0803/auto-sales-revive-amid-cash-for-clunkers-program"},{"title":"AOL: AutoNation execs cashing out as stock jumps on Cash for Clunkers","url":"https://www.aol.com/2009/08/10/autonation-execs-cashing-out-as-stock-jumps-on-cash-for-clunkers"}]},{"id":"media-2009-comcast-nbcu","date":"2009-12-03","end_date":"2011-01-28","sector":"communication_media","subindustries":["media_entertainment","telecom"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Comcast agrees to buy control of NBC Universal","summary":"On 3 December 2009 Comcast and GE announced a deal valuing NBC Universal at $30 billion, with Comcast taking 51% (closed 28 January 2011) and buying the rest in March 2013. The transaction fused cable distribution with content, a vertical-integration template later followed by AT&T-Time Warner, and it marked GE's retreat from media during the recession.","evidence":"Deal announced 2009-12-03 valuing NBC Universal at $30 billion; majority stake closed 2011-01-28.","sources":[{"title":"Acquisition of NBCUniversal by Comcast (Wikipedia)","url":"https://en.wikipedia.org/wiki/Acquisition_of_NBCUniversal_by_Comcast"}]},{"id":"ind-2011-caterpillar-mining-peak","date":"2010-01-04","end_date":"2012-04-27","sector":"industrials","subindustries":["machinery"],"direction":"in","magnitude":"moderate","driver_type":"commodity","title":"Mining capex boom carries Caterpillar to a 2012 peak","summary":"China-led commodity demand produced a second machinery boom after the GFC: Caterpillar returned 68.5% in 2010, bought Bucyrus for $8.6bn in 2011 and reported record profit on mining demand. The peak came in 2012; by 2015 Caterpillar said sales were 31% below the 2012 high with two-thirds of the decline from mining, making 2012 the top of the resource-capex cycle for machinery investors.","evidence":"CAT +68.5% total return in 2010; Caterpillar's 2015 8-K says sales were ~31% below the 2012 peak, nearly two-thirds of the decline from Resource Industries/mining","sources":[{"title":"Caterpillar 8-K (Sept 2015) restructuring presentation","url":"https://www.sec.gov/Archives/edgar/data/0000018230/000110465915072042/a15-21496_1ex99d2.htm"},{"title":"ChartRow CAT calendar-year returns","url":"https://chartrow.com/quote/cat/returns"}]},{"id":"hc-2010-aca-passage","date":"2010-03-22","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care"],"direction":"mixed","magnitude":"major","driver_type":"policy","title":"ACA passes the House: hospitals rally, big insurers lag","summary":"After the House passed the Affordable Care Act 219-212 on March 21 2010, hospital operators jumped on the prospect of 32 million newly insured patients while large commercial insurers fell on new MLR floors and taxes. Tenet rose about 9% and Health Management Associates 11%; UnitedHealth fell 3.2%, WellPoint 1.1% and Humana 1.4%. Medicaid-focused insurers rallied. Much of the move was relief after a year of overhang.","evidence":"THC +9%, HMA +11.3%, UNH -3.2% on 2010-03-22","sources":[{"title":"CNN Money: Health care stocks after reform vote","url":"https://money.cnn.com/2010/03/22/news/companies/health_care_stocks/index.htm"},{"title":"Lawrence Journal-World/AP: health stocks rise after House passes overhaul","url":"https://www2.ljworld.com/news/2010/mar/23/most-major-health-care-stocks-rise-modestly-after/"}]},{"id":"financials-2010-dodd-frank","date":"2010-07-21","end_date":null,"sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"Dodd-Frank signed: Volcker Rule, Durbin and the CFPB","summary":"President Obama signed Dodd-Frank on 21 July 2010, introducing the Volcker Rule limits on proprietary trading, the Durbin amendment capping debit interchange, the CFPB and systemic-risk designations. Higher capital and compliance costs capped bank returns on equity for most of the decade and pushed activity toward non-bank lenders and payment networks; the law was partially rolled back in May 2018.","evidence":"Dodd-Frank Act signed into law on 2010-07-21.","sources":[{"title":"Dodd-Frank Wall Street Reform and Consumer Protection Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Dodd%E2%80%93Frank_Wall_Street_Reform_and_Consumer_Protection_Act"}]},{"id":"en-2010-mlp-shale-boom","date":"2010-08-25","end_date":"2014-08-29","sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"MLP yield boom: shale build-out plus zero rates pull retail money into pipelines","summary":"Near-zero rates and the need for new pipelines out of the Bakken, Eagle Ford and Marcellus made master limited partnerships a favored yield vehicle; the AMLP ETF launched in August 2010 and the Alerian index compounded through 2014 while Cheniere, the first US LNG exporter, returned 128% in 2010, 116% in 2012 and 130% in 2013. Record MLP IPOs and drop-downs built the leverage that failed in 2015.","evidence":"AMLP +10.1% (2011), +18.5% (2013); LNG (Cheniere) +128.1% in 2010, +116.1% in 2012, +129.6% in 2013","sources":[{"title":"ChartRow AMLP calendar-year returns","url":"https://chartrow.com/quote/amlp/returns"},{"title":"ChartRow LNG calendar-year returns","url":"https://chartrow.com/quote/lng/returns"}]},{"id":"re-2010-qe-yield-trade","date":"2010-11-03","end_date":"2012-12-31","sector":"real_estate","subindustries":["residential_reits","self_storage_reits","data_center_tower_reits","net_lease_specialty_reits","healthcare_reits"],"direction":"in","magnitude":"major","driver_type":"rates","title":"QE2/Operation Twist: the REIT yield trade and the apartment boom","summary":"With the 10-year yield falling from 3.30% to 1.78% between 2010 and 2012, yield-starved capital poured into REITs (+28% in 2010, +8.3% in 2011, +19.7% in 2012) while the homeownership rate fell and apartment REITs returned 47% in 2010 and 15% in 2011. Self storage gained 35% in 2011, Realty Income 39% in 2010, and 2012 brought the first data-center/tower REIT conversions (American Tower, Equinix +103%).","evidence":"All Equity REITs +27.95% (2010) and +19.7% (2012) as the 10-year fell from 3.30% to 1.78%; Apartments +47.0% in 2010; EQIX +103.4% in 2012","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"Nareit REIT Industry Fact Sheet Dec 2020 (index levels and 10-year yields)","url":"https://www.reit.com/sites/default/files/2021-01/MediaFactSheet_Dec-2020.pdf"},{"title":"ChartRow EQIX calendar-year returns","url":"https://chartrow.com/quote/eqix/returns"}]},{"id":"utilities-2011-bond-proxy-leadership","date":"2011-01-03","end_date":"2011-12-31","sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Utilities best sector of 2011 as yields collapse","summary":"As the Eurozone crisis and the US downgrade drove Treasury yields to record lows and the Fed extended its zero-rate guidance, utilities returned 19.9% in 2011, the best S&P 500 sector against a 2.1% index return and -17.1% for financials. The year established the 'bond proxy' rotation pattern: utilities, staples and telecom absorb capital whenever real yields fall and growth fears rise.","evidence":"S&P 500 Utilities 2011 total return +19.9% (best sector) vs S&P 500 +2.1%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"August 2011 stock markets fall (Wikipedia)","url":"https://en.wikipedia.org/wiki/August_2011_stock_markets_fall"}]},{"id":"materials-2011-supercycle-peak","date":"2011-02-01","end_date":"2011-12-31","sector":"materials","subindustries":["metals_mining","chemicals"],"direction":"out","magnitude":"moderate","driver_type":"commodity","title":"Copper tops $10,000 and the commodity supercycle peaks","summary":"Copper rose above $10,000 a tonne in early 2011 and silver hit $47.94 on 29 April 2011 on China's post-stimulus demand, but 2011 marked the top of the supercycle: silver fell 12% on 2 May, and by 2013 copper was down about 33% and iron ore 36% from the early-2011 peaks. S&P 500 materials returned -9.6% in 2011 against +2.1% for the index as capital left cyclicals for bond proxies.","evidence":"Copper exceeded $10,000 per tonne in early 2011; S&P 500 Materials 2011 return -9.6% vs S&P 500 +2.1%.","sources":[{"title":"2000s commodities boom (Wikipedia)","url":"https://en.wikipedia.org/wiki/2000s_commodities_boom"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"nuclear-2011-fukushima","date":"2011-03-11","end_date":"2016-12-31","sector":"nuclear","subindustries":[],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"Fukushima halves uranium prices and starts a decade-long nuclear bear market","summary":"The 11 March 2011 Fukushima accident led to reactor shutdowns in Japan and Germany's exit decision; uranium spot prices fell by more than 50% from pre-accident levels and producers cut capacity, closed operations and deferred projects for years. The uranium ETF (URA, launched November 2010) and Cameco spent most of the following decade in drawdown, the base from which the 2023-2025 'nuclear renaissance' re-rating started.","evidence":"Uranium spot price fell more than 50% after the March 2011 Fukushima disaster, with producers cutting capacity.","sources":[{"title":"Uranium market (Wikipedia)","url":"https://en.wikipedia.org/wiki/Uranium_market"}]},{"id":"ind-2011-budget-control-act","date":"2011-08-02","end_date":"2013-03-01","sector":"industrials","subindustries":["defense","professional_services"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Debt ceiling and Budget Control Act put defense and federal services in limbo","summary":"The August 2011 debt-ceiling deal created $1.2 trillion of automatic cuts (sequestration) if the supercommittee failed, which it did. Defense primes had already trailed the S&P 500 for the 12 months before signing and hit valuation lows 'not seen since the end of the Cold War'; federal IT and professional services stocks lagged the market in both 2011 and 2012 as award decisions stalled ahead of the March 1, 2013 sequester.","evidence":"ITA +4.6% in 2011 and +12.7% in 2012 vs SPY +1.9% and +16.0%; federal IT/services stocks underperformed the broader market in 2011 and 2012","sources":[{"title":"Fox Business: Is this the biggest risk to defense stocks right now?","url":"https://www.foxbusiness.com/markets/is-this-the-biggest-risk-to-defense-stocks-right-now"},{"title":"CSIS: What has the Budget Control Act of 2011 meant for defense?","url":"https://www.csis.org/analysis/what-has-budget-control-act-2011-meant-defense"},{"title":"Washington Technology: Budget uncertainty puts damper on contractor stocks","url":"https://www.washingtontechnology.com/2012/05/budget-uncertainty-puts-damper-on-contractor-stocks/336864/"}]},{"id":"financials-2011-downgrade-eurozone","date":"2011-08-08","end_date":"2011-12-31","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"US downgrade and Eurozone crisis: financials worst sector of 2011","summary":"S&P stripped the US of its AAA rating on 6 August 2011 and the S&P 500 fell 6.7% on 8 August, with about $2.5 trillion of global equity value erased in a day as the Eurozone crisis spread to Italy and Spain; European regulators banned short selling of banks on 11 August. S&P 500 financials finished 2011 down 17.1%, the worst sector, versus +2.1% for the index, while utilities led at +19.9%.","evidence":"S&P 500 -6.7% on 2011-08-08; Financials sector 2011 return -17.1% vs S&P 500 +2.1%.","sources":[{"title":"August 2011 stock markets fall (Wikipedia)","url":"https://en.wikipedia.org/wiki/August_2011_stock_markets_fall"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"en-2011-solyndra-solar-crash","date":"2011-08-31","end_date":"2012-12-31","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Solyndra bankruptcy and Chinese oversupply: solar's second bust","summary":"Chinese capacity expansion collapsed module prices just as European subsidies were cut, and Solyndra's August 31, 2011 bankruptcy after a $535m DOE loan made solar politically toxic. TAN lost 70% in nine months and 63% for 2011, First Solar fell 74% (and 25% in one day when its CEO left on October 25), and the group kept falling in 2012.","evidence":"TAN -63.4% in 2011 and -30.8% in 2012; FSLR -74.1% in 2011, trading 89% below its May 2008 high by late 2011","sources":[{"title":"CNN Money: The Solyndra curse","url":"https://money.cnn.com/2011/09/27/markets/thebuzz/index.htm"},{"title":"CNN Money: First Solar shares tumble 25% as CEO leaves","url":"https://money.cnn.com/2011/10/25/technology/first_solar_ceo/index.htm"},{"title":"ChartRow TAN calendar-year returns","url":"https://chartrow.com/quote/tan/returns"}]},{"id":"ind-2012-housing-recovery-building-products","date":"2012-01-03","end_date":"2014-12-31","sector":"industrials","subindustries":["building_products_construction"],"direction":"in","magnitude":"moderate","driver_type":"rates","title":"Housing recovery and QE3 re-rate building products","summary":"Housing starts bottomed in 2011 and the Fed's open-ended MBS buying from September 2012 pushed mortgage rates to record lows, pulling capital into building products, HVAC and construction names. The PKB building ETF returned 41.2% in 2013 and 25.4% in 2014 versus 32.3% and 13.5% for the S&P 500.","evidence":"PKB +41.2% in 2013 and +25.4% in 2014 vs SPY +32.3% and +13.5%","sources":[{"title":"ChartRow PKB calendar-year returns","url":"https://chartrow.com/quote/pkb/returns"}]},{"id":"en-2012-refiners-brent-wti-spread","date":"2012-01-03","end_date":"2013-12-31","sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"major","driver_type":"commodity","title":"Cushing glut: Brent-WTI spread of $15-22 makes mid-continent refiners the trade","summary":"Shale oil trapped at Cushing drove WTI to a $15-22 discount to Brent, ending the year near $19, so refiners bought cheap domestic crude and sold product at world prices. Marathon Petroleum returned 89% and Valero 66% in 2012, HollyFrontier and Tesoro about 85%, and Valero added 65% in 2013 before new pipelines compressed the spread.","evidence":"MPC +88.6% and VLO +66.2% in 2012; Brent-WTI spread ended 2012 just under $19","sources":[{"title":"Motley Fool: A new golden age for refiners (Feb 2013)","url":"https://www.fool.com/investing/general/2013/02/06/a-new-golden-age-for-refiners.aspx"},{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"}]},{"id":"hc-2012-2015-biotech-bull","date":"2012-01-03","end_date":"2015-07-20","sector":"healthcare","subindustries":["biotech_large","biotech_smid"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"The 2012-2015 biotech bull market","summary":"A wave of approvals (hepatitis C, immuno-oncology, gene therapy), the 2012 JOBS Act and near-zero rates drove a three-year surge in biotech. The Nasdaq Biotech Index nearly tripled from 2010 and IBB was up about 214% from the start of 2012 by 2015; biotech IPO pricing went from a median 25% below range before 2012 to at-range afterward. The sector peaked in July 2015 with widespread bubble talk.","evidence":"IBB +214% from 2012-01 to mid-2015 (BioSpace); Nasdaq Biotech Index nearly tripled since 2010 (Motley Fool, April 2015)","sources":[{"title":"BioSpace: The coming crash in biotech stocks","url":"https://www.biospace.com/b-biopharm-executive-b-the-coming-crash-in-biotech-stocks"},{"title":"Motley Fool: Has the biotech bubble already popped? (April 2015)","url":"https://www.fool.com/investing/general/2015/04/04/has-the-biotech-bubble-already-popped.aspx"},{"title":"LifeSciVC: Evolution of the biotech IPO markets","url":"https://lifescivc.com/?p=10360"}]},{"id":"housing-2012-recovery","date":"2012-01-03","end_date":"2012-12-31","sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2012 housing recovery: PulteGroup +169% as builders lead the market","summary":"After six years of bust, home prices rose for eight straight months through October 2012 (CoreLogic), QE3 in September pushed mortgage rates to record lows, and homebuilders became the year's best-performing group. PulteGroup gained 169%, Lennar 92% and Toll Brothers 54% in 2012, and the group kept rallying into early 2013 before the taper tantrum. Capital that had avoided housing since 2006 rotated back into builders, building products and home improvement.","evidence":"PulteGroup +169% and Lennar +92% in 2012 (InvestorPlace year-end ranking).","sources":[{"title":"Best & worst stocks of 2012: homebuilders rule (InvestorPlace)","url":"https://investorplace.com/2012/12/best-worst-stocks-of-2012-homebuilders-rule-pcs-drool/"},{"title":"Homebuilders rally, ignore Case-Shiller drop (24/7 Wall St., March 2012)","url":"https://247wallst.com/housing/2012/03/27/homebuilders-rally-ignore-case-shiller-drop-len-phm-bzh-dhi/"}]},{"id":"internet-2012-facebook-ipo","date":"2012-05-18","end_date":"2012-09-04","sector":"technology","subindustries":["internet_platforms"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Facebook IPO at $38 breaks, halves by September","summary":"Facebook priced the largest internet IPO at $38 on 18 May 2012, fell below the offer price on day two and bottomed near $17.73 in early September 2012 amid doubts about mobile monetisation. The flop chilled consumer-internet listings for a year, yet marked the arrival of social media as an index-scale ad platform that would be reclassified into Communication Services in 2018.","evidence":"IPO priced at $38 on 2012-05-18; shares traded below $18 in September 2012, less than half the offer price.","sources":[{"title":"Initial public offering of Facebook (Wikipedia)","url":"https://www.wikipedia.org/wiki/Facebook_IPO"},{"title":"Facebook shares fall below $38 issue price (NBC News)","url":"https://www.nbcnews.com/news/world/stocks-rise-facebook-shares-fall-below-38-issue-price-flna784193"},{"title":"Facebook's first year as a public company: by the numbers (The Week)","url":"https://theweek.com/articles/464222/facebooks-first-year-public-company-by-numbers"}]},{"id":"hc-2012-scotus-aca","date":"2012-06-28","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care","medical_devices"],"direction":"mixed","magnitude":"major","driver_type":"regulatory","title":"Supreme Court upholds the ACA: hospitals soar, insurers slip","summary":"The Court upheld the individual mandate as a tax. Hospital stocks surged as coverage expansion was secured (HCA +10.75% to $29.47; HMA and Community Health roughly +10%), Medicaid managed-care names jumped, and large commercial insurers fell 3-4% as the MLR and fee provisions stayed in place. The ruling also preserved the 2.3% medical device excise tax, a mild negative for devices.","evidence":"HCA closed +10.75% at $29.47 on 2012-06-28; major health insurers fell about 3-4%","sources":[{"title":"KFF Health News: Hospital stocks soar as court upholds health act","url":"https://kffhealthnews.org/news/hospital-stocks-soar-as-court-upholds-health-act/"},{"title":"CNN Money: Health care stocks divided after ruling","url":"https://money.cnn.com/2012/06/28/investing/healthcare-stocks/index.htm"}]},{"id":"financials-2012-qe3-bank-rebound","date":"2012-09-13","end_date":"2012-12-31","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"in","magnitude":"major","driver_type":"rates","title":"QE3 and housing recovery make financials the best sector of 2012","summary":"The Fed launched open-ended purchases of $40 billion a month of agency MBS on 13 September 2012 and extended zero-rate guidance to mid-2015, supporting mortgage credit and bank balance sheets. S&P 500 financials returned 28.8% in 2012, the best sector against 16.0% for the index, as the Eurozone tail risk faded after the ECB's 'whatever it takes' pledge.","evidence":"S&P 500 Financials 2012 total return +28.8% vs S&P 500 +16.0%; QE3 announced 2012-09-13.","sources":[{"title":"FOMC statement, 13 September 2012 (QE3)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20120913a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"hc-2013-device-tax","date":"2013-01-01","end_date":"2019-12-20","sector":"healthcare","subindustries":["medical_devices"],"direction":"out","magnitude":"minor","driver_type":"policy","title":"2.3% medical device excise tax takes effect, then is suspended and repealed","summary":"The ACA's 2.3% excise tax on device sales began January 1 2013, a direct hit to margins for small and mid-cap device makers that became a persistent lobbying theme. Congress suspended it for 2016-2017, extended the moratorium through 2019, and repealed it in the December 20 2019 appropriations act. The repeal removed a multi-year overhang and coincided with the sector's re-rating into 2020.","evidence":"IRS: 2.3% tax on sales after 2012-12-31; moratorium 2016-2019; repealed by the Further Consolidated Appropriations Act, 2020 (signed 2019-12-20)","sources":[{"title":"IRS: Medical device excise tax FAQ","url":"https://www.irs.gov/newsroom/medical-device-excise-tax-frequently-asked-questions"}]},{"id":"ind-2013-boeing-production-supercycle","date":"2013-01-02","end_date":"2014-12-31","sector":"industrials","subindustries":["commercial_aerospace"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Boeing's 737/787 rate ramp drives an aerospace supercycle","summary":"With a $415bn backlog (4.5x annual sales) Boeing lifted 737 output from 31.5 to 38 a month and 787 output to 10 a month, and commercial margins rose to nearly 11%. The stock returned 84.7% in 2013, the best Dow component, and aftermarket suppliers (TransDigm, HEICO) re-rated as the installed base grew.","evidence":"BA total return +84.7% in 2013; backlog $415bn at Oct 2013","sources":[{"title":"Motley Fool: Boeing delivers strong quarter (Oct 2013)","url":"https://www.fool.com/investing/general/2013/10/23/boeing-delivers-strong-quarter-and-should-continue.aspx"},{"title":"Motley Fool: Boeing 3 key indicators to follow in 2015","url":"https://www.fool.com/investing/general/2015/01/20/boeing-cos-ba-3-key-indicators-to-follow-in-2015.aspx"},{"title":"ChartRow BA calendar-year returns","url":"https://chartrow.com/quote/ba/returns"}]},{"id":"en-2013-solar-rebound","date":"2013-01-02","end_date":"2014-03-07","sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"2013 solar rebound: module price stabilization and the yieldco model","summary":"After two years of collapse, polysilicon stabilized at $50-70/kg, Chinese demand replaced European demand and the yieldco structure (SunEdison's TerraForm) brought cheap capital to solar developers. TAN returned 128% in 2013 and First Solar 77%, the sector's best year until 2020.","evidence":"TAN +127.9% in 2013; ICLN +49.1% and FSLR +77.1% in 2013","sources":[{"title":"ChartRow TAN calendar-year returns","url":"https://chartrow.com/quote/tan/returns"},{"title":"VentureBeat: polysilicon prices fall (2011)","url":"https://venturebeat.com/2011/05/16/polysilicon-prices-fall-slow"}]},{"id":"hardware-2013-dell-lbo","date":"2013-02-05","end_date":"2013-10-30","sector":"technology","subindustries":["hardware"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"Dell goes private in a $24.4 billion LBO as PCs shrink","summary":"Michael Dell and Silver Lake announced a $24.4 billion leveraged buyout on 5 February 2013 (closed 30 October 2013 at $13.88 a share) as PC demand fell under tablets and smartphones. The deal removed a major hardware name from public markets and symbolised capital leaving legacy PC and server hardware for mobile and cloud; Dell relisted in 2018 as an AI-server play.","evidence":"LBO announced 2013-02-05 for $24.4 billion; completed 2013-10-30.","sources":[{"title":"Dell (Wikipedia)","url":"https://en.wikipedia.org/wiki/Dell"}]},{"id":"ind-2013-sequester-relief-rally","date":"2013-03-01","end_date":"2013-12-31","sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Sequestration arrives and defense stocks rally anyway","summary":"Once the sequester took effect, the worst case was priced in and primes responded with buybacks and margin discipline. Defense became one of the best groups of 2013: ITA returned 55.9% versus 32.3% for the S&P 500 and Lockheed Martin 68.1%, and the Bipartisan Budget Act of December 2013 then partially lifted the caps for FY14-15.","evidence":"ITA +55.9% and LMT +68.1% in 2013 vs SPY +32.3%","sources":[{"title":"Business Insider: investors unconcerned about defense budget cuts (2013)","url":"https://businessinsider.in/heres-another-sign-that-investors-are-totally-unconcerned-about-defense-budget-cuts/articleshow/21240800.cms"},{"title":"ChartRow ITA calendar-year returns","url":"https://chartrow.com/quote/ita/returns"}]},{"id":"re-2013-taper-tantrum","date":"2013-05-22","end_date":"2013-12-31","sector":"real_estate","subindustries":["mortgage_reits","net_lease_specialty_reits","residential_reits","healthcare_reits","data_center_tower_reits"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Taper tantrum: mortgage REITs and bond-proxy REITs de-rate","summary":"Bernanke's May 22, 2013 taper comments took the 10-year from 1.6% to 3.0%; mortgage REITs fell 21% from the end of April, Annaly cut its dividend from $0.45 to $0.30 and lost 20% for the year, and the longest-duration equity REITs (net lease, health care, apartments) went negative while the S&P 500 gained 32%. All Equity REITs returned just 2.9% in 2013, the first big relative loss of the QE era.","evidence":"Mortgage REIT stocks -21% from Apr 30 to late June 2013; NLY -20.0% in 2013; All Equity REITs +2.9% in 2013 vs S&P 500 +32.4%; Health Care REITs -7.1%, Apartments -6.2%","sources":[{"title":"Motley Fool: Why did Annaly and peers get crushed in the Fed's wake","url":"https://www.fool.com/investing/general/2013/06/20/why-did-annaly-and-peers-get-crushed-in-the-feds-w.aspx"},{"title":"InvestmentNews: Mortgage REITs in the cellar","url":"https://investmentnews.com/alternatives/mortgage-reits-in-the-cellar/52487"},{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"}]},{"id":"utilities-2013-taper-tantrum","date":"2013-05-22","end_date":"2013-09-05","sector":"utilities","subindustries":["regulated_utilities"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Taper tantrum hits utilities, REITs and telecom","summary":"Ben Bernanke's 22 May 2013 remarks on reducing bond purchases sent 10-year yields sharply higher and triggered a rotation out of bond proxies: in the week of 20 May utilities fell 3.4% and REITs 4.4% against a 1.07% drop in the S&P 500, with reported drawdowns of about 9% for XLU and 12% for VNQ over the episode. Utilities finished 2013 up 13.2% against 32.4% for the index, and the Fed began tapering on 18 December 2013.","evidence":"Week of 2013-05-20: Utilities -3.4%, REITs -4.4%, S&P 500 -1.07%; Utilities 2013 return +13.2% vs S&P 500 +32.4%.","sources":[{"title":"Friday's sell-off reminiscent of 2013 (SmartTrust)","url":"https://www.smarttrustuit.com/wcmu/fridays-sell-off-reminiscent-of-2013/"},{"title":"Tapering talk should keep toppling REITs (InvestorPlace, Aug 2013)","url":"https://investorplace.com/2013/08/the-taper-talk-toppled-reits"},{"title":"FOMC statement, 18 December 2013 (taper)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20131218a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"telecom-2013-taper-tantrum","date":"2013-05-22","end_date":"2013-12-31","sector":"technology","subindustries":["telecom"],"direction":"out","magnitude":"moderate","driver_type":"rates","title":"Telecom lags as taper talk lifts yields","summary":"High-dividend telecom carriers traded as bond proxies alongside utilities and REITs and were sold once the Fed signalled tapering in May 2013. S&P 500 telecom services returned 11.5% in 2013, the second-worst sector, against 32.4% for the S&P 500 and 28.4% for technology, as capital rotated from yield toward growth and cyclicals.","evidence":"S&P 500 Telecom Services 2013 total return +11.5% vs S&P 500 +32.4%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Taper tantrum paper (City, University of London)","url":"https://openaccess.city.ac.uk/id/eprint/15684/"}]},{"id":"re-2014-rate-reversal-rally","date":"2014-01-02","end_date":"2014-12-31","sector":"real_estate","subindustries":["residential_reits","healthcare_reits","net_lease_specialty_reits","mortgage_reits","self_storage_reits"],"direction":"in","magnitude":"major","driver_type":"rates","title":"2014: yields fall back and REITs double the S&P 500","summary":"The taper happened but rates fell anyway (10-year 3.04% to 2.17%), and the sectors punished in 2013 led a 28% REIT year: apartments +39.6%, health care +33.3%, self storage +31.4%, Realty Income +34.4% and mortgage REITs +17.9%. It was the clearest demonstration that the post-2013 REIT market trades as a duration asset.","evidence":"All Equity REITs +28.0% in 2014 vs S&P 500 +13.7%; Apartments +39.6%, Health Care +33.3%, Self Storage +31.4%","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"ChartRow O calendar-year returns","url":"https://chartrow.com/quote/o/returns"}]},{"id":"utilities-2014-yield-rally","date":"2014-01-02","end_date":"2014-12-31","sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Utilities return 29% in 2014 as yields fall again","summary":"Contrary to consensus for higher rates, the 10-year yield fell through 2014 as the Fed completed tapering and global growth disappointed, and utilities returned 29.0%, the second-best S&P 500 sector after real estate against a 13.7% index return. Energy (-7.8%) was the worst sector as the oil crash began, the first leg of the 2014-2016 industrial recession.","evidence":"S&P 500 Utilities 2014 total return +29.0% vs S&P 500 +13.7%; Energy -7.8%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"en-2014-opec-price-war","date":"2014-06-20","end_date":"2016-02-11","sector":"energy","subindustries":["exploration_production","oilfield_services","integrated"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"OPEC refuses to cut (Nov 27, 2014): the 2014-16 oil crash","summary":"With US shale adding a million barrels a day a year, OPEC held output at its November 27, 2014 meeting and crude dropped 10% that day to four-year lows; XOP was already down 40% from its June high by December 5 and WTI fell under $30 in February 2016. XOP lost 29% in 2014 and 36% in 2015, OIH 24% and 25%, and XLE 8.7% and 21.5% in years the S&P 500 rose, with dozens of E&P and service bankruptcies.","evidence":"XOP -40% from June 2014 high by Dec 5, 2014; XOP -29.4% (2014) and -35.8% (2015); XLE -21.5% in 2015 vs SPY +1.2%","sources":[{"title":"CNN Money: Oil stocks plunge after OPEC decision","url":"https://money.cnn.com/2014/11/28/investing/oil-stocks-plunge-opec/"},{"title":"Market Realist: Why the bottom fell out of crude oil (Dec 2014)","url":"https://marketrealist.com/2014/12/bottom-fell-crude-oil"},{"title":"ChartRow XOP calendar-year returns","url":"https://chartrow.com/quote/xop/returns"}]},{"id":"cyber-2014-sony-hack-etf-launch","date":"2014-11-24","end_date":"2014-12-19","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"in","magnitude":"minor","driver_type":"geopolitical","title":"Sony Pictures hack puts cybersecurity on the map as a theme","summary":"The Guardians of Peace leak of Sony Pictures data on 24 November 2014, formally attributed by the FBI to North Korea on 19 December, made breach risk a board-level issue two weeks after the first cybersecurity ETF (HACK) launched on 11 November 2014. Security budgets became a non-discretionary line in enterprise IT spending, the foundation of the sector's later premium valuation.","evidence":"Sony Pictures data leaked 2014-11-24; FBI linked the attack to North Korea on 2014-12-19.","sources":[{"title":"Sony Pictures hack (Wikipedia)","url":"https://en.wikipedia.org/wiki/Sony_Pictures_hack"}]},{"id":"ind-2015-industrial-recession","date":"2014-12-01","end_date":"2016-02-11","sector":"industrials","subindustries":["machinery","industrial_distribution","transportation","electrical_equipment"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"2015-16 industrial recession: oil capex collapse, strong dollar, rail bear market","summary":"The oil crash, a 20% dollar rally and Chinese slowdown produced a manufacturing recession without a broad one. Fastenal's CEO said in October 2015 that 44 of its top 100 customers were shrinking, Caterpillar guided to a fourth straight down year, railroads entered a bear market on collapsing coal and crude carloads, and Dow Transports underperformed the S&P 500 by 1,800bp in 2015-early 2016.","evidence":"XLI -4.3% in 2015 vs SPY +1.2%; CAT -23.0%, URI -28.9%, ODFL -23.9% in 2015; Transports lagged S&P 500 by 1,800bp (BofA, Feb 2016)","sources":[{"title":"Global Fastener News: Fastenal CEO on industrial recession","url":"https://www.globalfastenernews.com/?p=64524"},{"title":"Caterpillar 8-K Sept 2015","url":"https://www.sec.gov/Archives/edgar/data/0000018230/000110465915072042/a15-21496_1ex99d2.htm"},{"title":"Benzinga: BofA says move back into transports (Feb 2016)","url":"https://feeds2.benzinga.com/analyst-ratings/analyst-color/16/02/6492444/bofa-says-move-back-in-to-transports-upgrades-industry-e"},{"title":"Peak-oil.org/Bloomberg: US rails skid into bear market","url":"https://news.peak-oil.org/2015/06/u-s-rails-skid-into-bear-market-on-triple-whammy-cargo-slump/"}]},{"id":"biotech-2014-gilead-hepc-formulary-fight","date":"2014-12-22","end_date":null,"sector":"healthcare","subindustries":["biotech_large"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Express Scripts drops Sovaldi for AbbVie's Viekira Pak; Gilead -12% and PBM pricing power becomes a sector risk","summary":"After a year of political fire over Sovaldi's $84,000 list price, Express Scripts announced on December 22, 2014 that AbbVie's newly approved Viekira Pak would be the exclusive genotype-1 hepatitis C regimen on its national formulary from January 1, 2015 in exchange for a large discount, the first major specialty-drug exclusion of its kind. Gilead fell about 12% to roughly $95.70 and the Nasdaq Biotech index dropped 4.6% as investors re-priced the ability of PBMs to force rebates. Gilead and Express Scripts later made peace with a 2017 formulary deal, but net pricing for hepatitis C never recovered.","evidence":"Gilead -11.8% to about $95.70 on 2014-12-22; Nasdaq Biotechnology index -4.6%.","sources":[{"title":"Gilead Sciences falls amid AbbVie deal with Express Scripts (Benzinga)","url":"https://www.benzinga.com/news/14/12/5099689/gilead-sciences-plummets-amid-abbvie-deal-with-express-scripts"},{"title":"Express Scripts drops Gilead hep C drugs for cheaper AbbVie rival (Reuters via Yahoo)","url":"https://www.yahoo.com/news/express-scripts-cover-abbvie-hepatitis-c-drug-drops-050323412--finance.html"},{"title":"Gilead and Express Scripts make peace in hep C with 2017 formulary deal (FiercePharma)","url":"https://www.fiercepharma.com/pharma/gilead-and-express-scripts-make-peace-hep-c-2017-formulary-deal"}]},{"id":"en-2015-refiners-cheap-crude","date":"2015-01-02","end_date":"2015-12-31","sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"moderate","driver_type":"commodity","title":"Refiners are the only energy winners of the 2015 crash","summary":"Cheap crude, record US gasoline demand and strong export margins let refiners decouple from the rest of energy in 2015: Valero returned 47% in a year XLE lost 21.5% and XOP 36%. The episode cemented refiners' role as the counter-cyclical hedge inside the sector.","evidence":"VLO +46.8% in 2015 vs XLE -21.5% and XOP -35.8%","sources":[{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"},{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"}]},{"id":"re-2015-storage-peak-oversupply","date":"2015-01-02","end_date":"2019-12-31","sector":"real_estate","subindustries":["self_storage_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"macro","title":"Self storage peaks in 2015 then stalls under a development wave","summary":"Self storage was the best REIT sector of 2015 (+40.7%, Public Storage +38%) on 95% occupancy and double-digit rent growth, which triggered a national development boom; the sector then returned -8.1% in 2016, +3.7% in 2017 and +2.9% in 2018 as new supply saturated markets and street rates fell. The cycle set up the pandemic-era rebound.","evidence":"Self Storage REITs +40.65% in 2015, then -8.14% (2016), +3.74% (2017), +2.94% (2018)","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"Motley Fool: Self storage in 2022, what to expect (oversupply after 2019 development)","url":"https://www.fool.com/real-estate/2021/12/07/self-storage-in-2022-what-to-expect"}]},{"id":"semis-2015-consolidation-wave","date":"2015-05-28","end_date":"2016-01-31","sector":"technology","subindustries":["semiconductors","semicap"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Avago-Broadcom and the 2015 semiconductor M&A wave","summary":"Avago agreed to buy Broadcom for about $37 billion on 28 May 2015 (closed January 2016), days before Intel's $16.7 billion Altera deal, after NXP's $11.8 billion Freescale purchase in March. Announced semiconductor acquisitions totalled $72.6 billion in the first half of 2015 alone, nearly six times the prior five-year annual average, as slowing unit growth pushed the industry toward scale and pricing power that underpinned its later margin expansion.","evidence":"IC Insights: H1 2015 announced semiconductor M&A of $72.6 billion, about 6x the prior five-year annual average; Avago-Broadcom valued at about $37 billion.","sources":[{"title":"Tsunami of M&A deals in the semiconductor industry in 2015 (IC Insights via Design & Reuse)","url":"https://www.design-reuse.com/news/37935/m-a-deals-semiconductor-industry-in-2015.html"},{"title":"PMC-Sierra 8-K investor presentation on record semiconductor M&A (SEC)","url":"https://www.sec.gov/Archives/edgar/data/0000767920/000119312515339461/d26874dex991.htm"},{"title":"Broadcom (Wikipedia)","url":"https://en.wikipedia.org/wiki/Broadcom"}]},{"id":"en-2015-kinder-morgan-mlp-crash","date":"2015-06-01","end_date":"2016-02-11","sector":"energy","subindustries":["midstream"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Kinder Morgan cuts its dividend 75%: the MLP model breaks","summary":"Falling oil, over-leveraged balance sheets and a closed equity window ended the MLP yield trade: the Alerian MLP index fell 47% between June 2015 and February 2016, and on December 8, 2015 bellwether Kinder Morgan cut its dividend 75% to protect its investment-grade rating. KMI lost 63% in 2015 and AMLP 26%; Plains and others cut distributions in the following months, pushing the sector toward C-corp conversions and self-funding.","evidence":"KMI dividend cut 75% on Dec 8, 2015; KMI -62.8% and AMLP -25.7% in 2015; Alerian MLP index -47% Jun 2015-Feb 2016","sources":[{"title":"Fortune: Kinder Morgan dividend and oil prices (Dec 2015)","url":"https://dc.fortune.com/2015/12/09/kinder-morgan-dividend-oil-prices"},{"title":"Mauldin Economics: Steer clear of these oil MLPs","url":"https://www.mauldineconomics.com/the-weekly-profit/whatever-you-do-steer-clear-of-these-oil-mlps"},{"title":"ChartRow KMI calendar-year returns","url":"https://chartrow.com/quote/kmi/returns"}]},{"id":"managed-care-2015-megamergers","date":"2015-07-03","end_date":"2015-07-24","sector":"healthcare","subindustries":["managed_care"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"Aetna-Humana ($37bn) and Anthem-Cigna ($54bn): the summer-2015 insurer merger wave","summary":"Aetna agreed to buy Humana for $230 a share in cash and stock (about $37bn) on July 3, 2015, and Anthem agreed to buy Cigna for about $54bn on July 24, deals that would have cut the five national insurers to three. Humana rose as much as 4% and Aetna fell as much as 6% on announcement day, while Cigna fell from $154.36 to $145.91 and Anthem from $155.23 to $150.76 on July 24 as the Street doubted antitrust approval. Humana closed at $181.76, far below the offer value, a merger-arb spread that foreshadowed the DOJ suits of July 2016.","evidence":"Aetna offer of $230 per Humana share (2015-07-03); Cigna closed $145.91 on 2015-07-24 vs $154.36 the day before.","sources":[{"title":"Anthem to buy Cigna, creating biggest U.S. health insurer (Reuters via Yahoo)","url":"https://www.yahoo.com/news/health-insurer-anthem-buy-cigna-101732902.html"},{"title":"Wall Street hates the Anthem-Cigna deal (Forbes)","url":"https://www.forbes.com/sites/dandiamond/2015/07/24/since-announcing-merger-anthem-and-cigna-have-already-lost-3-billion-on-wall-street/"},{"title":"$34 billion Aetna-Humana merger: bad news for ANTM, CI (InvestorPlace)","url":"https://investorplace.com/2015/07/aetna-humana-merger-aet-stock-hum-stock-bad-news-for-antm-ci/"}]},{"id":"en-2016-sunedison-yieldco-bust","date":"2015-07-20","end_date":"2016-12-30","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"SunEdison collapse ends the yieldco era","summary":"SunEdison, briefly the world's largest renewable developer, buckled under $16bn of debt and filed for bankruptcy on April 21, 2016, discrediting the yieldco funding model and freezing capital for solar developers. TAN fell 43% in 2016, First Solar 51% and Enphase 71%, even as installations kept growing.","evidence":"TAN -43.2%, FSLR -51.4%, ENPH -71.2% in 2016","sources":[{"title":"ChartRow TAN calendar-year returns","url":"https://chartrow.com/quote/tan/returns"},{"title":"ChartRow ENPH calendar-year returns","url":"https://chartrow.com/quote/enph/returns"}]},{"id":"hc-2015-2016-biotech-crash","date":"2015-07-20","end_date":"2016-02-09","sector":"healthcare","subindustries":["biotech_smid","biotech_large"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"2015-2016 biotech crash: XBI nearly halves","summary":"From the July 2015 peak to February 2016, XBI fell about 49% and IBB about 40% (roughly $400 to $240), the worst biotech drawdown since 2000-2002 and far worse than the S&P 500's single-digit correction. Drivers were drug-pricing politics (Clinton, Valeant, Turing), the China/global-growth scare of August 2015 and a collapse of the IPO window. XBI was the worst-performing ETF of early 2016.","evidence":"XBI drawdown -49.25% from July 2015 to February 2016 (PortfoliosLab); XBI -30% YTD by 2016-02-16 (CNBC)","sources":[{"title":"PortfoliosLab: XBI drawdowns","url":"https://portfolioslab.com/symbol/XBI"},{"title":"CNBC: Is the worst ETF of 2016 about to get even worse?","url":"https://www.cnbc.com/2016/02/16/is-the-worst-etf-of-2016-about-to-get-even-worse.html"},{"title":"ETF Trends: Biotechs, buying opportunity or warning sign?","url":"https://www.etftrends.com/?p=179248"}]},{"id":"media-2015-disney-espn-selloff","date":"2015-08-04","end_date":"2015-08-05","sector":"communication_media","subindustries":["media_entertainment"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"Disney admits ESPN subscriber losses; media stocks suffer double-digit cord-cutting drops","summary":"On August 4, 2015 Disney trimmed its cable-network outlook and Bob Iger acknowledged 'modest sub losses' at ESPN; the stock fell more than 9% on August 5, its worst day in almost four years, and media peers (Viacom, Time Warner, Fox, CBS, Discovery) dropped double digits that week. Disney's annual filing later showed ESPN lost 3m subscribers in fiscal 2015 and about 7m over two years, to 92m. The week is generally treated as the market's first repricing of linear TV for cord-cutting.","evidence":"Disney shares -9% on 2015-08-05; ESPN subscribers fell 3m in FY2015 to 92m.","sources":[{"title":"Disney stock hit by ESPN fears (CNN Money)","url":"https://money.cnn.com/2015/08/05/media/disney-stock-down-espn/"},{"title":"Disney lowers forecast citing ESPN sub drop (Deadline)","url":"https://deadline.com/2015/08/disney-lower-financial-forecast-espn-subscriber-loss-1201491732/"},{"title":"Hollywood's stock crash one year later (Hollywood Reporter)","url":"https://www.hollywoodreporter.com/lists/hollywoods-stock-crash-one-year-918528/"}]},{"id":"materials-2015-commodity-bust","date":"2015-08-11","end_date":"2016-02-11","sector":"materials","subindustries":["metals_mining","chemicals","gold_miners"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"China devaluation, oil below $30 and the Glencore scare","summary":"China devalued the yuan on 11 August 2015 and global markets fell on 24 August; Glencore, carrying about $30 billion of debt, posted a $676 million first-half operating loss and its shares crashed on 28 September 2015. Oil fell below $30 on 3 February 2016, down almost 75% from mid-2014. S&P 500 materials returned -8.4% and energy -21.1% in 2015 versus +1.4% for the index, even as the Fed lifted rates off zero on 16 December 2015.","evidence":"Oil below $30 on 2016-02-03, down almost 75% from mid-2014; Materials 2015 return -8.4%, Energy -21.1% vs S&P 500 +1.4%.","sources":[{"title":"Price of oil (Wikipedia)","url":"https://en.wikipedia.org/wiki/Price_of_oil"},{"title":"2015-2016 stock market selloff (Wikipedia)","url":"https://en.wikipedia.org/wiki/2015%E2%80%932016_stock_market_selloff"},{"title":"Glencore (Wikipedia)","url":"https://en.wikipedia.org/wiki/Glencore"},{"title":"FOMC statement, 16 December 2015 (liftoff)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20151216a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"hc-2015-clinton-tweet","date":"2015-09-21","end_date":"2015-09-25","sector":"healthcare","subindustries":["biotech_large","biotech_smid","pharma"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Hillary Clinton's drug-pricing tweet starts the biotech bear market","summary":"Reacting to Turing's 5,000% Daraprim price hike, Clinton tweeted that she would lay out a plan to stop 'price gouging'. IBB went from flat to down about 4.6% that day, wiping roughly $40 billion from biotech, and the group fell about 13% for the week. The tweet crystallised drug-pricing as an election-year risk and marked the top of the 2012-2015 bull run.","evidence":"IBB -4.6% on 2015-09-21; biotech index -13% for the week","sources":[{"title":"CNN Money: Hillary Clinton biotech price gouging","url":"https://money.cnn.com/2015/09/21/investing/hillary-clinton-biotech-price-gouging/"},{"title":"CNBC: Biotech falls on Clinton price gouging comments","url":"https://www.cnbc.com/2015/09/21/biotech-falls-on-clinton-price-gouging-comments.html"},{"title":"Fortune: Biotech stocks fall into bear market","url":"https://fortune.com/2015/09/25/biotech-stocks-fall-bear-market"}]},{"id":"re-2015-hcp-manorcare-skilled-nursing","date":"2015-10-01","end_date":"2016-10-31","sector":"real_estate","subindustries":["healthcare_reits"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"HCR ManorCare blows up HCP: the skilled-nursing reimbursement risk","summary":"Medicare reimbursement pressure and a DOJ probe crushed HCP's largest tenant, HCR ManorCare: HCP took $1.3bn of 2015 impairments on the leases, fell 18% on February 9, 2016 when it guided below consensus, and spun the portfolio into QCP in October 2016. Health care REITs lost 7.3% in 2015 while Welltower and Ventas also de-rated on operator credit, and investors began paying up for private-pay senior housing over SNFs.","evidence":"HCP recorded an $817m Q4 2015 impairment ($1.3bn for the year) on HCRMC; HCP -18% on Feb 9, 2016; Health Care REITs -7.25% in 2015","sources":[{"title":"Motley Fool: Why HCP stock plunged today (Feb 9, 2016)","url":"https://www.fool.com/investing/general/2016/02/09/why-hcp-inc-stock-plunged-today.aspx"},{"title":"HCP 10-K FY2016","url":"https://www.sec.gov/Archives/edgar/data/0000765880/000155837017000535/hcp-20161231x10k.htm"}]},{"id":"staples-retail-2015-walmart-investor-day","date":"2015-10-14","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Walmart's investor day: -10%, its worst day since 1988, on wage and e-commerce investment","summary":"At its October 14, 2015 investor meeting Walmart guided fiscal 2017 EPS down 6-12% as wage and training investments ($1.5bn) and e-commerce and technology spending compressed margins, and said sales would be flat for the current year. The stock fell 10% to a three-year low, its worst day since 1988, and dragged the Dow, even though Walmart paired the guidance with a $20bn buyback. The reset marked the bottom of Walmart's reinvestment cycle; the omnichannel spending it financed underpinned the 2017-18 re-rating and the share gains that made staples retail a growth group by 2023-26.","evidence":"Walmart -10% on 2015-10-14; fiscal 2017 EPS guided to decline 6-12%.","sources":[{"title":"Walmart stock falls after retailer says wage hikes are killing its profits (CNN Money)","url":"https://money.cnn.com/2015/10/14/investing/walmart-outlook-wages/index.html"},{"title":"Walmart is having its worst day on Wall Street in more than 15 years (Slate)","url":"https://slate.com/business/2015/10/walmart-is-having-its-worst-day-on-wall-street-in-more-than-15-years-on-lowered-guidance.html"},{"title":"Dow slumps as Wal-Mart hammered after weak forecast (Reuters via Business Standard)","url":"https://www.business-standard.com/amp/article/reuters/dow-slumps-as-wal-mart-hammered-after-weak-forecast-115101401502_1.html"}]},{"id":"pharma-2015-valeant-citron","date":"2015-10-21","end_date":"2015-10-30","sector":"healthcare","subindustries":["pharma"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Citron's Philidor report: Valeant -39% intraday and the specialty-pharma roll-up model collapses","summary":"On October 21, 2015 short-seller Citron Research alleged Valeant used the specialty pharmacy Philidor to inflate sales; the shares fell as much as 39% (about $20bn of value) and were down 60% over three months by month-end, when Valeant cut ties with Philidor. Endo, Mallinckrodt and Horizon tumbled in sympathy and a large-cap pharma index fell 1.7% as investors abandoned the acquisition-plus-price-hike model. Coming a month after the Clinton drug-pricing tweet, it turned pricing power from an asset into a liability for the whole group and helped push health care to its 2016 underperformance.","evidence":"Valeant fell as much as 39% on 2015-10-21 after the Citron report.","sources":[{"title":"Valeant plunges 30% after short seller Citron Research makes fraud allegation (Forbes)","url":"https://www.forbes.com/sites/antoinegara/2015/10/21/valeant-plunges-30-after-short-seller-citron-research-makes-fraud-allegation/"},{"title":"Valeant drop ripples through drug stocks (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2015-10-21/valeant-rout-rips-drugmakers-with-endo-mallinckrodt-tumbling"},{"title":"Valeant scandal timeline (Fortune)","url":"https://dc.fortune.com/2015/10/31/valeant-scandal"}]},{"id":"cd-2015-chipotle-ecoli","date":"2015-10-31","end_date":"2016-02-08","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"Chipotle's E. coli and norovirus outbreaks end the fast-casual premium","summary":"A multi-state E. coli outbreak (55 infections in 11 states) forced Chipotle to close 43 stores in October-November 2015, followed by a second outbreak and a 140-person norovirus incident in December; all stores closed for a food-safety meeting on February 8 2016. Revenue fell from $4.50 billion in 2015 to $3.90 billion in 2016 and net income from $476 million to $23 million, and the stock lost roughly half its value, a template for how single-name food-safety shocks hit high-multiple restaurant stocks.","evidence":"2016 revenue $3,904M vs $4,501M in 2015; net income $23M vs $476M","sources":[{"title":"Wikipedia: Chipotle Mexican Grill","url":"https://en.wikipedia.org/wiki/Chipotle_Mexican_Grill"}]},{"id":"re-2016-ecommerce-logistics-and-digital","date":"2016-01-04","end_date":"2019-12-31","sector":"real_estate","subindustries":["industrial_logistics_reits","data_center_tower_reits"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"E-commerce and the cloud: logistics, data centers and towers become the growth REITs","summary":"Amazon's same-day push and cloud adoption shifted REIT leadership to the 'new economy' sectors: industrial REITs returned 30.7% in 2016, 20.6% in 2017 and 48.7% in 2019 (Prologis +56%), data centers 35.4% in 2017 and 44.2% in 2019 (Equinix +69%), and towers/infrastructure 42% in 2019 on 5G densification (American Tower +48%). By 2019 these three groups were roughly a third of REIT market cap.","evidence":"Industrial REITs +48.7%, Data Centers +44.2%, Infrastructure +42.0% in 2019; PLD +55.9% and EQIX +68.9% in 2019","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2020 (2019 sector returns)","url":"https://www.reit.com/sites/default/files/2021-01/MediaFactSheet_Dec-2020.pdf"},{"title":"ChartRow PLD calendar-year returns","url":"https://chartrow.com/quote/pld/returns"},{"title":"ChartRow AMT calendar-year returns","url":"https://chartrow.com/quote/amt/returns"}]},{"id":"en-2016-opec-vienna-cut","date":"2016-02-11","end_date":"2016-12-30","sector":"energy","subindustries":["exploration_production","oilfield_services","integrated","midstream"],"direction":"in","magnitude":"major","driver_type":"commodity","title":"Oil bottoms at $26 and OPEC agrees its first cut since 2008","summary":"After WTI bottomed near $26 in February 2016, energy rallied all year and OPEC's November 30 Vienna agreement to cut 1.2m b/d (plus 0.6m from non-OPEC) sent oil up 8% and XLE up 5.1% in a day. XLE returned 28% in 2016, XOP 38%, OIH 28% and KMI 43%, the sector's best year relative to the S&P 500 (+12%) since 2007.","evidence":"XLE +5.1% on Nov 30, 2016 (S&P -0.3%); XLE +28.0%, XOP +38.3%, OIH +27.8% in 2016 vs SPY +12.0%","sources":[{"title":"24/7 Wall St: Did OPEC production cut make speculative oil stocks rally too much?","url":"https://247wallst.com/energy/2016/11/30/did-opec-production-cut-make-more-speculative-oil-stocks-rally-too-much/"},{"title":"FX Empire: OPEC agrees to first production cuts since 2008","url":"https://www.fxempire.com/news/article/opec-agrees-to-first-production-cuts-since-2008-oil-soars-8-percent-375434"},{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"}]},{"id":"re-2016-gics-sector-bond-proxy","date":"2016-02-11","end_date":"2016-11-08","sector":"real_estate","subindustries":["net_lease_specialty_reits","mortgage_reits","industrial_logistics_reits","data_center_tower_reits"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Record-low yields and the new GICS Real Estate sector","summary":"The 10-year fell to a record 1.36% in July 2016 and REITs rallied as bond proxies into the September 1, 2016 creation of Real Estate as the 11th GICS sector, which forced generalist funds to reassess a structural underweight. Industrial (+30.7%), data centers (+26.4%) and mortgage REITs (+22.9%) led 2016; the trade reversed sharply after the November election as yields jumped.","evidence":"All Equity REITs +8.6% in 2016; Industrial +30.7%, Data Centers +26.4%, Mortgage REITs +22.9%; O +15.8%","sources":[{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"},{"title":"ChartRow O calendar-year returns","url":"https://chartrow.com/quote/o/returns"}]},{"id":"materials-2016-reflation-rebound","date":"2016-02-12","end_date":"2016-12-31","sector":"materials","subindustries":["metals_mining","chemicals"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2016 reflation: materials and energy lead off the February low","summary":"From the February 2016 commodity low, a weaker dollar, Chinese stimulus and then the November election's infrastructure and tariff expectations pulled capital back into cyclicals. S&P 500 materials returned 16.7% and energy 27.4% in 2016 versus 12.0% for the index, with steel and copper producers among the strongest groups; US indices set records in July 2016 after the Brexit dip.","evidence":"S&P 500 Materials 2016 total return +16.7%, Energy +27.4% (best sector) vs S&P 500 +12.0%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"2015-2016 stock market selloff (Wikipedia)","url":"https://en.wikipedia.org/wiki/2015%E2%80%932016_stock_market_selloff"}]},{"id":"ind-2016-election-reflation","date":"2016-11-09","end_date":"2018-01-26","sector":"industrials","subindustries":["machinery","industrial_distribution","building_products_construction","transportation","defense"],"direction":"in","magnitude":"major","driver_type":"election","title":"Trump election: infrastructure, tax-cut and reflation trade floods into industrials","summary":"Expectations of a $1 trillion infrastructure plan, corporate tax cuts and deregulation triggered an immediate rotation: industrials rose 4.4% in the three days after the election and about 9% in the first month, with Caterpillar and US Steel leading. The move extended through 2017's synchronized global growth, with XLI up 24% and United Rentals 63%.","evidence":"S&P industrials +4.4% in the three sessions after Nov 8, 2016; CAT +42.1% in 2016 and +75.0% in 2017; XLI +24.0% in 2017","sources":[{"title":"Business Insider: industrials and construction stocks rally after Trump victory","url":"https://businessinsider.in/industrials-and-construction-stocks-are-rallying-after-trumps-victory/articleshow/55341094.cms"},{"title":"CNBC: Trump stock market rally (Aug 2017)","url":"https://www.cnbc.com/2017/08/03/trump-stock-market-rally.html"},{"title":"ChartRow CAT calendar-year returns","url":"https://chartrow.com/quote/cat/returns"}]},{"id":"hc-2016-trump-election","date":"2016-11-09","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care","pharma","biotech_large"],"direction":"mixed","magnitude":"major","driver_type":"election","title":"Trump wins: hospital stocks crater, pharma and biotech rally","summary":"Trump's surprise win was read as the end of the ACA. Tenet closed down 25% and HCA about 10.8% on November 9 as investors priced lost coverage and higher bad debt; Medicaid-focused Molina fell about 15%. Pharma and biotech rallied on the removal of the Clinton price-control threat. Note: contrary to the common narrative, large commercial insurers did not uniformly rally on day one; they sold off before rebounding over the following weeks as repeal looked less likely.","evidence":"THC -24.96% and HCA -10.8% at the close on 2016-11-09; Molina -15%","sources":[{"title":"Fox Business: Trump's win causes a tremendous sell-off in hospital stocks","url":"https://foxbusiness.com/markets/trumps-win-is-causing-a-tremendous-sell-off-in-hospital-stocks"},{"title":"Healthcare Dive: Specter of ACA repeal sends hospital stocks down","url":"https://www.healthcaredive.com/news/specter-of-aca-repeal-sends-hospital-stocks-down/430116/"},{"title":"Becker's: Post-election healthcare stock report","url":"https://www.beckershospitalreview.com/finance/post-election-healthcare-stock-report.html"}]},{"id":"financials-2016-trump-election-bank-rally","date":"2016-11-09","end_date":"2016-11-30","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"in","magnitude":"major","driver_type":"election","title":"Trump election: banks post best month on record","summary":"The 8 November 2016 election triggered a rotation into banks on expectations of deregulation, tax cuts and higher rates: the SPDR S&P Bank ETF (KBE) rose 18.69% in November 2016, its best month on record, against 3.42% for the S&P 500, with Goldman Sachs and Morgan Stanley up about 23% and the 10-year yield rising from roughly 1.8% to 2.4%. The KBW bank index had gained nearly 14% within a week of the vote. Regional banks were up 27% by early February 2017 when Trump signed executive actions to begin unwinding Dodd-Frank.","evidence":"KBE +18.69% in November 2016 vs S&P 500 +3.42% (CNBC, 2016-11-30).","sources":[{"title":"Bank stocks rise nearly 19 percent, on pace for best month in history (CNBC)","url":"https://www.cnbc.com/2016/11/30/bank-stocks-rise-nearly-19-percent-on-pace-for-their-best-month-in-history.html"},{"title":"Bank stocks may have gotten way ahead of themselves (CNBC, 2016-11-16)","url":"https://www.cnbc.com/2016/11/16/bank-stocks-may-have-gotten-way-ahead-of-themselves.html"},{"title":"After big week, still more room to run for financial stocks (CNBC, 2017-02-04)","url":"https://www.cnbc.com/2017/02/04/after-big-week-still-more-room-to-run-for-financial-stocks.html"}]},{"id":"tech-2016-election-lag","date":"2016-11-09","end_date":"2016-12-31","sector":"technology","subindustries":["apple","internet_platforms","semiconductors","hardware"],"direction":"out","magnitude":"moderate","driver_type":"election","title":"Tech lags the post-election rotation into banks and industrials","summary":"In the week after the 2016 election Apple and other large technology names fell while banks and industrials surged, on concern that trade and tax policy would hurt overseas sales and because investors funded the cyclical rotation by selling crowded growth. Technology finished 2016 up 13.9%, roughly in line with the index (12.0%) but well behind financials (22.8%) and energy (27.4%); the lag reversed into the 2017 melt-up.","evidence":"Reuters, 2016-11-10: banks and industrials surged while Apple and other tech shares fell; Technology 2016 return +13.9% vs Financials +22.8%.","sources":[{"title":"Banks, healthcare lead post-election rally on Wall Street (Reuters via Business Standard)","url":"https://www.business-standard.com/amp/article/reuters/banks-healthcare-lead-post-election-rally-on-wall-street-116111000033_1.html"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"energy-2016-opec-vienna-cut","date":"2016-11-30","end_date":null,"sector":"energy","subindustries":["exploration_production","oilfield_services"],"direction":"in","magnitude":"major","driver_type":"commodity","title":"OPEC's Vienna deal: first cut since 2008 sends E&Ps and drillers up double digits","summary":"On November 30, 2016 OPEC agreed in Vienna to cut output by 1.2m b/d to 32.5m b/d from January 2017, its first cut in eight years, with Russia and other non-OPEC producers pledging a further 600k b/d. Brent rose $3.79 (8.2%) to $50.17 on the day and about 16% over two sessions; EOG, Apache and Chesapeake rose more than 8%, Marathon Oil 22% and Transocean 16%. The deal underwrote the 2017 shale recovery and the services rebound, though U.S. production growth capped crude below $60 for most of 2017.","evidence":"Brent +$3.79 to $50.17 (+8.2%) on 2016-11-30; Marathon Oil +22% and Transocean +16% the same day.","sources":[{"title":"Oil prices surge as OPEC reaches production deal (Al Jazeera)","url":"https://www.aljazeera.com/economy/2016/11/30/oil-prices-surge-as-opec-reaches-production-deal/"},{"title":"OPEC agrees to lower output to push up oil prices (CBS News)","url":"https://www.cbsnews.com/amp/news/opec-agrees-to-lower-output-to-push-up-oil-prices"},{"title":"What the OPEC production cut will really mean for oil prices (Fortune)","url":"https://fortune.com/2016/11/30/oil-prices-opec-meeting/"}]},{"id":"en-2017-shale-growth-underperformance","date":"2017-01-03","end_date":"2019-12-31","sector":"energy","subindustries":["exploration_production","oilfield_services","integrated"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"2017-19: shale over-production, Q4 2018 crash and energy's shrinking index weight","summary":"Three years of shale volume growth over returns kept energy the worst sector of the bull market: XOP lost 9.5%, 28.1% and 9.4% in 2017-19 and OIH 20%, 45% and 3%, while the S&P 500 compounded strongly. Brent fell 37% from its October 3, 2018 high to year-end, the Morningstar energy index dropped 22% in Q4 2018 and Exxon lost 14% in December 2018 alone; by 2019 energy was about 4% of the S&P 500 and generalists had largely exited.","evidence":"XOP -9.5% (2017), -28.1% (2018), -9.4% (2019); OIH -45.0% in 2018; Brent -37% from Oct 3, 2018 peak to year-end","sources":[{"title":"Motley Fool: Why these three oil company stocks collapsed in December 2018","url":"https://www.fool.com/investing/2019/01/07/why-these-three-oil-company-stocks-collapsed-in-de.aspx"},{"title":"Anadolu: Energy commodity prices fall significantly in 4Q18 (EIA)","url":"https://www.aa.com.tr/en/energy/stock-market/energy-commodity-prices-fall-significantly-in-4q18-eia/22931"},{"title":"ChartRow OIH calendar-year returns","url":"https://chartrow.com/quote/oih/returns"}]},{"id":"cd-2017-retail-apocalypse","date":"2017-01-03","end_date":"2017-11-09","sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"The 2017 'retail apocalypse'","summary":"A record roughly 8,000 store-closure announcements (Sears, JCPenney, Macy's, Payless, Toys R Us' September bankruptcy) and Amazon's share gains made 2017 the year investors abandoned mall retail: the equal-weight XRT was down 8.6% through November 9 2017 while the S&P 500 rose about 15%, before a Q3 earnings rebound trimmed the gap. Capital rotated within the sub-industry to off-price (TJX, Ross), auto parts and home improvement.","evidence":"XRT -8.6% YTD through 2017-11-09 vs S&P 500 +15%; ~8,000 store closures announced in 2017","sources":[{"title":"Fox Business/Motley Fool: Why retail stocks sank in Trump's first year","url":"https://www.foxbusiness.com/markets/why-retail-stocks-sank-in-trumps-first-year-in-office"},{"title":"Zacks: Is a wave of store closures troubling retail ETFs?","url":"https://www.zacks.com/amp/stock/news/254223/is-a-wave-of-store-closures-troubling-retail-etfs"}]},{"id":"cs-2018-bond-proxy-derating","date":"2017-01-03","end_date":"2018-05-16","sector":"consumer_staples","subindustries":["household_personal","food_beverage_tobacco"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Bond-proxy de-rating: staples trail the S&P 500 by 17 points in 2017 and fall 13% in early 2018","summary":"After five years of being bought as bond substitutes, staples were abandoned when yields rose: XLP fell 2.1% in 2017 while SPY gained 15.4%, then dropped about 13% by mid-May 2018 as the 10-year yield rose from 2.4% to 3.1%, putting it on track for its worst year since 2008's 17% decline. P&G, Kraft Heinz, General Mills and Campbell were hit by private-label share loss and retailer pressure on top of the rate effect; staples was the worst sector of Q1 2018.","evidence":"XLP -2.1% in 2017 vs SPY +15.4%; XLP ~-13% YTD on 2018-05-16 while the S&P 500 was up ~1%","sources":[{"title":"CNBC: One key group of stocks is on track for its worst year since 2008","url":"https://www.cnbc.com/2018/05/16/one-key-group-of-stocks-is-on-track-for-its-worst-year-since-2008.html"},{"title":"InvestmentNews: Safest assets provide no protection amid the brewing rate storm","url":"https://www.investmentnews.com/equities/safest-assets-provide-no-protection-amid-the-brewing-rate-storm/74363"}]},{"id":"tech-2017-melt-up","date":"2017-01-03","end_date":"2017-12-31","sector":"technology","subindustries":["internet_platforms","semiconductors","apple","application_software","hardware"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"2017 synchronized growth: tech returns 39%, FAANG 46%","summary":"Global synchronized growth, low volatility and the December 2017 tax cut drove a melt-up in large-cap technology: the S&P 500 IT sector returned 38.8% in 2017 against 21.8% for the index, and Goldman Sachs put the FAANG group at +46.5%. Telecom (-1.3%) and energy (-1.0%) were the only negative sectors, the mirror image of the 2016 rotation. Reuters noted the sector traded at 19x forward earnings versus 18x for the index, a modest premium by later standards.","evidence":"S&P 500 Information Technology 2017 total return +38.8% vs S&P 500 +21.8%; Telecom -1.3% (worst sector).","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Best ETFs and stocks from the top sector of 2017 (Zacks via Investing.com)","url":"https://investing.com/analysis/best-etfs--stocks-from-the-top-sector-of-2017-200276693"},{"title":"FAANG vs. S&P 500 2017 returns (Hedge Fund Alpha citing Goldman Sachs)","url":"https://hedgefundalpha.com/stocks/facebook-inc-fb-amazon-com-inc-amzn-apple-inc-aapl-vs-neflix-nflx/"}]},{"id":"towers-2017-rerating-2018-sprint-scare","date":"2017-01-03","end_date":"2018-05-24","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"tech_cycle","title":"Cell towers return 35% in 2017, then wobble on the Sprint/T-Mobile merger","summary":"Tower REITs were the best REIT sector of 2017 with a 35.38% total return (infrastructure was up 22% by mid-year) as carriers densified 4G networks and investors paid for escalator-driven growth; American Tower was up 38% year-to-date by late 2017. The run paused when the Sprint/T-Mobile merger was announced in April 2018: the tower group returned -7.2% from March 31 to May 24, 2018 against +2.9% for the RMZ on fears of losing a tenant. The 5G capex narrative then carried towers to a 42% return in 2019.","evidence":"Cell tower REITs total return 35.38% in 2017; -7.2% from 2018-03-31 to 2018-05-24 vs RMZ +2.9%.","sources":[{"title":"Spirit of America Investment Fund annual report 2017 (SEC N-CSR; cites tower REIT 35.38% return)","url":"https://www.sec.gov/Archives/edgar/data/0001039667/000119312518073113/d492317dncsr.htm"},{"title":"Cell tower REITs: for 5G, 4 beats 3 (Seeking Alpha)","url":"https://seekingalpha.com/article/4280713-cell-tower-reits-for-5g-4-beats-3"},{"title":"Mortgage REITs lead REIT market gains in 2017's first half (Nareit)","url":"https://www.reit.com/news/blog/nareit-media/mortgage-reits-lead-reit-market-gains-2017s-first-half"}]},{"id":"re-2017-retail-apocalypse","date":"2017-01-04","end_date":"2019-12-31","sector":"real_estate","subindustries":["retail_reits"],"direction":"out","magnitude":"major","driver_type":"macro","title":"Retail apocalypse: 7,000 store closures and a three-year mall de-rating","summary":"Macy's January 2017 closure list opened a year with 6,985 announced store closures (+200% y/y) and bankruptcies of Toys R Us, Sears and Payless; shopping-center REITs lost 11.4% in 2017 and 14.6% in 2018, regional malls fell three years running (-2.7%, -7.0%, -9.1%) and Simon traded a third below its 2016 high by 2019. Capital rotated from retail to industrial as the same e-commerce shift created logistics demand.","evidence":"6,985 store closures announced in 2017 (+200% y/y); Shopping Centers -11.4% (2017) and -14.6% (2018); Regional Malls -9.1% in 2019","sources":[{"title":"CNBC: Store closures rocked retail in 2017","url":"https://www.cnbc.com/2017/12/26/store-closures-rocked-retail-in-2017-and-more-should-come-next-year.html"},{"title":"Motley Fool: Simon Property Group in 5 charts (2019)","url":"https://www.fool.com/investing/2019/11/24/simon-property-group-in-5-charts.aspx"},{"title":"Nareit annual sector returns (AnnualSectorReturns.xlsx)","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"}]},{"id":"rails-2017-csx-psr-rally","date":"2017-01-19","end_date":"2019-12-31","sector":"industrials","subindustries":["transportation"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Hunter Harrison and Mantle Ridge: CSX +23% in a day starts the precision-scheduled-railroading rally","summary":"CSX rose 23.4% on January 19, 2017, its best day since 1980, after the Wall Street Journal reported that Hunter Harrison would leave Canadian Pacific and partner with Paul Hilal's Mantle Ridge to run CSX; Harrison was named CEO on March 6 with the stock up 35% since the report. Precision scheduled railroading then spread to Union Pacific (Unified Plan 2020, 2018), Norfolk Southern and Kansas City Southern, and rails re-rated on falling operating ratios through 2019 even as carload volumes declined. Harrison died in December 2017 but the margin playbook outlived him.","evidence":"CSX +23.4% on 2017-01-19 from a $36.88 prior close (Mantle Ridge DFAN14A).","sources":[{"title":"CSX shares see best day in 36 years amid reported activist interest (CNBC)","url":"https://www.cnbc.com/2017/01/19/csx-shares-tracking-for-best-day-in-36-years-amid-reported-activist-interest.html"},{"title":"CSX attracts new CEO and stock price rises sharply (Harvard Law corporate governance forum)","url":"https://corpgov.law.harvard.edu/2017/09/04/csx-attracts-new-ceo-and-stock-price-rises-sharply/"},{"title":"CSX reports improved progress in implementing precision scheduled railroading (CSX IR)","url":"https://investors.csx.com/news-and-events/news/news-details/2017/CSX-Reports-Improved-Progress-in-Implementing-Precision-Scheduled-Railroading-20170906080900/default.aspx"}]},{"id":"managed-care-2017-mergers-blocked","date":"2017-01-23","end_date":"2017-02-14","sector":"healthcare","subindustries":["managed_care"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Courts block Aetna-Humana and Anthem-Cigna; horizontal insurer consolidation ends","summary":"Judge John Bates blocked Aetna's acquisition of Humana on antitrust grounds on January 23, 2017 (Humana closed up 2.2% at $205.02, Aetna down about 2.5% near $119), and a second federal judge blocked Anthem-Cigna on February 9. Aetna and Humana terminated on February 14 with Aetna paying a $1bn break fee, and Cigna sued Anthem to exit. The rulings were widely expected and the stocks shrugged, but they rerouted managed-care capital into vertical deals (CVS-Aetna in December 2017, Cigna-Express Scripts in March 2018).","evidence":"Humana closed +2.2% at $205.02 on 2017-01-23; Aetna paid Humana a $1bn termination fee on 2017-02-14.","sources":[{"title":"Aetna-Humana shares fall after judge blocks deal (CNBC)","url":"https://www.cnbc.com/2017/01/23/judge-blocks-humanaaetna-deal-on-antitrust-grounds-reports.html"},{"title":"Aetna, Humana end $34 billion merger agreement (CNBC)","url":"https://www.cnbc.com/2017/02/14/aetna-and-humana-end-merger-agreement.html"},{"title":"Aetna, Humana call off merger; Cigna sues Anthem (AJMC)","url":"https://www.ajmc.com/view/aetna-humana-call-off-37-billion-merger"}]},{"id":"telecom-2017-verizon-unlimited-price-war","date":"2017-02-13","end_date":null,"sector":"technology","subindustries":["telecom"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Verizon brings back unlimited data: the 2017 wireless price war and telecom's lost year","summary":"Verizon reintroduced an $80-a-month unlimited plan on February 12, 2017, reversing its 2011 stance and matching T-Mobile and Sprint, after admitting in January that competition was biting harder than expected. AT&T, Sprint and Verizon shares each fell about 1% on February 13 as analysts warned of eroding margins across the industry. The plan locked in a year of service-revenue declines for the two incumbents and kept telecom among the S&P's worst sectors in 2017 while the market rose 20%.","evidence":"Verizon unlimited plan priced at $80 a month for a single line, announced 2017-02-12; VZ and T about -1% on 2017-02-13.","sources":[{"title":"Verizon's move to unlimited data ups ante in wireless war (Reuters via Fox Business)","url":"https://www.foxbusiness.com/markets/verizons-move-to-unlimited-data-ups-ante-in-wireless-war"},{"title":"Verizon jumps back into unlimited data, shares fall (Motley Fool)","url":"https://www.fool.com/investing/2017/02/13/verizon-jumps-back-into-unlimited-data-shares-fall.aspx"},{"title":"Verizon unlimited wireless data plan (Fortune)","url":"https://fortune.com/2017/02/12/verizon-unlimited-wireless-data-plan"}]},{"id":"staples-2017-kraft-heinz-unilever-bid","date":"2017-02-17","end_date":"2017-02-19","sector":"consumer_staples","subindustries":["household_personal","food_beverage_tobacco"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Kraft Heinz's $143bn bid for Unilever: a 3G cost-cut premium lands on every staple for a weekend","summary":"Kraft Heinz disclosed a $50-a-share, $143bn cash-and-stock approach for Unilever on February 17, 2017, which Unilever rejected as fundamentally undervaluing it; Unilever's U.S.-listed shares jumped 14% and Kraft Heinz 10% to a record. The bid was withdrawn on February 19 after the leak made a friendly deal impossible, but it forced Unilever into margin targets and buybacks and put a takeover premium on slow-growth food and household names (Campbell, General Mills, Kellogg, Mondelez were named as next targets). It marked the high-water mark of the 3G zero-based-budgeting era that Kraft Heinz's 2019 writedown ended.","evidence":"Unilever U.S.-listed shares +14% and Kraft Heinz +10% on 2017-02-17; bid withdrawn 2017-02-19.","sources":[{"title":"Kraft Heinz spurned in $143 billion Unilever takeover bid (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2017-02-17/kraft-heinz-says-unilever-rejected-approach-on-combination"},{"title":"Kraft Heinz withdraws its $143 billion bid for Unilever (Forbes)","url":"https://www.forbes.com/sites/antoinegara/2017/02/19/kraft-heinz-withdraws-its-143-billion-bid-for-unilever/"},{"title":"How Unilever dodged a bullet (Axios)","url":"https://www.axios.com/2019/02/24/unilever-kraft-heinz-takeover-bid-stock-prices"}]},{"id":"hc-2017-ahca-pulled","date":"2017-03-24","end_date":"2017-07-28","sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"ACA repeal fails: hospitals squeeze higher","summary":"When House Republicans pulled the American Health Care Act on March 24 2017, heavily shorted hospital stocks rallied (Tenet up as much as 8%, Universal Health up 5.4% the next session) with short interest near 21% of float in Tenet and Community Health. Gains faded as repeal talk revived, and the final Senate 'skinny repeal' failure on July 28 2017 closed the repeal window, leaving the ACA coverage base intact for providers and Medicaid insurers.","evidence":"THC up as much as 8% on 2017-03-24; short interest ~21% of shares outstanding in THC and CYH (Thomson Reuters)","sources":[{"title":"Reuters via StreetInsider: Hospital shares surge as market absorbs Republican health bill failure","url":"https://www.streetinsider.com/Reuters/Hospitals+shares+surge+as+market+absorbs+Republican+health+bill+failure/12708780.html"},{"title":"Kiplinger: Hospital stocks rally on failed Obamacare repeal","url":"https://www.kiplinger.com/article/investing/T052-C008-S001-hospital-stocks-rally-on-failed-obamacare-repeal.html"},{"title":"Bloomberg: Hospitals gain as Republican health repeal bill is pulled","url":"https://www.bloomberg.com/news/articles/2017-03-24/hospitals-insurers-gain-as-republican-health-bill-is-pulled"}]},{"id":"cd-2017-amazon-whole-foods","date":"2017-06-16","end_date":null,"sector":"consumer_discretionary","subindustries":["internet_retail"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Amazon buys Whole Foods: the 'Amazon effect' goes physical","summary":"Amazon's $13.7 billion deal for Whole Foods lifted AMZN 2.4% and erased about $29 billion from grocers and mass merchants in a day (Kroger -9.2%, Costco -7.2%, Target -5.2%, Walmart -4.7%). The deal confirmed that the internet-retail premium came partly from the market's willingness to fund Amazon's entry into any category, and it kicked off a two-year period in which every Amazon announcement moved incumbents (pharmacy, healthcare, logistics).","evidence":"AMZN +2.4%, KR -9.2%, COST -7.2%, TGT -5.2%, WMT -4.7% at the close on 2017-06-16","sources":[{"title":"TechCrunch: Other grocery stocks plummet as Amazon buys Whole Foods","url":"https://techcrunch.com/2017/06/16/foodpocalypse"},{"title":"Reuters via Business Standard: Wall St falls as Amazon-Whole Foods deal crushes retailers","url":"https://www.business-standard.com/amp/article/reuters/wall-st-falls-as-amazon-whole-foods-deal-crushes-retailers-117061601315_1.html"}]},{"id":"cs-2017-whole-foods-grocers","date":"2017-06-16","end_date":"2017-06-19","sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"major","driver_type":"ma","title":"Amazon-Whole Foods erases $29 billion from grocers in a day","summary":"Amazon's $13.7 billion Whole Foods deal was read as the start of a price war in groceries: Kroger closed down 9.2%, Costco 7.2%, Target 5.2% and Walmart 4.7% (Kroger was down 12% intraday), with about $29 billion of market value lost across grocery-related stocks; Target, Walmart and Costco were still lower the following Monday. Grocers spent the next three years investing in delivery and price, compressing margins and leaving the sub-industry's returns to Walmart and Costco.","evidence":"KR -9.2%, COST -7.2%, TGT -5.2%, WMT -4.7% at the close on 2017-06-16; ~$29B of grocery market value lost","sources":[{"title":"TechCrunch: Other grocery stocks plummet as Amazon buys Whole Foods","url":"https://techcrunch.com/2017/06/16/foodpocalypse"},{"title":"CNBC: Target, Wal-Mart endure the aftermath of Amazon's Whole Foods buy","url":"https://www.cnbc.com/2017/06/19/target-wal-mart-endure-the-aftermath-of-amazons-whole-foods-buy-stocks-still-falling.html"}]},{"id":"ind-2017-defense-budget-boom","date":"2017-07-12","end_date":"2018-02-09","sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"Defense re-rates on Trump budget push and the Bipartisan Budget Act of 2018","summary":"Lockheed and Northrop hit all-time highs in July 2017 as the administration proposed a ~10% defense increase, and the February 9, 2018 Bipartisan Budget Act raised the caps to $700bn for FY2018 and $716bn for FY2019, 15% above the original cap. ITA returned 34.6% in 2017 and defense's budget overhang was removed for two years.","evidence":"ITA +34.6% in 2017 vs SPY +21.7%; BBA 2018 set defense at $700bn (FY18) and $716bn (FY19)","sources":[{"title":"CNBC: Lockheed, Northrop reach all-time highs (Jul 2017)","url":"https://www.cnbc.com/2017/07/12/lockheed-northrop-reach-all-time-highs-as-investors-see-weapons-boost.html"},{"title":"CSIS: Making sense of the Bipartisan Budget Act of 2018","url":"https://www.csis.org/analysis/making-sense-bipartisan-budget-act-2018-and-what-it-means-defense"}]},{"id":"cs-2017-fda-nicotine","date":"2017-07-28","end_date":null,"sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"FDA proposes cutting nicotine to non-addictive levels; Altria drops 17%","summary":"FDA Commissioner Gottlieb announced a plan to begin rulemaking on lowering nicotine in cigarettes to non-addictive levels while easing the path for reduced-risk products. Altria fell more than 17% (as much as 19% intraday, its biggest drop since 1999), BAT 3%, while Philip Morris International recovered within hours because it has no US combustible exposure. The rule has never been finalised, but the day priced a permanent regulatory discount into US tobacco.","evidence":"MO -17% at the close on 2017-07-28 (intraday -19%, biggest since 1999)","sources":[{"title":"CNBC: Altria shares fall after FDA releases roadmap to curb tobacco-related deaths","url":"https://www.cnbc.com/2017/07/28/altria-shares-fall-after-fda-releases-roadmap-to-curb-tobacco-related-deaths-.html"},{"title":"BNN Bloomberg: FDA looks to cut nicotine in cigarettes to non-addictive level","url":"https://www.bnnbloomberg.ca/fda-looks-to-cut-nicotine-in-cigarettes-to-non-addictive-level-1.816272"}]},{"id":"healthcare-2017-skinny-repeal-fails","date":"2017-07-28","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"Senate 'skinny repeal' fails 49-51; ACA-exposed hospitals and Medicaid insurers keep their 2017 rally","summary":"In the early hours of July 28, 2017 John McCain, Susan Collins and Lisa Murkowski voted no on the 'skinny' Obamacare repeal, ending the seven-year Republican repeal effort at 49-51. Hospital operators (HCA, Tenet, Community Health) and exchange/Medicaid insurers (Centene, Molina) had traded all year as repeal proxies, jumping on each failure (Tenet +7.4% and Community Health +9.5% on March 24 when the House bill was pulled; Centene hit a record $87.94 on July 25). The vote removed the coverage-loss overhang for the group, although HCA's guidance cut three days earlier capped the hospital names.","evidence":"Senate rejected the Health Care Freedom Act 49-51 on 2017-07-28; Tenet +7.4% and Community Health +9.5% on the prior repeal failure (2017-03-24).","sources":[{"title":"Obamacare repeal fails: three GOP senators rebel in 49-51 vote (NBC News)","url":"https://www.nbcnews.com/politics/congress/senate-gop-effort-repeal-obamacare-fails-n787311"},{"title":"McCain's 'no' vote kills 'skinny repeal' (STAT)","url":"https://www.statnews.com/2017/07/28/mccain-obamacare-skinny-repeal/"},{"title":"Winners and losers after Friday's pulled health-care bill (CNBC, 2017-03-24)","url":"https://www.cnbc.com/2017/03/24/winners-and-losers-after-fridays-pulled-health-care-bill.html"}]},{"id":"cyber-2017-equifax-breach","date":"2017-09-07","end_date":"2019-07-22","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"in","magnitude":"minor","driver_type":"regulatory","title":"Equifax breach: 147.9 million records and a $575 million settlement","summary":"Equifax disclosed on 7 September 2017 that attackers had accessed data on about 147.9 million Americans; its shares fell about 13% the next day and the company agreed a roughly $575 million settlement in July 2019. Together with WannaCry earlier that year, the breach pushed security spending up the enterprise priority list and supported the re-rating of cybersecurity vendors relative to broader software.","evidence":"Equifax shares fell about 13% on 2017-09-08; July 2019 settlement of about $575 million.","sources":[{"title":"2017 Equifax data breach (Wikipedia)","url":"https://en.wikipedia.org/wiki/2017_Equifax_data_breach"}]},{"id":"household-2017-pg-peltz-proxy-fight","date":"2017-10-10","end_date":"2017-11-15","sector":"consumer_staples","subindustries":["household_personal"],"direction":"mixed","magnitude":"minor","driver_type":"positioning","title":"Peltz vs P&G: the largest proxy fight ever ends in a recount and a board seat","summary":"Procter & Gamble declared a preliminary win over Nelson Peltz's Trian at its October 10, 2017 annual meeting and the stock slipped; on November 15 Trian claimed victory on the IVS tabulation by roughly 43,000 votes out of about 2 billion, and P&G rose 2-3%. P&G seated Peltz in March 2018 and accelerated its restructuring, after which the stock began a multi-year re-rating. The fight established activism as the lever for underperforming staples (later replayed at Unilever, Kellogg and Kenvue) at the end of the sector's 2017 bond-proxy de-rating.","evidence":"Trian's margin in the IVS preliminary tabulation was about 42,700 votes (announced 2017-11-15).","sources":[{"title":"Procter & Gamble shareholders vote against adding Peltz to board (CNBC)","url":"https://www.cnbc.com/2017/10/10/procter-gamble-shareholders-vote-against-adding-nelson-peltz-to-board.html"},{"title":"Nelson Peltz claims victory in P&G proxy fight (WCPO / CNBC)","url":"https://www.wcpo.com/money/local-business-news/nelson-peltz-wins-procter-gamble-proxy-fight-after-recount-sources-tell-cnbc"},{"title":"Procter & Gamble claims narrow win over Peltz (Reuters via Business Standard)","url":"https://www.business-standard.com/amp/article/reuters/procter-gamble-foresees-proxy-war-victory-peltz-refuses-to-concede-117101100028_1.html"}]},{"id":"ind-2018-ge-collapse","date":"2017-11-13","end_date":"2018-12-31","sector":"industrials","subindustries":["electrical_equipment","commercial_aerospace"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"GE's power-business implosion and exit from the Dow","summary":"GE halved its dividend in November 2017 as the gas-turbine (Power) business collapsed with the shift to renewables, took large insurance charges, and was removed from the Dow on June 26, 2018 after 110 years. The stock fell 57% in the two years to June 2018 while the Dow rose 44%, dragging the electrical-equipment group and forcing the eventual breakup that produced GE Vernova and GE Aerospace.","evidence":"GE shares -57% over the two years to June 19, 2018 vs Dow +44%; GE -42.4% in 2017 and -55.1% in 2018","sources":[{"title":"Fortune: GE, last original Dow stock, out; Walgreens in","url":"https://fortune.com/2018/06/19/ge-last-original-dow-industrial-stock-out-walgreens-in/"},{"title":"ChartRow GE calendar-year returns","url":"https://chartrow.com/quote/ge/returns"}]},{"id":"waste-2018-china-national-sword","date":"2018-01-01","end_date":"2018-12-31","sector":"industrials","subindustries":["waste"],"direction":"out","magnitude":"minor","driver_type":"policy","title":"China's National Sword: recycled-commodity collapse costs Waste Management $90m of 2018 earnings","summary":"China's National Sword policy banned 24 categories of imported scrap and imposed a 0.5% contamination limit from January 1, 2018, collapsing prices for mixed paper and plastics in the U.S. Waste Management's recycling revenue fell $197m and recycling earnings $90m in 2018 with another $100m decline guided for 2019, and Waste Connections' recycling revenue fell 43%. The haulers responded by adding processing fees and renegotiating municipal contracts, which turned recycling from a commodity exposure into a fee-for-service line and, by 2021-22, into a tailwind when prices recovered.","evidence":"Waste Management 2018 recycling earnings down $90m y/y; recycling revenue down $197m.","sources":[{"title":"National Sword bruises hauler recycling businesses (Resource Recycling)","url":"https://resource-recycling.com/recycling/2019/02/19/national-sword-bruises-hauler-recycling-businesses/"},{"title":"From Green Fence to red alert: a China timeline (Resource Recycling)","url":"https://resource-recycling.com/recycling/2018/02/13/green-fence-red-alert-china-timeline/"}]},{"id":"hc-2018-amazon-berkshire-jpm","date":"2018-01-30","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Amazon-Berkshire-JPMorgan venture spooks PBMs, pharmacies and insurers","summary":"The three companies announced a non-profit venture to cut employee health costs. Express Scripts fell as much as 11% at the open, CVS 6.4%, and UnitedHealth, Cigna and Anthem 4-7%; McKesson lost about 3% and roughly $69 billion of health-care market value evaporated. The threat never materialised (Haven was wound down in 2021) but the day captured the 'Amazon disruption' fear that weighed on PBMs and drug distributors through 2018-2019.","evidence":"ESRX -11% and CVS -6.4% at the open on 2018-01-30; ~$69B of healthcare market cap lost","sources":[{"title":"Bloomberg: Health stocks fall after Amazon, JPMorgan, Berkshire deal","url":"https://www.bloomberg.com/news/articles/2018-01-30/health-stocks-slump-as-amazon-led-group-unveils-efficiency-plans"},{"title":"Becker's: Healthcare stocks lost $69B on news of Amazon-JPMorgan-Berkshire deal","url":"https://beckershospitalreview.com/finance/healthcare-stocks-lost-69b-on-news-of-amazon-jpmorgan-berkshire-hathaway-deal.html"}]},{"id":"ind-2018-trade-war","date":"2018-03-01","end_date":"2018-12-24","sector":"industrials","subindustries":["machinery","industrial_distribution","transportation","commercial_aerospace","building_products_construction"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Section 232/301 tariffs: industrials become the trade-war proxy","summary":"Steel and aluminum tariffs in March 2018 and escalating China tariffs made Boeing and Caterpillar the market's trade-war barometers; Boeing fell 6% premarket when China retaliated on April 4 and Caterpillar's record profits could not stop a 12% year-to-date slide by December. XLI lost 13.2% in 2018 versus 4.6% for the S&P 500, with United Rentals down 40% and EMCOR 27%.","evidence":"XLI -13.2% in 2018 vs SPY -4.6%; CAT -17.6%, URI -40.4%, EME -26.7% in 2018","sources":[{"title":"NBR: Trade tariff threats weigh on Wall Street industrials","url":"https://www.nbr.co.nz/trade-tariff-threats-weigh-on-wall-street-industrials"},{"title":"Engineering News: Caterpillar's record profit can't save it from trade-war carnage","url":"https://www.engineeringnews.co.za/article/caterpillars-record-profit-cant-save-it-from-trade-war-carnage-2018-06-20"},{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"}]},{"id":"materials-2018-steel-tariffs","date":"2018-03-08","end_date":"2018-12-31","sector":"materials","subindustries":["metals_mining","chemicals"],"direction":"mixed","magnitude":"major","driver_type":"policy","title":"Section 232 steel and aluminum tariffs and the start of the trade war","summary":"Trump announced 25% steel and 10% aluminum tariffs on 1 March 2018 and signed the order on 8 March; on 22 March he directed Section 301 tariffs on about $50 billion of Chinese goods and the Dow fell 724 points (2.9%). Domestic steelmakers initially benefited, but the broader materials sector returned -14.7% in 2018 against -4.4% for the S&P 500 as global growth and Chinese demand expectations weakened.","evidence":"Section 232 order signed 2018-03-08 (25% steel, 10% aluminum); S&P 500 Materials 2018 return -14.7% vs S&P 500 -4.4%.","sources":[{"title":"Tariffs in the first Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_first_Trump_administration"},{"title":"China-United States trade war (Wikipedia)","url":"https://en.wikipedia.org/wiki/China%E2%80%93United_States_trade_war"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"financials-2018-s2155-dereg","date":"2018-05-24","end_date":null,"sector":"financials","subindustries":["banks"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Dodd-Frank rollback raises the SIFI threshold to $250 billion","summary":"The Economic Growth, Regulatory Relief and Consumer Protection Act, signed 24 May 2018, lifted the enhanced-supervision threshold from $50 billion to $250 billion of assets, exempted banks under $10 billion from the Volcker Rule and cut stress-test frequency for mid-sized banks. It was the regulatory payoff of the 2016 bank rally, although the relief later drew blame after Silicon Valley Bank, whose CEO had lobbied for the law, failed in 2023.","evidence":"Act signed 2018-05-24; SIFI threshold raised from $50 billion to $250 billion in assets.","sources":[{"title":"Economic Growth, Regulatory Relief, and Consumer Protection Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Economic_Growth,_Regulatory_Relief,_and_Consumer_Protection_Act"}]},{"id":"memory-2018-supercycle-peak","date":"2018-06-01","end_date":"2018-12-26","sector":"technology","subindustries":["memory"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"The 2016-18 DRAM supercycle peaks: Micron -56% from its June 2018 high","summary":"Two years of DRAM and NAND price inflation driven by cloud over-ordering took Micron from under $10 in 2016 to an intraday high of $64.66 in June 2018. Hyperscalers then worked down inventory through 2018, Micron guided below expectations on September 20, 2018, and the stock fell 56% to $28.39 by December 26 (down 22.8% for the calendar year). Fiscal 2019 revenue fell 23% to $23.4bn, yet the shares rose 69% in 2019 as the market looked through the trough, the classic memory-cycle pattern.","evidence":"Micron fell 56% from its 2018 high to $28.39 on 2018-12-26; weak fiscal Q1 guidance on 2018-09-20.","sources":[{"title":"Wall Street analysts are worried about a memory chip downturn as Micron shares keep falling (CNBC)","url":"https://www.cnbc.com/2018/09/21/wall-street-is-worried-about-a-memory-chip-downturn-as-micron-shares-keep-falling.html"},{"title":"Why Micron Technology stock fell 22.8% in 2018 (Motley Fool)","url":"https://www.fool.com/investing/2019/01/14/why-micron-technology-stock-fell-228-in-2018.aspx"},{"title":"Why it's (kind of) different this time for Micron stock (Motley Fool, 2020)","url":"https://www.fool.com/investing/2020/01/16/why-its-kind-of-different-this-time-for-micron-sto.aspx"}]},{"id":"media-2018-att-time-warner-approved","date":"2018-06-12","end_date":"2018-06-14","sector":"communication_media","subindustries":["media_entertainment","telecom"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Judge Leon clears AT&T-Time Warner without conditions; the media bidding war begins","summary":"On June 12, 2018 Judge Richard Leon rejected the Justice Department's challenge and approved AT&T's $85bn acquisition of Time Warner with no conditions. Time Warner rose about 5% after hours, AT&T slipped, Discovery gained 3.7%, and the next day Comcast launched a $65bn all-cash bid for Fox's entertainment assets, which Disney topped at $71.3bn on June 20. The ruling unleashed the 2018-19 media consolidation wave and loaded AT&T with debt that led to the 2022 WarnerMedia spin-off.","evidence":"Time Warner +~5% after hours on 2018-06-12; Comcast's $65bn Fox bid followed on 2018-06-13.","sources":[{"title":"U.S. judge approves AT&T's $85 billion merger with Time Warner (NPR)","url":"https://www.npr.org/2018/06/12/614092532/u-s-judge-approves-at-ts-85-billion-merger-with-time-warner"},{"title":"Time Warner shares shoot higher after judge rules in favor of merger with AT&T; other media stocks gain (CNBC)","url":"https://www.cnbc.com/2018/06/12/time-warner-shares-shoot-higher-after-judge-rules-in-favor-of-merger-with-att.html"},{"title":"Time Warner stock jumps, AT&T falls after ruling clears path to merger (Variety)","url":"https://variety.com/2018/biz/news/att-time-warner-stocks-doj-antitrust-ruling-1202843216/"}]},{"id":"internet-2018-facebook-growth-shock","date":"2018-07-26","end_date":null,"sector":"technology","subindustries":["internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Facebook loses $119 billion in a day on slowing growth","summary":"After the Cambridge Analytica revelations of 17 March 2018 had already knocked about 24% ($134 billion) off the stock by 26 March, Facebook's 25 July 2018 guidance for slowing revenue growth and higher costs erased over $119 billion of market value on 26 July, then the largest one-day loss for any US company. The episode introduced regulatory and privacy risk into platform valuations just before the sector's September 2018 reclassification.","evidence":"Over $119 billion wiped off Facebook's market capitalisation on 2018-07-26 after a growth warning.","sources":[{"title":"Facebook-Cambridge Analytica data scandal (Wikipedia)","url":"https://en.wikipedia.org/wiki/Facebook%E2%80%93Cambridge_Analytica_data_scandal"}]},{"id":"media-2018-gics-communication-services","date":"2018-09-28","end_date":null,"sector":"communication_media","subindustries":["media_entertainment","telecom","internet_platforms"],"direction":"mixed","magnitude":"major","driver_type":"regulatory","title":"GICS creates Communication Services: Alphabet, Facebook, Netflix leave tech and discretionary","summary":"S&P Dow Jones Indices and MSCI, in a change announced 11 January 2018 and implemented after the close on 28 September 2018, renamed Telecommunication Services as Communication Services and moved Alphabet and Facebook out of Information Technology and Netflix and Comcast out of Consumer Discretionary. About 23 S&P 500 companies and roughly 10% of index market cap changed sector, forcing sector-ETF rebalancing (XLK lost Alphabet and Facebook) and turning a 2% bond-proxy telecom sector into a 10% growth sector.","evidence":"Changes effective after the close on 2018-09-28; Lipper estimated 23 S&P 500 companies and roughly 10% of index market cap reclassified.","sources":[{"title":"S&P Dow Jones Indices and MSCI announce companies changing under the 2018 GICS revisions","url":"https://press.spglobal.com/2018-01-11-S-P-Dow-Jones-Indices-And-MSCI-Announce-Select-List-Of-Companies-Changing-Due-To-Revisions-To-The-GICS-R-Structure-In-2018"},{"title":"Major sector changes are coming to the S&P 500 (Lipper Alpha)","url":"https://lipperalpha.refinitiv.com/2018/09/earnings-roundup-major-sector-changes-are-coming-to-the-sp-500"},{"title":"A massive shift in stock sector classifications starts today (ThinkAdvisor)","url":"https://thinkadvisor.com/2018/09/24/a-massive-shift-in-stock-sector-classifications-st"}]},{"id":"tech-2018-q4-selloff","date":"2018-10-03","end_date":"2018-12-24","sector":"technology","subindustries":["apple","semiconductors","internet_platforms","hardware","application_software"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Q4 2018 selloff: Fed hikes, trade war and Apple's December-quarter slump","summary":"The Nasdaq fell 17.5% and the S&P 500 13.97% in Q4 2018 as the Fed hiked a fourth time on 19 December to 2.25-2.5% and US-China trade talks stalled; the Dow and S&P posted their worst December since 1931 and the Nasdaq 100 entered a bear market on 21 December. Apple fell more than 31% in the December quarter ahead of its January 2019 China revenue warning, and semiconductors led the decline. Technology still finished 2018 at -0.3% versus -4.4% for the index.","evidence":"Nasdaq Composite -17.5% in Q4 2018; S&P 500 -13.97%; Apple down more than 31% in the December quarter.","sources":[{"title":"US stocks post worst year in a decade (CNBC, 2018-12-31)","url":"https://www.cnbc.com/amp/2018/12/31/stock-market-wall-street-stocks-eye-us-china-trade-talks.html"},{"title":"Dow, S&P 500 post worst December since 1931 (Fox Business)","url":"https://www.foxbusiness.com/markets/dow-sp-500-having-worst-month-since-1931-as-grinch-hits-wall-st"},{"title":"FOMC statement, 19 December 2018","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20181219a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"semis-2018-q4-bottom","date":"2018-12-26","end_date":"2019-12-31","sector":"technology","subindustries":["semiconductors"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Semiconductor bottom of December 2018: Nvidia's crypto glut, then a 60% SOX year","summary":"The SOX fell about 25% from October to late December 2018 (-15.5% in Q4) as the trade war, Fed hikes and a crypto-mining inventory glut hit the group; Nvidia lost 54% in Q4 alone and Micron bottomed at $28.39 on December 26. The index put in its low in the last week of December and then returned 60.1% in 2019, more than 20% of it in Q1, as the Fed pivoted and inventories cleared. The episode set the template later used in 2022: semis bottom on inventory capitulation, roughly two quarters before fundamentals.","evidence":"PHLX Semiconductor index Q4 2018 return -15.48% and 2019 return +60.12% (Nasdaq index fact sheet).","sources":[{"title":"PHLX Semiconductor Sector Index fact sheet (Nasdaq)","url":"https://indexes.nasdaqomx.com/docs/FS_SOX.pdf"},{"title":"Chip stocks are bleeding today: the 2018 and 2022 selloffs tell you what comes next (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/05/12/chip-stocks-are-bleeding-today-the-2018-and-2022-selloffs-tell-you-exactly-what-comes-next/"},{"title":"Why Micron Technology stock fell 22.8% in 2018 (Motley Fool)","url":"https://www.fool.com/investing/2019/01/14/why-micron-technology-stock-fell-228-in-2018.aspx"}]},{"id":"biotech-2019-bms-celgene","date":"2019-01-03","end_date":null,"sector":"healthcare","subindustries":["biotech_large","pharma"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"Bristol-Myers buys Celgene for $74bn: big pharma becomes biotech's bid in 2019","summary":"On January 3, 2019 Bristol-Myers Squibb agreed to buy Celgene for one BMY share plus $50 in cash and a CVR per share, about $74bn and then the largest pharma deal ever, funded with roughly $32bn of new debt. Bristol fell about 12% to $45.55 while Celgene rose 25-28%, and the deal lifted other depressed large biotechs (Gilead, Biogen) on the read-through that patent-cliff pharma would pay for pipelines; AbbVie-Allergan ($63bn) followed in June. It set the tone for the 2019 recovery in IBB after the Q4 2018 selloff.","evidence":"Celgene holders received 1 BMY share plus $50 cash per share; BMY -12% to $45.55 on 2019-01-03.","sources":[{"title":"Bristol-Myers Squibb shares fall on $74 billion Celgene acquisition (CNBC)","url":"https://www.cnbc.com/2019/01/03/bristol-myers-squibb-shares-fall-on-74-billion-celgene-acquisition.html"},{"title":"Bristol-Myers to buy Celgene in a $74 billion deal; Celgene shares surge (CNBC)","url":"https://www.cnbc.com/2019/01/03/bristol-myers-to-buy-celgene-in-a-74-billion-deal.html"},{"title":"Bristol-Myers to buy Celgene in $74 billion cancer-drug bet (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2019-01-03/bristol-myers-squibb-to-buy-celgene-in-74-billion-pharma-deal"}]},{"id":"re-2019-fed-pivot-rally","date":"2019-01-04","end_date":"2019-12-31","sector":"real_estate","subindustries":["office_reits","residential_reits","healthcare_reits","mortgage_reits","industrial_logistics_reits"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Powell pivot: REITs return 28.7% in 2019","summary":"After a -4% 2018 driven by the 10-year reaching 3.2%, the Fed's January 2019 pivot and three cuts pulled yields to 1.9% and REITs returned 28.7%, nearly matching the S&P 500 with half the volatility. Office (+31.4%), residential (+30.9%, manufactured homes +49%), health care (+21.2%) and mortgage REITs (+21.3%) all re-rated; REITs raised a record $113bn of capital.","evidence":"All Equity REITs +28.66% in 2019; Office +31.42%, Residential +30.89%, Health Care +21.20%, Mortgage REITs +21.33%","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2020 (2019 sector returns)","url":"https://www.reit.com/sites/default/files/2021-01/MediaFactSheet_Dec-2020.pdf"},{"title":"Nareit annual index values and returns","url":"https://www.reit.com/data-research/reit-market-data/report/annual-index-values-returns"}]},{"id":"utilities-2019-pge-bankruptcy","date":"2019-01-14","end_date":"2020-07-01","sector":"utilities","subindustries":["regulated_utilities"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"PG&E collapses on Camp Fire liabilities and files Chapter 11","summary":"PG&E shares fell 60% between the day before the 8 November 2018 Camp Fire and 7 January 2019, then dropped 52% to $8.38 on 14 January 2019 when the company said it would file for Chapter 11 (filed 29 January) facing at least $30 billion of wildfire liabilities. The bankruptcy introduced wildfire liability as a structural discount for Western utilities and reshaped how investors price inverse condemnation risk; PG&E emerged on 1 July 2020.","evidence":"PG&E closed down 52% at $8.38 on 2019-01-14; potential wildfire liabilities of at least $30 billion.","sources":[{"title":"PG&E stock craters as utility faces bankruptcy (CNBC, 2019-01-14)","url":"https://www.cnbc.com/2019/01/14/pge-stock-craters-as-beleaguered-utility-faces-bankruptcy.html"},{"title":"PG&E shares are hammered as potential liabilities mount (KTVU)","url":"https://www.ktvu.com/news/pge-shares-are-hammered-as-potential-liabilities-mount"},{"title":"Pacific Gas and Electric Company (Wikipedia)","url":"https://en.wikipedia.org/wiki/Pacific_Gas_and_Electric_Company"}]},{"id":"cs-2019-kraft-heinz-writedown","date":"2019-02-22","end_date":null,"sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Kraft Heinz's $15.4 billion writedown and SEC subpoena","summary":"Kraft Heinz disclosed a $15.4 billion impairment of the Kraft and Oscar Mayer brands, a $12.6 billion quarterly loss, a dividend cut and an SEC subpoena over procurement accounting; the stock fell as much as 28% to $34.90, a record low, on February 22 2019 and Berkshire took a multi-billion mark. The day discredited the 3G cost-cutting model for packaged food and began a six-year period in which the big food companies were valued as melting ice cubes (Kraft Heinz was down ~60% from the 2015 merger by 2025).","evidence":"KHC fell as much as 28% to $34.90 on 2019-02-22; $15.4B impairment, $12.6B Q4 net loss","sources":[{"title":"BNN Bloomberg: Kraft Heinz plunges to record low on $15.4B writedown","url":"https://www.bnnbloomberg.ca/kraft-heinz-plunges-to-record-low-on-us-15-4b-writedown-1.1218151"},{"title":"Reuters via Business Standard: Kraft Heinz forecasts gloomy 2019, writes down iconic brands","url":"https://www.business-standard.com/amp/article/reuters/kraft-heinz-forecasts-gloomy-2019-writes-down-value-of-iconic-brands-119022200165_1.html"}]},{"id":"ind-2019-737-max-grounding","date":"2019-03-10","end_date":"2020-11-18","sector":"industrials","subindustries":["commercial_aerospace"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Boeing 737 MAX grounded after second crash","summary":"The Ethiopian Airlines crash on March 10, 2019 led regulators worldwide to ground the 737 MAX; Boeing fell 11% in two days, its biggest two-day drop in a decade, wiping ~$16bn of market value, and production was halted in January 2020. The 20-month grounding, then COVID, turned the sector's growth engine into its biggest drag and pushed Spirit AeroSystems and other MAX suppliers down with it.","evidence":"BA -11% over Mar 11-12, 2019 (biggest two-day drop in a decade); BA +3.3% in 2019 vs SPY +31.2%","sources":[{"title":"Fortune: Boeing stock tumbles after 737 MAX grounding","url":"https://fortune.com/2019/03/12/boeing-stock-tumbles-737-max"},{"title":"ChartRow BA calendar-year returns","url":"https://chartrow.com/quote/ba/returns"}]},{"id":"hc-2019-medicare-for-all","date":"2019-04-15","end_date":"2019-04-18","sector":"healthcare","subindustries":["managed_care","healthcare_facilities_services"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Medicare for All scare: $150B wiped from health care in four days","summary":"With Sanders' Medicare for All bill gaining Democratic co-sponsors, UnitedHealth's CEO used the April 16 earnings call to warn the plan would 'destabilize' the system, which only amplified fears. S&P 500 health care lost about $150 billion between April 15 and April 18, the managed-care index fell 4% on the Thursday to its lowest since January, and HCA had its worst day since the 2016 election. The episode made 'political beta' the dominant factor for insurers through the 2020 primaries.","evidence":"S&P 500 Health Care Index companies lost ~$150B of market value from 2019-04-15 to 2019-04-18 (Becker's)","sources":[{"title":"Becker's: Healthcare stocks take $150B beating over 4 days","url":"https://www.beckershospitalreview.com/finance/healthcare-stocks-take-150b-beating-over-4-days.html"},{"title":"Axios: Wall Street is still freaking out over health care stocks","url":"https://www.axios.com/2019/04/22/health-care-stocks-medicare-for-all"},{"title":"Bloomberg: HCA sinks most since post-Trump election sell-off","url":"https://www.bloombergquint.com/onweb/hca-healthcare-stuns-street-with-worst-plunge-since-16-election"}]},{"id":"semis-2019-huawei-entity-list","date":"2019-05-15","end_date":"2019-06-29","sector":"technology","subindustries":["semiconductors","semicap","hardware","telecom"],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"Huawei entity listing hits semiconductors","summary":"On 15 May 2019 Trump declared a national emergency over threats to US technology and Commerce added Huawei to the Entity List, cutting off a customer worth 13% of Micron's sales and about 10% for Skyworks and Qorvo; Micron fell 11.4% between 3 and 15 May and the Philadelphia semiconductor index's May decline reached about 14%, after tariffs on $200 billion of Chinese goods had been raised to 25% on 10 May. The G20 truce on 29 June and the Fed's July pivot reversed the move, and semiconductors led the market for the rest of 2019.","evidence":"Micron -11.4% from 2019-05-03 to 2019-05-15 with 13% of sales from Huawei; Philadelphia semiconductor index down about 14% in May 2019.","sources":[{"title":"Trump's latest tough trade action could hit already struggling chip stocks (CNBC, 2019-05-16)","url":"https://www.cnbc.com/2019/05/16/trumps-latest-tough-trade-action-could-hit-already-struggling-chip-stocks.html"},{"title":"Chip stock rout worsens with Qualcomm's latest blast of bad news (Bloomberg via BQ)","url":"https://www.bloombergquint.com/business/chip-stock-rout-worsens-with-qualcomm-s-latest-blast-of-bad-news"},{"title":"Trump's Huawei ban takes its toll on US semiconductor shares (BusinessLive)","url":"https://www.businesslive.co.za/bd/companies/telecoms-and-technology/2019-05-21-trumps-huawei-ban-takes-its-toll-on-us-semiconductor-shares/"}]},{"id":"tech-2019-fed-pivot-rally","date":"2019-07-31","end_date":"2019-12-31","sector":"technology","subindustries":["semiconductors","apple","application_software","internet_platforms","hardware"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Fed pivot: technology returns 50% in 2019","summary":"After the December 2018 hike, the Fed reversed course, cutting 25 bp to 2-2.25% on 31 July 2019 (the first of three cuts) and ending balance-sheet runoff early. Falling discount rates and the Phase One trade truce, signed 15 January 2020, drove the S&P 500 IT sector to a 50.3% return in 2019, the best sector against 31.5% for the index, with semiconductors and Apple leading and multiple expansion doing most of the work.","evidence":"FOMC cut to 2-2.25% on 2019-07-31; S&P 500 Information Technology 2019 total return +50.3% vs S&P 500 +31.5%.","sources":[{"title":"FOMC statement, 31 July 2019","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20190731a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"China-United States trade war (Wikipedia)","url":"https://en.wikipedia.org/wiki/China%E2%80%93United_States_trade_war"}]},{"id":"cd-2019-list4-tariffs","date":"2019-08-01","end_date":"2020-01-15","sector":"consumer_discretionary","subindustries":["apparel_luxury","specialty_retail"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Trade-war List 4 tariffs reach apparel, footwear and consumer goods","summary":"Having raised tariffs on $200 billion of Chinese goods to 25% in May 2019, Trump announced on August 1 a 10% tariff on the remaining $300 billion; 15% took effect on about $112 billion on September 1 2019, bringing more than two-thirds of Chinese consumer goods under tariff, with a second tranche delayed past Christmas and then cancelled by the December 13 Phase One deal (signed January 15 2020). Apparel and footwear brands sourcing from China led the summer-2019 sell-offs and accelerated moves to Vietnam, the exposure that would hurt them in 2025.","evidence":"15% tariff on ~$112B of Chinese imports effective 2019-09-01; Phase One deal signed 2020-01-15","sources":[{"title":"Wikipedia: China-United States trade war","url":"https://en.wikipedia.org/wiki/China%E2%80%93United_States_trade_war"}]},{"id":"energy-2019-abqaiq-attack","date":"2019-09-16","end_date":null,"sector":"energy","subindustries":["exploration_production","integrated","oilfield_services"],"direction":"in","magnitude":"moderate","driver_type":"geopolitical","title":"Abqaiq-Khurais attack removes 5.7m b/d: oil's largest one-day jump in a decade, faded within weeks","summary":"Drone and missile strikes on September 14, 2019 knocked out 5.7m b/d of Saudi output, about 5% of world supply and the largest gross supply loss on record. Brent rose about 15% on September 16, its biggest single-day increase in a decade (nearly 20% at the open), and U.S. energy stocks jumped while the broad market fell. Saudi Arabia restored output by the end of the month and crude gave back the entire spike within two weeks, a demonstration of how little geopolitical premium the market would hold with shale growing and energy at a record-low index weight.","evidence":"Attack removed 5.7m b/d of Saudi production; Brent and WTI posted their largest single-day gains in a decade on 2019-09-16 (EIA).","sources":[{"title":"Saudi Arabia crude oil production outage affects global crude oil and gasoline prices (EIA)","url":"https://www.eia.gov/todayinenergy/detail.php?id=41413"},{"title":"Aramco attack: worst disruption ever sends oil prices soaring (Al Jazeera)","url":"https://www.aljazeera.com/economy/2019/9/16/aramco-attack-worst-disruption-ever-sends-oil-prices-soaring"},{"title":"Oil prices jump by 20% after weekend attacks on Saudi facility (ABC News)","url":"https://abcnews.com/International/oil-prices-jump-20-weekend-attacks-saudi-facility/story?id=65640002"}]},{"id":"distributors-2019-opioid-ohio-settlement","date":"2019-10-21","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Drug distributors settle the Ohio opioid bellwether for $260m hours before trial","summary":"McKesson, Cardinal Health and AmerisourceBergen agreed to pay a combined $215m, and Teva $20m in cash plus Suboxone, to Cuyahoga and Summit counties on the morning the first federal opioid trial was due to start. The deal removed a near-term binary that had weighed on distributor multiples through 2018-19 and signalled that a global settlement framework was achievable. Walgreens did not settle and remained a defendant.","evidence":"Three distributors to pay $215m combined to the two Ohio counties, announced 2019-10-21.","sources":[{"title":"Companies reach $260 million deal to settle opioids lawsuit (Marketplace)","url":"https://www.marketplace.org/story/2019/10/21/ohio-opioid-lawsuit-settlement"},{"title":"4 drug companies agree to $260M opioid settlement with 2 Ohio counties (ABA Journal)","url":"https://www.abajournal.com/news/article/4-drug-companies-agree-to-260m-opioid-settlement-with-two-ohio-counties"}]},{"id":"media-2019-disney-plus-launch","date":"2019-11-12","end_date":"2020-12-10","sector":"communication_media","subindustries":["media_entertainment"],"direction":"in","magnitude":"moderate","driver_type":"tech_cycle","title":"Disney+ launches with 10 million day-one sign-ups","summary":"Disney+ launched on 12 November 2019 and reported more than 10 million sign-ups on day one, reaching 86.8 million subscribers by 10 December 2020. The launch validated the streaming pivot for legacy media and briefly re-rated Disney and peers as growth stocks, even as cord-cutting accelerated (MoffettNathanson called Q1 2019 the worst quarter ever for pay-TV losses) and set up the 2022 streaming-profitability reckoning.","evidence":"More than 10 million Disney+ sign-ups within the first day (2019-11-12); 86.8 million subscribers announced 2020-12-10.","sources":[{"title":"Disney+ (Wikipedia)","url":"https://en.wikipedia.org/wiki/Disney%2B"},{"title":"Cord-cutting (Wikipedia)","url":"https://en.wikipedia.org/wiki/Cord-cutting"}]},{"id":"tech-2020-covid-wfh-boom","date":"2020-02-19","end_date":"2020-12-31","sector":"technology","subindustries":["application_software","infrastructure_software_cyber","hardware","internet_platforms","apple","semiconductors","fintech_payments"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"COVID crash and the work-from-home boom","summary":"The Dow fell 12.93% on 16 March 2020 after the Fed's emergency cut to 0-0.25% and $700 billion of purchases on 15 March, but the pandemic then pulled capital into digital winners: Zoom was up about 580% year-to-date by November 2020, global PC demand rose about 13%, Apple became the first $2 trillion company on 19 August 2020, and the Nasdaq returned 43.6% for the year. S&P 500 technology returned 43.9% against 18.4% for the index while energy lost 33.7%.","evidence":"S&P 500 Information Technology 2020 total return +43.9% vs S&P 500 +18.4%; Nasdaq Composite 2020 +43.64%.","sources":[{"title":"FOMC statement, 15 March 2020","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20200315a.htm"},{"title":"2020 stock market crash (Wikipedia)","url":"https://en.wikipedia.org/wiki/2020_stock_market_crash"},{"title":"Zoom, Okta, DocuSign work-from-home stocks (Trefis, 2020-11-02)","url":"https://www.trefis.com/stock/work/articles/502247/zoom-okta-docusign-with-covid-cases-surging-should-you-revisit-work-from-home-stocks/2020-11-02"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"},{"title":"2020-2023 global chip shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2020%E2%80%932023_global_chip_shortage"}]},{"id":"ind-2020-covid-crash-travel","date":"2020-02-20","end_date":"2020-03-23","sector":"industrials","subindustries":["transportation","commercial_aerospace","professional_services"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"COVID lockdowns: airlines and aerospace crash, Buffett sells","summary":"Air travel collapsed 95% and the JETS airline ETF fell 59% between February 21 and March 23, 2020 versus 33% for SPY; United lost 49% in March alone and Berkshire sold its airline stakes. Boeing lost two-thirds of its value peak to trough as MAX and COVID combined, and staffing names fell on the unemployment spike before the CARES Act payroll support stabilized the group.","evidence":"JETS -59.1% from Feb 21 to Mar 23, 2020 vs SPY -32.7%; UAL -48.8% in March 2020","sources":[{"title":"ETF Strategy: Airline ETF assets surge as Buffett hits eject","url":"https://www.etfstrategy.com/airline-etf-jets-us-assets-surge-as-warren-buffett-berkshire-hathaway-hits-eject-button-48593"},{"title":"Motley Fool: Why shares of major airlines lost altitude in March 2020","url":"https://www.fool.com/investing/2020/04/02/why-shares-of-major-airlines-lost-altitude-in-marc.aspx"},{"title":"ChartRow BA calendar-year returns","url":"https://chartrow.com/quote/ba/returns"}]},{"id":"re-2020-covid-crash","date":"2020-02-20","end_date":"2020-11-06","sector":"real_estate","subindustries":["lodging_reits","mortgage_reits","retail_reits","office_reits","residential_reits","healthcare_reits","net_lease_specialty_reits"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"COVID: hotels, malls and mortgage REITs crash; dividends suspended","summary":"REITs lost 23.4% in Q1 2020 and mortgage REITs 56% as repo lenders issued margin calls (MFA faced ~$800m, Western Asset $116m on March 23; MFA fell from $7.64 to $0.32); Host Hotels suspended its dividend after April, lodging REITs were down 48% by August, malls fell 37% and EPR's theater tenants stopped paying. Full-year 2020: lodging -23.6%, retail -25.2% (malls -37.2%), office -18.4%, apartments -15.3% (urban exodus), health care -9.9% (senior-housing occupancy), free-standing net lease -10.5%.","evidence":"FTSE Nareit Mortgage REITs -56.1% in Q1 2020; Lodging/Resorts -47.7% YTD at Aug 31, 2020 and -23.6% for 2020; Regional Malls -37.2% in 2020","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2020","url":"https://www.reit.com/sites/default/files/2021-01/MediaFactSheet_Dec-2020.pdf"},{"title":"Western Asset Mortgage Capital 10-Q Q1 2020 (margin calls)","url":"https://www.sec.gov/Archives/edgar/data/1465885/000162828020007474/wmc-20200331.htm"},{"title":"Bisnow: Retail and hospitality REITs battered","url":"https://www.bisnow.com/news/national/capital-markets/retail-and-hospitality-reits-battered-but-other-classes-in-good-shape-105850"},{"title":"Host Hotels 10-K FY2020 (dividend suspension)","url":"https://www.sec.gov/Archives/edgar/data/1070750/000156459021008676/hst-10k_20201231.htm"}]},{"id":"cs-2020-pantry-loading","date":"2020-03-02","end_date":"2020-04-30","sector":"consumer_staples","subindustries":["food_beverage_tobacco","household_personal","staples_retail"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"COVID hoarding: Clorox, Campbell and the grocers become momentum stocks","summary":"Panic buying sent the S&P 500 packaged-food index up 4.7% on March 2 2020 (Campbell +6.3%, its biggest day in nine months), Clorox rose 7.9% in a day, the most since 2011, and was up about 20% over the month, and Kroger was up 15% year-to-date on March 18 while the S&P 500 was down 26%. Staples retail (Walmart, Costco, Kroger) and cleaning/food names led the market through the March crash and only gave up leadership when the reopening trade began in November.","evidence":"S&P 500 packaged-food index +4.7% and CPB +6.3% on 2020-03-02; KR +15% YTD vs S&P 500 -26% on 2020-03-18","sources":[{"title":"Bloomberg: Panic buying spurs investors to stock up on packaged food shares","url":"https://www.bloomberg.com/news/articles/2020-03-02/panic-buying-spurs-investors-to-stock-up-on-packaged-food-shares"},{"title":"Motley Fool: These 3 stocks have crushed the coronavirus (Clorox)","url":"https://www.fool.com/investing/2020/03/18/these-3-stocks-have-crushed-the-coronavirus.aspx"},{"title":"Motley Fool: Kroger is hiring to meet high coronavirus demand","url":"https://www.fool.com/investing/2020/03/18/kroger-is-hiring-to-meet-high-coronavirus-demand.aspx"}]},{"id":"en-2020-covid-negative-oil","date":"2020-03-06","end_date":"2020-08-31","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services","refining","midstream"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"COVID demand collapse and negative WTI; Exxon leaves the Dow","summary":"The OPEC+ breakdown on March 6, 2020 and lockdowns pushed the energy sector down about 50% in Q1; on April 20 the May WTI contract settled at -$37.63, the first negative oil price in history, and on August 24 Exxon was removed from the Dow after 92 years with energy at ~2.4% of the S&P 500. XLE lost 32.7% in 2020, XOP 36%, OIH 41%, AMLP 32% and Valero 36%, and several shale producers (Whiting, Chesapeake) went bankrupt.","evidence":"May 2020 WTI contract settled at -$37.63 on Apr 20, 2020; energy sector -~50% in Q1 2020; XLE -32.7% in 2020 vs SPY +18.3%","sources":[{"title":"Convextrade daily recap Apr 20, 2020: WTI crude goes negative","url":"https://convextrade.com/recap/daily/2020-04-20"},{"title":"LPL: What happened to oil","url":"https://qa65.lpl.com/news-media/research-insights/weekly-market-commentary/what-happened-to-oil.html"},{"title":"CNBC: Exxon Mobil replaced by a software stock after 92 years in the Dow","url":"https://www.cnbc.com/2020/08/25/exxon-mobil-replaced-by-a-software-stock-after-92-years-in-the-dow-is-a-sign-of-the-times.html"},{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"}]},{"id":"cd-2020-cruise-collapse","date":"2020-03-09","end_date":"2020-04-02","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"COVID sinks cruise lines, hotels, casinos and restaurants","summary":"After the State Department told Americans to avoid ship travel, Norwegian fell 26.7% and Royal Caribbean 25.8% on March 9 2020; by March 11 Carnival was down about 60% year-to-date, Royal Caribbean 67% and Norwegian 75%, and the three lost about $54 billion (70%) of value in under two months while the S&P 500 fell roughly 30%. Norwegian lost 70.6% in March alone. Hotels, casinos, theme parks and full-service restaurants suffered similar drawdowns and the whole group had to raise rescue capital.","evidence":"NCLH -26.7% and RCL -25.8% on 2020-03-09; CCL/RCL/NCLH lost ~$54B (70%) of market value in under two months","sources":[{"title":"Cruise Industry News: Black Monday for cruise line stocks","url":"https://cruiseindustrynews.com/cruise-news/2020/03/black-monday-for-cruise-line-stocks"},{"title":"CNN live blog, March 11 2020","url":"https://amp.cnn.com/cnn/business/live-news/stock-market-news-today-031120/index.html"},{"title":"Motley Fool: Why Norwegian Cruise Line plummeted 70.6% in March","url":"https://www.fool.com/investing/2020/04/02/why-norwegian-cruise-lines-plummeted-706-in-march.aspx"}]},{"id":"ind-2020-waste-commercial-volume-hit","date":"2020-03-16","end_date":"2020-12-31","sector":"industrials","subindustries":["waste"],"direction":"mixed","magnitude":"minor","driver_type":"pandemic","title":"Lockdowns cut commercial waste volumes; haulers lag the 2020 rebound","summary":"Business closures cut commercial and industrial collection volumes in Q2 2020 while residential volumes rose, so the haulers' defensive reputation held in the March crash but they lagged the recovery: Waste Management returned 5.5% in 2020 against 10.9% for XLI and 18.3% for the S&P 500. Pricing power and landfill scarcity kept estimates stable, and the group resumed outperforming in 2021 (WM +43.8%).","evidence":"WM +5.5% in 2020 vs XLI +10.9% and SPY +18.3%; WM +43.8% in 2021","sources":[{"title":"ChartRow WM calendar-year returns","url":"https://chartrow.com/quote/wm/returns"},{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"}]},{"id":"hc-2020-covid-tools-boom","date":"2020-03-16","end_date":"2021-12-31","sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"COVID testing and vaccine manufacturing supercharge life-science tools","summary":"Thermo Fisher won FDA emergency authorisation for a SARS-CoV-2 PCR test in March 2020, built out testing-supply capacity and signed mRNA vaccine manufacturing deals with Pfizer and Moderna; Danaher, Bio-Rad and the bioprocessing suppliers saw similar demand. The group re-rated as 'growth plus defensiveness', and Thermo used its windfall to buy the CRO PPD for $17.4 billion in April 2021. Exact 2020 COVID revenue figures were not retrievable from the sources used; the direction and scale are qualitative here.","evidence":"Thermo Fisher agreed to acquire PPD for $17.4B cash plus ~$3.5B net debt (April 2021), funded by pandemic-era cash generation","sources":[{"title":"Wikipedia: Thermo Fisher Scientific (COVID-19 response, PPD acquisition)","url":"https://en.wikipedia.org/wiki/Thermo_Fisher_Scientific"}]},{"id":"hc-2020-telehealth-boom","date":"2020-03-16","end_date":"2021-02-16","sector":"healthcare","subindustries":["healthcare_technology"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"Telehealth boom: Teladoc triples and buys Livongo","summary":"Lockdowns made virtual care the default and Teladoc's shares ran from about $83 at the start of 2020 to $294 by mid-February 2021, a 3.5x gain against a roughly 20% S&P 500 rise. Teladoc paid $18.5 billion in cash and stock for Livongo in October 2020 at the peak of the enthusiasm. Digital-health SPACs and IPOs (Hims, Oscar, Clover) followed in the same window.","evidence":"TDOC from ~$83 (2020-01) to $294 (2021-02); Livongo acquired for $18.5B (Oct 2020)","sources":[{"title":"IG: Where next for Teladoc shares after their 88% collapse?","url":"https://www.ig.com/en/news-and-trade-ideas/where-next-for-teladoc-shares-after-their-88--collapse--220502"}]},{"id":"cd-2020-travel-liquidity-crunch","date":"2020-03-17","end_date":"2020-06-30","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"Cruise lines, hotels and airlines scramble for cash","summary":"With revenue near zero, cruise lines, hotel owners and airlines drew down revolvers and raised emergency debt and equity in March-June 2020; S&P warned of downgrades for Carnival and Royal Caribbean on diminished demand and rising leverage, and the cruise operators were excluded from the US CARES Act because of their foreign domiciles. The dilution and leverage taken on in this window (Carnival, Norwegian and Royal Caribbean issued tens of billions of dollars of debt and equity) is why the group's share prices never regained 2019 levels even as 2023-2025 bookings hit records.","evidence":"S&P Global Ratings placed Carnival and Royal Caribbean on review for downgrade in March 2020 on diminished demand and rising leverage; hotels, airlines and cruise lines all raised emergency liquidity","sources":[{"title":"Fortune: Airlines, cruise ships, hotels race for cash in the coronavirus crisis","url":"https://fortune.com/2020/03/17/airlines-cruise-ships-hotels-cash-coronavirus-crisis/"},{"title":"Seatrade Cruise News: Cruise shares hammered after US says avoid ship travel","url":"https://www.seatrade-cruise.com/news/cruise-shares-hammered-after-us-says-avoid-ship-travel"}]},{"id":"hc-2020-covid-elective-halt","date":"2020-03-18","end_date":"2020-06-30","sector":"healthcare","subindustries":["medical_devices","healthcare_facilities_services"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"CMS tells hospitals to postpone elective surgery","summary":"On March 18 2020 CMS recommended that all elective surgeries and non-essential procedures be postponed to preserve PPE, beds and staff. Procedure-driven device makers (orthopaedics, surgical robotics, structural heart) and hospital operators lost their revenue base overnight and lagged the market through the spring, while diagnostics, PPE and ventilator names and telehealth rallied. Volumes recovered from the summer as deferred procedures returned.","evidence":"CMS recommendation to postpone all elective surgeries and non-essential medical, surgical and dental procedures, issued 2020-03-18","sources":[{"title":"CMS: Recommendations on adult elective surgeries (March 18 2020)","url":"https://www.cms.gov/newsroom/press-releases/cms-releases-recommendations-adult-elective-surgeries-non-essential-medical-surgical-and-dental"}]},{"id":"ind-2020-defense-esg-lag","date":"2020-03-23","end_date":"2021-12-31","sector":"industrials","subindustries":["defense"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Defense sits out the 2020-21 bull market","summary":"With budgets flat after the BBA boom, Afghanistan withdrawal looming and ESG mandates excluding weapons makers, defense primes missed the post-COVID rally entirely. ITA lost 14% in 2020 and gained only 9.4% in 2021 while the S&P 500 returned 18.3% and 28.7%; Lockheed was down in 2020 and flat in 2021, setting up the cheap valuations that the Ukraine invasion would re-rate.","evidence":"ITA -14.0% in 2020 and +9.4% in 2021 vs SPY +18.3% and +28.7%; LMT -6.5% (2020) and +3.2% (2021)","sources":[{"title":"ChartRow ITA calendar-year returns","url":"https://chartrow.com/quote/ita/returns"},{"title":"ChartRow LMT calendar-year returns","url":"https://chartrow.com/quote/lmt/returns"}]},{"id":"en-2020-clean-energy-mania","date":"2020-03-23","end_date":"2021-02-10","sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"major","driver_type":"policy","title":"2020 clean-energy mania: zero rates, ESG flows and the Biden election","summary":"Zero rates, record ESG fund inflows, falling solar costs and expectations of a Biden climate program produced the biggest clean-energy bubble on record: ICLN returned 142% in 2020, TAN 234% and Enphase 572%, with the peak in February 2021. Fossil-fuel energy meanwhile had its worst year, so the rotation between the two sub-sectors was the widest ever recorded.","evidence":"ICLN +141.8%, TAN +234.0%, ENPH +571.5% in 2020 vs XLE -32.7%","sources":[{"title":"ChartRow ICLN calendar-year returns","url":"https://chartrow.com/quote/icln/returns"},{"title":"ChartRow TAN calendar-year returns","url":"https://chartrow.com/quote/tan/returns"},{"title":"FlowBank: Top performing ETFs of 2020 sink in 2021","url":"https://www.flowbank.com/en/livewire/top-performing-etfs-of-2020-sink-in-2021"}]},{"id":"re-2020-digital-and-logistics-winners","date":"2020-03-23","end_date":"2020-12-31","sector":"real_estate","subindustries":["data_center_tower_reits","industrial_logistics_reits","self_storage_reits"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"Pandemic winners: data centers, warehouses and storage","summary":"Lockdowns accelerated e-commerce and cloud demand, so the digital REITs were the only groups to finish 2020 positive: data centers +21%, industrial +12.2% (Prologis +15%), self storage +12.9% (moving and home-office demand) and infrastructure/towers +7.3%, against -5.1% for all equity REITs. The dispersion between 'COVID winners' and hotels/malls was the widest in REIT history.","evidence":"Data Centers +21.0%, Industrial +12.17%, Self Storage +12.91% in 2020 vs All Equity REITs -5.12%","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2020","url":"https://www.reit.com/sites/default/files/2021-01/MediaFactSheet_Dec-2020.pdf"},{"title":"ChartRow EQIX calendar-year returns","url":"https://chartrow.com/quote/eqix/returns"}]},{"id":"hc-2020-2021-biotech-peak","date":"2020-03-23","end_date":"2021-02-08","sector":"healthcare","subindustries":["biotech_smid","healthcare_technology"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Zero rates and the SPAC/IPO window push XBI to a February 2021 record","summary":"Emergency rate cuts, a flood of retail and crossover capital and the mRNA halo drove SMID biotech to a record on February 8 2021, with the IPO calendar and SPAC mergers running at the fastest pace in the sector's history. The gain proved entirely cyclical: the subsequent 64% drawdown wiped out every dollar of the post-COVID rally by mid-2022, and XBI has not regained its 2021 high as of late 2026.","evidence":"XBI peak close 2021-02-08; the following drawdown erased all gains since the COVID low (Bloomberg)","sources":[{"title":"BNN Bloomberg: Biotech fund wipes out last of its gains since COVID started","url":"https://www.bnnbloomberg.ca/biotech-fund-wipes-out-last-of-its-gains-since-covid-started-1.1763436"},{"title":"Driehaus: XBI and M2","url":"https://www.driehaus.com/perspectives/XBI-and-M2"}]},{"id":"telecom-2020-tmobile-sprint-close","date":"2020-04-01","end_date":null,"sector":"technology","subindustries":["telecom"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"T-Mobile completes the Sprint merger","summary":"T-Mobile closed its acquisition of Sprint on 1 April 2020, consolidating the US wireless market to three national carriers and giving T-Mobile the mid-band spectrum that underpinned its 5G share gains. The consolidation improved pricing discipline for the carriers and later drove Verizon and AT&T into fiber and spectrum acquisitions to keep pace.","evidence":"Sprint became a T-Mobile US subsidiary on 2020-04-01; the Sprint brand was retired 2020-08-02.","sources":[{"title":"Sprint Corporation (Wikipedia)","url":"https://en.wikipedia.org/wiki/Sprint_Corporation"}]},{"id":"energy-2020-negative-wti-day","date":"2020-04-20","end_date":null,"sector":"energy","subindustries":["exploration_production","oilfield_services"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"WTI settles at -$37.63: S&P energy -3.7% on the day oil went negative","summary":"With Cushing storage nearly full a day before expiry, the May 2020 WTI contract settled at -$37.63 on April 20, 2020, the first negative price in the contract's history; the June contract stayed above $20. S&P 500 energy stocks fell 3.7% and XLE 3.6%, the sharpest sector loss of the session, while Halliburton reported a $1.1bn impairment the same morning. The print accelerated the shale bankruptcy wave (Whiting had filed April 1; Chesapeake followed in June) and the shift of E&Ps to capital-return models.","evidence":"May 2020 WTI futures settled at -$37.63 on 2020-04-20; S&P 500 energy sector -3.7%.","sources":[{"title":"Oil price goes negative as demand collapses; stocks dip (AP via News3LV)","url":"https://news3lv.com/amp/news/nation-world/oil-price-goes-negative-as-demand-collapses-stocks-dip-04-20-2020-195435591"},{"title":"Energy sector update for 04/20/2020 (MT Newswires via Nasdaq)","url":"https://www.nasdaq.com/articles/energy-sector-update-for-04-20-2020:-bambam-a.totopshalchk-2020-04-20"},{"title":"Halliburton books $1.1 billion charge in low price outlook (CNBC)","url":"https://www.cnbc.com/2020/04/20/halliburton-hal-earnings-q1-2020.html"}]},{"id":"cd-2020-retail-bankruptcies","date":"2020-05-04","end_date":"2020-08-03","sector":"consumer_discretionary","subindustries":["apparel_luxury","specialty_retail"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"Lockdowns trigger a wave of apparel and department-store bankruptcies","summary":"US retail sales fell a record 16.4% in April 2020 and the weakest apparel names failed in quick succession: J.Crew (May 4), Neiman Marcus (May 7), JCPenney (May 15) and Brooks Brothers (July 8), with 43 retailer bankruptcies counted by August 3 and Coresight projecting up to 25,000 store closures. Capital fled mall apparel and department stores for e-commerce and home categories; the survivors (Nike, Lululemon, off-price) emerged with share gains in 2021.","evidence":"US retail sales -16.4% in April 2020 (record); 43 US retailer bankruptcies by 2020-08-03","sources":[{"title":"Wikipedia: Impact of the COVID-19 pandemic on retail","url":"https://en.wikipedia.org/wiki/Impact_of_the_COVID-19_pandemic_on_retail"}]},{"id":"cd-2020-home-improvement-boom","date":"2020-05-19","end_date":"2021-02-24","sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"Nesting and stimulus drive a home-improvement and housing boom","summary":"Stuck at home with stimulus checks and sub-3% mortgages, consumers poured money into DIY and housing: Home Depot's Q2 2020 sales rose a record 23.4%, Lowe's Q4 US comps rose 28.6%, and over the following year Lowe's stock gained more than 65% and Home Depot 29%. Builders rallied to records on the suburban migration, and the sub-industry became the pandemic's biggest 'goods' winner alongside e-commerce.","evidence":"HD Q2 2020 sales +23.4% (record); LOW stock +65% over the year to early 2021 vs HD +29%","sources":[{"title":"CNBC: Home Depot and Lowe's earnings boosted by pandemic-induced nesting","url":"https://www.cnbc.com/2020/11/20/home-depot-and-lowes-earnings-boosted-by-pandemic-induced-nesting.html"},{"title":"Axios: Lowe's CEO, the quest for the top spot continues","url":"https://www.axios.com/local/charlotte/2021/03/08/lowes-ceo-the-quest-for-the-top-spot-continues-250108"}]},{"id":"financials-2020-covid-dividend-caps","date":"2020-06-25","end_date":"2020-12-31","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"major","driver_type":"pandemic","title":"Fed caps bank dividends and bars buybacks after COVID stress scenarios","summary":"On 25 June 2020 the Fed published stress results with pandemic sensitivity scenarios projecting $560-700 billion of loan losses across 34 banks, barred share repurchases and capped dividends at Q2 levels for the third quarter. With rates at zero flattening the curve, financials returned -1.7% in 2020 against +18.4% for the S&P 500, their worst relative year since 2011, before the vaccine and reflation trade reversed the gap in 2021.","evidence":"Fed, 2020-06-25: projected loan losses of $560-700 billion; buybacks suspended and dividends capped for Q3 2020; Financials 2020 return -1.7%.","sources":[{"title":"Federal Reserve stress test results and capital distribution restrictions, 25 June 2020","url":"https://www.federalreserve.gov/newsevents/pressreleases/bcreg20200625c.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"ind-2021-reopening-capex-boom","date":"2020-11-09","end_date":"2021-12-31","sector":"industrials","subindustries":["machinery","industrial_distribution","transportation","professional_services","building_products_construction"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Vaccine rotation and the 2021 goods boom","summary":"Pfizer's vaccine news on November 9, 2020 started a rotation into reopening cyclicals, and 2021's inventory restocking, record freight rates and labor shortage produced a broad industrial earnings surge. Old Dominion returned 85% in 2021, Robert Half 81%, United Rentals 43% and ADP 43%, with XLI up 21.1%; farm income headed to a 2022 record and Deere rallied 29%.","evidence":"ODFL +84.7%, RHI +81.3%, URI +43.3%, ADP +42.6% in 2021; XLI +21.1%","sources":[{"title":"ChartRow ODFL calendar-year returns","url":"https://chartrow.com/quote/odfl/returns"},{"title":"ChartRow RHI calendar-year returns","url":"https://chartrow.com/quote/rhi/returns"},{"title":"United Rentals 2021 Annual Report","url":"https://s21.q4cdn.com/336331232/files/doc_financials/2021/ar/United-Rentals-Inc.-2021-Annual-Report.pdf"}]},{"id":"en-2021-energy-reopening-rebound","date":"2020-11-09","end_date":"2021-12-31","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services","refining","midstream"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Vaccine rotation and capital discipline: energy's 2021 comeback","summary":"From the November 2020 vaccine news, reopening demand and the new shale model of flat volumes, buybacks and variable dividends produced the best energy year since 2005: XLE returned 53.3% in 2021, XOP 66.7%, AMLP 39%, SLB 40%, Exxon 58% and Cheniere 70%, versus 28.7% for the S&P 500. Free cash flow replaced growth as the sector's investment case.","evidence":"XLE +53.3%, XOP +66.7%, AMLP +39.1%, XOM +57.6% in 2021 vs SPY +28.7%","sources":[{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"},{"title":"ChartRow AMLP calendar-year returns","url":"https://chartrow.com/quote/amlp/returns"},{"title":"ChartRow XOM calendar-year returns","url":"https://chartrow.com/quote/xom/returns"}]},{"id":"re-2021-vaccine-reopening-boom","date":"2020-11-09","end_date":"2021-12-31","sector":"real_estate","subindustries":["retail_reits","self_storage_reits","residential_reits","industrial_logistics_reits","lodging_reits","office_reits"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Vaccine rotation and the 2021 REIT boom: best year on record","summary":"REITs jumped 9.2% in November 2020 on the Pfizer vaccine (mortgage REITs +18%) and 2021 became the best REIT year ever at +41.3%: regional malls +92% (Simon +96%), shopping centers +65%, self storage +79% (Public Storage +67%, Extra Space occupancy 97.2%), apartments +64% on record rent growth and industrial +62% (Prologis +72%). Lodging (+18%) and office (+22%) lagged as business travel and return-to-office stalled.","evidence":"All Equity REITs +41.3% in 2021; Regional Malls +92.05%, Self Storage +79.43%, Apartments +63.61%, Industrial +62.03%; SPG +95.7%","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2022 (2021 sector returns)","url":"https://www.reit.com/sites/default/files/2023-01/MediaFactSheet_Dec-2022.pdf"},{"title":"GlobeSt: Self-storage REITs gear up for growth (Nareit 2021 data)","url":"https://globest.com/2022/03/25/self-storage-reits-gear-up-for-growth"},{"title":"ChartRow SPG calendar-year returns","url":"https://chartrow.com/quote/spg/returns"}]},{"id":"hc-2020-vaccine-day","date":"2020-11-09","end_date":"2020-12-18","sector":"healthcare","subindustries":["biotech_large","pharma"],"direction":"in","magnitude":"major","driver_type":"pandemic","title":"Pfizer/BioNTech 90% efficacy and the mRNA vaccine trade","summary":"Pfizer and BioNTech's announcement that their mRNA vaccine was more than 90% effective triggered a violent rotation on November 9 2020: the Dow rallied more than 800 points led by cyclicals while stay-at-home winners sold off (Amazon -5%, Zoom -17%). Moderna received its EUA on December 18 2020 and booked $18.5 billion of revenue and $12.2 billion of net income in 2021, making mRNA the sector's defining growth story before the 2022-2025 collapse (Moderna revenue fell to $1.9 billion by 2025).","evidence":"Dow +800 points, Nasdaq -1.5%, Amazon -5%, Zoom -17% on 2020-11-09; Moderna 2021 revenue $18.5B vs $1.9B in 2025","sources":[{"title":"CNBC: Stock market news, November 9 2020","url":"https://www.cnbc.com/2020/11/09/stock-market-futures-open-to-close-news.html"},{"title":"Wikipedia: Moderna (EUA, financials)","url":"https://en.wikipedia.org/wiki/Moderna"}]},{"id":"cd-2020-vaccine-reopening-rotation","date":"2020-11-09","end_date":"2021-03-31","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants","internet_retail"],"direction":"mixed","magnitude":"major","driver_type":"pandemic","title":"Vaccine day: reopening trade in, stay-at-home trade out","summary":"Pfizer's 90% efficacy announcement on November 9 2020 produced the sharpest one-day rotation of the pandemic: the Dow rallied more than 800 points led by cyclicals (cruise lines, airlines, hotels, casinos) while Amazon fell 5%, Zoom 17% and Netflix sold off. The reopening trade ran into spring 2021 and set up the eventual unwind of pandemic winners in 2022.","evidence":"Dow +800 points, Nasdaq -1.5%, AMZN -5%, ZM -17% on 2020-11-09","sources":[{"title":"CNBC: Stock market news, November 9 2020","url":"https://www.cnbc.com/2020/11/09/stock-market-futures-open-to-close-news.html"}]},{"id":"cd-2020-tesla-sp500","date":"2020-11-16","end_date":"2020-12-21","sector":"consumer_discretionary","subindustries":["autos"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Tesla joins the S&P 500 after a 743% year","summary":"S&P announced on November 16 2020 that Tesla would join the index in one step on December 21, the largest addition ever; the stock jumped about 12% on the news and index funds were estimated to need roughly $80 billion of the shares. Tesla rose 743% in 2020, the best in the S&P 500, and its weight turned the consumer discretionary sector into a two-stock (AMZN, TSLA) index that would dominate XLY's behaviour thereafter.","evidence":"TSLA +743% in 2020; ~$80B of index-fund buying for the 2020-12-21 inclusion","sources":[{"title":"Motley Fool: Why Tesla stock climbed 24.3% in December (2020 gain)","url":"https://www.fool.com/investing/2021/01/04/why-tesla-stock-climbed-243-in-december/"},{"title":"Al Jazeera: Tesla shares up 12 percent as automaker zooms to join S&P 500","url":"https://www.aljazeera.com/economy/2020/11/16/tesla-shares-up-12-after-announcement-it-will-zoom-onto-sp-500"}]},{"id":"cyber-2020-solarwinds","date":"2020-12-13","end_date":"2021-01-05","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"in","magnitude":"moderate","driver_type":"geopolitical","title":"SolarWinds supply-chain attack on US agencies","summary":"The SolarWinds Orion compromise became public on 13 December 2020 after FireEye disclosed the theft of its red-team tools on 8 December, exposing Treasury, Commerce and other agencies to a Russian intelligence operation. SolarWinds faced shareholder suits over the subsequent share-price fall, while the breach accelerated federal zero-trust mandates and budgets that benefited next-generation security vendors.","evidence":"Breach publicly confirmed 2020-12-13; FireEye confirmed the trojaned Orion update as the vector on 2020-12-15.","sources":[{"title":"2020 United States federal government data breach (Wikipedia)","url":"https://en.wikipedia.org/wiki/2020_United_States_federal_government_data_breach"}]},{"id":"materials-2021-reflation","date":"2021-01-04","end_date":"2021-12-31","sector":"materials","subindustries":["chemicals","metals_mining"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2021 reopening reflation lifts materials and energy","summary":"Vaccines, fiscal stimulus and supply bottlenecks drove commodity prices higher through 2021: S&P 500 materials returned 27.3% and energy 54.6% (the best sector) against 28.7% for the index, with steel, copper and chemicals producers reporting record margins. The IIJA in November added an infrastructure demand tailwind, while utilities (+17.7%) were the laggard as yields rose.","evidence":"S&P 500 Materials 2021 total return +27.3%, Energy +54.6% vs S&P 500 +28.7%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Infrastructure Investment and Jobs Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Infrastructure_Investment_and_Jobs_Act"}]},{"id":"real-estate-services-2021-record-year","date":"2021-01-04","end_date":"2021-12-31","sector":"real_estate","subindustries":["real_estate_services"],"direction":"in","magnitude":"major","driver_type":"macro","title":"2021: record $1.3 trillion of global CRE investment makes CBRE's best year ever","summary":"Global commercial real estate investment hit a record $1.3 trillion in 2021, up 55% from 2020 and 21% from 2019, with the Americas near $775bn (+83%) as cheap debt and reopening demand released pent-up transactions. CBRE reported record revenue, earnings and free cash flow for 2021 (GAAP EPS $5.41, +143%; free cash flow $2.2bn), and brokers rallied through the year. Transaction-driven services were the biggest beneficiaries of the zero-rate era and the first casualties of the 2022 rate shock.","evidence":"Global CRE investment volume $1.3 trillion in 2021, +55% y/y (CBRE Research); CBRE 2021 GAAP EPS $5.41, +143%.","sources":[{"title":"2021 global investment volume hits record level (CBRE)","url":"https://www.cbre.com/insights/briefs/2021-global-investment-volume-hits-record-level"},{"title":"CBRE Group reports financial results for Q4 and full year 2021 (CBRE IR)","url":"https://ir.cbre.com/press-releases/detail/38/cbre-group-inc-reports-financial-results-for-q4-and-full"}]},{"id":"clean-energy-2021-georgia-runoff","date":"2021-01-06","end_date":null,"sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"major","driver_type":"election","title":"Georgia runoffs hand Democrats the Senate: solar ETF +9%, SunPower +25% at the cycle top","summary":"As Raphael Warnock and Jon Ossoff won Georgia's Senate runoffs on January 6, 2021, giving Democrats a 50-50 Senate with the vice-president's tie-break, clean energy stocks surged on the prospect of reconciliation-passed climate credits: the Invesco Solar ETF rose 8-10%, SunPower 25%, Sunrun 16% and Enphase and SolarEdge more than 12%. The day sits within weeks of the clean-energy peak (ICLN topped in early February 2021), making it the final blow-off of the 2020 ESG/zero-rate mania before rising yields cut the group by a quarter.","evidence":"Invesco Solar ETF (TAN) +9.8% and SunPower +25% on 2021-01-06.","sources":[{"title":"Clean energy stocks jump as Georgia results roll in (CNBC)","url":"https://www.cnbc.com/2021/01/06/clean-energy-stocks-jump-as-georgia-results-roll-in.html"},{"title":"Why residential solar stocks jumped today (Motley Fool)","url":"https://www.fool.com/investing/2021/01/06/why-residential-solar-stocks-jumped-today/"},{"title":"Solar ETF lights up as Georgia's Senate race fuels green energy outlook (ETF Trends)","url":"https://www.etftrends.com/esg-content-hub/solar-etf-lights-up-as-georgias-senate-race-fuels-green-energy-outlook/"}]},{"id":"cd-2021-gamestop-squeeze","date":"2021-01-28","end_date":"2021-02-02","sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"GameStop short squeeze","summary":"Retail traders coordinated on Reddit drove GameStop from $17.25 at the start of January 2021 to an intraday $483 on January 28 with short interest around 140% of float; AMC rose 480% and Bed Bath & Beyond 78% in the same week before brokerages restricted buying and GME fell 60% on February 2. It was the extreme of the 2021 liquidity-driven, retail-led flows into distressed specialty retail, and it forced short-biased hedge funds to de-gross across the sector.","evidence":"GME intraday high $483.00 on 2021-01-28 from $17.25 at the start of January; short interest ~140% of float on 2021-01-22","sources":[{"title":"Wikipedia: GameStop short squeeze","url":"https://en.wikipedia.org/wiki/GameStop_short_squeeze"}]},{"id":"semis-2021-chip-shortage","date":"2021-02-05","end_date":"2021-12-31","sector":"technology","subindustries":["semiconductors","semicap","hardware","memory"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"2021 chip shortage: automakers idle plants, chip pricing surges","summary":"By February 2021 chip lead times had stretched to about 15 weeks, the longest since 2017 (Broadcom's reached 22.2 weeks by April), and GM, Ford, Toyota, Volkswagen and others cut production; AlixPartners estimated the shortage cost automakers about $210 billion of 2021 revenue. Pricing power and capacity plans pulled capital into semiconductors: the Philadelphia semiconductor index was up 36% in 2021 by the autumn, outperforming the Nasdaq 100 for a third straight year at about 6.3x forward sales versus a 10-year average of 3.6x.","evidence":"Chip lead times about 15 weeks in February 2021 (IHS Markit); AlixPartners estimate of $210 billion in lost automaker revenue in 2021.","sources":[{"title":"2020-2023 global chip shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2020%E2%80%932023_global_chip_shortage"},{"title":"'Chip famine' slams the auto industry (Axios, 2021-02-05)","url":"https://www.axios.com/2021/02/05/chip-shortage-automakers"},{"title":"Red-hot chip stocks are cooling after remarkable run (Bloomberg via BQ)","url":"https://www.bloombergquint.com/amp/markets/red-hot-chip-stocks-are-cooling-after-remarkable-run-tech-watch"}]},{"id":"hc-2021-2022-xbi-bear","date":"2021-02-08","end_date":"2022-05-11","sector":"healthcare","subindustries":["biotech_smid","biotech_large","life_sciences_tools","healthcare_technology"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Rate shock: XBI's 64% drawdown, the deepest in its history","summary":"As real yields rose from deeply negative levels and the Fed turned hawkish, long-duration, cash-burning biotech was repriced first and hardest. XBI fell 63.9% from its February 8 2021 close to the May 11 2022 trough (about 16 months), worse than the 2015-16 and 2008 episodes, and the IPO window shut. Life-science tools and digital health suffered second-order damage as biotech customers cut spending. The S&P 500's own drawdown over the same window was roughly 20%.","evidence":"XBI maximum drawdown -63.89% from 2021-02-08 to 2022-05-11 (PortfoliosLab/ChartRow)","sources":[{"title":"PortfoliosLab: SPDR S&P Biotech ETF (XBI)","url":"https://portfolioslab.com/symbol/XBI"},{"title":"ChartRow: XBI drawdown","url":"https://chartrow.com/quote/xbi/drawdown"},{"title":"Investing.com: Biotech's bounce, expecting continued strength (June 2022)","url":"https://uk.investing.com/analysis/biotechs-bounce-expecting-continued-strength-200524709"}]},{"id":"en-2021-clean-energy-bust","date":"2021-02-10","end_date":"2021-12-31","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Clean energy peaks and loses a quarter of its value as yields rise","summary":"When 10-year yields rose in early 2021 and the stimulus-driven retail bid faded, the 2020 winners reversed: ICLN lost 24% and TAN 25% in 2021, ESG inflows slowed sharply and concentration issues forced ICLN to rebalance. The bust began a three-year de-rating that was only interrupted by the IRA.","evidence":"ICLN -24.2% and TAN -25.1% in 2021 vs SPY +28.7%","sources":[{"title":"FlowBank: Top performing ETFs of 2020 sink in 2021","url":"https://www.flowbank.com/en/livewire/top-performing-etfs-of-2020-sink-in-2021"},{"title":"Energy Connects: Hot corner of ESG investing is cooling fast and losing cash (May 2021)","url":"https://energyconnects.com/news/renewables/2021/may/hot-corner-of-esg-investing-is-cooling-fast-and-losing-cash"}]},{"id":"fintech-2021-coinbase-listing-bubble","date":"2021-04-14","end_date":"2021-11-08","sector":"technology","subindustries":["fintech_payments"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Coinbase direct listing marks the fintech, SPAC and crypto peak","summary":"Coinbase listed directly on Nasdaq on 14 April 2021 with a $250 reference price (about $47 billion) and closed its first day at $328.28, the high-water mark of a cycle in which Affirm, Upstart, SoFi and dozens of SPAC fintechs raised capital at venture-style multiples. Bitcoin peaked on 8 November 2021 and Meta briefly crossed $1 trillion on 28 June 2021; the cohort then lost most of its value in 2022.","evidence":"Coinbase closed at $328.28 on 2021-04-14 versus a $250 Nasdaq reference price.","sources":[{"title":"Coinbase (Wikipedia)","url":"https://en.wikipedia.org/wiki/Coinbase"},{"title":"2022 stock market decline (Wikipedia)","url":"https://en.wikipedia.org/wiki/2022_stock_market_decline"}]},{"id":"hc-2021-tmo-ppd","date":"2021-04-15","end_date":"2021-12-08","sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"Thermo Fisher buys PPD: tools roll up the CRO space","summary":"Thermo Fisher agreed to buy clinical research organisation PPD for $17.4 billion in cash plus about $3.5 billion of net debt, valuing it near $20.9 billion, extending the tools-and-services consolidation (ICON-PRA, Danaher-Aldevron the same year). The deal marked the peak of confidence in biopharma R&D outsourcing just before the 2022 funding collapse.","evidence":"PPD purchase price $17.4B cash, enterprise value ~$20.9B (announced April 2021)","sources":[{"title":"Wikipedia: Thermo Fisher Scientific","url":"https://en.wikipedia.org/wiki/Thermo_Fisher_Scientific"}]},{"id":"net-lease-2021-realty-income-vereit","date":"2021-04-29","end_date":"2021-11-01","sector":"real_estate","subindustries":["net_lease_specialty_reits"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Realty Income buys VEREIT: a $50bn net-lease consolidator is born","summary":"Realty Income agreed on April 29, 2021 to acquire VEREIT in an all-stock deal at 0.705 Realty Income shares per VEREIT share, creating a company with about $50bn of enterprise value and spinning the combined office assets into Orion Office REIT. VEREIT jumped about 16% to $48 while Realty Income rose less than 2%, and the merger closed on November 1, 2021. With cap rates at cycle lows and the cost of capital at record lows, scale and an A-rated balance sheet became the net-lease sector's main source of accretion, a model that was stress-tested by the 2022 rate shock.","evidence":"Exchange ratio 0.705 Realty Income shares per VEREIT share; VEREIT +16.3% intraday on 2021-04-29.","sources":[{"title":"Realty Income to merge with VEREIT (SEC 8-K exhibit 99.1)","url":"https://www.sec.gov/Archives/edgar/data/726728/000110465921056901/tm2114533d1_ex99-1.htm"},{"title":"What's going on with VEREIT and Realty Income today? (Benzinga)","url":"https://benzinga.com/m-a/21/04/20861591/whats-going-on-with-vereit-and-realty-income-today"},{"title":"Realty Income closes merger with VEREIT (PR Newswire)","url":"https://www.prnewswire.com/news-releases/realty-income-closes-merger-with-vereit-301412667.html"}]},{"id":"cyber-2021-colonial-pipeline","date":"2021-05-07","end_date":"2021-05-27","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Colonial Pipeline ransomware and the federal cyber executive order","summary":"The DarkSide ransomware attack shut the Colonial Pipeline for six days from 7 May 2021 and prompted Executive Order 14028 on 12 May and the TSA's first pipeline cybersecurity directive on 27 May, mandating incident reporting and zero-trust adoption. The attack converted cybersecurity from an IT budget line into critical-infrastructure policy, supporting multi-year spending visibility for the sector.","evidence":"Pipeline shut 2021-05-07 to 2021-05-12; Executive Order 14028 signed 2021-05-12.","sources":[{"title":"Colonial Pipeline ransomware attack (Wikipedia)","url":"https://en.wikipedia.org/wiki/Colonial_Pipeline_ransomware_attack"}]},{"id":"distributors-2021-opioid-global-settlement","date":"2021-07-21","end_date":"2022-02-25","sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"$26bn global opioid settlement lifts the liability overhang from MCK, CAH and ABC","summary":"State attorneys general unveiled a $26bn agreement on July 21, 2021: McKesson $7.9bn, Cardinal Health $6.4bn and AmerisourceBergen $6.4bn over 18 years, plus Johnson & Johnson $5bn over nine years, with an independent monitor and data sharing. The deal became effective on February 25, 2022 after enough states and localities joined. Capping the liability at a known, multi-decade payment stream let the drug distributors re-rate as steady GLP-1 and specialty-volume compounders rather than litigation risks.","evidence":"McKesson's share of the settlement: $7.9bn paid over 18 years (announced 2021-07-21).","sources":[{"title":"Big 3 U.S. drug distributors, J&J reach landmark $26 billion opioid settlement (CNBC)","url":"https://www.cnbc.com/2021/07/21/drug-distributors-jj-reach-landmark-26-billion-opioid-settlement-.html"},{"title":"Drug distributors, J&J reach $26 billion opioids settlement (Axios)","url":"https://www.axios.com/2021/07/21/jnj-mckesson-cardinal-amerisourcebergen-opioids-settlement"},{"title":"4 U.S. companies will pay $26 billion to settle opioid claims (NPR, 2022-02-25)","url":"https://www.npr.org/2022/02/25/1082901958/opioid-settlement-johnson-26-billion"}]},{"id":"real-estate-services-2021-zillow-exits-ibuying","date":"2021-11-02","end_date":"2021-11-03","sector":"real_estate","subindustries":["real_estate_services"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Zillow shuts Zillow Offers: the iBuying model breaks before rates even rise","summary":"Zillow announced on November 2, 2021 that it would wind down Zillow Offers, cut 25% of its staff (about 2,000 people) and sell roughly 7,000 homes after its pricing algorithm overpaid; the unit lost $422m in Q3 and the company had $2.9bn of related debt to repay. The stock fell 15% in the session and another 7.5% after hours, Opendoor dropped about 15% and Offerpad 6%. The exit removed the largest buyer from the iBuying market and proved that algorithmic home-flipping could not survive a mere flattening of prices, a year before mortgage rates doubled.","evidence":"Zillow Offers lost $422m in Q3 2021; Zillow cut about 2,000 jobs (25% of staff) on 2021-11-02.","sources":[{"title":"Zillow says it's closing homebuying business, cutting 25% of workforce (CNBC)","url":"https://www.cnbc.com/2021/11/02/zillow-shares-plunge-after-announcing-it-will-close-home-buying-business.html"},{"title":"Zillow says it's making good progress on home sales as it exits house-flipping business (GeekWire)","url":"https://www.geekwire.com/2021/zillow-says-its-making-good-progress-on-home-sales-as-it-exits-house-flipping-business-announces-750m-stock-repurchase/"},{"title":"Zillow exits iBuying: five key takeaways (Mike DelPrete)","url":"https://www.mikedp.com/articles/2021/11/3/zillow-exits-ibuying-five-key-takeaways"}]},{"id":"ind-2021-iija-infrastructure","date":"2021-11-15","end_date":"2025-01-20","sector":"industrials","subindustries":["building_products_construction","machinery","industrial_distribution","electrical_equipment"],"direction":"in","magnitude":"major","driver_type":"policy","title":"Infrastructure Investment and Jobs Act creates a multi-year construction tailwind","summary":"The $1.2 trillion IIJA (with $550bn of new spending) signed November 15, 2021 funded roads, grid, water and broadband, and together with the CHIPS Act and IRA produced a mega-project wave in semiconductors, EV plants and LNG. The PAVE infrastructure ETF returned 36.4% in 2021, 31% in 2023 and 17.9% in 2024, and investors who bought at passage earned a total return above 96%; by early 2025 only $400-450bn of the money had been announced or awarded, leaving a long outlay tail.","evidence":"PAVE total return >96% from Nov 2021 passage; PAVE +31.0% in 2023 and +17.9% in 2024","sources":[{"title":"Nasdaq/MarketBeat: 3 infrastructure stocks riding the US building boom","url":"https://www.nasdaq.com/articles/3-infrastructure-stocks-riding-us-building-boom"},{"title":"ChartRow PAVE calendar-year returns","url":"https://chartrow.com/quote/pave/returns"},{"title":"Global X PAVE fund page","url":"https://globalxetfs.com/funds/pave/"}]},{"id":"reshoring-2021-iija","date":"2021-11-15","end_date":null,"sector":"reshoring_infrastructure","subindustries":[],"direction":"in","magnitude":"major","driver_type":"policy","title":"Infrastructure Investment and Jobs Act signed","summary":"President Biden signed the $1.2 trillion IIJA on 15 November 2021, including $550 billion of new spending: $110 billion for roads and bridges, $65 billion for broadband, $73 billion for energy infrastructure and $7.5 billion for EV charging. The law anchored the reshoring and infrastructure theme (PAVE), giving engineering and construction, aggregates and electrical-equipment names a multi-year public backlog that later merged with the data-center build-out.","evidence":"IIJA signed 2021-11-15: about $1.2 trillion total, $550 billion new spending.","sources":[{"title":"Infrastructure Investment and Jobs Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Infrastructure_Investment_and_Jobs_Act"}]},{"id":"ind-2022-rate-shock-housing-linked","date":"2022-01-03","end_date":"2022-10-12","sector":"industrials","subindustries":["building_products_construction","industrial_distribution"],"direction":"out","magnitude":"major","driver_type":"rates","title":"2022 rate shock: mortgage rates go from 3% to 7% and building products de-rate","summary":"The fastest Fed tightening since the 1980s pushed 30-year mortgage rates from about 3.1% to 7% during 2022, collapsing housing turnover. A basket of builders, building products and home-improvement names fell 28% versus 20% for the S&P 500, the S&P 400 building products index fell nearly 20%, and PKB lost 21.7% for the year; repair-and-remodel names like Masco held up better than new-construction exposure.","evidence":"PKB -21.7% in 2022 vs SPY -18.2%; S&P 400 Building Products sub-index -~20% in 2022 as mortgage rates rose from ~3% to 7%","sources":[{"title":"Trefis: Housing stocks are pricing in a big downturn (2022)","url":"https://www.trefis.com/stock/hd/articles/540858/housing-stocks-are-pricing-in-a-big-downturn/2022-06-22"},{"title":"National Mortgage News: repair-and-remodeling stock rally hits a wall","url":"https://www.nationalmortgagenews.com/articles/repair-and-remodeling-stock-rally-hits-a-wall"},{"title":"ChartRow PKB calendar-year returns","url":"https://chartrow.com/quote/pkb/returns"}]},{"id":"ind-2022-waste-defensive-bid","date":"2022-01-03","end_date":"2022-12-31","sector":"industrials","subindustries":["waste"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Waste stocks absorb the 2022 defensive rotation","summary":"With inflation running at 8-9%, waste haulers' CPI-plus pricing and landfill scarcity made them the sector's inflation hedge: Waste Management was beating the S&P, Nasdaq and Dow by May 2022 and WM and Republic made new all-time highs in August. WM finished 2022 down only 4.5% versus 18.2% for the S&P 500, though the group's premium multiple became a headwind once risk appetite returned in 2023.","evidence":"WM -4.5% in 2022 vs SPY -18.2%; WM/RSG set new all-time monthly highs in Aug 2022","sources":[{"title":"Motley Fool: Recession or not, this aspiring Dividend Aristocrat (May 2022)","url":"https://www.fool.com/investing/2022/05/19/recession-or-not-this-aspiring-dividend-aristocrat"},{"title":"Zacks: Waste Management and Republic Services feature (Aug 2022)","url":"https://zacks.com/stock/news/1967646/zacks-investment-ideas-feature-highlights-waste-management-and-republic-services"},{"title":"ChartRow WM calendar-year returns","url":"https://chartrow.com/quote/wm/returns"}]},{"id":"re-2022-rate-shock-derating","date":"2022-01-03","end_date":"2022-10-31","sector":"real_estate","subindustries":["office_reits","residential_reits","net_lease_specialty_reits","self_storage_reits","healthcare_reits","mortgage_reits","lodging_reits"],"direction":"out","magnitude":"major","driver_type":"rates","title":"2022 rate shock: worst REIT year since 2008","summary":"The 10-year yield rose 243bp to 3.88% and the Fed funds rate went from zero to above 4%, and the FTSE Nareit All Equity REITs index lost 24.95%, its worst year since 2008 (XLRE fell from $50 to $36.93). Office (-37.6%) was hit by hybrid work on top of rates, apartments fell 32%, self storage 27%, health care 22%, mortgage REITs 27% as MBS spreads blew out, while free-standing net lease (-6.5%, Realty Income -7.4%) and specialty (-0.8%) held up best.","evidence":"All Equity REITs -24.95% in 2022 (10-year yield +243bp to 3.88%); Office -37.62%, Apartments -31.95%, Self Storage -26.73%, Mortgage REITs -26.61%, Free Standing -6.53%","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2022","url":"https://www.reit.com/sites/default/files/2023-01/MediaFactSheet_Dec-2022.pdf"},{"title":"Benzinga: The 2 REIT benchmark ETFs end 2022 down by more than 25%","url":"https://www.benzinga.com/real-estate/reit/23/01/30261356/the-2-reit-benchmark-etfs-end-2022-down-by-more-than-25"},{"title":"The Real Deal: REITs post worst year since 2008","url":"https://therealdeal.com/2022/12/14/reits-post-worst-year-since-2008-have-they-hit-bottom"}]},{"id":"cd-2022-amazon-unwind","date":"2022-01-03","end_date":"2022-12-29","sector":"consumer_discretionary","subindustries":["internet_retail","specialty_retail"],"direction":"out","magnitude":"major","driver_type":"rates","title":"2022 consumer rotation: Amazon halves, pandemic winners give back everything","summary":"Rising rates, inflation and a hangover from pandemic over-building drove Amazon down 51% in 2022, its worst year since 2000, giving back all of its pandemic gains and dropping below a $1 trillion valuation in November; Tesla fell 68%. Spending rotated from goods to services and from discretionary to staples, and retailers that over-ordered inventory (Target, Walmart, Gap, Kohl's) took margin hits in May 2022. XLY was among the worst sectors of the year.","evidence":"AMZN -51% in 2022, biggest decline since 2000; TSLA -68%","sources":[{"title":"CNBC: Amazon shed half its value in 2022 as tech stocks got crushed","url":"https://www.cnbc.com/2022/12/29/amazon-shed-half-its-value-in-2022-as-tech-stocks-got-crushed.html"},{"title":"CNBC: Amazon sell-off pushes market cap below $1 trillion","url":"https://www.cnbc.com/amp/2022/11/01/amazon-plunge-pushes-valuation-below-1-trillion-first-time-since-2020.html"}]},{"id":"cd-2022-housing-rate-shock","date":"2022-01-03","end_date":"2022-12-30","sector":"consumer_discretionary","subindustries":["housing"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Mortgage rates at 21-year highs: homebuilder ETFs fall ~28% in 2022","summary":"As the Fed hiked and 30-year mortgage rates climbed to levels not seen in 21 years, ITB lost 28.9% and XHB 26.3% in 2022 against an 18% fall in the S&P 500. Existing-home transactions froze on the lock-in effect and home-improvement retailers, furniture and appliance makers guided down. The sub-industry's drawdown was concentrated in the first nine months before rates peaked in October.","evidence":"ITB -28.9% and XHB -26.3% in 2022 vs S&P 500 -18%","sources":[{"title":"Nasdaq/TipRanks: XHB, this homebuilder ETF is quietly surging","url":"https://www.nasdaq.com/articles/xhb:-this-homebuilder-etf-is-quietly-surging.-can-it-continue"},{"title":"etf.com: Housing downturn making itself felt in ETFs","url":"https://www.etf.com/sections/news/housing-downturn-making-itself-felt-etfs"}]},{"id":"tech-2022-rate-shock","date":"2022-01-03","end_date":"2022-10-12","sector":"technology","subindustries":["application_software","internet_platforms","semiconductors","fintech_payments","infrastructure_software_cyber","hardware","memory"],"direction":"out","magnitude":"major","driver_type":"rates","title":"2022 rate shock: growth-to-value rotation, software halves, energy +66%","summary":"The Fed began hiking on 16 March 2022 (to 0.25-0.5%) and raised rates 11 times while starting QT in June; the S&P 500 fell about 25% from its 3 January peak to the October low and finished 2022 at -18.1%. Technology returned -28.2%, communication services -39.9% and the Nasdaq -33.1%, while energy returned +65.7% and utilities +1.6%. The software ETF IGV was roughly cut in half and its price-to-tangible-book multiple fell 36% between November 2021 and November 2022 as long-duration cash flows were repriced.","evidence":"S&P 500 Information Technology 2022 total return -28.2%, Energy +65.7%, S&P 500 -18.1%; Nasdaq Composite 2022 -33.10%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"FOMC statement, 16 March 2022","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20220316a.htm"},{"title":"2022 stock market decline (Wikipedia)","url":"https://en.wikipedia.org/wiki/2022_stock_market_decline"},{"title":"The Claude Crash: how AI triggered a historic selloff in software stocks (StockCharts, with 2022 IGV context)","url":"https://articles.stockcharts.com/article/the-claude-crash-how-ai-triggered-a-historic-selloff-in-software-stocks/"},{"title":"Did Goldman Sachs just declare open season on software stocks (Nasdaq.com)","url":"https://nasdaq.com/articles/did-goldman-sachs-just-declare-open-season-software-stocks"}]},{"id":"utilities-2022-relative-haven","date":"2022-01-03","end_date":"2022-12-31","sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Utilities hold flat while the S&P 500 drops 18% in 2022","summary":"Despite the fastest hiking cycle in four decades, regulated utilities returned +1.6% in 2022 against -18.1% for the S&P 500 and -28.2% for technology, because earnings visibility, the Inflation Reduction Act's clean-energy credits and a rotation out of growth offset the rise in yields. It was one of the sector's best relative years on record and the inverse of 2023, when utilities became the worst sector.","evidence":"S&P 500 Utilities 2022 total return +1.6% vs S&P 500 -18.1%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Inflation Reduction Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Inflation_Reduction_Act"}]},{"id":"fintech-2022-bust","date":"2022-01-03","end_date":"2022-12-31","sector":"technology","subindustries":["fintech_payments"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Fintech, SPAC and crypto bust of 2022","summary":"Rising rates and credit worries collapsed the 2020-21 fintech cohort: the F-Prime Fintech Index fell 72% in 2022, Coinbase posted a record $1.1 billion quarterly loss and cut 18% of staff, Upstart had to hold loans on balance sheet, and Block, PayPal, Fiserv, Bill.com and LendingClub were down an average 49% by mid-June. PayPal's year-end price fell to $71.22 from $188.58 a year earlier, and the fintech IPO window was described as 'essentially closed'.","evidence":"F-Prime Fintech Index -72% in 2022; PayPal year-end price $71.22 (2022) vs $188.58 (2021).","sources":[{"title":"Why the IPO window for fintech is essentially closed in 2022 / F-Prime index (TechCrunch)","url":"https://techcrunch.com/?p=2498030"},{"title":"Making sense of fintech in a bear market (Cowboy Ventures)","url":"https://medium.com/cowboy-ventures/investing-in-the-next-wave-of-fintech-making-sense-of-fintech-in-a-down-market-e24fc016da78"},{"title":"PayPal (Wikipedia)","url":"https://en.wikipedia.org/wiki/PayPal"},{"title":"Coinbase (Wikipedia)","url":"https://en.wikipedia.org/wiki/Coinbase"}]},{"id":"media-2022-worst-sector","date":"2022-01-03","end_date":"2022-12-31","sector":"communication_media","subindustries":["media_entertainment","internet_platforms","telecom"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Communication services worst sector of 2022 at -39.9%","summary":"The sector created in 2018 to house Alphabet, Meta, Netflix and the media groups lost 39.9% in 2022, the worst S&P 500 sector against -18.1% for the index, as rate hikes compressed growth multiples, Meta fell 24-27% on two earnings days, Netflix lost subscribers and the ad market slowed. Telecom carriers within the sector held up better on yield but AT&T's WarnerMedia spin and dividend reset weighed.","evidence":"S&P 500 Communication Services 2022 total return -39.9% (worst sector) vs S&P 500 -18.1%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Meta Platforms (Wikipedia)","url":"https://en.wikipedia.org/wiki/Meta_Platforms"}]},{"id":"internet-2022-meta-crash","date":"2022-02-03","end_date":"2022-10-27","sector":"technology","subindustries":["internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Meta's record $230 billion one-day loss and the metaverse derating","summary":"Meta fell 27% in early February 2022 after reporting its first decline in daily active users and weak guidance, erasing about $230 billion of market value, the largest one-day loss in US history at the time. On 27 October 2022 it fell another 24% as metaverse spending and Apple's privacy changes crushed margins, leaving its market value near $268 billion, roughly $700 billion below the 2021 peak, before the 2023 'year of efficiency' recovery.","evidence":"Meta shares -27% in early February 2022, erasing about $230 billion; -24% on 2022-10-27 to a market value of about $268 billion.","sources":[{"title":"Meta Platforms (Wikipedia)","url":"https://en.wikipedia.org/wiki/Meta_Platforms"},{"title":"Netflix and Meta stocks have seen five years of gains wiped out (Business Insider)","url":"https://businessinsider.in/stock-market/news/netflix-and-meta-stocks-have-seen-their-gains-from-the-last-5-years-nearly-wiped-out-as-they-struggle-with-lofty-growth-forecasts-and-fed-tightening-is-adding-to-the-pain/amp_articleshow/91082918.cms"}]},{"id":"ind-2022-ukraine-defense-rerating","date":"2022-02-24","end_date":"2022-12-31","sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"Russia invades Ukraine; defense primes re-rate in a bear market","summary":"Northrop and Lockheed rose 3% and 2% on the day of the invasion and kept going as Europe pledged rearmament and US supplementals flowed; Northrop returned 41% and Lockheed 40.5% in 2022 while the S&P 500 lost 18%. The SPADE defense index gained 8.6% and ITA 10% in the market's worst year since 2008, ending defense's ESG-era underperformance.","evidence":"LMT +40.5% and NOC +41% in 2022 vs SPY -18.2%; ITA +10.0%","sources":[{"title":"Business Insider: US defense stocks rally after Russia attacks Ukraine","url":"https://businessinsider.in/stock-market/news/us-defense-stocks-rally-after-russia-launches-attacks-on-ukraine/amp_articleshow/89807316.cms"},{"title":"Defense News: defense stocks flourish after Russian invasion","url":"https://www.defensenews.com/?p=65234"},{"title":"ChartRow LMT calendar-year returns","url":"https://chartrow.com/quote/lmt/returns"}]},{"id":"en-2022-ukraine-only-positive-sector","date":"2022-02-24","end_date":"2022-12-30","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services","refining","midstream"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"Russia invades Ukraine: energy is the only positive S&P sector in 2022","summary":"Sanctions and the loss of Russian supply pushed Brent above $120 and European gas to records; XLE returned 64.3% in 2022 while the S&P 500 fell 19.6%, the widest outperformance on record. Exxon gained 87%, SLB 81% as international and offshore spending resumed, refiners hit records on $60 diesel cracks (Marathon Petroleum earned $28.17 a share, +1,287%), and Cheniere/LNG exporters re-rated on Europe's scramble for gas.","evidence":"XLE +64.3% in 2022 vs S&P 500 -19.6%; XOM +87.4%, SLB +81.2%, VLO +75.0%, AMLP +25.5% in 2022","sources":[{"title":"Nasdaq: 3 must-know energy sector ETFs","url":"https://www.nasdaq.com/articles/3-must-know-energy-sector-etfs-with-upside-potential"},{"title":"Business Insider: Energy outperforming S&P 500 by widest margin on record","url":"https://businessinsider.in/stock-market/news/the-energy-sector-is-outperforming-the-sp-500-by-the-widest-margin-on-record-amid-war-in-ukraine-investment-research-firm-says/amp_articleshow/90143931.cms"},{"title":"Nasdaq: 2 oil refiners posting record margins","url":"https://www.nasdaq.com/articles/2-oil-refiners-posting-record-margins:-can-the-trend-continue"}]},{"id":"media-2022-wbd-merger-att-spin","date":"2022-04-08","end_date":"2022-12-31","sector":"communication_media","subindustries":["media_entertainment","telecom"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"AT&T spins off WarnerMedia into Warner Bros. Discovery","summary":"AT&T completed the spin-off of WarnerMedia and its merger with Discovery on 8 April 2022, with WBD trading on Nasdaq from 11 April and AT&T shareholders receiving 0.24 WBD shares per AT&T share. The deal unwound AT&T's 2018 media bet, returned the carrier to a pure telecom with a reset dividend, and created a heavily indebted media company whose shares fell steadily through the 2022 streaming derating.","evidence":"WarnerMedia-Discovery merger closed 2022-04-08; WBD began trading 2022-04-11.","sources":[{"title":"Warner Bros. Discovery (Wikipedia)","url":"https://en.wikipedia.org/wiki/Warner_Bros._Discovery"},{"title":"AT&T (Wikipedia)","url":"https://en.wikipedia.org/wiki/AT%26T"}]},{"id":"media-2022-netflix-subscriber-loss","date":"2022-04-19","end_date":"2022-04-29","sector":"communication_media","subindustries":["media_entertainment","internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Netflix loses subscribers for the first time in a decade, stock -35%","summary":"Netflix reported a 200,000 net subscriber loss on 19 April 2022, its first decline in more than ten years, and the shares closed down 35% on 20 April, erasing about $54 billion; the stock fell 49% for the month of April. The result ended the 'streaming at any cost' era, forcing Disney, Warner Bros. Discovery and Paramount to pivot to profitability and ad tiers, and helped make communication services the worst S&P 500 sector of 2022 at -39.9%.","evidence":"Netflix closed down 35% on 2022-04-20 after reporting a 200,000 subscriber loss; Communication Services 2022 return -39.9%.","sources":[{"title":"Netflix shares plunge 35% after massive subscriber loss (Bloomberg via BNN)","url":"https://www.bnnbloomberg.ca/netflix-shares-plunge-35-after-massive-subscriber-loss-1.1754275"},{"title":"Why Netflix shares fell another 49% in April (Motley Fool)","url":"https://www.fool.com/investing/2022/05/06/why-netflix-shares-fell-another-49-in-april"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"re-2022-prologis-amazon-pullback","date":"2022-04-28","end_date":"2022-12-31","sector":"real_estate","subindustries":["industrial_logistics_reits"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Amazon says it has too much warehouse space; logistics REITs de-rate","summary":"Amazon's April 28, 2022 admission that it over-built warehouse capacity, days after Prologis's Q1 results, ended the sector's premium: Prologis fell nine straight sessions (about 28%) and finished 2022 down 31%, and industrial REITs lost 28.6% for the year despite record rent growth. Management called the Amazon reports 'much ado about nothing' for Prologis itself, but the group never regained its 2021 multiple.","evidence":"PLD -31.3% in 2022; Industrial REITs -28.58% in 2022; PLD slid for 9 sessions (~-28%) after its Apr 19, 2022 results","sources":[{"title":"Motley Fool: Down 26%, is Prologis still a buy? (May 2022)","url":"https://www.fool.com/investing/2022/05/16/down-26-is-prologis-still-a-buy"},{"title":"The Real Deal: Prologis CEO denies Amazon, FedEx industrial pullback","url":"https://therealdeal.com/2022/10/19/prologis-ceo-denies-amazon-fedex-industrial-pullback/"},{"title":"ChartRow PLD calendar-year returns","url":"https://chartrow.com/quote/pld/returns"}]},{"id":"hc-2022-teladoc-crash","date":"2022-04-28","end_date":"2022-07-28","sector":"healthcare","subindustries":["healthcare_technology"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Teladoc writes down Livongo; digital health capitulates","summary":"Teladoc fell about 40% on April 28 2022 after taking a $6.6 billion goodwill impairment on Livongo and cutting revenue guidance from $2.6 billion to $2.45 billion; a further impairment in July took 2022 write-downs to $13.4 billion. By then the stock was down roughly 88% from its 2021 peak, the clearest marker of the unwind of the pandemic telehealth trade as patients returned to in-person care and rates rose.","evidence":"TDOC -40% on 2022-04-28 on a $6.6B goodwill impairment; shares -88% from peak","sources":[{"title":"Motley Fool: Why Teladoc stock cratered on Thursday","url":"https://www.fool.com/investing/2022/04/28/why-teladoc-health-stock-cratered-on-thursday"},{"title":"Healthcare Dive: Teladoc records $6.6B impairment on Livongo","url":"https://www.healthcaredive.com/news/teladoc-records-66b-impairment-charge-on-livongo-acquisition-spurring-re/622793/"}]},{"id":"cs-2022-target-walmart-margin-shock","date":"2022-05-17","end_date":"2022-05-18","sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Walmart and Target margin shocks: inflation and inventory glut","summary":"Walmart fell about 11% on May 17 2022 after inflated inventory and fuel costs crushed Q1 profit, and Target fell 25% the next day, its worst day since 1987, as its operating margin collapsed to 5.3% from 9.8% and comparable sales fell for the fourth straight quarter; the Dow had its biggest drop since 2020. The pair showed that even 'defensive' retailers could not pass through costs fast enough, and that consumers were rotating from discretionary goods to food and fuel, which later favoured Walmart's grocery mix over Target's.","evidence":"WMT -11% on 2022-05-17; TGT -24.9% on 2022-05-18 (worst since 1987), operating margin 5.3% vs 9.8%","sources":[{"title":"Motley Fool: Target headed toward its biggest plunge since 1987","url":"https://www.fool.com/investing/2022/05/18/target-headed-toward-its-biggest-plunge-since-1987"},{"title":"IBTimes: Dow plunges 1,100 points in biggest selloff since 2020","url":"https://www.ibtimes.com/stock-market-today-dow-plunges-1100-points-biggest-selloff-2020-3512559"},{"title":"Motley Fool: Why Walmart stock fell again today","url":"https://www.fool.com/investing/2022/05/18/why-walmart-stock-fell-again-today"}]},{"id":"ind-2022-freight-recession","date":"2022-06-01","end_date":"2025-12-31","sector":"industrials","subindustries":["transportation"],"direction":"out","magnitude":"major","driver_type":"macro","title":"The long freight recession: spot rates collapse, trucking and intermodal de-rate","summary":"After the 2021 goods binge, import volumes and truckload spot rates rolled over in mid-2022 and stayed depressed for three years: dry-van spot rates were down 24% year on year in May 2023, J.B. Hunt fell 13% in a day on its April 2023 miss, and Yellow's August 2023 bankruptcy only briefly helped LTL. Old Dominion lost 20% in 2022, 12% in 2024 and 11% in 2025, and the trucking downturn was still being described as 'prolonged' entering 2026.","evidence":"Dry-van spot rates -23.9% y/y in May 2023; ODFL -20.1% (2022), -12.4% (2024), -10.5% (2025)","sources":[{"title":"Talk Business: Freight recession about 40% complete (Jun 2023)","url":"https://talkbusiness.net/2023/06/analysts-freight-recession-about-40-complete/"},{"title":"Loadstar: JB Hunt riding a new pricing cycle","url":"https://theloadstar.com/fasten-your-seat-belts-us-trucking-slowdown-ominous-for-smaller-players/"},{"title":"ChartRow ODFL calendar-year returns","url":"https://chartrow.com/quote/odfl/returns"}]},{"id":"re-2022-chanos-data-center-short","date":"2022-06-29","end_date":"2022-12-31","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Chanos shorts 'legacy' data centers; DLR and EQIX lose a third","summary":"Jim Chanos raised a fund to short Digital Realty and Equinix in June 2022, arguing hyperscalers would self-build; data-center REITs fell more than 5% on the report and finished 2022 down 28% (Digital Realty -41%, Equinix -21%), while towers lost 28.6% on rates and Sprint-merger churn. The thesis was reversed within a year by AI leasing, but the 2022 drawdown was the sector's worst since 2008.","evidence":"Data Center REITs -27.97% and Infrastructure/Tower REITs -28.61% in 2022; DLR -41.0%, EQIX -21.1%, AMT -25.7% in 2022","sources":[{"title":"Benzinga: Short seller Jim Chanos betting against data centers","url":"https://benzinga.com/news/22/06/27900928/short-seller-jim-chanos-betting-against-data-centers-heres-why"},{"title":"Data Center Dynamics: Data center REITs outperform S&P 500 in November but worse off YTD","url":"https://www.datacenterdynamics.com/en/news/data-center-reits-outperform-sp-500-in-november-but-are-worse-off-ytd"},{"title":"ChartRow DLR calendar-year returns","url":"https://chartrow.com/quote/dlr/returns"}]},{"id":"en-2022-inflation-reduction-act","date":"2022-07-27","end_date":"2022-12-30","sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"major","driver_type":"policy","title":"Inflation Reduction Act: $369bn of clean-energy credits","summary":"The surprise Manchin-Schumer deal on July 27, 2022 and the IRA's signing on August 16 extended and expanded solar, wind, storage, nuclear and hydrogen credits for a decade; in the two weeks to August 8 ICLN rose 15%, TAN 18.5% and QCLN 17%. Enphase finished 2022 up 45% and First Solar up 72% on domestic-manufacturing credits, bucking the broader market.","evidence":"TAN +18.5% and ICLN +15.4% in the two weeks to Aug 8, 2022; FSLR +71.9% and ENPH +44.8% in 2022","sources":[{"title":"VanEck: Clean energy boost (IRA)","url":"https://vaneck.com.au/blog/etfs/clean-energy-boost"},{"title":"CMC Markets: US climate bill benefits Bloom, SunPower, Brookfield","url":"https://www.cmcmarkets.com/en/optox/us-climate-bill-benefits-bloom-energy-sunpower-and-brookfield"},{"title":"ChartRow FSLR calendar-year returns","url":"https://chartrow.com/quote/fslr/returns"}]},{"id":"semis-2022-chips-act","date":"2022-08-09","end_date":null,"sector":"technology","subindustries":["semiconductors","semicap","memory"],"direction":"in","magnitude":"major","driver_type":"policy","title":"CHIPS and Science Act signed: $52.7 billion plus a 25% fab tax credit","summary":"President Biden signed the CHIPS and Science Act on 9 August 2022, appropriating $52.7 billion for semiconductor manufacturing, R&D and workforce (about $39 billion in manufacturing incentives) and creating a 25% investment tax credit for fab equipment, within a roughly $280 billion authorisation. The law triggered the US fab build-out by Intel, TSMC, Samsung and Micron that drives semicap and construction demand, and it was later paired with tariffs as the policy lever for reshoring chips.","evidence":"CHIPS and Science Act signed 2022-08-09; $52.7 billion appropriated and a 25% investment tax credit.","sources":[{"title":"CHIPS and Science Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/CHIPS_and_Science_Act"},{"title":"President Biden signs CHIPS Act into law (Mayer Brown)","url":"https://www.mayerbrown.com/es/insights/publications/2022/08/president-biden-signs-chips-act-into-law"}]},{"id":"hc-2022-ira-signed","date":"2022-08-16","end_date":null,"sector":"healthcare","subindustries":["pharma","biotech_large"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Inflation Reduction Act brings Medicare drug-price negotiation","summary":"Signed August 16 2022 after a 51-50 Senate vote, the IRA let Medicare negotiate prices on 10 drugs from 2026 (rising to more than 20 a year by 2029), capped Part D out-of-pocket costs at $2,000, capped insulin at $35 and extended enhanced ACA subsidies for three years. Pharma's reaction was muted on the day because the provisions had been telegraphed, but the law introduced a permanent revenue haircut on the biggest Medicare drugs and a 'pill penalty' that shifted R&D incentives toward biologics.","evidence":"IRA signed 2022-08-16; negotiation of 10 drugs effective 2026, $2,000 Part D cap, $35 insulin cap","sources":[{"title":"Wikipedia: Inflation Reduction Act","url":"https://en.wikipedia.org/wiki/Inflation_Reduction_Act"},{"title":"CMS: Inflation Reduction Act and Medicare","url":"https://www.cms.gov/inflation-reduction-act-and-medicare"}]},{"id":"reshoring-2022-ira","date":"2022-08-16","end_date":null,"sector":"reshoring_infrastructure","subindustries":[],"direction":"in","magnitude":"major","driver_type":"policy","title":"Inflation Reduction Act: $391 billion of energy and climate incentives","summary":"The Senate passed the IRA 51-50 on 7 August 2022 and Biden signed it on 16 August, authorising $391 billion of energy and climate spending (CBO/JCT later estimated $783 billion of energy-security and climate provisions) through manufacturing (45X), clean-electricity, nuclear (45U) and EV credits. Together with the IIJA and CHIPS Act it formed the policy backbone of the reshoring trade in electrical equipment, grid, solar manufacturing and nuclear, parts of which were repealed in July 2025.","evidence":"IRA signed 2022-08-16; authorised energy and climate spending of $391 billion.","sources":[{"title":"Inflation Reduction Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/Inflation_Reduction_Act"}]},{"id":"software-2022-adobe-figma","date":"2022-09-15","end_date":"2023-12-18","sector":"technology","subindustries":["application_software"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"Adobe's $20 billion Figma deal knocks 17% off the stock","summary":"Adobe agreed to buy Figma for about $20 billion on 15 September 2022 and its shares fell roughly 17%, a sign that investors would no longer fund growth-at-any-price M&A in a rising-rate market. The deal was abandoned in December 2023 on EU and UK antitrust objections with a $1 billion break fee; Figma later listed on 31 July 2025 and more than tripled on its first day.","evidence":"Adobe shares dropped about 17% after the 2022-09-15 announcement of the $20 billion Figma acquisition.","sources":[{"title":"Figma (Wikipedia)","url":"https://en.wikipedia.org/wiki/Figma"}]},{"id":"semicap-2022-october-export-controls","date":"2022-10-07","end_date":"2022-10-21","sector":"technology","subindustries":["semicap","semiconductors","memory"],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"October 2022 export controls cut China off from advanced chips and tools","summary":"On 7 October 2022 the Bureau of Industry and Security imposed licence requirements on advanced computing chips and semiconductor manufacturing equipment destined for China, with a presumption of denial for Chinese-owned advanced fabs and restrictions on US persons supporting them; the rules took full effect on 21 October. Lam Research, Applied Materials and KLA each fell more than 4% on the day, and China exposure (roughly 30-40% of equipment revenue) became a standing discount for the semicap group.","evidence":"BIS interim final rule issued 2022-10-07; Lam Research, Applied Materials and KLA each fell more than 4% that day.","sources":[{"title":"BIS implements new semiconductor and supercomputer export controls (WSGR)","url":"https://wsgr.com/en/insights/bis-implements-new-semiconductor-and-supercomputer-related-export-controls-and-end-use-controls.html"},{"title":"Chip industry grapples with new US curbs on China sales (Reuters via Investing.com)","url":"https://m.investing.com/news/economy/chip-industry-grapples-with-new-us-curbs-on-china-sales-2907578?ampMode=1"},{"title":"US export controls on advanced computing and semiconductors to China (Wikipedia)","url":"https://en.wikipedia.org/wiki/United_States_New_Export_Controls_on_Advanced_Computing_and_Semiconductors_to_China"}]},{"id":"ai-2022-chatgpt-launch","date":"2022-11-30","end_date":"2023-12-31","sector":"ai","subindustries":["semiconductors","infrastructure_software_cyber","internet_platforms","application_software"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"ChatGPT launch ignites the 2023 AI trade","summary":"OpenAI released ChatGPT on 30 November 2022 and it reached an estimated 100 million monthly users by January 2023; Microsoft followed with a further $10 billion investment on 23 January 2023. The AI narrative reversed the 2022 bear market for mega-cap tech: the Magnificent Seven rose about 76% on a cap-weighted basis in 2023, S&P 500 technology returned 57.8% and communication services 55.8% against 26.3% for the index.","evidence":"S&P 500 Information Technology 2023 total return +57.8% vs S&P 500 +26.3%; ChatGPT reached about 100 million monthly users by January 2023 (UBS via Reuters).","sources":[{"title":"AI stocks rally in latest Wall Street craze sparked by ChatGPT (Reuters via Kitco)","url":"https://www.kitco.com/news/off-the-wire/2023-02-06/ai-stocks-rally-latest-wall-street-craze-sparked-chatgpt-0"},{"title":"Behold the Magnificent Seven (Business Day)","url":"https://www.pressreader.com/south-africa/business-day/20240219/281870123362749"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"OpenAI (Wikipedia)","url":"https://en.wikipedia.org/wiki/OpenAI"}]},{"id":"ind-2023-waste-pricing-rng","date":"2023-01-03","end_date":"2024-12-31","sector":"industrials","subindustries":["waste"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Waste compounders grind higher on pricing and renewable natural gas","summary":"Pricing above CPI, landfill-gas (RNG) projects and steady M&A kept waste names compounding through the 2023-24 bull market even as they lost their 2022 defensive premium. Waste Management returned 16.2% in 2023 and 14.3% in 2024, lagging the S&P 500 but with low volatility, and analysts flagged that both WM and Republic traded at significant premiums to the market.","evidence":"WM +16.2% in 2023 and +14.3% in 2024 vs SPY +26.2% and +24.9%","sources":[{"title":"ChartRow WM calendar-year returns","url":"https://chartrow.com/quote/wm/returns"},{"title":"Simply Wall St: Waste Management positive expectations are priced in","url":"https://simplywall.st/stocks/us/commercial-services/nyse-wm/waste-management/news/waste-management-incs-nysewm-positive-expectations-are-price"}]},{"id":"en-2023-clean-energy-rate-bust","date":"2023-01-03","end_date":"2024-11-06","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"rates","title":"5% yields and the Trump election: clean energy's third bust","summary":"Rising rates hit project economics and residential solar demand (California NEM 3.0, Europe inventory glut): TAN fell 27% in 2023 and 38% in 2024, Enphase 50% and 48%, ICLN 20% and 26%. Solar stocks nosedived again on November 6, 2024 when Trump's win raised the odds of IRA repeal.","evidence":"TAN -26.8% (2023) and -37.6% (2024); ENPH -50.1% (2023) and -48.0% (2024); TAN down 36% YTD at Dec 8, 2023","sources":[{"title":"Zacks: After a tough 2023, solar ETFs likely to make a comeback in 2024","url":"https://www.zacks.com/amp/stock/news/2197852/after-a-tough-2023-solar-etfs-likely-to-make-a-comeback-in-2024"},{"title":"pv magazine: Solar stocks nosedive as Trump victory is secured","url":"https://pv-magazine.com/2024/11/07/solar-stocks-nosedive-as-trump-victory-is-secured"},{"title":"ChartRow ENPH calendar-year returns","url":"https://chartrow.com/quote/enph/returns"}]},{"id":"re-2023-mpw-steward","date":"2023-01-03","end_date":"2024-05-06","sector":"real_estate","subindustries":["healthcare_reits"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Medical Properties Trust and the Steward bankruptcy","summary":"Hospital landlord MPW lost 82% from its 2021 peak, about four times the health-care REIT decline, as its largest tenant Steward stopped paying rent; the dividend was slashed, $11.5bn of market value evaporated and Steward's May 6, 2024 Chapter 11 filing sent MPW down another 17%. The failure pushed capital from leased hospital and skilled-nursing exposure toward operating senior housing (Welltower, Ventas).","evidence":"MPW -82% from 2021 peak (about 4x the health-care REIT decline); MPW -17% on May 6, 2024 Steward bankruptcy","sources":[{"title":"Boston Globe: For supporting Steward, landlord pays a steep price","url":"https://www.bostonglobe.com/2024/05/08/business/steward-health-care-bankruptcy-medical-properties-trust-hospitals"},{"title":"TipRanks: Medical Properties plunges on largest tenant's bankruptcy","url":"https://www.tipranks.com/news/medical-properties-nysempw-plunges-on-largest-tenants-bankruptcy"}]},{"id":"re-2023-data-center-ai-leasing","date":"2023-01-03","end_date":"2024-12-31","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"AI leasing boom: data-center REITs lead for two years","summary":"Generative-AI demand produced record hyperscale leasing (Digital Realty signed more than $520m of new leases in Q3 2024 alone, backlog at historic highs) and power-constrained supply, and data-center REITs returned 30.1% in 2023 and 25.2% in 2024, the top sector both years. Digital Realty gained 40% and 36%, Equinix 25% and 20%, reversing the 2022 Chanos narrative.","evidence":"Data Center REITs +30.08% (2023) and +25.22% (2024); DLR new leasing >$520m in Q3 2024","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2024 (sector returns)","url":"https://www.reit.com/sites/default/files/2025-01/MediaFactSheet_Dec-2024.pdf"},{"title":"Barchart: 2 AI data center stocks to buy for momentum into 2025","url":"https://www.barchart.com/story/news/28938523/2-ai-data-center-stocks-to-buy-now-for-strong-momentum-into-2025"},{"title":"ChartRow DLR calendar-year returns","url":"https://chartrow.com/quote/dlr/returns"}]},{"id":"re-2023-tower-reit-slump","date":"2023-01-03","end_date":"2025-03-13","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Towers lag for three years: rates, Sprint churn and Crown Castle's fiber exit","summary":"While data centers boomed, towers were the REIT market's laggard: telecom REITs returned -1.5% in 2023 and -14.2% in 2024 as carriers cut capex after 5G, T-Mobile removed Sprint sites and DISH wrote down, and leverage met 5% yields; from end-2022 Crown Castle fell 22% and SBA 29% while the S&P 500 rose 49%. Crown Castle cut 2023 guidance, then sold its fiber and small-cell units for $8.5bn in March 2025 and cut its dividend 32%.","evidence":"Telecommunications REITs -1.52% (2023) and -14.15% (2024); CCI -22% and SBAC -29% total return from end-2022 vs S&P 500 +49%; CCI dividend cut 32% to $1.0625/qtr (Mar 2025)","sources":[{"title":"Inside Towers: US tower stocks have had a rough road the past 18 months","url":"https://insidetowers.com/?p=60721"},{"title":"Barchart: Crown Castle lowers dividend by 32%","url":"https://www.barchart.com/story/news/32528902/crown-castle-lowers-dividend-by-32"},{"title":"Nareit REIT Industry Fact Sheet Dec 2024","url":"https://www.reit.com/sites/default/files/2025-01/MediaFactSheet_Dec-2024.pdf"}]},{"id":"re-2023-senior-housing-supercycle","date":"2023-01-03","end_date":"2026-11-05","sector":"real_estate","subindustries":["healthcare_reits"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Senior-housing supercycle makes health care the best REIT sector","summary":"The 80-plus population wave, near-zero new senior-housing construction and post-COVID occupancy recovery produced double-digit same-store NOI growth (Welltower's senior-housing NOI +14.5% y/y): health care REITs returned 13.9% in 2023, 24.2% in 2024 and 28.5% in 2025, the top sector, and 18.9% through September 2026. Welltower returned 42%, 43% and 50% in 2023-25, sold its $7.2bn outpatient-medical portfolio in October 2025 to go all-in on senior housing, and is the only REIT sector trading above NAV (+10%).","evidence":"Health Care REITs +28.45% in 2025 (best sector) and +18.9% YTD at Sep 30, 2026; WELL +49.9% (2025) and +33.7% YTD 2026","sources":[{"title":"Nareit: REITs post narrow gains in 2025","url":"https://www.reit.com/news/blog/market-commentary/reits-post-narrow-gains-2025"},{"title":"Stockopedia/Reuters: Welltower boosts FFO forecast, unveils senior housing expansion","url":"https://www.stockopedia.com/share-prices/welltower-NYQ:WELL/news/welltower-boosts-annual-ffo-forecast-unveils-23-billion-senior-housing-expansion-019e69ef-f8d0-70b4-8aa3-80de32e38d9e/"},{"title":"ChartRow WELL calendar-year returns","url":"https://chartrow.com/quote/well/returns"}]},{"id":"re-2024-retail-reit-recovery","date":"2023-01-03","end_date":"2024-12-31","sector":"real_estate","subindustries":["retail_reits"],"direction":"in","magnitude":"moderate","driver_type":"macro","title":"No new supply: malls and shopping centers quietly recover","summary":"A decade without new retail construction, record occupancy at Simon and Kimco and the failure of weak tenants (Bed Bath, Rite Aid, Big Lots) turning into re-leasing spreads lifted regional malls 29.9% in 2023 and 27.4% in 2024 and shopping centers 17% in 2024; Simon returned 29% and 27%. Retail went from the 2017-20 pariah to a core holding.","evidence":"Regional Malls +29.94% (2023) and +27.42% (2024); Shopping Centers +17.04% in 2024; SPG +29.2% (2023), +26.9% (2024)","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2024","url":"https://www.reit.com/sites/default/files/2025-01/MediaFactSheet_Dec-2024.pdf"},{"title":"ChartRow SPG calendar-year returns","url":"https://chartrow.com/quote/spg/returns"}]},{"id":"cd-2023-homebuilder-rally","date":"2023-01-03","end_date":"2023-12-29","sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Builders rally despite 7% mortgages, then surge on the Fed pivot","summary":"With existing-home inventory locked up, builders captured an outsized share of transactions using rate buy-downs: XHB was up 30.3% and ITB 38.3% by early autumn 2023 even with soft sales, and both hit records after the Fed's December 2023 pivot signalled rate cuts. The move inverted the 2022 trade and showed builders can outperform the index when supply, not demand, is the binding constraint.","evidence":"XHB +30.3% and ITB +38.3% YTD by early autumn 2023; record highs after the December 2023 Fed meeting","sources":[{"title":"Zacks: Here's why housing ETFs are up in 2023 despite soft sales","url":"https://www.zacks.com/amp/stock/news/2043889/heres-why-housing-etfs-are-up-in-2023-despite-soft-sales"},{"title":"etf.com: Homebuilder ETFs rally, hit records after Fed comments","url":"https://www.etf.com/sections/news/homebuilder-etfs-rally-hit-records-after-fed-comments"}]},{"id":"utilities-2023-worst-sector","date":"2023-01-03","end_date":"2023-12-31","sector":"utilities","subindustries":["regulated_utilities"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Utilities are the worst S&P 500 sector of 2023 as yields hit cycle highs","summary":"The Fed's final hike to 5.25-5.5% on 26 July 2023 and the autumn surge in long-term yields to cycle highs drained capital from bond proxies into AI-led growth: utilities returned -7.1% in 2023, the worst sector, against +26.3% for the S&P 500 and +57.8% for technology. The derating left the sector cheap enough that the 2024 data-center power narrative produced one of its best years on record.","evidence":"S&P 500 Utilities 2023 total return -7.1% (worst sector) vs S&P 500 +26.3%.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"FOMC statement, 26 July 2023","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20230726a.htm"}]},{"id":"datacenter-2023-vertiv-breakout","date":"2023-01-03","end_date":"2023-12-31","sector":"datacenter_power","subindustries":[],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Vertiv +252% in 2023 as data-center power and cooling become the AI picks-and-shovels trade","summary":"Vertiv, the data-center power and thermal-management supplier, rose 252% in 2023, outperforming every S&P 500 company, as hyperscaler orders for liquid cooling and power distribution surged with AI server deployments. The move established 'data-center power and cooling' as a distinct industrial overlay on the AI trade, later joined by GE Vernova, Eaton and the independent power producers.","evidence":"Vertiv share price +252% in 2023, outperforming all S&P 500 companies (company Q4 2023 call).","sources":[{"title":"Vertiv (Wikipedia)","url":"https://en.wikipedia.org/wiki/Vertiv"}]},{"id":"media-2023-2024-rebound","date":"2023-01-03","end_date":"2024-12-31","sector":"communication_media","subindustries":["media_entertainment","internet_platforms"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Communication services rebounds 56% and 40% on Meta's efficiency pivot and streaming profits","summary":"After its -39.9% 2022, communication services returned 55.8% in 2023 and 40.2% in 2024 (the best sector that year) against 26.3% and 25.0% for the S&P 500, led by Meta's 'year of efficiency' (+150% in 2023 to within 2% of $1 trillion in January 2024), Netflix's ad tier and password-sharing crackdown, and Alphabet's AI narrative. Legacy media lagged inside the sector as streaming consolidation began.","evidence":"S&P 500 Communication Services total return +55.8% in 2023 and +40.2% in 2024; Meta share price +150% in 2023.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Meta Platforms (Wikipedia)","url":"https://en.wikipedia.org/wiki/Meta_Platforms"}]},{"id":"infra-2023-microsoft-openai","date":"2023-01-23","end_date":null,"sector":"hyperscalers","subindustries":["infrastructure_software_cyber","internet_platforms"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Microsoft commits a further $10 billion to OpenAI","summary":"Microsoft announced a multi-year, multibillion-dollar investment in OpenAI on 23 January 2023, reported at $10 billion at a $29 billion valuation, securing Azure as OpenAI's compute platform. The deal made Azure growth the market's benchmark for AI monetisation and pulled capital into infrastructure software and cloud, the start of the hyperscaler capex cycle that quadrupled combined spending by 2025.","evidence":"Microsoft's additional $10 billion investment announced 2023-01-23 at a $29 billion valuation.","sources":[{"title":"OpenAI (Wikipedia)","url":"https://en.wikipedia.org/wiki/OpenAI"},{"title":"Hyperscaler capex has quadrupled since GPT-4's release (Epoch AI)","url":"https://epoch.ai/data-insights/hyperscaler-capex-trend"}]},{"id":"re-2023-regional-bank-office-collapse","date":"2023-03-10","end_date":"2023-05-31","sector":"real_estate","subindustries":["office_reits","mortgage_reits","real_estate_services"],"direction":"out","magnitude":"major","driver_type":"macro","title":"SVB fails: office REITs collapse on the CRE-lending freeze","summary":"Silicon Valley Bank's March 10, 2023 failure hit the small and mid-sized banks that make 70% of commercial real-estate loans; the MSCI REIT index fell 8.3% in two weeks, SL Green 37% in a month, Vornado 27% and Boston Properties 21%, and office was down 24% year to date by late May. Commercial mortgage REITs and the brokers (CBRE and JLL transaction revenue down ~50% as global CRE investment fell 48% y/y) were hit by the same freeze; office returned 2% in 2023 versus 11.4% for all REITs.","evidence":"SLG -37% and VNO -27% in the month to Mar 31, 2023; MSCI US REIT index -8.3% in the two weeks after Mar 10; Office REITs +2.03% in 2023 vs All Equity REITs +11.36%","sources":[{"title":"Blue Vault: Investors sold REITs in response to the banking crisis","url":"https://bluevaultpartners.com/investors-sold-reits-in-response-to-the-banking-crisis-they-may-have-overreacted/"},{"title":"Inquirer/Reuters: Banking crisis scars struggling US real estate stocks","url":"https://business.inquirer.net/396630/banking-crisis-scars-struggling-u-s-real-estate-stocks"},{"title":"CoStar: JLL earnings drop 99% as sales, leasing and financing decline","url":"https://www.costar.com/article/1525935567/jll-earnings-drop-99-as-sales-leasing-and-financing-decline"},{"title":"Nareit REIT Industry Fact Sheet Dec 2024 (2023 sector returns)","url":"https://www.reit.com/sites/default/files/2025-01/MediaFactSheet_Dec-2024.pdf"}]},{"id":"financials-2023-svb-regional-bank-crisis","date":"2023-03-10","end_date":"2023-05-01","sector":"financials","subindustries":["banks","capital_markets"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Silicon Valley Bank fails and regional banks crash","summary":"Regulators seized SVB on 10 March 2023 after $42 billion of withdrawals in a day, closed Signature on 12 March and launched the Bank Term Funding Program the same day; First Republic fell 62% on 13 March and was sold to JPMorgan on 1 May. The SPDR Regional Banking ETF (KRE) fell 14.4% between 9 and 14 March and roughly 20% for the week, the S&P 500 bank index was down 14% year-to-date by April, and the 2018 rollback of enhanced supervision drew blame.","evidence":"KRE down 14.4% from the 2023-03-09 close to 2023-03-14; SVB depositors withdrew about $42 billion on 2023-03-09.","sources":[{"title":"2023 United States banking crisis (Wikipedia)","url":"https://en.wikipedia.org/wiki/2023_United_States_banking_crisis"},{"title":"SVB's collapse hit banking ETFs (etf.com)","url":"https://www.etf.com/sections/news/svbs-collapse-hit-banking-etfs"},{"title":"Regional bank ETFs: what to watch for next (ETF Trends)","url":"https://www.etftrends.com/regional-bank-etfs-what-to-watch-for-next/"}]},{"id":"biotech-2023-svb-cash-fears","date":"2023-03-10","end_date":"2023-03-13","sector":"healthcare","subindustries":["biotech_smid","life_sciences_tools"],"direction":"out","magnitude":"moderate","driver_type":"macro","title":"SVB fails: biotech's house bank disappears and XBI falls 3.5% on cash-exposure fears","summary":"Silicon Valley Bank, the lender behind roughly half of venture-backed health-care companies, was closed on March 10, 2023; venture-backed health firms made up 12% of its $173bn deposits and 36% of $168bn in off-balance-sheet funds. XBI dropped about 3.5% that day as companies disclosed exposure (Vir about $220m, Sangamo $34m, Zealand 15% of cash) before the March 12 deposit backstop capped the damage. Public biotechs were largely shielded, but losing SVB's venture-debt channel deepened the 2023 funding drought for private and early-stage companies and for the tools and CRO suppliers that depend on them.","evidence":"XBI -3.5% on 2023-03-10; venture-backed health companies were 12% of SVB's $173bn deposits.","sources":[{"title":"SVB collapse brings another blow to cash-starved biotech industry (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2023-03-10/svb-sivb-collapse-brings-another-blow-to-cash-starved-biotech-industry"},{"title":"SVB, biotech's bank of choice, just failed (STAT)","url":"https://www.statnews.com/2023/03/10/svb-biotechs-bank-of-choice-just-failed-it-could-have-ripple-effects/"},{"title":"SVB failure triggers shock waves across biotech industry (Fierce Biotech)","url":"https://www.fiercebiotech.com/biotech/biotech-bank-svbs-capital-crunch-sparks-bank-run-companies-huddle-consider-exposure"}]},{"id":"fintech-2023-gics-payments-to-financials","date":"2023-03-17","end_date":null,"sector":"technology","subindustries":["fintech_payments"],"direction":"mixed","magnitude":"major","driver_type":"regulatory","title":"GICS moves Visa, Mastercard and payment processors from IT to Financials","summary":"After the close on 17 March 2023 GICS discontinued the Data Processing & Outsourced Services sub-industry, moving Visa, Mastercard, PayPal, Fiserv and other payment processors into a new Transaction & Payment Processing Services sub-industry within Financials, and payroll processors such as ADP into Industrials. UBS estimated the change cut Information Technology's S&P 500 weight by about 3.2 points and raised Financials by 2.7, forcing sector-fund rebalancing and making XLF a part-owner of the payments growth story.","evidence":"Effective after the close on 2023-03-17; estimated IT weight -3.2 points, Financials +2.7 points (UBS).","sources":[{"title":"GICS reveals sector shifts for 2023 (etf.com)","url":"https://www.etf.com/sections/features-and-news/gics-reveals-sector-shifts-2023"},{"title":"GICS changes set to impact S&P 500 and sector ETFs (ETF Strategy)","url":"https://www.etfstrategy.com/gics-changes-set-to-impact-sp-500-and-sector-etfs-10339/"},{"title":"UBS note on 2023 GICS changes","url":"https://ubs.com/us/en/wealth-management/insights/market-news/article.1587314.html"}]},{"id":"re-2023-storage-merger-and-turnover-slump","date":"2023-04-03","end_date":"2025-12-31","sector":"real_estate","subindustries":["self_storage_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Extra Space buys Life Storage, then housing turnover freezes storage demand","summary":"Extra Space's $12.7bn all-stock acquisition of Life Storage (announced April 3, 2023, closed July) made it the largest operator with 3,500 stores; self storage returned 18.5% in 2023 on consolidation, but 7% mortgage rates cut home sales to 30-year lows, move-in street rates fell double digits and the sector returned -0.5% in 2024 and -10% in 2025 (Public Storage -9.7%).","evidence":"EXR-LSI deal $12.7bn (Apr 3, 2023); Self Storage REITs +18.49% (2023), -0.52% (2024), -9.98% (2025)","sources":[{"title":"Inside Self-Storage: Extra Space, Life Storage complete merger","url":"https://www.insideselfstorage.com/reits/self-storage-reits-extra-space-life-storage-complete-merger"},{"title":"Nareit REIT Industry Fact Sheet Dec 2025 (2024-25 sector returns)","url":"https://www.reit.com/sites/default/files/2026-01/MediaFactSheet_Dec-2025.pdf"},{"title":"ChartRow PSA calendar-year returns","url":"https://chartrow.com/quote/psa/returns"}]},{"id":"hc-2023-tools-destocking","date":"2023-04-25","end_date":"2023-10-25","sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Bioprocessing destocking and biotech funding drought hit tools","summary":"Danaher cut its 2023 outlook on April 25 as large customers worked down pandemic-era inventories of filters and single-use bags, and the stock tumbled; Thermo Fisher followed on October 25 (shares -5.5%, $458.26 to $433.18) citing bioprocessing orders that failed to normalise, weak early-stage biotech funding and China. The group, a pandemic winner, became one of 2023's worst healthcare sub-sectors while the S&P 500 rose 24%.","evidence":"TMO -5.5% from $458.26 to $433.18 after its 2023-10-25 guidance cut; DHR guidance cut 2023-04-25 on bioprocessing destocking","sources":[{"title":"CNBC: Danaher's guidance weighs on the stock (April 2023)","url":"https://www.cnbc.com/2023/04/25/danahers-guidance-weighs-on-the-stock-forces-reassessment-.html"},{"title":"MedTech Dive: Thermo Fisher cuts 2023 guidance","url":"https://www.medtechdive.com/news/thermo-fisher-Q3-cuts-2023-guidance/697768/"},{"title":"GEN: Danaher, Thermo Fisher revenue declines rattle analysts","url":"https://genengnews.com/gen-edge/stockwatch-danaher-thermo-fisher-revenue-declines-rattle-analysts"}]},{"id":"semis-2023-nvidia-guidance","date":"2023-05-24","end_date":"2023-05-30","sector":"technology","subindustries":["semiconductors","memory","semicap","hardware"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Nvidia guides $11 billion, jumps 26% and reaches $1 trillion","summary":"On 24 May 2023 Nvidia guided fiscal Q2 revenue to about $11 billion versus $7.15 billion expected, citing data-center demand for AI accelerators; the stock rose 26% on 25 May to about $950 billion of market value and first crossed $1 trillion on 30 May, finishing May up 36.3%. The print made Nvidia the bellwether for the entire AI capex chain, from memory (HBM) to networking, servers and semicap.","evidence":"Nvidia fiscal Q2 2024 guidance of about $11 billion vs $7.15 billion consensus; shares +26% on 2023-05-25.","sources":[{"title":"Nvidia nears elite trillion-dollar market cap club (CNBC, 2023-05-25)","url":"https://www.cnbc.com/2023/05/25/nvidia-nears-elite-trillion-dollar-market-cap-club-of-apple-microsoft-alphabet-and-amazon.html"},{"title":"Why Nvidia surged 36.3% in May (Nasdaq.com)","url":"https://www.nasdaq.com/articles/why-nvidia-surged-36.3-in-may"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"id":"ind-2023-ai-datacenter-power-trade","date":"2023-05-25","end_date":"2025-12-31","sector":"industrials","subindustries":["electrical_equipment","building_products_construction","machinery"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"AI data-center build-out turns electrical equipment into the sector's growth engine","summary":"Nvidia's May 2023 guidance started a capital rotation into everything that powers and cools data centers: Vertiv returned 252% in 2023 and 137% in 2024, Eaton 56% and 40%, EMCOR 111% in 2024 as hyperscale backlog exploded, and GE Vernova, spun out in April 2024, returned 99% in 2025. Comfort Systems' backlog rose from $9.4bn to $17.8bn in a year and Eaton's data-center orders jumped 240%, while Caterpillar's turbine and genset business gave machinery a share of the trade (CAT +60% in 2025).","evidence":"VRT +251.8% (2023) and +136.8% (2024); GEV +99.0% in 2025; EME +111.3% in 2024; Comfort Systems backlog $17.81bn vs $9.38bn a year earlier","sources":[{"title":"ChartRow VRT calendar-year returns","url":"https://chartrow.com/quote/vrt/returns"},{"title":"Motley Fool: 2 industrial stocks worth watching (GE Vernova, Vertiv)","url":"https://www.fool.com/investing/2026/06/17/2-industrial-stocks-worth-watching/"},{"title":"Zacks: Comfort Systems order momentum","url":"https://www.zacks.com/stock/news/2899078/comfort-systems-order-momentum-strong-multi-year-growth"},{"title":"ChartRow EME calendar-year returns","url":"https://chartrow.com/quote/eme/returns"}]},{"id":"hc-2023-utilization-shock","date":"2023-06-14","end_date":null,"sector":"healthcare","subindustries":["managed_care","medical_devices","healthcare_facilities_services"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"UnitedHealth flags surging outpatient surgery: insurers fall, devices and hospitals rally","summary":"At the Goldman Sachs conference UnitedHealth's CFO said seniors were returning for deferred procedures, pushing its medical-cost ratio to the top of its range. UNH closed about 6% lower, Humana fell 11% and Elevance 7%, while the same news lifted procedure beneficiaries: Stryker +5%, Medtronic +3%, HCA +3%, Tenet +4%. It was the start of the Medicare Advantage cost-trend problem that would dominate managed care for the next three years.","evidence":"UNH -6%, HUM -11%, ELV -7%; SYK +5%, HCA +3% on 2023-06-14","sources":[{"title":"CNBC: Health insurance stocks slide after UnitedHealth warns of higher medical costs","url":"https://www.cnbc.com/2023/06/14/health-stocks-slide-after-unitedhealth-warns-of-higher-medical-costs.html"},{"title":"InsuranceNewsNet: UnitedHealth slumps, rival insurers follow","url":"https://insurancenewsnet.com/oarticle/unitedhealth-slumps-rival-insurers-follow-on-worries-over-rising-medical-costs-4"}]},{"id":"telecom-2023-lead-cables","date":"2023-07-10","end_date":"2023-07-19","sector":"technology","subindustries":["telecom"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"WSJ lead-cable report: AT&T at a 30-year low, Verizon at a 2010 low","summary":"A July 9, 2023 Wall Street Journal investigation found more than 2,000 lead-sheathed legacy Bell System cables in waterways and on poles. Verizon fell 7.5% to $31.46 on July 10, its lowest close since 2010, and AT&T closed at $13.45 on July 18, its lowest since 1993; over the stretch AT&T lost about 14%, Verizon 10% and Frontier 33% as JPMorgan and others downgraded on remediation and litigation risk. AT&T rebounded 6.4% on July 19 after saying lead cables were a small share of its wireline footprint, but the episode added a new tail risk to an already yield-driven sector.","evidence":"AT&T closed at $13.45 on 2023-07-18, its lowest since 1993; Verizon -7.5% to $31.46 on 2023-07-10.","sources":[{"title":"AT&T shares hit 30-year low after toxic lead cable report (Reuters via Yahoo)","url":"https://finance.yahoo.com/news/t-shares-hit-30-low-221423480.html"},{"title":"AT&T, Verizon stocks plunge as concerns mount over lead cables (Yahoo Finance)","url":"https://finance.yahoo.com/news/att-verizon-stocks-plunge-as-concerns-mount-over-lead-cables-193156681.html"},{"title":"AT&T bounces back after it eases fears over lead cable exposure (Yahoo Finance)","url":"https://finance.yahoo.com/news/t-bounces-back-eases-fears-120920672.html"}]},{"id":"media-2023-hollywood-double-strike","date":"2023-07-14","end_date":"2023-11-09","sector":"communication_media","subindustries":["media_entertainment"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"SAG-AFTRA joins the writers: Hollywood's first double strike since 1960 shuts production","summary":"Actors walked out on July 14, 2023, two months into the Writers Guild strike, halting most scripted film and TV production. Warner Bros. Discovery fell more than 5%, Paramount 4.6%, Disney 2% and Netflix 1.8% that day, and WBD later cut 2023 adjusted EBITDA guidance by $300-500m for strike costs; levered studios were hit hardest while Netflix's global library insulated it. The actors settled on November 9 and media shares popped, but the four-month stoppage pushed content releases into 2024-25 and deepened the linear-TV earnings hole.","evidence":"Warner Bros. Discovery cut 2023 adjusted EBITDA guidance by $300-500m due to the strikes (announced 2023-09-05).","sources":[{"title":"Entertainment stocks slump as Hollywood strike widens to SAG-AFTRA (TheWrap)","url":"https://www.thewrap.com/sag-aftra-strike-disney-warner-bros-discovery-netflix-stocks/"},{"title":"Warner Bros. Discovery says strikes will cost it up to $500 million this year (CNN)","url":"https://www.cnn.com/2023/09/05/media/warner-bros-discovery-strike-impact/index.html"},{"title":"Media stocks pop as SAG-AFTRA strike settles (Deadline)","url":"https://deadline.com/2023/11/media-shares-actors-sag-aftra-strike-settlement-1235598215/"}]},{"id":"glp1-2023-select-trial","date":"2023-08-08","end_date":"2023-11-08","sector":"glp1","subindustries":[],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Novo's SELECT trial proves cardiovascular benefit; Lilly's Zepbound approved","summary":"Novo Nordisk announced on 8 August 2023 that semaglutide cut major adverse cardiovascular events in the 17,604-patient SELECT trial (6.5% vs 8.0% for placebo), and its shares rose 18% to DKK 1,285.60. The result turned GLP-1s from a weight-loss product into a reimbursable cardiometabolic franchise, and the FDA approved Lilly's tirzepatide as Zepbound for obesity in November 2023; food, medical-device and dialysis stocks sold off on substitution fears.","evidence":"SELECT trial: MACE in 6.5% of the semaglutide group vs 8% on placebo; Novo shares +18% to DKK 1,285.60 on the announcement.","sources":[{"title":"SELECT: Novo Nordisk comes roaring back (Citeline)","url":"https://insights.citeline.com/SC148847/SELECT-Novo-Nordisk-Comes-Roaring-Back/link-DUYP5VHPIJFOPHASZNJGJ7GADM"},{"title":"Semaglutide (Wikipedia)","url":"https://en.wikipedia.org/wiki/Semaglutide"},{"title":"Eli Lilly and Company (Wikipedia)","url":"https://en.wikipedia.org/wiki/Eli_Lilly_and_Company"}]},{"id":"memory-2023-downturn","date":"2023-08-31","end_date":"2023-12-31","sector":"technology","subindustries":["memory","semiconductors"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"Memory downturn: Micron's revenue halves and it posts a $5.8 billion loss","summary":"After the pandemic PC and smartphone boom reversed, DRAM and NAND prices collapsed: Micron's fiscal 2023 (ended August 2023) revenue fell to $15.5 billion from $30.8 billion and it lost $5.8 billion, its worst year on record, as the industry cut wafer starts and capex. The supply cuts, combined with the shift of capacity to HBM for AI accelerators from mid-2024, set up the 2025-2026 memory shortage.","evidence":"Micron FY2023 revenue $15.5 billion (vs $30.8 billion in FY2022) and a net loss of $5.8 billion.","sources":[{"title":"Micron Technology (Wikipedia)","url":"https://en.wikipedia.org/wiki/Micron_Technology"},{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"}]},{"id":"hc-2023-glp1-scare-devices","date":"2023-10-04","end_date":"2023-12-31","sector":"healthcare","subindustries":["medical_devices"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"GLP-1 scare trade hits diabetes devices, CPAP and bariatric names","summary":"Walmart's US CEO said GLP-1 users were already buying less food, and the 'Ozempic trade' spread from staples to devices. Insulin-pump and CGM makers were already under pressure (Dexcom -30% and Insulet -54% year-to-date by October 2023), and CPAP makers including ResMed fell when sleep-apnea trial data showed reduced need for therapy. Intuitive Surgical flagged softer bariatric volumes. The device sub-sector lagged the S&P 500 in 2023 before fears were judged overdone in 2024.","evidence":"DXCM -30% and PODD -54% YTD as of October 2023; CPAP makers fell on sleep-apnea GLP-1 data","sources":[{"title":"Yahoo Finance: Wall Street is still jittery on GLP-1s","url":"https://sg.finance.yahoo.com/news/wall-street-is-still-jittery-on-glp-1s-193106560.html"},{"title":"Business Insider: Food retailers and producers slammed as GLP-1 alarms grow","url":"https://businessinsider.nl/food-retailers-and-producers-are-getting-slammed-as-glp-1-drugs-like-ozempic-raise-growing-alarms-about-demand"}]},{"id":"cd-2023-glp1-restaurants","date":"2023-10-04","end_date":"2023-10-31","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"The Ozempic scare reaches restaurants, snacks and beer","summary":"Walmart's comment that GLP-1 users were buying less food broadened the 'Ozempic trade' into restaurants, candy, beer and even airlines in the first week of October 2023; sell-side notes listed quick-service and casual-dining chains as volume losers. The move was sentiment-driven (consumer staples had its worst week since September 2022) and restaurant fundamentals did not show a GLP-1 effect in 2024, but the theme has resurfaced with every price cut since.","evidence":"Selloff in candy and beer stocks on GLP-1 fears the week of 2023-10-04; staples gauge -2.7% on the Friday","sources":[{"title":"Central Maine/Bloomberg: Ozempic threat is causing a selloff in candy and beer stocks","url":"https://www.centralmaine.com/2023/10/06/ozempic-threat-is-causing-a-selloff-in-candy-and-beer-stocks/"},{"title":"Word & Brown: Food, clothing, airlines, Ozempic is coming for these industries","url":"https://jrreport.wordandbrown.com/2023/10/10/food-clothing-airlines-ozempic-is-coming-for-these-industries-and-more/"}]},{"id":"cs-2023-glp1-food-scare","date":"2023-10-04","end_date":"2024-01-31","sector":"consumer_staples","subindustries":["food_beverage_tobacco","staples_retail"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Walmart says GLP-1 users buy less; packaged food de-rates","summary":"Walmart US CEO John Furner told Bloomberg on October 4 2023 that GLP-1 users were already buying less, and the consumer staples gauge fell as much as 2.7% on October 6, its worst week since September 2022, with Walmart, Costco and Kroger also down; snack, candy and beer names led the declines. Over the following year the five largest pure-play packaged-food stocks fell roughly 18% while the S&P 500 gained 24%, and although fears eased in 2024 they returned in 2025 as GLP-1 prices were cut.","evidence":"Staples gauge -2.7% on 2023-10-06, worst week since Sept 2022; five largest packaged-food stocks -18% vs S&P 500 +24% over the following year","sources":[{"title":"Business Insider: Food retailers and producers slammed as GLP-1 drugs raise alarms","url":"https://businessinsider.nl/food-retailers-and-producers-are-getting-slammed-as-glp-1-drugs-like-ozempic-raise-growing-alarms-about-demand"},{"title":"Manhattan Institute: Will GLP-1 drugs transform the food business?","url":"https://manhattan.institute/article/will-glp-1-drugs-transform-the-food-business"},{"title":"Penn Mutual AM: GLP-1 drugs drop more than just weight","url":"https://www.pennmutualam.com/market-insights-news/blogs/chart-of-the-week/2023-10-19-glp-1-drugs-drop-more-than-just-weight"}]},{"id":"defense-2023-israel-hamas","date":"2023-10-09","end_date":null,"sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"moderate","driver_type":"geopolitical","title":"October 7 attack on Israel: Northrop +11%, Lockheed's best non-earnings day since 2020","summary":"On the first trading day after Hamas's October 7, 2023 attack, Northrop Grumman rose about 11%, Lockheed Martin 8-9% (its biggest non-earnings gain since March 2020), General Dynamics 9% and RTX 4-5% while the S&P 500 slipped. The move came with Ukraine aid stalled in Congress and ahead of the White House's $106bn supplemental request on October 20, and it started a defense re-rating that ran through 2024 as munitions demand and the Red Sea conflict widened.","evidence":"Northrop Grumman +11% and Lockheed Martin +8-9% on 2023-10-09.","sources":[{"title":"Lockheed Martin, Northrop Grumman stocks notch best days in years amid Israel-Hamas conflict (Forbes)","url":"https://www.forbes.com/sites/dereksaul/2023/10/09/lockheed-martin-northrop-grumman-stocks-notch-best-days-in-years-amid-israel-hamas-conflict/"},{"title":"Defense stocks jump as war rages between Israel and Hamas (Yahoo Finance)","url":"https://finance.yahoo.com/news/defense-stocks-jump-war-rages-000436010.html"}]},{"id":"en-2023-shale-consolidation-wave","date":"2023-10-11","end_date":"2024-12-31","sector":"energy","subindustries":["exploration_production","integrated"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"Exxon-Pioneer and Chevron-Hess: the shale M&A wave","summary":"Exxon's ~$60bn all-stock deal for Pioneer (October 11, 2023) and Chevron's $53bn deal for Hess (October 23) started a consolidation wave (Diamondback-Endeavor, ConocoPhillips-Marathon Oil) driven by scarce Tier-1 Permian inventory. The deals shrank the public E&P universe and shifted capital toward the integrateds, but with oil flat around $75 the sector lagged: XLE -0.6% in 2023 and +5.6% in 2024 versus 26% and 25% for the S&P 500.","evidence":"XOM-Pioneer ~$60bn (Oct 11, 2023) and CVX-Hess $53bn (Oct 23, 2023); XLE -0.6% in 2023 vs SPY +26.2%","sources":[{"title":"Hart Energy: Chevron buys Hess for $53B, historic M&A bonanza continues","url":"https://hartenergy.com/exclusives/chevron-buys-hess-53b-historic-ma-bonanza-continues-206929"},{"title":"Natural Gas World: Two mega-deals mark major step in US oil and gas consolidation","url":"https://naturalgasworld.com/two-mega-deals-mark-major-step-in-us-oil-and-gas-consolidation-gas-in-transition-108522"},{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"}]},{"id":"net-lease-2023-realty-income-spirit","date":"2023-10-30","end_date":"2024-01-23","sector":"real_estate","subindustries":["net_lease_specialty_reits"],"direction":"mixed","magnitude":"minor","driver_type":"ma","title":"Realty Income buys Spirit Realty for $9.3bn with the 10-year near 5%","summary":"Realty Income announced an all-stock acquisition of Spirit Realty Capital on October 30, 2023 at 0.762 shares per Spirit share, a 15% premium, for an enterprise value of about $9.3bn and a combined company of roughly $63bn. The deal came in the same fortnight the 10-year Treasury touched 5%, when net-lease REITs traded at their widest discounts to NAV since 2020 and external growth through equity issuance had stalled; buying a peer at a discount was the only accretive use of expensive stock. Spirit holders approved the deal with 99.8% support and it closed in January 2024.","evidence":"Exchange ratio 0.762 Realty Income shares per Spirit share, a 15% premium (announced 2023-10-30).","sources":[{"title":"Realty Income to acquire Spirit Realty Capital in $9.3 billion transaction (PR Newswire)","url":"https://www.prnewswire.com/news-releases/realty-income-to-acquire-spirit-realty-capital-in-9-3-billion-transaction-301971059.html"},{"title":"Realty Income 8-K on Spirit merger (SEC)","url":"https://www.sec.gov/Archives/edgar/data/726728/000110465923112361/tm2329370d1_ex99-1.htm"}]},{"id":"re-2024-office-rto-bounce-and-relapse","date":"2023-11-01","end_date":"2026-09-30","sector":"real_estate","subindustries":["office_reits"],"direction":"mixed","magnitude":"major","driver_type":"positioning","title":"Office REITs: 2024 return-to-office bounce, then renewed de-rating","summary":"From the November 2023 low, return-to-office mandates, falling rates and trophy-asset leasing produced a violent short squeeze: office returned 21.5% in 2024 and SL Green 49% in 2023 and 58% in 2024. The trade reversed as rates rose and CMBS maturities hit: office lost 14% in 2025 (SL Green -29%) and was down 10.8% for the first nine months of 2026, the worst equity sector, with only 2.7% YTD by Nareit's Q3 cut.","evidence":"Office REITs +21.50% in 2024, -13.99% in 2025, -10.77% YTD through Sep 2026 (2nd Market Capital); SLG +58.3% (2024) and -29.0% (2025)","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2025","url":"https://www.reit.com/sites/default/files/2026-01/MediaFactSheet_Dec-2025.pdf"},{"title":"2nd Market Capital: The State of REITs, October 2026 edition","url":"https://www.2ndmarketcapital.com/2026/10/28/the-state-of-reits-october-2026-edition/"},{"title":"ChartRow SLG calendar-year returns","url":"https://chartrow.com/quote/slg/returns"}]},{"id":"cs-2023-estee-lauder-collapse","date":"2023-11-01","end_date":null,"sector":"consumer_staples","subindustries":["household_personal"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Estee Lauder's China travel-retail bust","summary":"Estee Lauder cut its fiscal 2024 outlook on a slower recovery in Asia travel retail (Hainan, Korea) and mainland China and fell 18.9% to $104.51 on November 1 2023, its largest one-day drop since the 1995 IPO and a six-year low; organic sales were down 8% in the quarter. From a January 2022 peak above $370 the company lost more than $100 billion of value over three years, the clearest casualty of the post-COVID China consumer disappointment within staples.","evidence":"EL -18.9% to $104.51 on 2023-11-01, largest drop since 1995 IPO; peak above $370 in January 2022","sources":[{"title":"AlphaStreet: Estee Lauder lowers FY2024 outlook on slow growth in China","url":"https://news.alphastreet.com/estee-lauder-el-lowers-full-year-2024-outlook-on-slow-growth-in-china"},{"title":"Fortune via AOL: Estee Lauder has lost $100 billion in value in three years","url":"https://www.aol.com/finance/est-e-lauder-lost-100-103000729.html"},{"title":"Investing.com/Reuters: Estee Lauder cuts annual profit outlook on weaker Asia travel retail","url":"https://m.investing.com/news/stock-market-news/estee-lauder-cuts-annual-profit-outlook-on-weaker-recovery-in-asia-travel-retail-3216792?ampMode=1"}]},{"id":"hc-2023-glp1-boom","date":"2023-11-08","end_date":"2024-06-30","sector":"healthcare","subindustries":["pharma"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"GLP-1 boom: Zepbound approval and the Lilly/Novo re-rating","summary":"The FDA approved Lilly's Zepbound (tirzepatide) for obesity on November 8 2023 after trials showing about 18% placebo-adjusted weight loss, following Novo's Wegovy outcomes data earlier in the year. Capital poured into the two GLP-1 leaders at the expense of the rest of pharma: Novo became Europe's most valuable company in 2023 and hit a $604 billion market cap in March 2024, while Lilly went on to a $1 trillion valuation on November 21 2025, the first for a health-care company.","evidence":"Zepbound approved 2023-11-08 (18% weight loss at 15 mg vs placebo); Novo market cap $604B in March 2024; Lilly $1T on 2025-11-21","sources":[{"title":"FDA: FDA approves new medication for chronic weight management (Zepbound)","url":"https://www.fda.gov/news-events/press-announcements/fda-approves-new-medication-chronic-weight-management"},{"title":"Wikipedia: Novo Nordisk","url":"https://en.wikipedia.org/wiki/Novo_Nordisk"},{"title":"Wikipedia: Eli Lilly and Company","url":"https://en.wikipedia.org/wiki/Eli_Lilly_and_Company"}]},{"id":"en-2024-midstream-gas-demand","date":"2024-01-02","end_date":"2024-12-31","sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Pipelines re-rate on LNG exports and data-center gas demand","summary":"Natural-gas pipelines became an AI derivative in 2024 as analysts projected 3.5% annual gas demand growth from LNG, reshoring and roughly 300 data centers under construction: Williams returned 49%, Kinder Morgan 64% (including a 15% November post-election jump on permitting hopes), AMLP 23% and Cheniere 27%, all beating the S&P 500. The group also offered yield with less commodity beta than E&Ps.","evidence":"KMI +64.4% and WMB +49.3% in 2024; AMLP +22.8% in 2024","sources":[{"title":"Zacks via Tiger: Williams up 49% in 2024","url":"https://itiger.com/news/2492110694"},{"title":"Seeking Alpha: Does the Kinder Morgan AI-rally have further to run?","url":"https://seekingalpha.com/article/4746959-does-the-kinder-morgan-ai-rally-have-further-to-run"},{"title":"ChartRow KMI calendar-year returns","url":"https://chartrow.com/quote/kmi/returns"}]},{"id":"en-2024-oilfield-services-downturn","date":"2024-01-02","end_date":"2025-10-20","sector":"energy","subindustries":["oilfield_services"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Services slump: falling US rig count and E&P capital discipline","summary":"With US producers prioritizing buybacks and consolidation cutting the number of customers, the US rig count fell steadily and pressure-pumping pricing eroded; OIH lost 10.5% in 2024 and SLB 24.5%, and Halliburton traded at multiyear lows in summer 2025 with North American revenue down 7% sequentially in Q4 2025. International and offshore work (Middle East, deepwater) was the only growth, and the group only recovered after Halliburton's October 2025 cost-cut plan.","evidence":"OIH -10.5% and SLB -24.5% in 2024 vs XLE +5.6%; HAL at multiyear lows in summer 2025, NAM revenue -7% q/q in Q4 2025","sources":[{"title":"Motley Fool: Cost cuts power Halliburton's big run (Feb 2026)","url":"https://www.fool.com/investing/2026/02/11/cost-cuts-power-halliburtons-big-run"},{"title":"ChartRow SLB calendar-year returns","url":"https://chartrow.com/quote/slb/returns"},{"title":"ChartRow OIH calendar-year returns","url":"https://chartrow.com/quote/oih/returns"}]},{"id":"en-2024-refiner-margin-normalization","date":"2024-01-02","end_date":"2024-12-31","sector":"energy","subindustries":["refining"],"direction":"out","magnitude":"moderate","driver_type":"commodity","title":"Crack spreads normalize after the 2022-23 windfall","summary":"New capacity in the Middle East, Nigeria and China plus softer diesel demand pulled margins back toward mid-cycle in 2024; the CRAK refiners ETF fell 15% and Valero 3% in a year the S&P 500 gained 25%. Announced closures (LyondellBasell Houston, Phillips 66 Los Angeles) set up the 2025-26 rebound.","evidence":"CRAK -15.1% and VLO -3.0% in 2024 vs SPY +24.9%","sources":[{"title":"ChartRow CRAK calendar-year returns","url":"https://chartrow.com/quote/crak/returns"},{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"}]},{"id":"re-2024-sunbelt-supply-wave","date":"2024-01-02","end_date":"2026-05-14","sector":"real_estate","subindustries":["residential_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"macro","title":"Sunbelt apartment supply peaks; coastal landlords outperform","summary":"Record 2021-22 starts delivered a Sunbelt supply wave in 2024-25: Bank of America downgraded Camden and MAA as new-lease rents turned negative, apartments returned 20.5% in 2024 on rate-cut hopes but -8.6% in 2025 and single-family rentals -10.2%. By May 2026 coastal and California REITs (Equity Residential, AvalonBay, Essex) were posting the strongest pricing while Austin, Phoenix and Denver lagged; residential is the only REIT sector negative for 2026.","evidence":"Apartment REITs +20.48% (2024) then -8.56% (2025); Single Family Homes -10.24% in 2025; Residential -3.8% YTD at Sep 30, 2026","sources":[{"title":"Multifamily Dive: Apartment REITs hit with analyst downgrades on supply","url":"https://www.multifamilydive.com/news/Apartment-REITs-analyst-downgrades-aprtment-supply/700779/"},{"title":"GlobeSt: Multifamily REITs point to pricing outperformance in California and coastal markets (May 2026)","url":"https://www.globest.com/amp/2026/05/14/multifamily-reits-point-to-pricing-outperformance-in-california-and-coastal-markets/"},{"title":"Nareit property sector returns Sep 30, 2026","url":"https://www.reit.com/sites/default/files/returns/prop.pdf"}]},{"id":"hyperscalers-2024-capex-acceleration","date":"2024-01-02","end_date":"2024-12-31","sector":"hyperscalers","subindustries":["semiconductors","hardware","memory","infrastructure_software_cyber"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"2024 AI capex acceleration: hyperscaler spending heads toward $450 billion a year","summary":"Combined capital spending by Alphabet, Amazon, Meta, Microsoft and Oracle rose from $37.8 billion in Q1 2023 to $140.6 billion in Q4 2025 (3.7x), with 2024 totals around $226 billion for the big four and 2025 around $410-450 billion. The 2024 step-up, announced on successive earnings calls, pushed capital into the suppliers (Nvidia reached $3 trillion on 5 June 2024) and into power, cooling and networking, while raising the free-cash-flow questions that resurfaced in 2026.","evidence":"Combined hyperscaler capex $37.8 billion in Q1 2023 vs $140.6 billion in Q4 2025 (Epoch AI); Nvidia crossed $3 trillion on 2024-06-05.","sources":[{"title":"Hyperscaler capex has quadrupled since GPT-4's release (Epoch AI)","url":"https://epoch.ai/data-insights/hyperscaler-capex-trend"},{"title":"Big Tech AI capex 2025-2026 (ValueAdd VC)","url":"https://valueaddvc.com/blog/big-tech-ai-capex-in-2025-microsoft-google-meta-amazon-and-the-spending-race"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"id":"utilities-2024-ai-power-trade","date":"2024-01-02","end_date":"2024-12-31","sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Utilities become the AI-power trade: +23% in 2024","summary":"Data-center load forecasts (Goldman Sachs expected data centers to be the largest driver of US power demand growth through 2030) and Fed cuts starting 18 September 2024 turned the worst sector of 2023 into one of the best of 2024: XLU was up 22% year-to-date by 11 September and utilities returned 23.4% for the year against 25.0% for the S&P 500, with independent power producers Vistra (+108% YTD by September) and Constellation (+60%) leading.","evidence":"XLU +22% year-to-date as of 2024-09-11 (then the top-performing sector); S&P 500 Utilities 2024 total return +23.4%.","sources":[{"title":"This under-the-radar defensive AI sector quietly outperforms (Benzinga, Sept 2024)","url":"https://benzinga.com/analyst-ratings/analyst-color/24/09/40823561/this-under-the-radar-defensive-ai-sector-quietly-outperforms-all-others-despite-rec"},{"title":"Utilities outperform amid enthusiasm over AI electricity demand (Yahoo Finance)","url":"https://nz.finance.yahoo.com/news/utilities-outperform-the-broader-markets-amid-enthusiasm-over-ai-electricity-demand-175702728.html"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"FOMC statement, 18 September 2024","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20240918a.htm"}]},{"id":"ind-2024-boeing-door-plug","date":"2024-01-05","end_date":"2024-11-04","sector":"industrials","subindustries":["commercial_aerospace"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Alaska Airlines door-plug blowout, FAA production cap and the machinists' strike","summary":"A door plug blew off a 737 MAX 9 on January 5, 2024; Boeing fell 8% on the first session and Spirit AeroSystems 11%, and on January 24 the FAA capped MAX output at 38 a month. An eight-week machinists' strike from September idled factories, Boeing raised $24bn of equity and lost roughly $35bn of market value in 2024, returning -32% in a year the S&P 500 gained 25%.","evidence":"BA -8% on Jan 8, 2024 and -32.1% for 2024 vs SPY +24.9%; FAA cap of 38 MAX/month imposed Jan 24, 2024","sources":[{"title":"Spokesman-Review: Boeing's stock drops as investors assess fallout","url":"https://www.spokesman.com/stories/2024/jan/08/boeings-stock-drops-as-investors-assess-fallout-fr"},{"title":"Skift: FAA halts Boeing 737 MAX production expansion","url":"https://skift.com/2024/01/24/faa-halts-boeing-737-max-production-expansion"},{"title":"AOL: Boeing lost $35 billion in market cap this year","url":"https://www.aol.com/boeing-lost-35-billion-market-195847020.html"}]},{"id":"ind-2024-deere-ag-downturn","date":"2024-02-15","end_date":"2025-05-15","sector":"industrials","subindustries":["machinery"],"direction":"out","magnitude":"moderate","driver_type":"commodity","title":"Farm income slides 25% and Deere cuts guidance twice","summary":"After net farm income hit a record $182bn in 2022 with corn near $6, prices fell toward $4 and USDA projected 2024 farm income down 25.5%, the biggest drop since 2006. Deere cut its FY2024 profit outlook in February and again in May 2024, shares fell as much as 5.5% on the first cut and traded 18% below their July 2023 record, and ag equipment entered a two-year dealer destocking cycle.","evidence":"USDA projected 2024 farm income -25.5% to $116.1bn; Deere cut FY24 net income guidance to $7.5-7.75bn (Feb 2024) then ~$7bn (May 2024)","sources":[{"title":"Grainews/Reuters: Deere cuts 2024 profit forecast","url":"https://www.grainews.ca/daily/deere-cuts-2024-profit-forecast-as-sliding-farm-income-stifles-demand"},{"title":"BNN Bloomberg: Deere cuts outlook with farmer demand easing","url":"https://www.bnnbloomberg.ca/deere-cuts-2024-profit-outlook-with-farmer-demand-easing-1.2035230"}]},{"id":"fintech-2024-capital-one-discover","date":"2024-02-19","end_date":"2025-05-18","sector":"financials","subindustries":["banks","fintech_payments"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Capital One buys Discover for $35.3 billion","summary":"Capital One announced an all-stock acquisition of Discover Financial valued at $35.3 billion on 19 February 2024; regulators approved it in April 2025 and it closed on 18 May 2025. The deal created a card issuer with its own payment network, a competitive signal for Visa and Mastercard, and its approval under the new administration marked the reopening of large-bank M&A after years of regulatory resistance.","evidence":"Deal announced 2024-02-19 at $35.3 billion; completed 2025-05-18.","sources":[{"title":"Capital One (Wikipedia)","url":"https://en.wikipedia.org/wiki/Capital_One"}]},{"id":"hc-2024-change-healthcare","date":"2024-02-21","end_date":"2024-04-16","sector":"healthcare","subindustries":["managed_care","healthcare_technology","healthcare_facilities_services"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Change Healthcare ransomware attack","summary":"Hackers breached UnitedHealth's Change Healthcare claims-clearing unit on February 21 2024, paralysing provider payments for weeks. The attack cost $872 million in Q1 alone, an estimated $1.15-1.35 per share for the year, and UnitedHealth advanced about $9 billion of interest-free loans to providers. UNH was down about 15% year-to-date going into April earnings; providers and health-IT names with claims exposure were hit on cash-flow fears.","evidence":"Q1 2024 cyberattack cost $872M; full-year impact $1.15-1.35 per share; ~$9B of provider advances (UNH 10-Q)","sources":[{"title":"Healthcare Dive: Change cyberattack cost UnitedHealth $872M in Q1","url":"https://www.healthcaredive.com/news/change-cyberattack-unitedhealth-cost-q1-earnings/713288/"},{"title":"UnitedHealth Group 10-Q, Q1 2024","url":"https://www.sec.gov/Archives/edgar/data/731766/000073176624000155/unh-20240331.htm"}]},{"id":"en-2024-nuclear-ipp-ai-power","date":"2024-03-04","end_date":"2025-12-31","sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Data-center power trade: nuclear PPAs, record PJM auctions and the IPP re-rating","summary":"Amazon's $650m purchase of Talen's Susquehanna data-center campus (March 2024), the July 2024 PJM capacity auction clearing at $269.92/MW-day (from $28.92), and Constellation's 20-year Microsoft PPA to restart Three Mile Island (September 20, 2024) turned merchant generators into AI plays: Vistra returned 262% and Constellation 93% in 2024. Trump's May 23, 2025 nuclear executive orders then sent Oklo up 130% in a month and NLR up 28% in May, and PJM auctions set further records at $329 (July 2025) and $333 (December 2025).","evidence":"VST +261.5% and CEG +92.7% in 2024; CEG +32.2% in Sept 2024 on the Microsoft TMI PPA; PJM capacity price $269.92/MW-day (2025/26) then $329.17 (2026/27)","sources":[{"title":"Motley Fool: Here's why this stock soared 32% in September (Constellation)","url":"https://www.fool.com/investing/2024/10/03/heres-why-this-stock-soared-322-in-september-makin"},{"title":"Utility Dive: PJM capacity auction, Vistra and Constellation","url":"https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-vistra-constellation/722872/"},{"title":"Benzinga: Uranium stocks hit 17-year highs as May 2025 rally marks best month on record","url":"https://www.benzinga.com/government/regulations/25/05/45650179/uranium-stocks-hit-17-year-highs-as-mays-rally-marks-best-month-on-record"},{"title":"ChartRow VST calendar-year returns","url":"https://chartrow.com/quote/vst/returns"}]},{"id":"hardware-2024-supermicro-boom-bust","date":"2024-03-04","end_date":"2024-10-30","sector":"technology","subindustries":["hardware"],"direction":"mixed","magnitude":"major","driver_type":"earnings","title":"Super Micro: S&P 500 entry, Hindenburg short, auditor resignation","summary":"Super Micro's market value rose from $4.5 billion at the end of 2022 to about $60 billion by March 2024 on AI-server demand, and the stock jumped more than 18% on 4 March 2024 when it was added to the S&P 500. A Hindenburg Research short report in August 2024 (stock -22% on 28 August) and EY's resignation as auditor on 30 October 2024 (stock -33%) then exposed governance risk in the AI hardware supply chain, and capital rotated to Dell and the networking names.","evidence":"Super Micro +18% on 2024-03-04 S&P 500 inclusion; -33% on 2024-10-30 after EY resigned as auditor.","sources":[{"title":"Super Micro Computer (Wikipedia)","url":"https://en.wikipedia.org/wiki/Super_Micro_Computer"}]},{"id":"datacenter-2024-talen-amazon","date":"2024-03-04","end_date":"2024-12-31","sector":"datacenter_power","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Talen sells a nuclear-powered data-center campus to Amazon","summary":"Talen Energy announced the sale of its Cumulus data-center campus next to the Susquehanna nuclear plant to Amazon Web Services for $650 million, with a long-term power purchase agreement, in March 2024. It was the first large 'behind-the-meter' nuclear-to-data-center deal and the trigger for the re-rating of independent power producers (Vistra +108% and Constellation +60% year-to-date by September 2024).","evidence":"Talen's Cumulus campus sold to AWS for $650 million with a PPA from the Susquehanna plant (announced March 2024); Vistra +107.95% YTD by 2024-09-11.","sources":[{"title":"Talen Energy (Wikipedia)","url":"https://en.wikipedia.org/wiki/Talen_Energy"},{"title":"This under-the-radar defensive AI sector quietly outperforms (Benzinga, Sept 2024)","url":"https://benzinga.com/analyst-ratings/analyst-color/24/09/40823561/this-under-the-radar-defensive-ai-sector-quietly-outperforms-all-others-despite-rec"}]},{"id":"re-2024-nar-commission-settlement","date":"2024-03-15","end_date":"2024-08-17","sector":"real_estate","subindustries":["real_estate_services"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"NAR's $418m commission settlement hits brokerages and portals","summary":"The National Association of Realtors agreed on March 15, 2024 to pay $418m and end the practice of listing buyer-agent compensation on MLSs, threatening the 5-6% commission pool; Zillow fell 13.5%, Compass 14.3%, eXp 9.9% and Redfin 4.9% that day while CoStar (Homes.com) rose 8%. The rule change took effect in August 2024 and accelerated brokerage consolidation.","evidence":"Z -13.5%, COMP -14.3%, EXPI -9.9%, RDFN -4.9% on Mar 15, 2024; CSGP +8%","sources":[{"title":"BAM: Wall Street reacts to the NAR settlement","url":"https://nowbam.com/wall-street-reacts-to-the-nar-settlement/"},{"title":"TipRanks/The Fly: Zillow, Redfin drop after realtor group agrees to cut commissions","url":"https://www.tipranks.com/news/the-fly/zillow-redfin-drop-after-realtor-group-agrees-to-cut-commissions-2"}]},{"id":"hc-2024-ma-final-rate","date":"2024-04-02","end_date":"2024-04-05","sector":"healthcare","subindustries":["managed_care"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"2025 Medicare Advantage final rate notice disappoints","summary":"CMS finalised 2025 MA payment rates essentially unchanged from the January advance notice (a 3.7% headline that was effectively flat on benchmarks), breaking the pattern of final rates coming in above the proposal. Insurers fell 6-12% on April 2 and Humana, the most MA-exposed, lost about 11% for the week. CMS also said it saw no late-2023 utilisation surge, contradicting the insurers, which investors read as a margin squeeze into 2025.","evidence":"Health insurers fell ~6% to 12% on 2024-04-02; HUM -10.9% for the week","sources":[{"title":"Reuters via Investing.com: US health insurers slide as final MA rate sparks margin fears","url":"https://m.investing.com/news/stock-market-news/us-health-insurers-slide-as-final-medicare-advantage-rate-sparks-margin-hit-fears-3361136?ampMode=1"},{"title":"Motley Fool: Why Humana stock fell 10.9% this week","url":"https://www.fool.com/investing/2024/04/05/why-humana-stock-fell-109-this-week"}]},{"id":"datacenter-2024-ge-vernova-spin","date":"2024-04-02","end_date":null,"sector":"datacenter_power","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"tech_cycle","title":"GE Vernova spins off as the gas-turbine and grid play on AI power demand","summary":"GE Vernova began trading on 2 April 2024 as the power, wind and electrification spin-off from General Electric, just as data-center load growth created a shortage of gas turbines and grid equipment. The listing gave investors a liquid vehicle for the power-generation equipment cycle; the company later agreed in October 2026 to buy Trench Group for $9 billion to expand high-voltage grid gear.","evidence":"GE Vernova incorporated and listed on the NYSE as GEV on 2024-04-02.","sources":[{"title":"GE Vernova (Wikipedia)","url":"https://en.wikipedia.org/wiki/GE_Vernova"}]},{"id":"hc-2024-hims-compounded-glp1","date":"2024-05-20","end_date":"2025-02-21","sector":"healthcare","subindustries":["healthcare_technology"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Hims & Hers rides compounded GLP-1s during the semaglutide shortage","summary":"With Ozempic and Wegovy on the FDA shortage list, Hims & Hers began selling compounded injectable semaglutide in May 2024 at a fraction of branded prices, turning a telehealth platform into the fastest-growing GLP-1 channel and the standout digital-health stock of 2024. The trade depended entirely on the shortage designation, which the FDA lifted in February 2025, setting up the 2025 confrontation with Novo.","evidence":"Hims launched compounded semaglutide in May 2024 following the national shortage of branded Ozempic/Wegovy","sources":[{"title":"Wikipedia: Hims & Hers Health","url":"https://en.wikipedia.org/wiki/Hims_%26_Hers_Health"}]},{"id":"waste-2024-wm-stericycle","date":"2024-06-03","end_date":"2024-11-04","sector":"industrials","subindustries":["waste"],"direction":"mixed","magnitude":"minor","driver_type":"ma","title":"Waste Management buys Stericycle for $7.2bn to enter medical waste","summary":"WM agreed on June 3, 2024 to acquire Stericycle for $62 a share in cash (about $7.2bn including debt), its largest deal since Advanced Disposal, to add regulated medical waste and document destruction. Stericycle closed up 14.6% while WM traded flat to lower as investors weighed the turnaround risk and leverage against a stated path to synergies; the deal cleared DOJ review in September and closed on November 4, 2024. It extended the sector's pattern of using M&A and pricing, rather than volume, to compound earnings.","evidence":"Stericycle holders received $62.00 per share in cash; SRCL +14.6% on 2024-06-03.","sources":[{"title":"WM completes acquisition of Stericycle (WM investor relations)","url":"https://investors.wm.com/news-releases/news-release-details/wm-completes-acquisition-stericycle"},{"title":"Stericycle's $7.2B sale to WM clears DOJ antitrust review (Waste Dive)","url":"https://www.wastedive.com/news/stericycle-shareholder-vote-wm-transaction-doj/724310/"},{"title":"Waste Management's big move is a win for Stericycle (Seeking Alpha)","url":"https://seekingalpha.com/article/4697290-waste-managements-big-move-is-a-win-for-stericycle"}]},{"id":"cs-2025-walgreens-take-private","date":"2024-06-27","end_date":"2025-08-29","sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"Walgreens' collapse ends in a $10 billion take-private","summary":"Walgreens said in June 2024 that only about 75% of its 8,600 US stores were profitable and it would close more than 2,000 by 2027; the stock fell more than 55% between January and July 2024 and was removed from the Dow in February 2024 in favour of Amazon. In March 2025 Sycamore Partners agreed to take it private at $11.45 a share (about $10 billion equity, up to $23.7 billion including debt and contingent payments), closing in August 2025. Drugstores had become a value trap within staples retail as reimbursement pressure and front-end share loss compounded.","evidence":"WBA -55% from January to July 2024; Sycamore deal at $11.45/share (~$10B equity) announced March 2025, closed August 2025","sources":[{"title":"NBC News: Walgreens to go private in roughly $10 billion deal","url":"https://www.nbcnews.com/business/business-news/walgreens-go-private-roughly-10-billion-deal-rcna195243"},{"title":"Wikipedia: Walgreens Boots Alliance","url":"https://en.wikipedia.org/wiki/Walgreens_Boots_Alliance"}]},{"id":"cd-2024-nike-plunge","date":"2024-06-28","end_date":null,"sector":"consumer_discretionary","subindustries":["apparel_luxury"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Nike's worst day on record on a surprise sales-decline forecast","summary":"Nike fell 20% on June 28 2024, its biggest one-day drop ever, wiping about $28.4 billion of value, after guiding to a fiscal 2025 sales decline on China weakness, lifestyle-franchise fatigue and share loss to On and Hoka; at least six brokers downgraded. The stock had already lagged for two years, and the day confirmed that capital had rotated from the mega-brands to challenger brands and off-price retailers.","evidence":"NKE -20% on 2024-06-28, worst day on record, ~$28.41B of market value lost","sources":[{"title":"Al Jazeera: Nike stock plunges on surprise forecast of drop in sales","url":"https://www.aljazeera.com/economy/2024/6/28/nike-stock-plunges-on-surprise-forecast-of-drop-in-sales"},{"title":"Motley Fool: Nike's stock crashes, just do it and buy the dip","url":"https://www.fool.com/investing/2024/07/02/nikes-stock-crashes-just-do-it-and-buy-the-dip"}]},{"id":"re-2024-fed-cut-rally-and-reversal","date":"2024-07-01","end_date":"2024-12-31","sector":"real_estate","subindustries":["net_lease_specialty_reits","residential_reits","healthcare_reits","mortgage_reits","self_storage_reits"],"direction":"mixed","magnitude":"major","driver_type":"rates","title":"Q3 2024 rate-cut rally (+16.8%) and the Q4 reversal","summary":"Softer inflation and the Fed's 50bp cut on September 18, 2024 produced the best REIT quarter since 2009 (+16.8% in Q3), led by bond proxies: Realty Income went from about $50 to $65 and health care, apartments and storage re-rated. When the 10-year rebounded from 3.8% to 4.58% after the election, REITs gave back 8.15% in Q4 and finished 2024 up only 4.9% versus 25% for the S&P 500.","evidence":"All Equity REITs +16.79% in Q3 2024 and -8.15% in Q4 2024 (10-year yield 3.81% to 4.58%); O rose from ~$50 to ~$65 by Oct 2024","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2024","url":"https://www.reit.com/sites/default/files/2025-01/MediaFactSheet_Dec-2024.pdf"},{"title":"Motley Fool: 1 growth stock down 25% to buy right now (Realty Income, Oct 2024)","url":"https://www.fool.com/investing/2024/10/06/1-growth-stock-down-25-to-buy-right-now/"}]},{"id":"cyber-2024-crowdstrike-outage","date":"2024-07-19","end_date":"2024-08-08","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"mixed","magnitude":"major","driver_type":"earnings","title":"CrowdStrike update crashes 8.5 million Windows devices","summary":"A faulty CrowdStrike Falcon update on 19 July 2024 crashed about 8.5 million Windows devices, cancelled 5,078 flights and cost Delta about $550 million; CrowdStrike fell more than 11% that day while Palo Alto Networks rose about 2.4%. The outage shifted share within cybersecurity toward platform rivals for several months but did not dent aggregate security budgets, and CrowdStrike recovered to new highs in 2025.","evidence":"About 8.5 million Windows devices affected on 2024-07-19; CrowdStrike shares fell more than 11% that day.","sources":[{"title":"2024 CrowdStrike-related IT outages (Wikipedia)","url":"https://en.wikipedia.org/wiki/2024_CrowdStrike-related_IT_outages"},{"title":"Palo Alto, SentinelOne, CyberArk and Fortinet rally after CrowdStrike outage (Benzinga)","url":"https://news.streetbeat.com/article/39857391"}]},{"id":"internet-2024-google-monopoly-ruling","date":"2024-08-05","end_date":"2025-09-02","sector":"technology","subindustries":["internet_platforms"],"direction":"mixed","magnitude":"major","driver_type":"regulatory","title":"Google ruled a search monopolist; remedies spare Chrome and the stock jumps 8%","summary":"Judge Amit Mehta ruled on 5 August 2024 that Google illegally maintained a monopoly in general search and text advertising, and the DOJ proposed a Chrome divestiture in November 2024. The 2 September 2025 remedies order barred exclusive search contracts and required data sharing but did not force the sale of Chrome or Android, and Alphabet rose about 8% on the news; Alphabet crossed $3 trillion on 15 September 2025.","evidence":"Liability ruling 2024-08-05; remedies order 2025-09-02 with no Chrome divestiture, Alphabet shares +8%.","sources":[{"title":"United States v. Google LLC (2020) (Wikipedia)","url":"https://en.wikipedia.org/wiki/United_States_v._Google_LLC_(2020)"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"id":"hc-2024-first-negotiated-prices","date":"2024-08-15","end_date":null,"sector":"healthcare","subindustries":["pharma","biotech_large"],"direction":"out","magnitude":"minor","driver_type":"policy","title":"CMS publishes first 10 negotiated Medicare drug prices","summary":"CMS announced the outcome of the first IRA negotiation cycle: prices for 10 drugs (including Eliquis, Jardiance, Xarelto, Januvia, Imbruvica and Enbrel) effective 2026 that would have cut aggregate net Medicare spending by about 22%, or roughly $6 billion, had they applied in 2023. Stocks barely moved because the discounts were close to existing net prices, which reassured investors that the program was manageable, but it set the template for successive annual rounds.","evidence":"Negotiated prices equal to 22% lower aggregate net spending (~$6B) vs 2023; announced 2024-08-15","sources":[{"title":"CMS fact sheet: Negotiated prices for initial price applicability year 2026","url":"https://www.cms.gov/newsroom/fact-sheets/medicare-drug-price-negotiation-program-negotiated-prices-initial-price-applicability-year-2026"}]},{"id":"cs-2024-dollar-general-plunge","date":"2024-08-29","end_date":"2024-12-31","sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Dollar General's 32% drop exposes the low-income consumer","summary":"Dollar General fell 32% on August 29 2024, its biggest drop since its 2009 IPO, after cutting full-year guidance and saying its core lower-income customers were financially constrained; Dollar Tree fell in sympathy. The stock ended 2024 down 44% as Walmart took share from dollar stores, splitting staples retail into winners (Walmart, Costco) and losers (dollar stores, drugstores) that persisted into 2025-2026.","evidence":"DG -32% on 2024-08-29, biggest decline since its 2009 IPO; DG -44% in 2024","sources":[{"title":"Bloomberg: Dollar General drops as forecast cut amid faltering turnaround","url":"https://www.bloomberg.com/news/articles/2024-08-29/dollar-general-drops-as-forecast-cut-amid-faltering-turnaround"},{"title":"Motley Fool: Why Dollar General stock fell 44% in 2024","url":"https://www.fool.com/investing/2025/01/14/why-dollar-general-stock-fell-44-in-2024"}]},{"id":"semis-2024-nvidia-record-drop","date":"2024-09-03","end_date":null,"sector":"technology","subindustries":["semiconductors"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Nvidia's $279 billion one-day loss, the record before DeepSeek","summary":"On 3 September 2024 Nvidia lost about $279 billion of market value in a single session, then the largest one-day loss for any US company, amid weak manufacturing data and reports of a DOJ antitrust inquiry weeks after it had become the world's most valuable company on 18 June 2024. The episode showed how concentrated index risk had become in one AI supplier; the record lasted less than five months until the DeepSeek rout.","evidence":"Nvidia one-day market-value loss of about $279 billion on 2024-09-03 (cited as the prior record by Bloomberg on 2025-01-27).","sources":[{"title":"Nvidia's $589 billion DeepSeek rout is largest in market history (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2025-01-27/asml-sinks-as-china-ai-startup-triggers-panic-in-tech-stocks"},{"title":"Nvidia (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nvidia"}]},{"id":"software-2024-palantir-sp500","date":"2024-09-06","end_date":"2025-11-30","sector":"technology","subindustries":["application_software"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"Palantir joins the S&P 500 and becomes the index's most expensive stock","summary":"S&P announced Palantir's inclusion on 6 September 2024 and the stock rose 14% the next session; by 2025 its market value exceeded $400 billion and in November 2025 it was the most expensive S&P 500 stock at about 85 times forward sales. Palantir became the retail and momentum proxy for 'AI software that works', the exception that highlighted how the rest of application software was derating on agent-substitution fears.","evidence":"Palantir +14% on the first trading day after the 2024-09-06 S&P 500 inclusion announcement; about 85x forward sales in November 2025.","sources":[{"title":"Palantir Technologies (Wikipedia)","url":"https://en.wikipedia.org/wiki/Palantir_Technologies"}]},{"id":"biotech-2024-fed-50bp-cut","date":"2024-09-18","end_date":"2024-09-19","sector":"healthcare","subindustries":["biotech_smid"],"direction":"in","magnitude":"moderate","driver_type":"rates","title":"Fed's 50bp cut: XBI's 'anticlimactic' reaction after a six-month pre-rally","summary":"The Fed opened its easing cycle with a 50bp cut on September 18, 2024, the largest since 2008. XBI spiked about $2 at the 2pm announcement, closed flat near $100, and rose about 2% the next morning; analysts called the reaction a net positive but anticlimactic because SMID biotech had already rallied hard from its spring lows in anticipation. The episode showed that cost-of-capital trades in long-duration biotech are front-run rather than bought on the news.","evidence":"XBI closed near $100 on 2024-09-18 after an intraday spike; up about 2% on 2024-09-19 morning.","sources":[{"title":"After Fed rate cut, biotech stocks face 'anticlimactic' reality (BioSpace)","url":"https://www.biospace.com/business/after-fed-rate-cut-biotech-stocks-face-anticlimactic-reality"},{"title":"Can the Fed's rate cut change biotech's 'new normal'? (BioPharma Dive)","url":"https://www.biopharmadive.com/news/biotech-interest-rates-impact-startups-venture-capital/727479/"}]},{"id":"housing-2024-fed-50bp-cut","date":"2024-09-18","end_date":"2024-09-19","sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"moderate","driver_type":"rates","title":"Fed's 50bp cut: homebuilders pop, then mortgage rates rise anyway","summary":"Homebuilders rallied on the 50bp cut: XHB rose more than 3% before the open on September 19, 2024, Lennar nearly 4%, and D.R. Horton, PulteGroup and Toll 1-3%, with the S&P 500 Homebuilding index already up more than 30% year to date against 17% for the S&P 500. The rally proved to be the top: the 10-year yield rose roughly 80bp over the following two months and mortgage rates went back above 7%, so the group gave back its gains into early 2025. It is the clearest recent example of builders pricing the easing cycle before it arrived.","evidence":"S&P 500 Homebuilding index +30% year-to-date vs S&P 500 +17% as of 2024-09-19; XHB +3% premarket.","sources":[{"title":"US homebuilder stocks surge on hopes for demand boost after Fed rate cuts (Reuters via Yahoo)","url":"https://finance.yahoo.com/news/us-homebuilder-stocks-surge-hopes-121147068.html/"},{"title":"Stock market news for September 19, 2024 (CNBC)","url":"https://www.cnbc.com/2024/09/18/stock-market-today-live-updates.html"}]},{"id":"nuclear-2024-three-mile-island","date":"2024-09-20","end_date":null,"sector":"nuclear","subindustries":["regulated_utilities"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Constellation to restart Three Mile Island for Microsoft","summary":"Constellation announced on 20 September 2024 that it would restart Three Mile Island Unit 1 (renamed the Crane Clean Energy Center) under a 20-year power purchase agreement with Microsoft for more than 800 MW; its shares were up about 14.4% by mid-morning and NuScale, Nano Nuclear and Oklo rallied in sympathy. The deal made existing nuclear fleets the scarcest asset in the AI power chain and started the 'nuclear renaissance' overlay.","evidence":"Constellation shares +14.4% by 10 a.m. ET on 2024-09-20 on the Three Mile Island restart and Microsoft PPA.","sources":[{"title":"Why Constellation, NuScale, Nano Nuclear and Oklo stocks all popped today (Motley Fool)","url":"https://www.fool.com/investing/2024/09/20/constellation-nuscale-nano-nuclear-stocks-popped"},{"title":"Constellation Energy (Wikipedia)","url":"https://en.wikipedia.org/wiki/Constellation_Energy"}]},{"id":"nuclear-2024-google-amazon-smr-deals","date":"2024-10-14","end_date":"2024-10-16","sector":"nuclear","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"tech_cycle","title":"Google and Amazon sign small modular reactor deals","summary":"Google agreed on 14 October 2024 to buy 500 MW from six to seven Kairos Power small modular reactors, with the first unit due by 2030, and Amazon joined X-energy in October 2024 to fund four Xe-100 reactors as part of a 5 GW program. The hyperscaler commitments gave pre-revenue SMR developers (Oklo, NuScale, X-energy) credible offtake narratives and pushed uranium and fuel-cycle names higher.","evidence":"Google-Kairos agreement for 500 MW with the first reactor by 2030 (announced 2024-10-14); Amazon-X-energy program targeting 5 GW.","sources":[{"title":"Kairos Power (Wikipedia)","url":"https://en.wikipedia.org/wiki/Kairos_Power"},{"title":"X-energy (Wikipedia)","url":"https://en.wikipedia.org/wiki/X-energy"}]},{"id":"semicap-2024-asml-bookings-miss","date":"2024-10-15","end_date":null,"sector":"technology","subindustries":["semicap"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"ASML's bookings miss: -16%, the worst day since 1998, and equipment stocks' worst since 2020","summary":"ASML's Q3 2024 results leaked a day early on October 15, 2024 showing net bookings of EUR 2.6bn against roughly EUR 5.4bn expected and a 2025 revenue guide cut to EUR 30-35bn, the lower half of the prior range, as non-AI demand (China, logic node delays) recovered slower than hoped. The stock fell 16% in Amsterdam, Applied Materials and Lam had their worst days since 2020, KLA its biggest drop in nearly a decade and the SOX lost 5.3%. It split the semiconductor trade into AI-exposed winners and a WFE cycle that was not recovering.","evidence":"ASML Q3 2024 net bookings EUR 2.6bn vs ~EUR 5.4bn consensus; shares -16% on 2024-10-15.","sources":[{"title":"ASML shares plunge as bookings miss signals chipmaker woes (Japan Times / Bloomberg)","url":"https://www.japantimes.co.jp/business/2024/10/16/companies/asml-shares-bookings-chipmaker/"},{"title":"ASML shares plunge as Q3 net bookings miss estimates (StreetInsider)","url":"https://www.streetinsider.com/Earnings/ASML+shares+plunge+as+Q3+net+bookings+miss+estimates,+outlook+disappoints/23836836.html"},{"title":"Why ASML stock lost 17% in October (Motley Fool)","url":"https://www.fool.com/investing/2024/11/04/why-asml-stock-lost-17-in-october/"}]},{"id":"banks-2024-election-rally","date":"2024-11-06","end_date":null,"sector":"financials","subindustries":["banks","capital_markets"],"direction":"in","magnitude":"major","driver_type":"election","title":"Trump's 2024 win: regional banks +13%, Goldman +13%, the biggest bank day since 2020","summary":"Banks were the sharpest winners of the November 6, 2024 post-election rally: KRE rose 13.4%, its largest gain since November 2020, Goldman Sachs 13%, JPMorgan 12% and the KBW Bank index 11% against a 2.5% rise in the S&P 500. Investors priced a lighter Basel III endgame, faster merger approvals and a steeper curve; the trade persisted into 2025 and was validated by the 2025 enhanced-SLR cut and the 2026 Basel re-proposal.","evidence":"KRE +13.4% on 2024-11-06, its largest one-day gain since November 2020.","sources":[{"title":"Regional bank stocks notch strongest day in 4 years (Benzinga)","url":"https://www.benzinga.com/etfs/sector-etfs/24/11/41788181/regional-bank-stocks-notch-strongest-day-in-4-years-why-analysts-expect-several-tailwinds-from-t"},{"title":"Bank stock prices soar on hopes that Trump will ease regulation (American Banker)","url":"https://www.americanbanker.com/news/bank-stock-prices-soar-on-hopes-that-trump-will-ease-regulation"},{"title":"Wall Street's Trump party could end in a hangover (Euromoney)","url":"https://www.euromoney.com/article/2dzrjdd21riuri4tnzeo0/banking/wall-streets-trump-party-could-end-in-a-hangover/"}]},{"id":"hc-2024-rfk-nomination","date":"2024-11-14","end_date":"2025-02-13","sector":"healthcare","subindustries":["pharma","biotech_large"],"direction":"out","magnitude":"moderate","driver_type":"election","title":"Trump picks RFK Jr. for HHS; vaccine makers sell off","summary":"Nine days after the 2024 election, reports that Trump would nominate vaccine sceptic Robert F. Kennedy Jr. as HHS Secretary sent Moderna down about 5.6%, Novavax 7%, Pfizer 2.6% and GSK 2% on November 14 2024, with further drops as the nomination advanced in January and was confirmed on February 13 2025. The move began a prolonged de-rating of vaccine and mRNA names and raised the perceived regulatory risk premium across pharma and biotech.","evidence":"MRNA -5.6%, NVAX -7%, PFE -2.6% on 2024-11-14","sources":[{"title":"NBC News: Vaccine maker stocks fall as Trump chooses RFK Jr. to lead HHS","url":"https://www.nbcnews.com/business/markets/vaccine-maker-stocks-fall-trump-chooses-rfk-jr-lead-hhs-rcna180236"},{"title":"Sherwood: Vaccine stocks tumbling on RFK Jr. nomination","url":"https://sherwood.news/business/vaccine-stocks-are-tumbling-on-news-of-rfk-jr-nomination-to-lead-hhs"}]},{"id":"staples-retail-2024-kroger-albertsons-blocked","date":"2024-12-10","end_date":"2024-12-11","sector":"consumer_staples","subindustries":["staples_retail"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Judge blocks the $25bn Kroger-Albertsons merger; Kroger rises, Albertsons sues","summary":"U.S. District Judge Adrienne Nelson sided with the FTC on December 10, 2024, finding the proposed divestiture of hundreds of stores to C&S Wholesale would not replace lost competition. Kroger closed up 5.14% at $60.73 as investors welcomed the end of a leveraged deal, while Albertsons fell 2-4%; Albertsons terminated the agreement the next day and sued Kroger for breach. The ruling closed the door on scale M&A as a response to Walmart and Costco share gains in grocery.","evidence":"Kroger closed +5.14% at $60.73 on 2024-12-10.","sources":[{"title":"Kroger stock up after judge blocks Albertsons deal (Benzinga)","url":"https://benzinga.com/z/42424808"},{"title":"Judge blocks Albertsons-Kroger $25 billion supermarket merger (NBC News)","url":"https://www.nbcnews.com/business/business-news/judge-blocks-albertsons-kroger-25-billion-supermarket-merger-rcna183677"}]},{"id":"ind-2025-ai-services-substitution-fear","date":"2025-01-02","end_date":"2026-03-15","sector":"industrials","subindustries":["professional_services"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"AI substitution fears crush staffing and data/payroll services","summary":"Robert Half lost 59% in 2025 and ADP 10% as investors concluded that AI agents would replace white-collar hiring, payroll seats and data lookups; the selloff climaxed on February 3, 2026 when Anthropic's Claude Cowork plug-ins triggered a $285bn one-day rout across software, information services and asset managers, with Thomson Reuters down a record 16% and the S&P software & services index falling 13% in five sessions. Staffing names bottomed in February-March 2026.","evidence":"RHI -59.1% in 2025 and ADP -10.2% in 2025; S&P 500 Software & Services index -13% over five sessions to Feb 4, 2026","sources":[{"title":"BNN Bloomberg: US software stocks hit by Anthropic wake-up call (Feb 4, 2026)","url":"https://www.bnnbloomberg.ca/business/2026/02/04/us-software-stocks-hit-by-anthropic-wake-up-call-on-ai-disruption/"},{"title":"Seeking Alpha: ADP, the selloff made it cheap","url":"https://seekingalpha.com/article/4918527-automatic-data-processing-the-selloff-automatically-made-it-cheap"},{"title":"ChartRow RHI calendar-year returns","url":"https://chartrow.com/quote/rhi/returns"}]},{"id":"en-2025-refiners-closures-rally","date":"2025-01-02","end_date":"2025-12-31","sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"major","driver_type":"commodity","title":"Refinery closures tighten product markets; refiners rally in a flat oil year","summary":"With roughly 400k b/d of US capacity closing and cheap crude from OPEC+ hikes, refiners decoupled from oil again: Valero returned 37% and the CRAK ETF 39% in 2025 while XLE gained 8% and E&Ps fell. Diesel tightness ahead of the 2026 war made the group the best-positioned energy sub-sector going into the Hormuz shock.","evidence":"VLO +37.0% and CRAK +39.1% in 2025 vs XLE +7.9% and XOP -2.2%","sources":[{"title":"ChartRow CRAK calendar-year returns","url":"https://chartrow.com/quote/crak/returns"},{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"}]},{"id":"re-2025-mortgage-reit-rally","date":"2025-01-02","end_date":"2025-12-31","sector":"real_estate","subindustries":["mortgage_reits"],"direction":"in","magnitude":"major","driver_type":"rates","title":"Agency mortgage REITs rally 26% on Fed cuts and a steeper curve","summary":"Three Fed cuts, a steeper curve, the end of QT and talk of releasing Fannie and Freddie from conservatorship made agency mortgage REITs the best-performing REIT group of 2025: the Nareit Mortgage REIT index returned 16% (home financing +26.4%, Annaly +40%) while equity REITs gained 2.3%. Net interest spreads were still compressing (AGNC 1.92% vs 3.06% in 2023), so the rally was mostly multiple and book-value recovery.","evidence":"FTSE Nareit Mortgage REITs +16.02% and Home Financing +26.37% in 2025 vs All Equity REITs +2.27%; NLY +40.0% in 2025","sources":[{"title":"Nareit: REITs post narrow gains in 2025","url":"https://www.reit.com/news/blog/market-commentary/reits-post-narrow-gains-2025"},{"title":"Motley Fool: Why AGNC's net interest spread matters more than its 14% yield","url":"https://www.fool.com/investing/2026/05/25/why-agnc-investments-net-interest-spread-matters-m/"},{"title":"ChartRow NLY calendar-year returns","url":"https://chartrow.com/quote/nly/returns"}]},{"id":"distribution-2025-uri-he-herc-bidding-war","date":"2025-01-14","end_date":"2025-02-19","sector":"industrials","subindustries":["industrial_distribution"],"direction":"mixed","magnitude":"minor","driver_type":"ma","title":"United Rentals bids $4.8bn for H&E, then Herc tops it: rental consolidation reprices","summary":"United Rentals agreed in January 2025 to buy H&E Equipment Services for $92 a share (about $4.8bn including debt) to extend its branch density in the Gulf Coast and Southeast. During the go-shop Herc Holdings offered $78.75 cash plus 0.1287 Herc shares, valued at $104.89 a share or $5.3bn, and United Rentals declined to match on February 19; H&E rose about 13% while Herc fell 7.3% at the close on dilution and integration worries. The contest showed that rental-penetration and mega-project narratives were still attracting strategic capital even as short-cycle industrial demand stagnated.","evidence":"Herc's winning offer: $78.75 cash plus 0.1287 Herc shares per H&E share, valued at $104.89 (2025-02-19).","sources":[{"title":"Herc's surprise bid for H&E makes rival United Rentals walk away (Reuters via Investing.com)","url":"https://www.investing.com/news/stock-market-news/united-rentals-to-walk-away-after-he-receives-superior-takeover-bid-from-herc-3874940"},{"title":"United Rentals drops $3.4 billion purchase of H&E Equipment (Transport Topics)","url":"https://www.ttnews.com/articles/united-rentals-drops-buy"},{"title":"Herc's $5.3bn power play snags H&E from United Rentals (International Rental News)","url":"https://www.internationalrentalnews.com/news/hercs-53b-power-play-snags-h-e-from-united-/8050928.article"}]},{"id":"ai-2025-stargate","date":"2025-01-21","end_date":null,"sector":"ai","subindustries":["infrastructure_software_cyber","semiconductors","hardware"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Stargate: a $500 billion OpenAI-Oracle-SoftBank data-center venture","summary":"On 21 January 2025 President Trump announced the Stargate Project, a joint venture of OpenAI, Oracle, SoftBank and MGX intended to invest up to $500 billion in US AI data centers over four years. The announcement made Oracle a core AI-infrastructure stock and signalled that frontier-model compute would be financed off hyperscaler balance sheets, the structure behind the 2025 'circular financing' deals and the 2026 credit stress.","evidence":"Stargate announced 2025-01-21 with an estimated $500 billion of investment over four years.","sources":[{"title":"OpenAI (Wikipedia)","url":"https://en.wikipedia.org/wiki/OpenAI"}]},{"id":"hc-2025-nih-cuts","date":"2025-01-22","end_date":"2026-01-31","sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"NIH funding freeze and grant terminations hit academic tools demand","summary":"On January 22 2025 the new administration froze NIH meetings, travel and hiring (affecting $47.4 billion of activity), followed by the proposed 15% cap on indirect costs and mass grant terminations; more than 5,800 grants were cancelled or suspended within a year and about 2,600 worth $1.4 billion remained suspended in January 2026. Academic and government labs are a mid-single-digit to low-teens share of tools revenue, so instrument makers (Bruker, Waters, Agilent, Thermo) guided to softer academic demand through 2025.","evidence":"More than 5,800 NIH grants cancelled or suspended within a year; ~2,600 grants worth $1.4B still suspended as of January 2026","sources":[{"title":"Wikipedia: National Institutes of Health (2025 funding disruptions)","url":"https://en.wikipedia.org/wiki/National_Institutes_of_Health"}]},{"id":"ind-2025-deepseek-power-selloff","date":"2025-01-27","end_date":"2025-01-27","sector":"industrials","subindustries":["electrical_equipment"],"direction":"out","magnitude":"moderate","driver_type":"tech_cycle","title":"DeepSeek shock: AI power-equipment stocks crash in a day","summary":"DeepSeek's claim that its model was trained at a fraction of US costs raised doubts about data-center electricity demand; GE Vernova fell as much as 18% and Vertiv 24% intraday on January 27, 2025, alongside 20-30% drops at the independent power producers. The move was the first real stress test of the AI power trade, and most of it was recovered within months as hyperscaler capex guidance kept rising.","evidence":"GEV -18% and VRT -24% intraday on Jan 27, 2025 (Barron's); CEG -20%, VST -28% (S&P Global)","sources":[{"title":"Barron's via Tiger: Constellation, Vertiv and GE Vernova tumble","url":"https://itiger.com/news/2506937248"},{"title":"S&P Global: IPP shares plunge in selloff tied to AI development","url":"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2025/1/independent-power-producer-shares-plunge-in-selloff-tied-to-ai-development-87276103"}]},{"id":"en-2025-deepseek-ipp-crash","date":"2025-01-27","end_date":"2025-01-27","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"DeepSeek day: independent power producers are the worst S&P stocks","summary":"On January 27, 2025 DeepSeek's cheap-training claims made independent power producers the worst-performing group in the S&P 500: Constellation fell 20%, Vistra 28% and Talen 22% as investors questioned the data-center load forecasts underpinning their PPAs. The group recovered within months, but the day marked the AI-power trade's dependence on hyperscaler capex narratives.","evidence":"CEG -20%, VST -28%, TLN -22% on Jan 27, 2025","sources":[{"title":"S&P Global: IPP shares plunge in selloff tied to AI development","url":"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2025/1/independent-power-producer-shares-plunge-in-selloff-tied-to-ai-development-87276103"},{"title":"Bloomberg: Power providers drop with Big Tech on DeepSeek AI worry","url":"https://www.bloomberg.com/news/articles/2025-01-27/global-tech-stock-selloff-spreads-to-power-equipment-providers"}]},{"id":"re-2025-data-center-reit-reset","date":"2025-01-27","end_date":"2025-12-31","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"2025 data-center REIT reset: DeepSeek, Equinix's capex guide and a -14% year","summary":"After two years of leadership, data-center REITs were the worst REIT sector of 2025 at -14.2%: DeepSeek knocked Equinix 7% and Digital Realty 12% on January 27, Equinix's June investor day raised capex and cut near-term AFFO growth guidance, and rates stayed high. Equinix lost 17% and Digital Realty 10% in 2025 even as hyperscale leasing stayed at records.","evidence":"Data Center REITs -14.20% in 2025 (worst sector); EQIX -16.9% and DLR -10.1% in 2025; EQIX -7%, DLR -12% on Jan 27, 2025","sources":[{"title":"Nareit REIT Industry Fact Sheet Dec 2025","url":"https://www.reit.com/sites/default/files/2026-01/MediaFactSheet_Dec-2025.pdf"},{"title":"Barchart: Analyst says ignore the panic and buy these 2 data center AI stocks","url":"https://www.barchart.com/story/news/30776762/analyst-ignore-the-panic-and-buy-these-2-data-center-ai-stocks"},{"title":"ChartRow EQIX calendar-year returns","url":"https://chartrow.com/quote/eqix/returns"}]},{"id":"ai-2025-deepseek-shock","date":"2025-01-27","end_date":"2025-01-28","sector":"ai","subindustries":["semiconductors","semicap","hardware","infrastructure_software_cyber","memory"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"DeepSeek shock: Nvidia loses $589 billion in a day","summary":"After DeepSeek's R1 model (released 20 January 2025, reportedly trained for under $6 million) topped the US App Store, Nvidia fell about 17% on 27 January 2025, erasing $589 billion, the largest one-day loss for any company; Broadcom fell more than 19%, Oracle about 15%, TSMC's ADRs more than 15% and ASML nearly 8%. The selloff extended to power and data-center names and introduced the 'capex efficiency' debate, although hyperscalers reaffirmed spending within days.","evidence":"Nvidia -17% on 2025-01-27, a record $589 billion one-day market-value loss.","sources":[{"title":"Nvidia's $589 billion DeepSeek rout is largest in market history (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2025-01-27/asml-sinks-as-china-ai-startup-triggers-panic-in-tech-stocks"},{"title":"DeepSeek: what it means for tech stocks (Fortune, 2025-01-28)","url":"https://fortune.com/2025/01/28/deepseek-what-it-means-for-tech-stocks-ai-startups-and-everything-in-between/"},{"title":"DeepSeek (Wikipedia)","url":"https://en.wikipedia.org/wiki/DeepSeek"}]},{"id":"ind-2025-rearm-europe-nato-5pct","date":"2025-02-17","end_date":"2025-06-25","sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"ReArm Europe and NATO's 5% target: the European defense supercycle","summary":"After Munich Security Conference remarks that NATO's target would be 'considerably more than 3%', Rheinmetall jumped 8% on February 17, 2025; the EU's €800bn ReArm Europe plan on March 4 and Germany's debt-brake exemption drove BAE, Thales and Rheinmetall to records, and the June 25 Hague summit set 5% of GDP (3.5% core) by 2035. US primes benefited from the global re-rating, with ITA returning 48.6% in 2025.","evidence":"ITA +48.6% in 2025 vs SPY +17.7%; EU ReArm plan sized at €800bn (Mar 4, 2025); NATO 5% of GDP by 2035 agreed June 2025","sources":[{"title":"Fortune: Europe announces unprecedented $840 billion rearmament plan","url":"https://fortune.com/europe/2025/03/04/europe-announces-unprecedented-840-billion-rearmament-plan-tackle-grave-threats-defense-giants-bae-thales-rheinmetall/"},{"title":"XTB: Rheinmetall shares pop 8% to new ATH","url":"https://www.xtb.com/en/market-analysis/rheinmetall-shares-pop-8-setting-new-ath-european-defense-sector-surges-on-budget-spending-shift"},{"title":"Oninvest: NATO countries will raise defense spending to 5% of GDP","url":"https://en.oninvest.com/article/nato-countries-will-raise-defense-spending-to-5-of-gdp-which-arms-manufacturers-will-benefit"},{"title":"ChartRow ITA calendar-year returns","url":"https://chartrow.com/quote/ita/returns"}]},{"id":"ind-2025-defense-doge-whiplash","date":"2025-02-19","end_date":"2025-04-07","sector":"industrials","subindustries":["defense"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"DOGE 8% cut memo, then a $1 trillion budget: defense whipsaws","summary":"On February 19, 2025 Defense Secretary Hegseth ordered plans for 8% annual cuts through 2030 and defense primes and Palantir sold off; on April 7 Trump said the FY2026 budget would be roughly $1 trillion and the group rallied, with the eventual request including reconciliation money for Golden Dome and shipbuilding. The episode showed that the Trump-era defense trade depends on priority shifts (missile defense, drones) more than on the topline.","evidence":"Feb 19, 2025 memo directed 8%/yr cut plans; Apr 7, 2025 $1T budget statement lifted defense stocks","sources":[{"title":"Military Times: White House eyes 8% cut to defense budget","url":"https://www.militarytimes.com/news/pentagon-congress/2025/02/19/white-house-eyes-8-cut-to-defense-budget-to-boost-trump-priorities/"},{"title":"Motley Fool: Defense stocks surge on trillion-dollar budget talk","url":"https://www.fool.com/investing/2025/04/08/defense-stocks-surge-on-trillion-dollar-budget-tal"}]},{"id":"cyber-2025-google-wiz","date":"2025-03-18","end_date":"2026-03-11","sector":"cybersecurity","subindustries":["infrastructure_software_cyber","internet_platforms"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Google agrees to buy Wiz for $32 billion","summary":"Alphabet announced an all-cash $32 billion acquisition of cloud-security firm Wiz on 18 March 2025, its largest deal ever, after Wiz had rejected a roughly $23 billion offer in July 2024 to pursue an IPO; the deal closed on 11 March 2026 after EU clearance. The price re-rated private and public cloud-security assets and confirmed hyperscalers as acquirers of security platforms.","evidence":"Wiz acquisition announced 2025-03-18 for $32 billion in cash; completed 2026-03-11.","sources":[{"title":"Wiz (Wikipedia)","url":"https://en.wikipedia.org/wiki/Wiz_(company)"}]},{"id":"cd-2025-auto-tariffs","date":"2025-03-26","end_date":"2025-03-27","sector":"consumer_discretionary","subindustries":["autos"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"25% tariffs on imported vehicles and parts","summary":"Trump's March 26 2025 proclamation imposed 25% tariffs on all imported cars and light trucks (effective April 3) and on certain parts (by May 3). GM, the most Mexico-exposed, fell more than 7% on March 27, Ford more than 3% and Stellantis about 1%, while Tesla, with all US assembly, was unchanged; Toyota and European makers also fell. The tariff was later layered with the Section 232 regime that survived the 2026 IEEPA ruling.","evidence":"GM -7%+, F -3%+, STLA -1% on 2025-03-27; TSLA flat","sources":[{"title":"CNBC: Why GM stock is getting hit the hardest by Trump auto tariffs","url":"https://www.cnbc.com/2025/03/27/gm-stock-trump-auto-tariffs.html"},{"title":"Forbes: US and global auto stocks tumble after Trump's 25% tariff announcement","url":"https://www.forbes.com/sites/siladityaray/2025/03/27/us-and-global-auto-stocks-tumble-after-trumps-25-tariff-announcement-tesla-shares-unaffected/"}]},{"id":"ind-2025-liberation-day-tariffs","date":"2025-04-02","end_date":"2025-04-09","sector":"industrials","subindustries":["machinery","transportation","industrial_distribution","commercial_aerospace"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Liberation Day tariffs hit heavy equipment and transports hardest","summary":"The April 2, 2025 reciprocal tariffs sent the S&P 500 down more than 12% in four sessions, with heavy-equipment makers (Caterpillar, Deere) and airlines falling more than the market before the April 9 90-day pause produced a 9.5% one-day rebound. Industrials recovered to lead for the year as the AI-capex and defense themes dominated, XLI returning 19.3% in 2025, but import-dependent transports and small-cap distributors lagged.","evidence":"S&P 500 -12%+ from Apr 2 to Apr 8, 2025 then +9.5% on Apr 9; XLI +19.3% for 2025 vs SPY +17.7%","sources":[{"title":"Finviz/Motley Fool: Why heavy equipment manufacturer stocks are falling (Apr 3, 2025)","url":"https://finviz.com/news/16792/why-heavy-equipment-manufacturer-stocks-are-falling-today"},{"title":"Stocktwits: Liberation Day tariffs one year on (GE, DE, MMM)","url":"https://stocktwits.com/news-articles/markets/equity/liberation-day-tariffs-one-year-ge-de-mmm-stocks/cZ7xNdYRIFD"},{"title":"ChartRow XLI calendar-year returns","url":"https://chartrow.com/quote/xli/returns"}]},{"id":"en-2025-tariffs-opec-double-hit","date":"2025-04-02","end_date":"2025-12-31","sector":"energy","subindustries":["exploration_production","integrated","oilfield_services"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"Liberation Day tariffs plus OPEC+ output hikes send oil to a four-year low","summary":"The day after the April 2 tariffs, OPEC+ tripled its planned May increase to 411,000 b/d; Brent fell 6% on April 3 and WTI closed the week at $61.99, the lowest since 2021, with XLE down about 7% in a day and nearly 13% for the week. OPEC+ kept unwinding cuts all year, oil spent 2025 in the $60s, and XLE returned only 7.9% (XOP -2.2%) against 17.7% for the S&P 500 as E&Ps cut rigs.","evidence":"OPEC+ raised May 2025 output by 411k b/d (vs ~135k expected); WTI $61.99 on Apr 4, 2025, lowest since early 2021; XLE -~13% that week; XOP -2.2% for 2025","sources":[{"title":"Bloomberg: Oil tumbles as surprise OPEC+ hike, Trump tariffs depress prices","url":"https://www.bloomberg.com/news/articles/2025-04-03/surprise-opec-hike-and-growth-sapping-tariffs-send-oil-plunging"},{"title":"Arabian Post: Oil prices plummet amid OPEC+ output surge and tariffs","url":"https://thearabianpost.com/oil-prices-plummet-amid-opec-output-surge-and-escalating-trade-tariffs/"},{"title":"ChartRow XOP calendar-year returns","url":"https://chartrow.com/quote/xop/returns"}]},{"id":"re-2025-tariff-logistics-selloff","date":"2025-04-02","end_date":"2025-04-30","sector":"real_estate","subindustries":["industrial_logistics_reits"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Liberation Day tariffs: warehouse REITs fall to five-year lows","summary":"Industrial REITs were the hardest-hit property type after the April 2, 2025 tariffs, on fears of lower import volumes: the All Equity REIT index fell more than 9% from April 2 to April 30, Prologis dropped about 21% to a nearly five-year low and was double-downgraded by Scotiabank, and Piper Sandler cut EastGroup and Terreno. The group had already lost 17.8% in 2024 on oversupply; it recovered to +17% for 2025 as reshoring and data-center land demand took over.","evidence":"All Equity REITs -9%+ from Apr 2 to Apr 30, 2025; PLD -~21% in early April 2025 to a near five-year low; Industrial REITs -17.78% (2024) then +17.05% (2025)","sources":[{"title":"Propmodo: Sifting through the rubble of the tariff REIT selloff","url":"https://propmodo.com/sifting-through-the-rubble-of-the-tariff-reit-selloff/"},{"title":"Bisnow: Prologis downgraded by Scotiabank amid tariff turmoil","url":"https://www.bisnow.com/news/national/industrial/prologis-scotiabank-128830"},{"title":"Nareit REIT Industry Fact Sheet Dec 2025","url":"https://www.reit.com/sites/default/files/2026-01/MediaFactSheet_Dec-2025.pdf"}]},{"id":"cd-2025-liberation-day-apparel","date":"2025-04-02","end_date":"2025-04-09","sector":"consumer_discretionary","subindustries":["apparel_luxury","specialty_retail"],"direction":"out","magnitude":"major","driver_type":"policy","title":"'Liberation Day' tariffs: 46% on Vietnam hammers apparel and footwear","summary":"The April 2 2025 reciprocal tariffs put 46% on Vietnam, 32% on Indonesia and 34% on China, the three countries that make most US footwear and apparel. Nike, which sources about half its shoes from Vietnam, fell 10-13% on April 3; Lululemon, Deckers, Abercrombie, Gap, American Eagle and Wayfair dropped as much as 11%; Stifel estimated a $1.69 hit to Nike's EPS. Specialty and discount retailers importing from Asia (Five Below, Dollar Tree) were hit as hard, and the sub-industry only stabilised after the April 9 pause.","evidence":"NKE -10% to -13% on 2025-04-03 after the 46% Vietnam tariff; LULU, DECK, ANF, GAP down up to 11%","sources":[{"title":"CNBC: Trump's 46% Vietnam tariffs pummel Nike, American Eagle and Wayfair","url":"https://www.cnbc.com/2025/04/02/trump-tariffs-on-vietnam-could-raise-prices-for-shoes-furniture-toys.html"},{"title":"Bloomberg: Nike, Adidas stocks fall as Trump's tariffs hit Vietnam","url":"https://www.bloomberg.com/news/articles/2025-04-02/trump-tariffs-poised-to-make-nike-adidas-shoes-more-expensive"},{"title":"GuruFocus: Lululemon's Vietnam bet backfires as Trump slaps 46% tariff","url":"https://www.gurufocus.com/news/2762037/lululemons-vietnam-bet-backfires-as-trump-slaps-46-tariff"}]},{"id":"cd-2025-de-minimis-end","date":"2025-04-02","end_date":"2025-08-29","sector":"consumer_discretionary","subindustries":["internet_retail"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"End of the de minimis exemption","summary":"Executive Order 14256 (April 2 2025) ended duty-free de minimis treatment for Chinese and Hong Kong parcels, and EO 14324 (signed July 30) extended the suspension to all countries from August 29 2025, subjecting every low-value import to duties. The change removed the cost advantage of Temu, Shein and AliExpress direct-from-China shipping and was read as a relative positive for Amazon, Etsy and domestic marketplaces, while raising costs for small cross-border sellers.","evidence":"EO 14324 signed 2025-07-30 suspending de minimis for all countries effective 2025-08-29, following the China/HK suspension under EO 14256 (2025-04-02)","sources":[{"title":"White House: Suspending duty-free de minimis treatment for all countries","url":"https://www.whitehouse.gov/presidential-actions/2025/07/suspending-duty-free-de-minimis-treatment-for-all-countries/"}]},{"id":"tech-2025-liberation-day","date":"2025-04-02","end_date":"2025-04-11","sector":"technology","subindustries":["apple","hardware","semiconductors","semicap","internet_platforms","fintech_payments"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Liberation Day tariffs: S&P 500 -12% in four sessions, then a record 9.5% rebound","summary":"Trump announced a 10% baseline tariff and reciprocal rates of 11-50% on 2 April 2025; the S&P 500 fell 4.84% on 3 April and 5.97% on 4 April and closed at 4,982.77 on 8 April, about 12% below its 2 April level, with the Nasdaq down about 13%, the VIX at 45.31 and the 10-year yield swinging from 3.86% to about 4.5%. The 9 April 90-day pause (China excepted, at 145%) produced a 9.52% S&P 500 gain, the largest since 2008, and on 11 April smartphones, computers and semiconductors were exempted from reciprocal tariffs; the S&P 500 made a new high on 27 June 2025.","evidence":"S&P 500 close 4,982.77 on 2025-04-08 (about -12% from 2025-04-02); +9.52% on 2025-04-09.","sources":[{"title":"2025 stock market crash (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025_stock_market_crash"},{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"},{"title":"Trump pauses most of his tariffs (Inquirer/AP)","url":"https://business.inquirer.net/518883/trump-pauses-most-of-his-tariffs"}]},{"id":"semis-2025-section-232-investigation","date":"2025-04-14","end_date":"2026-01-14","sector":"technology","subindustries":["semiconductors","semicap","hardware","apple"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Section 232 semiconductor investigation opens the door to chip tariffs","summary":"In April 2025 Commerce opened Section 232 national-security investigations into semiconductors and semiconductor equipment (alongside pharmaceuticals), creating a tariff overhang that was partly offset by the 11 April exemption of chips from reciprocal tariffs. The Semiconductor Industry Association's May 2025 comments argued for exemptions for firms investing in US fabs, the structure adopted in the January 2026 proclamation, and chipmakers with US fab pledges (TSMC, Micron, Apple's suppliers) traded on expected offsets.","evidence":"Section 232 investigation into semiconductor and equipment imports directed in April 2025 (Bloomberg, 2025-04-14); SIA comments filed May 2025.","sources":[{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"},{"title":"SIA comments on the Section 232 investigation (May 2025)","url":"https://www.semiconductors.org/wp-content/uploads/2025/05/SIA-Comments-Section-232-Investigation.pdf"}]},{"id":"hc-2025-unh-collapse","date":"2025-04-17","end_date":"2025-12-31","sector":"healthcare","subindustries":["managed_care"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"UnitedHealth collapses: guidance cut, CEO exit, DOJ probe","summary":"UnitedHealth fell 23% on April 17 2025 after cutting 2025 adjusted EPS guidance to $26-26.50 from $29.50-30 on Medicare Advantage costs 'far above' plan. On May 13 CEO Andrew Witty resigned and guidance was suspended; on May 15 a WSJ report of a DOJ criminal Medicare-fraud probe took the stock down a further 13%, and in July the company confirmed criminal and civil investigations (-4.7%). UNH ended 2025 at $330.11 versus $505.86 at end-2024, a 35% loss in a year the S&P 500 rose, dragging the whole managed-care group.","evidence":"UNH -23.1% on 2025-04-17; -13% on 2025-05-15; closed 2025 at $330.11 vs $505.86 at end-2024","sources":[{"title":"Fierce Healthcare: UnitedHealth cuts profit outlook, shares plunge","url":"https://www.fiercehealthcare.com/payers/unitedhealth-group-cuts-profit-outlook-citing-higher-expected-medicare-advantage-care-costs"},{"title":"CNBC: UnitedHealth shares plunge 13% on report of DOJ probe","url":"https://www.cnbc.com/2025/05/15/unitedhealth-group-stock-doj-investigation-report.html"},{"title":"Wikipedia: UnitedHealth Group","url":"https://en.wikipedia.org/wiki/UnitedHealth_Group"}]},{"id":"cs-2025-maha-food-dyes","date":"2025-04-22","end_date":"2026-12-31","sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"minor","driver_type":"regulatory","title":"MAHA: HHS moves to phase out synthetic food dyes","summary":"HHS Secretary Kennedy and the FDA announced on April 22 2025 a plan to remove six synthetic dyes (including Red 40 and Yellow 5) from the food supply by the end of 2026, stopping short of a formal ban and relying on voluntary industry action; Campbell and Nestle pledged compliance while Mondelez and Coca-Cola did not commit. The announcement added reformulation cost and 'ultra-processed food' headline risk to a packaged-food group already de-rated by GLP-1 fears. A measurable same-day stock reaction was not found.","evidence":"Plan to eliminate six synthetic dyes by end-2026 announced 2025-04-22; two of eight large food companies had pledged by the Reuters review","sources":[{"title":"NPR: RFK Jr. wants the food industry to stop using synthetic dyes","url":"https://www.npr.org/sections/shots-health-news/2025/04/22/nx-s1-5372637/food-dyes-ban-fda-rfk-kennedy"},{"title":"Reuters via Investing.com: RFK Jr. pushed food companies to cut artificial dyes, why they're moving slowly","url":"https://www.investing.com/news/stock-market-news/rfk-jr-pushed-food-companies-to-cut-artificial-dyes-heres-why-theyre-moving-slowly-4469634"}]},{"id":"ind-2025-waste-soft-patch","date":"2025-05-01","end_date":"2025-07-31","sector":"industrials","subindustries":["waste"],"direction":"out","magnitude":"minor","driver_type":"positioning","title":"Risk-on summer leaves waste stocks behind","summary":"As the market rallied from the April 2025 tariff low, investors rotated out of defensives: waste stocks fell by mid-single digits over May-July 2025 while the S&P 500 gained about 6%, with volume softness and a premium multiple cited. WM still finished 2025 up 10.5%, but the episode showed the group trades as a bond-proxy/low-vol factor rather than on its own fundamentals.","evidence":"Waste stocks fell mid-single digits over two months to July 2025 vs S&P 500 +6% (Barron's); WM +10.5% in 2025 vs SPY +17.7%","sources":[{"title":"Barron's via Tiger: Garbage stocks have hit a soft spot","url":"https://www-web.itiger.com/news/2552449235"},{"title":"ChartRow WM calendar-year returns","url":"https://chartrow.com/quote/wm/returns"}]},{"id":"re-2025-0506-marriott-revpar-guidance-cut","date":"2025-05-06","end_date":null,"sector":"real_estate","subindustries":["lodging_reits"],"direction":"out","magnitude":"moderate","driver_type":"macro","title":"Marriott cuts 2025 RevPAR outlook to 1.5-3.5% as Hyatt and Wyndham also trim; hotel REIT guidance seen 300-400 bp too high","summary":"On its Q1 call on May 6, 2025 Marriott lowered its full-year 2025 RevPAR growth guidance to 1.5%-3.5% from 2%-4%, citing economic uncertainty, weaker consumer confidence and 'tougher visibility into the back half of the year', despite Q1 global RevPAR of +4.1%. Hyatt and Wyndham made similar cuts in their Q1 reports, confirming a broad US lodging demand slowdown tied to tariff uncertainty and softer government and inbound travel. Baird had already warned on April 21 that US RevPAR was tracking 300-400 bp below prior expectations while lodging REITs (HST, PK, PEB, RLJ, DRH, SHO) had guided to 1%-3% growth, describing investor sentiment as 'extremely negative'.","evidence":"Marriott 2025 RevPAR guidance cut to +1.5%-3.5% from +2%-4% on 2025-05-06.","sources":[{"title":"Hotel Dive: Marriott touts development bright spot as it lowers 2025 RevPAR guidance","url":"https://www.hoteldive.com/news/marriott-development-revpar-earnings-q1-2025/747242/"},{"title":"Hotel Management: Marriott lowers U.S. RevPAR guidance as uncertainty looms","url":"https://www.hotelmanagement.net/operate/marriott-lowers-us-revpar-guidance-uncertainty-looms"},{"title":"Skift Daily Lodging Report: Hotel REITs See Softer U.S. RevPARs (Baird, Apr 21 2025)","url":"https://dlr.skift.com/2025/04/21/hotel-reits-see-softer-u-s-revpars/"}]},{"id":"hc-2025-mfn-executive-order","date":"2025-05-12","end_date":null,"sector":"healthcare","subindustries":["pharma","biotech_large","biotech_smid"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Most-favored-nation drug pricing order: sell the rumour, buy the news","summary":"Trump signed an executive order directing drugmakers to match the lowest prices paid in other rich countries. Because the threat had been telegraphed and investors doubted it could be implemented without legislation, pharma and biotech rallied on the day (XBI up more than 4% by midday; Merck, Pfizer, Lilly higher). The order nonetheless became the lever for the September-November 2025 company-by-company pricing deals and the TrumpRx channel.","evidence":"XBI +4% intraday on 2025-05-12 despite the MFN order (STAT)","sources":[{"title":"STAT: Trump's drug-pricing order takes a hard line; investors shrugged","url":"https://www.statnews.com/2025/05/12/trump-drug-pricing-order-most-favored-nations-market-reaction/"},{"title":"CNBC: Trump to sign most favored nation drug pricing order","url":"https://www.cnbc.com/2025/05/12/trump-drug-pricing-order-most-favored-nation.html"}]},{"id":"re-2025-0512-us-china-tariff-truce-reits","date":"2025-05-12","end_date":null,"sector":"real_estate","subindustries":["industrial_logistics_reits","lodging_reits","retail_reits"],"direction":"in","magnitude":"major","driver_type":"policy","title":"US-China 90-day tariff truce sends industrial, lodging and mall REITs sharply higher","summary":"After weekend talks in Geneva, the US and China agreed on May 12, 2025 to cut reciprocal tariffs for 90 days, with the US rate on Chinese goods falling to 30% from as high as 145%. The trade-sensitive REIT groups that had been crushed after Liberation Day rebounded hardest: Bisnow reported the FTSE Nareit US industrial REIT index up 4.9% in early trading, lodging/resort REITs up nearly 6%, regional mall REITs up more than 5% and shopping-center REITs up more than 3%, versus roughly +0.4% for the FTSE Nareit All Equity REITs index. The Dow rose more than 1,000 points and the 10-year yield rose 6 bp to 4.44%, so the move was a cyclical/import-volume trade rather than a rates trade.","evidence":"FTSE Nareit US industrial REIT index +4.9% and lodging REITs +~6% in early trading on 2025-05-12 (Bisnow).","sources":[{"title":"Bisnow: Markets Rally On China-U.S. Tariff Reprieve, Lodging And Industrial REITs Soar","url":"https://www.bisnow.com/national/news/capital-markets/markets-rally-on-china-us-tariff-reprieve-lodging-and-industrial-reits-soar-129331"},{"title":"CBS News: Dow jumps more than 1,000 points as U.S. and China agree to slash tariffs for 90 days","url":"https://www.cbsnews.com/news/stocks-up-china-tariffs-pause-agreement-may-12-2025/"}]},{"id":"telecom-2025-cable-fiber-consolidation","date":"2025-05-16","end_date":"2026-08-20","sector":"technology","subindustries":["telecom"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Charter-Cox and AT&T-Lumen: cable and fiber consolidate","summary":"Charter announced a merger with Cox Communications on 16 May 2025 (Cox Enterprises taking 23% of the combined company; closed 20 August 2026) and AT&T agreed on 21 May 2025 to buy Lumen's mass-market fiber business for $5.75 billion (closed 2 February 2026). The deals were a defensive response to broadband share losses to fixed wireless and fiber overbuilders, and they shifted telecom from a yield trade to a scale-and-synergy story.","evidence":"Charter-Cox merger announced 2025-05-16; AT&T-Lumen fiber deal announced 2025-05-21 for $5.75 billion.","sources":[{"title":"Charter Communications (Wikipedia)","url":"https://en.wikipedia.org/wiki/Charter_Communications"},{"title":"AT&T (Wikipedia)","url":"https://en.wikipedia.org/wiki/AT%26T"}]},{"id":"reits-2025-moodys-downgrade","date":"2025-05-16","end_date":"2025-05-19","sector":"real_estate","subindustries":["net_lease_specialty_reits","regulated_utilities"],"direction":"out","magnitude":"minor","driver_type":"rates","title":"Moody's strips the last Aaa: 30-year Treasury tops 5%, bond-proxy REITs and utilities wobble","summary":"Moody's cut the U.S. to Aa1 after the close on May 16, 2025, citing deficits heading toward 9% of GDP by 2035, the last of the three agencies to remove the top rating. The 30-year yield rose above 5% (5.02%) on May 19 and S&P futures fell 1.1% before the index closed up 0.1%, so the equity damage was concentrated in rate-sensitive groups rather than the market. For net-lease REITs and utilities, the move reinforced the term-premium problem: long yields at 5% leave dividend yields of 4-6% without a spread, a theme that recurred in the 2026 selloff.","evidence":"30-year Treasury yield 5.023% on 2025-05-19, the first close above 5% since late 2023.","sources":[{"title":"Moody's downgrade pushes yields to 5%: what it means for stocks (Benzinga)","url":"https://www.benzinga.com/economics/macro-economic-events/25/05/45500872/30-year-treasury-yields-hit-5-what-that-means-for-stocks"},{"title":"Stock market news for May 19, 2025 (CNBC)","url":"https://www.cnbc.com/2025/05/18/stock-futures-slide-after-us-debt-downgrade-highlights-deficit-risk-live-updates.html"}]},{"id":"re-2025-0521-trump-gse-ipo-post","date":"2025-05-21","end_date":null,"sector":"real_estate","subindustries":["mortgage_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Trump floats Fannie/Freddie public offering; GSE shares soar 40%","summary":"On May 21, 2025 President Trump posted on Truth Social that Fannie Mae and Freddie Mac were 'doing very well' and that he was giving 'very serious consideration' to taking them public; on May 22 common shares of both GSEs rose more than 40% to 52-week highs, with preferreds up double digits. A May 27 follow-up post said the government would keep its implicit guarantee. For agency mortgage REITs (NLY, AGNC, DX, ARR, ORC) the episode reopened the GSE-reform/guarantee debate that drives agency MBS spread risk, while the White House later (Aug 2025) discussed an IPO of up to 15% of the companies.","evidence":"Fannie Mae and Freddie Mac common shares rose more than 40% on 2025-05-22 after Trump's May 21 post (Inman).","sources":[{"title":"Trump's Interest Sends Shares In Fannie, Freddie Soaring (Inman, May 22 2025)","url":"https://www.inman.com/2025/05/22/trumps-interest-sends-shares-in-fannie-mae-freddie-mac-soaring/"},{"title":"Trump says Fannie Mae, Freddie Mac IPO still on the table (HousingWire)","url":"https://www.housingwire.com/articles/fannie-freddie-ipo-trump/"},{"title":"Trump is planning a massive IPO of the government's mortgage companies (CNN, Aug 8 2025)","url":"https://www.cnn.com/2025/08/08/business/fannie-freddie-ipo"}]},{"id":"en-2025-obbba-ira-phaseout","date":"2025-05-22","end_date":"2025-07-04","sector":"energy","subindustries":["new_energy_power"],"direction":"mixed","magnitude":"major","driver_type":"policy","title":"One Big Beautiful Bill Act phases out IRA credits; solar whipsaws","summary":"Sunrun fell 39% and Enphase 19% when the House passed its bill on May 22, 2025, and Sunrun dropped another 40% on June 17 when the Senate draft ended credits by 2028; the final law signed July 4 ended the 25D residential credit after 2025 and phased out wind/solar credits from mid-2026 but preserved third-party leasing, so Sunrun rebounded 7.8% on passage. The year ended with a split: First Solar (+48%) and ICLN (+47%) up on tariffs, FEOC rules and AI power demand, Enphase down 53%.","evidence":"RUN -39% and ENPH -19% on May 22, 2025; RUN -40% on Jun 17, 2025; ENPH -53.3% vs FSLR +48.2% for 2025","sources":[{"title":"TipRanks: Sunrun plummets 40% as Senate targets solar credits","url":"https://www.tipranks.com/news/article/sunrun-stock-run-plummets-40-as-u-s-senate-targets-solar-credits"},{"title":"Benzinga: Solar stocks get a reprieve as Big Beautiful Bill lands softer than feared","url":"https://benzinga.com/z/46300815"},{"title":"ChartRow ENPH calendar-year returns","url":"https://chartrow.com/quote/enph/returns"}]},{"id":"nuclear-2025-executive-orders","date":"2025-05-23","end_date":null,"sector":"nuclear","subindustries":[],"direction":"in","magnitude":"major","driver_type":"policy","title":"Trump's nuclear executive orders target 10 new large reactors by 2030","summary":"Executive Order 14302 of 23 May 2025 directed the Energy Department to facilitate 5 GW of uprates at existing reactors and have 10 new large reactors under construction by 2030, to expand enrichment and conversion capacity, use surplus plutonium as advanced-reactor fuel and fund restarts through the Loan Programs Office. Oklo was selected for DOE's Reactor Pilot Program that month, and the orders extended the 2024 hyperscaler-driven re-rating of uranium, fuel-cycle and SMR names.","evidence":"EO 14302 signed 2025-05-23: 5 GW of uprates and 10 new large reactors under construction by 2030.","sources":[{"title":"Reinvigorating the Nuclear Industrial Base (White House, 2025-05-23)","url":"https://www.whitehouse.gov/presidential-actions/2025/05/reinvigorating-the-nuclear-industrial-base/"},{"title":"Oklo Inc. (Wikipedia)","url":"https://en.wikipedia.org/wiki/Oklo_Inc."}]},{"id":"en-2025-0531-opec-july-hike","date":"2025-05-31","end_date":null,"sector":"energy","subindustries":["integrated","exploration_production"],"direction":"mixed","magnitude":"moderate","driver_type":"commodity","title":"OPEC+ adds a third 411,000 b/d hike for July; relief rally as market feared bigger","summary":"On Saturday May 31, 2025 the eight OPEC+ voluntary cutters agreed to raise July output by 411,000 b/d, matching the May and June hikes and unwinding about 62% of the 2.2 mb/d cut, despite Russian and Algerian pushback. Markets had feared a larger increase after Kazakhstan refused to cut, so crude rallied on Monday June 2: WTI +2.85% to $62.52 and Brent +2.95% to $64.63, helped by a US rig count at its lowest since 2021. The steady-pace outcome eased the worst-case scenario for E&Ps but kept the group on a market-share path that weighed on the integrateds through the summer.","evidence":"WTI closed +$1.73 (2.85%) at $62.52/bbl on 2025-06-02 after the 411,000 b/d July decision","sources":[{"title":"CNBC - U.S. crude oil rises about 3% as rig count falls, OPEC+ increases output at steady rate","url":"https://www.cnbc.com/2025/06/02/us-crude-oil-rises-after-opec-increases-output-at-steady-rate.html"},{"title":"World Oil - OPEC+ to increase July supply by 411,000 bpd despite pushback from Russia","url":"https://worldoil.com/news/2025/5/30/opec-to-increase-july-supply-by-411-000-bpd-despite-pushback-from-russia/"}]},{"id":"financials-2025-june-reinsurance-renewals-soften","date":"2025-06-01","end_date":null,"sector":"financials","subindustries":["insurance"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"June 1 2025 Florida reinsurance renewals: first real rate cut in years (-10.7%)","summary":"At the June 1, 2025 Florida-focused renewals, Gallagher Re data showed cedents secured a risk-adjusted property-catastrophe price decrease of 10.7% with reductions across all layers, the first significant decline after several hard-market years, as tort reform and abundant capital outweighed the January LA wildfire losses. Softer reinsurance costs help primary carriers such as Allstate, Progressive and Travelers while signalling the top of the pricing cycle for reinsurers like RenaissanceRe and Arch.","evidence":"Florida 6/1/2025 risk-adjusted reinsurance pricing -10.7% (Gallagher Re)","sources":[{"title":"Artemis: June reinsurance renewals highlight Florida's recovery following tort reforms - Gallagher Re","url":"https://www.artemis.bm/news/june-reinsurance-renewals-highlight-floridas-recovery-following-tort-reforms-gallagher-re/"},{"title":"Reinsurance News: Reinsurance rates seen down 10-15% ahead of Jan 1 - Florida Chamber panel","url":"https://www.reinsurancene.ws/reinsurance-rates-seen-down-10-15-ahead-of-jan-1-florida-chamber-panel/"}]},{"id":"materials-2025-steel-aluminum-50","date":"2025-06-04","end_date":null,"sector":"materials","subindustries":["metals_mining","chemicals"],"direction":"mixed","magnitude":"major","driver_type":"policy","title":"Steel and aluminum tariffs doubled to 50%","summary":"Section 232 tariffs on steel and aluminum, reset at 25% with exemptions removed in March 2025, were doubled to 50% on 4 June 2025 and extended to appliances and 407 derivative products later in the year. Domestic steelmakers gained pricing power while metal-consuming manufacturers and chemical producers absorbed higher input costs; materials returned 10.5% in 2025 against 17.9% for the S&P 500.","evidence":"Steel and aluminum tariffs raised from 25% to 50% effective 2025-06-04.","sources":[{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"},{"title":"White House fact sheet on steel, aluminum and copper tariffs (April 2026)","url":"https://www.whitehouse.gov/fact-sheets/2026/04/fact-sheet-president-donald-j-trump-strengthens-tariffs-on-steel-aluminum-and-copper-imports/"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"fintech-2025-circle-ipo-coinbase-sp500","date":"2025-06-05","end_date":"2025-06-20","sector":"technology","subindustries":["fintech_payments"],"direction":"in","magnitude":"major","driver_type":"regulatory","title":"Circle IPO soars 247% in two days; Coinbase joins the S&P 500","summary":"Stablecoin issuer Circle listed on the NYSE on 4-5 June 2025, raising about $1.1 billion, and had gained 247% by its second day to a market value of about $28.6 billion; after the Senate passed the GENIUS Act on 17 June, Circle traded 675% above its debut level and Coinbase, which shares USDC reserve income, had been added to the S&P 500 on 19 May 2025. The listings marked the return of the fintech IPO window and the market's embrace of stablecoins as regulated payment rails.","evidence":"Circle up 247% by its second trading day with a market value of about $28.6 billion; Coinbase added to the S&P 500 on 2025-05-19.","sources":[{"title":"Circle (company) (Wikipedia)","url":"https://en.wikipedia.org/wiki/Circle_(company)"},{"title":"Coinbase (Wikipedia)","url":"https://en.wikipedia.org/wiki/Coinbase"},{"title":"Crypto stocks soar after Senate passes stablecoin bill (Fortune, 2025-06-20)","url":"https://fortune.com/crypto/2025/06/20/crypto-stocks-soar-after-senate-passes-stablecoin-bill-circle-up-over-50"}]},{"id":"pharma-2025-acip-overhaul","date":"2025-06-09","end_date":"2025-06-10","sector":"healthcare","subindustries":["pharma","biotech_large"],"direction":"out","magnitude":"minor","driver_type":"policy","title":"RFK Jr. fires all 17 ACIP vaccine advisers; vaccine makers barely move because the risk is priced","summary":"HHS Secretary Robert F. Kennedy Jr. dismissed the entire CDC Advisory Committee on Immunization Practices on June 9, 2025 and named eight replacements days later. Moderna fell about 2% and Novavax was flat on June 10 while Pfizer and Merck rose 1.4-2%; analysts at Leerink called the overhaul a risk for every vaccine manufacturer, but BMO and Morningstar argued the stocks' weak 2025 already discounted Kennedy's scepticism. The muted reaction marked the shift from vaccine-policy shock (the November 2024 nomination selloff) to a slow grind of narrower recommendations.","evidence":"Moderna -2% on 2025-06-10, the first session after the dismissals.","sources":[{"title":"Vaccine stocks muted as investors assess Kennedy's overhaul of key panel (Globe and Mail / Reuters)","url":"https://www.theglobeandmail.com/investing/article-vaccine-stocks-muted-as-investors-assess-kennedys-overhaul-of-key/"},{"title":"BMO Capital warns of potential risks for vaccine stocks after ACIP changes (Investing.com)","url":"https://www.investing.com/news/analyst-ratings/bmo-capital-warns-of-potential-risks-for-vaccine-stocks-after-rfk-jrs-acip-changes-93CH-4089168"},{"title":"RFK Jr. reveals picks for influential vaccine panel (BioPharma Dive)","url":"https://www.biopharmadive.com/news/rfk-kennedy-names-acip-cdc-panel-vaccines/750528/"}]},{"id":"media-2025-wbd-split-announcement","date":"2025-06-09","end_date":null,"sector":"communication_media","subindustries":["media_entertainment"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Warner Bros. Discovery announces split into streaming/studios and cable networks","summary":"On 2025-06-09 WBD said it would separate into a Streaming & Studios company (Warner Bros., HBO, HBO Max, led by David Zaslav) and a Global Networks company (CNN, TNT, Discovery, led by CFO Gunnar Wiedenfels) by mid-2026, with most of its ~$38bn debt assigned to the networks entity. WBD shares jumped as much as 12% at the open but closed down about 3%, and the move framed the industry-wide pattern of carving out declining linear TV (Comcast's Versant, Disney's ABC/FX review) ahead of the Paramount-WBD bidding war.","evidence":"WBD +12% intraday, closed about -3% on 2025-06-09","sources":[{"title":"CNBC: Warner Bros. Discovery to split into two public companies by next year","url":"https://www.cnbc.com/2025/06/09/warner-bros-discovery-to-split-into-two-public-companies-by-next-year.html"},{"title":"Yahoo Finance: Warner Bros. Discovery stock pops as company confirms it will split into 2 companies","url":"https://finance.yahoo.com/news/warner-bros-discovery-stock-pops-as-company-confirms-it-will-split-into-2-companies-141412752.html"}]},{"id":"en-2025-0613-israel-strikes-iran-oil-spike","date":"2025-06-13","end_date":"2025-06-24","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"Israel strikes Iran: crude posts biggest one-day jump since 2022, energy leads","summary":"Israel's June 13, 2025 strikes on Iranian nuclear and military sites sent Brent up as much as 13% intraday, its largest intraday jump since March 2022, with Brent closing +7.6% and WTI settling +7.26% at about $72.98. Energy stocks rose in premarket trading led by Exxon Mobil and Chevron while airlines and the broad market fell. The 12-day episode ended with the June 24 ceasefire, after which the risk premium bled out of crude and the group.","evidence":"WTI settled +7.26% at ~$72.98/bbl on 2025-06-13 (CNN); Brent +7.6% after a 13% intraday spike (Bloomberg)","sources":[{"title":"CNN - Oil prices jump 7% and stocks drop as Israel-Iran tensions escalate","url":"https://www.cnn.com/2025/06/13/business/oil-prices-markets-israel-iran-attack-intl-hnk"},{"title":"World Oil - Oil prices surge following Israel's attack on Iran","url":"https://www.worldoil.com/news/2025/6/13/oil-prices-surge-following-israel-s-attack-on-iran/"},{"title":"S&P Global - Oil futures: crude surges 6% as Israel launches preemptive strike on Iran","url":"https://www.spglobal.com/energy/en/news-research/latest-news/crude-oil/061325-oil-futures-crude-surges-6-as-israel-launches-preemptive-strike-on-iran"}]},{"id":"distribution-2025-home-depot-gms-qxo","date":"2025-06-18","end_date":"2025-09-04","sector":"industrials","subindustries":["industrial_distribution","building_products_construction"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"QXO's hostile bid and Home Depot's $5.5bn win for GMS reprice building-products distribution","summary":"Brad Jacobs's QXO went public with an unsolicited $95.20-a-share (about $5bn) offer for drywall distributor GMS on June 18, 2025, two months after closing its $11bn Beacon deal; GMS jumped as much as 30% on June 20. Home Depot's SRS unit then agreed on June 30 to pay $110 a share, about $4.3bn of equity and $5.5bn of enterprise value (a 36% premium to the undisturbed price), and QXO declined to raise. The contest put a strategic premium on specialty distribution (SiteOne, Builders FirstSource, Core & Main) as Home Depot pursued the pro contractor and QXO signalled more roll-ups.","evidence":"Home Depot paid $110 per GMS share, about $5.5bn enterprise value, a 36% premium to the 2025-06-18 close.","sources":[{"title":"Home Depot wins the bidding war against QXO, acquires GMS (Yahoo Finance)","url":"https://finance.yahoo.com/news/home-depot-wins-bidding-war-120828795.html"},{"title":"QXO won't raise its offer for GMS after Home Depot bid (Transport Topics)","url":"https://www.ttnews.com/articles/qxo-wont-raise-offer-gms"},{"title":"Home Depot expands B2B reach with $5.5 billion acquisition of GMS (Digital Commerce 360)","url":"https://www.digitalcommerce360.com/2025/06/30/home-depot-b2b-5-billion-srs-distribution-acquisition-gms/"}]},{"id":"hc-2025-hims-novo-breakup","date":"2025-06-23","end_date":null,"sector":"healthcare","subindustries":["healthcare_technology"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Novo ends Hims & Hers partnership; HIMS falls 35%","summary":"Two months after agreeing in April 2025 to sell branded Wegovy through Hims & Hers, Novo Nordisk unilaterally terminated the collaboration, accusing Hims of 'deceptive promotion' of compounded knock-offs. Hims shares fell roughly 35% in a day and securities class actions followed. The episode showed how dependent the GLP-1 telehealth trade was on regulatory tolerance of compounding after the FDA ended the shortage designation.","evidence":"HIMS fell ~35% on 2025-06-23 after Novo terminated the Wegovy collaboration","sources":[{"title":"Wikipedia: Hims & Hers Health","url":"https://en.wikipedia.org/wiki/Hims_%26_Hers_Health"}]},{"id":"re-2025-0623-compass-sues-zillow-listing-standards","date":"2025-06-23","end_date":null,"sector":"real_estate","subindustries":["real_estate_services"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Compass sues Zillow over listing-access ban as enforcement starts June 30","summary":"On June 23, 2025 Compass filed an antitrust suit against Zillow in the Southern District of New York, alleging Zillow's Listing Access Standards (announced April 2025) unlawfully used its 60%-plus share of home-search traffic to block Compass's three-phase 'private exclusive' marketing; Zillow began blocking an agent's third non-compliant listing from Zillow and Trulia on June 30, 2025. The fight defined the private-listing/portal-power debate for Z, COMP, EXPI, RMAX and Redfin: Judge Vargas denied Compass an injunction in February 2026, Compass dropped the case on March 18, 2026 after Zillow carved out pre-marketing on Compass and Redfin sites, and Zillow then sued Compass and Chicago's MRED in May 2026.","evidence":"Compass v. Zillow filed 2025-06-23 in SDNY; Zillow enforcement of the one-business-day MLS rule began 2025-06-30 (Real Estate News).","sources":[{"title":"Zillow to Compass: We're not legally required to work with you (Real Estate News, Jul 17 2025)","url":"https://www.realestatenews.com/2025/07/17/zillow-to-compass-were-not-legally-required-to-work-with-you"},{"title":"Compass challenges Zillow's listing policy in court (HousingWire)","url":"https://www.housingwire.com/articles/compass-zillow-lawsuit/"},{"title":"Compass drops lawsuit after Zillow embraces pre-marketing (Real Estate News, Mar 18 2026)","url":"https://www.realestatenews.com/2026/03/18/compass-drops-lawsuit-after-zillow-embraces-pre-marketing"}]},{"id":"financials-2025-eslr-deregulation","date":"2025-06-25","end_date":"2025-11-25","sector":"financials","subindustries":["banks","capital_markets"],"direction":"in","magnitude":"major","driver_type":"regulatory","title":"Fed proposes and finalises the enhanced supplementary leverage ratio cut","summary":"On 25 June 2025 the Fed voted 5-2 to propose recalibrating the enhanced supplementary leverage ratio for the eight US GSIBs; dissenting Governor Barr estimated it would cut tier 1 capital requirements at their bank subsidiaries by 27%, or $210 billion. The rule was finalised on 25 November 2025 with the bank-level buffer capped at 1 percentage point, the first major post-crisis capital rollback and the centrepiece of the 2025 bank-deregulation trade; Basel III endgame was re-proposed with reductions on 19 March 2026.","evidence":"Fed board vote 5-2 on 2025-06-25; Barr dissent: 27% ($210 billion) reduction in tier 1 capital requirements at GSIB depository subsidiaries; final rule 2025-11-25.","sources":[{"title":"Statement by Governor Barr on the eSLR proposal, 25 June 2025","url":"https://www.federalreserve.gov/newsevents/pressreleases/barr-statement-20250625.htm"},{"title":"US banking regulators propose eSLR reform (Mayer Brown)","url":"https://www.mayerbrown.com/en/insights/publications/2025/06/us-banking-regulators-propose-enhanced-supplementary-leverage-ratio-reform"},{"title":"Regulators finalize revised leverage rule for big banks (American Banker)","url":"https://www.americanbanker.com/news/regulators-finalize-revised-leverage-rule-for-big-banks"},{"title":"Basel III endgame: where the US rule stands in 2026","url":"https://governancedocs.com/basel-iii-endgame/"}]},{"id":"re-2025-0625-equinix-analyst-day-guidance-cut","date":"2025-06-25","end_date":"2025-06-26","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Equinix cuts 2025-2029 AFFO/share growth target to 5-9% at analyst day; shares plunge ~9-10%","summary":"At its June 25, 2025 analyst day Equinix lowered its five-year (2025-2029) AFFO-per-share growth outlook to 5%-9% from the 7%-10% set in 2023, blaming higher interest costs on refinancing and new debt plus a step-up in capex under its 'Build Bolder' plan to chase AI and hyperscale demand (revenue growth 7%-10%, EBITDA margin to 52%+). Shares fell about 9% to $824.31 and were down nearly 10% by midday on June 26 as Raymond James downgraded to Market Perform and JPMorgan, BofA and Wells Fargo cut targets; elevated churn and capex intensity became the market's concern for the data center REIT complex, including Digital Realty.","evidence":"EQIX 2025-2029 AFFO/share growth target cut to 5%-9% from 7%-10%; shares -9% to $824.31 on 2025-06-25 (Investing.com).","sources":[{"title":"Investing.com: Equinix stock falls as analyst maintains rating despite lower growth outlook","url":"https://www.investing.com/news/analyst-ratings/equinix-stock-falls-as-analyst-maintains-rating-despite-lower-growth-outlook-93CH-4112005"},{"title":"Motley Fool: Why Shares in This Data Center REIT Slumped Today (June 26, 2025)","url":"https://www.fool.com/investing/2025/06/26/why-shares-in-this-data-center-reit-slumped-today"},{"title":"Seeking Alpha: Equinix stock slides after five-year outlook sees AFFO growth slowing in 2026","url":"https://seekingalpha.com/news/4462778-equinix-stock-slides-after-five-year-outlook-sees-affo-growth-slowing-in-2026"}]},{"id":"apparel-2025-nike-turnaround-rally","date":"2025-06-26","end_date":"2025-06-27","sector":"consumer_discretionary","subindustries":["apparel_luxury"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Nike jumps 15% as a 'better than feared' quarter marks the peak of the turnaround drag despite a $1bn tariff bill","summary":"Nike's fiscal Q4 2025 results on June 26, 2025 showed revenue of $11.1bn, down 12% but above the $10.72bn consensus, and EPS of $0.14 versus $0.12 expected; management said the quarter was the peak of the financial drag from CEO Elliott Hill's 'Win Now' reset and that tariffs would add about $1bn of cost in fiscal 2026, to be offset by 'surgical' price increases and shifting US-bound sourcing out of China to a high-single-digit share by May 2026. Shares surged about 15% on June 27, the stock's best day in years, lifting the whole footwear and apparel complex that had been sold on Vietnam and China tariff exposure.","evidence":"NKE +15% on 2025-06-27; fiscal Q4 2025 revenue $11.1bn vs $10.72bn consensus, EPS $0.14 vs $0.12; ~$1bn fiscal-2026 tariff cost estimate.","sources":[{"title":"Why Nike stock is skyrocketing today (Motley Fool, 2025-06-27)","url":"https://www.fool.com/investing/2025/06/27/why-nike-stock-is-skyrocketing-today"},{"title":"Nike shares rally as turnaround takes shape (RTE, 2025-06-27)","url":"https://www.rte.ie/news/business/2025/0627/1520651-nike-shares-rally-as-turnaround-takes-shape"},{"title":"Nike jumps 18% after Q4 beat and signs turnaround headwinds are easing (Financial Modeling Prep)","url":"https://site.financialmodelingprep.com/market-news/fmp-nike-jumps-18-after-q4-beat-and-signs-turnaround-headwinds-are-easing"}]},{"id":"tech-2025-ai-second-leg","date":"2025-06-27","end_date":"2025-10-29","sector":"technology","subindustries":["semiconductors","internet_platforms","infrastructure_software_cyber","memory","hardware"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Post-tariff recovery: S&P 500 record on 27 June 2025 and the AI trade's second leg","summary":"The S&P 500 closed at a record 6,173.07 on 27 June 2025, fully recovering the Liberation Day drawdown as tariff deals and chip exemptions arrived, and the Nasdaq followed through to successive records (first close above 20,500 on 3 July, above 23,500 on 8 October). Leadership narrowed to AI suppliers and hyperscalers: Microsoft reached $4 trillion on 31 July, Nvidia $4 trillion on 9 July and $5 trillion on 29 October 2025, while software, IT services and consumer names lagged.","evidence":"S&P 500 record close 6,173.07 on 2025-06-27; Nvidia $4 trillion on 2025-07-09 and $5 trillion on 2025-10-29.","sources":[{"title":"2025 stock market crash (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025_stock_market_crash"},{"title":"Nasdaq Composite (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"id":"hc-2025-centene-guidance","date":"2025-07-01","end_date":"2025-07-02","sector":"healthcare","subindustries":["managed_care"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Centene pulls guidance on ACA exchange risk adjustment","summary":"Centene withdrew its 2025 guidance after Wakely data covering 22 of its 29 marketplace states implied a $1.8 billion cut to risk-adjustment revenue (about $2.75 of EPS) because exchange enrollees were sicker and growth slower than priced. The stock fell as much as 40% on July 2 and Molina, Oscar and Elevance sold off in sympathy, as investors re-priced the whole government-sponsored book (Medicaid redeterminations, exchange morbidity) ahead of the subsidy cliff.","evidence":"CNC withdrew guidance 2025-07-01 citing a $1.8B risk-adjustment shortfall; shares fell as much as 40% on 2025-07-02","sources":[{"title":"Centene 8-K press release, July 1 2025","url":"https://www.sec.gov/Archives/edgar/data/1071739/000107173925000128/a7012025formex991pressrele.htm"},{"title":"Fierce Healthcare: Centene stock sinks as insurer withdraws 2025 guidance","url":"https://www.fiercehealthcare.com/payers/centene-stock-sinks-insurer-withdraws-2025-guidance"},{"title":"AdvisorHub/Bloomberg: Centene plunges in foreboding sign for health insurers","url":"https://www.advisorhub.com/centene-plunges-in-foreboding-sign-for-health-insurers/"}]},{"id":"hc-2025-obbba-medicaid","date":"2025-07-04","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services","managed_care"],"direction":"out","magnitude":"major","driver_type":"policy","title":"One Big Beautiful Bill Act cuts Medicaid by about $1 trillion","summary":"The OBBBA, signed July 4 2025, imposes 80-hour monthly work requirements, six-monthly eligibility checks, a provider-tax cap falling from 6% to 3.5% by 2031 and tighter retroactive coverage, cutting federal Medicaid/CHIP funding by roughly $1 trillion over ten years; CBO estimated about 10 million more uninsured by 2034 (10.9 million for the House version), partly offset by a $50 billion rural hospital fund. Hospital operators and Medicaid managed-care insurers (Centene, Molina) carry the exposure, with most provisions phasing in from 2027.","evidence":"CBO: ~$1T reduction in federal Medicaid/CHIP funding over 10 years and ~10M more uninsured by 2034; provider tax cap 6% to 3.5% by 2031","sources":[{"title":"Wikipedia: One Big Beautiful Bill Act","url":"https://en.wikipedia.org/wiki/One_Big_Beautiful_Bill_Act"},{"title":"CRS: Health coverage provisions in H.R. 1","url":"https://www.congress.gov/crs-product/R48569"},{"title":"Select Medical 10-Q (Q3 2025) discussion of OBBBA","url":"https://www.sec.gov/Archives/edgar/data/1320414/000132041425000015/sem-20250930.htm"}]},{"id":"cd-2025-ev-credit-expiry","date":"2025-07-04","end_date":"2025-09-30","sector":"consumer_discretionary","subindustries":["autos"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"OBBBA terminates EV tax credits after September 30 2025","summary":"The One Big Beautiful Bill Act ended the $7,500 new and $4,000 used clean-vehicle credits for purchases after September 30 2025 and the charging-property credit after June 2026. The deadline produced a Q3 2025 EV sales pull-forward followed by a demand cliff in Q4, hitting Rivian, Lucid and the EV programs of GM and Ford, while Tesla's exposure was partly offset by its robotaxi and AI narrative.","evidence":"Clean-vehicle credits end for purchases after 2025-09-30 (OBBBA, signed 2025-07-04)","sources":[{"title":"Wikipedia: One Big Beautiful Bill Act","url":"https://en.wikipedia.org/wiki/One_Big_Beautiful_Bill_Act"}]},{"id":"cs-2025-obbba-snap-cuts","date":"2025-07-04","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail","food_beverage_tobacco"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"OBBBA cuts SNAP by $186 billion","summary":"The One Big Beautiful Bill Act extends SNAP work requirements to ages 18-64, shifts up to 15% of benefit costs and 75% of administration costs to states and restricts Thrifty Food Plan updates, reducing federal nutrition funding by $186 billion over 2025-2034. SNAP is a meaningful share of sales at dollar stores, discount grocers and Walmart and of volumes for packaged-food makers, so the law is a slow-burning headwind for the lower-income staples channel from 2026.","evidence":"Federal nutrition (SNAP) funding reduced by $186B over 2025-2034; work requirements extended to age 64","sources":[{"title":"Wikipedia: One Big Beautiful Bill Act","url":"https://en.wikipedia.org/wiki/One_Big_Beautiful_Bill_Act"}]},{"id":"reshoring-2025-obbba","date":"2025-07-04","end_date":null,"sector":"reshoring_infrastructure","subindustries":[],"direction":"mixed","magnitude":"major","driver_type":"policy","title":"One Big Beautiful Bill Act: solar and wind credits phased out, nuclear and manufacturing kept","summary":"Signed 4 July 2025, the OBBBA ends wind and solar credits for projects not started by June 2026 or online by December 2027, ends residential clean-energy and EV credits after 2025, but keeps advanced-manufacturing (45X), carbon-capture and nuclear credits and adds a 10% nuclear bonus, alongside permanent 100% expensing and a new factory-depreciation allowance. The law split the reshoring theme: solar and residential-energy names derated while nuclear, factory construction and electrical-equipment beneficiaries kept their policy tailwind.","evidence":"OBBBA signed 2025-07-04; wind and solar credits limited to projects beginning construction by June 2026 or in service by December 2027; EV credits end after 2025-09-30.","sources":[{"title":"One Big Beautiful Bill Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/One_Big_Beautiful_Bill_Act"}]},{"id":"re-2025-0704-obbb-medicaid-snf-reits","date":"2025-07-04","end_date":null,"sector":"real_estate","subindustries":["healthcare_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"One Big Beautiful Bill signed: ~$940B Medicaid cuts, but SNF rate cuts dropped and staffing mandate delayed 10 years","summary":"The House passed the One Big Beautiful Bill on July 3, 2025 and President Trump signed it on July 4. The law cuts federal Medicaid spending by roughly $940 billion over 10 years, mainly through work requirements, provider-tax limits (hospital provider-tax ceiling stepping down from 6% to 3.5% in expansion states) and state-directed-payment caps starting in 2027. For skilled-nursing landlords (OHI, SBRA, CTRE, LTC, NHI) the outcome was better than feared: the final text omitted the previously proposed Medicaid reimbursement cuts for SNFs and delayed the federal nursing-home staffing mandate by a decade, which CareTrust's 10-Q said should give 'continued stability' to tenants in high-Medicaid-census states.","evidence":"Signed 2025-07-04; ~$940B Medicaid reduction over 10 years with the federal SNF staffing mandate delayed 10 years (Skilled Nursing News).","sources":[{"title":"Skilled Nursing News: House Passes Big Beautiful Bill With Nursing Home-Friendly Provisions","url":"https://skillednursingnews.com/2025/07/house-passes-big-beautiful-bill-with-nursing-home-friendly-provisions-amid-reverberations-for-long-term-care/"},{"title":"CareTrust REIT 10-Q for Q3 2025 (Medicaid SNF cuts omitted from final law)","url":"https://www.sec.gov/Archives/edgar/data/1590717/000162828025049531/ctre-20250930.htm"},{"title":"PALTmed: The One Big Beautiful Bill and Its Impact on Medicaid, Medicare, and Long-Term Care","url":"https://paltmed.org/news-media/one-big-beautiful-bill-and-its-impact-medicaid-medicare-and-long-term-care"}]},{"id":"materials-2025-copper-tariff","date":"2025-07-09","end_date":"2025-08-01","sector":"materials","subindustries":["metals_mining"],"direction":"in","magnitude":"major","driver_type":"policy","title":"50% copper tariff sends Comex copper to a record $5.65/lb","summary":"Trump announced a 50% Section 232 tariff on copper imports on 9 July 2025, effective 1 August, after a February investigation; Comex copper spiked to a record of about $5.65 a pound as traders front-ran the duty, far above London prices. US producers (Freeport) and recyclers benefited from the arbitrage while wire, cable and electrical-equipment makers faced higher costs for the grid and data-center build-out.","evidence":"50% copper tariff announced 2025-07-09 effective 2025-08-01; Comex copper record of about $5.65/lb (previous record $5.243 on 2025-03-26).","sources":[{"title":"US to impose 50pc tariff on copper imports (Argus Media)","url":"https://www.argusmedia.com/metals-platform/newsandanalysis/article/2708067-US-to-impose-50pc-tariff-on-copper-imports"},{"title":"Trump announces 50% tariff on copper (Nasdaq.com)","url":"https://www.nasdaq.com/articles/trump-announces-50-tariff-copper"}]},{"id":"materials-2025-mp-materials-dod","date":"2025-07-10","end_date":"2025-07-15","sector":"materials","subindustries":["metals_mining"],"direction":"in","magnitude":"major","driver_type":"policy","title":"Pentagon becomes MP Materials' largest shareholder; shares jump about 50%","summary":"On 10 July 2025 the Department of Defense agreed to buy $400 million of MP Materials preferred stock and back a new rare-earth magnet plant, making it the company's largest shareholder; the shares surged about 50%, and Apple's $500 million supply investment on 15 July added another 17%. The deal signalled direct state equity in critical-minerals supply chains, a template later extended to Intel.","evidence":"DoD $400 million preferred-stock investment announced 2025-07-10; MP shares up about 50%, then +17% on Apple's $500 million deal (2025-07-15).","sources":[{"title":"MP Materials (Wikipedia)","url":"https://en.wikipedia.org/wiki/MP_Materials"}]},{"id":"re-2025-opendoor-meme-squeeze","date":"2025-07-14","end_date":"2025-07-31","sector":"real_estate","subindustries":["real_estate_services"],"direction":"mixed","magnitude":"moderate","driver_type":"positioning","title":"Opendoor becomes the new meme stock","summary":"A hedge-fund manager's $82 target and WallStreetBets attention sent Opendoor from about $0.55 at the start of July 2025 to a $4.97 high on July 21 (intraday +121% that day, ~+600% for the month) with 22% of the float short; it then fell 40% in a week. The episode showed how little institutional ownership remained in the iBuying/brokerage names, which still ended 2025 up 264% before losing 69% in 2026 as mortgage rates rose back above 7%.","evidence":"OPEN rose from ~$0.50-0.60 at the start of July 2025 to a $4.97 high; +42.7% close on Jul 21, 2025; OPEN +264.4% in 2025 and -69.3% YTD 2026","sources":[{"title":"Bloomberg: Opendoor shares jump as traders flock to newest meme stock","url":"https://www.bloomberg.com/news/articles/2025-07-21/opendoor-shares-swing-as-traders-flock-to-newest-meme-stock"},{"title":"XTB: Opendoor up 90% and nearly 600% since the beginning of July","url":"https://www.xtb.com/sca-en/market-analysis/news-and-research/opendoor-up-90-and-nearly-600-since-the-beginning-of-july-the-next-gamestop"},{"title":"ChartRow OPEN calendar-year returns","url":"https://chartrow.com/quote/open/returns"}]},{"id":"re-2025-0716-prologis-q2-2025-guidance-raise","date":"2025-07-16","end_date":null,"sector":"real_estate","subindustries":["industrial_logistics_reits"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Prologis Q2 2025: Core FFO beat, low end of guidance raised, development starts guidance lifted 43%","summary":"On July 16, 2025 Prologis reported Q2 Core FFO of $1.46 per share (up 9% y/y and 4 cents above consensus) on revenue of $2.18 billion (+9%). It raised the low end of full-year Core FFO guidance by 10 cents to $5.80-$5.85 (ex-promotes) and lifted development-starts guidance to $2.25-$2.75 billion, a 43% increase at the midpoint, signalling that tariff-driven paralysis in leasing decisions had eased. Average occupancy was 94.9% (period-end 95.1%) and new leases commenced rose 10% y/y to 51.2 million sq ft.","evidence":"Q2 2025 Core FFO $1.46/share, +9.0% y/y; FY Core FFO guidance low end raised $0.10 to $5.80-$5.85 (2025-07-16).","sources":[{"title":"FreightWaves: First look: Prologis Q2 earnings","url":"https://www.freightwaves.com/news/first-look-prologis-q2-earnings"},{"title":"Prologis Q2 2025 results press release (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/1045609/000095017025096077/pld-ex99_2.htm"}]},{"id":"fintech-2025-genius-act","date":"2025-07-18","end_date":null,"sector":"technology","subindustries":["fintech_payments"],"direction":"in","magnitude":"major","driver_type":"regulatory","title":"GENIUS Act signed: federal stablecoin framework","summary":"The GENIUS Act passed the Senate 68-30 on 17 June 2025 and the House 308-122 on 17 July, and was signed on 18 July 2025, requiring payment stablecoins to be backed one-for-one by dollars or low-risk assets and carving them out of securities and commodities law. Circle jumped nearly 20% and Coinbase 16% on the Senate vote; the signing-day reaction was muted (Coinbase +1.9%, Circle +0.9% the next session), and banks and card networks began planning their own stablecoin and deposit-token products.","evidence":"Signed 2025-07-18 after a 68-30 Senate vote (2025-06-17) and 308-122 House vote (2025-07-17).","sources":[{"title":"GENIUS Act (Wikipedia)","url":"https://en.wikipedia.org/wiki/GENIUS_Act"},{"title":"Crypto-linked stocks advance as Trump signs stablecoin law (Reuters via The Star)","url":"https://www.thestar.com.my/tech/tech-news/2025/07/21/crypto-linked-stocks-advance-as-trump-signs-stablecoin-law"},{"title":"Crypto stocks soar after Senate passes stablecoin bill (Fortune)","url":"https://fortune.com/crypto/2025/06/20/crypto-stocks-soar-after-senate-passes-stablecoin-bill-circle-up-over-50"}]},{"id":"en-2025-0718-chevron-wins-hess-arbitration","date":"2025-07-18","end_date":null,"sector":"energy","subindustries":["integrated"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"ICC panel rules for Chevron over Exxon; $53B Hess deal closes same day","summary":"On July 18, 2025 the International Chamber of Commerce arbitration panel rejected ExxonMobil's claim that its right of first refusal covered Hess's 30% Stabroek stake, letting Chevron close its $53 billion all-stock Hess acquisition the same day. Chevron shares rose roughly 3.4%-3.6% premarket and Hess 7.4%-7.7%, while Exxon was marginally lower. The ruling removed an 18-month overhang on Chevron and reset the Guyana growth story inside the integrated group.","evidence":"Chevron +3.6% and Hess +7.4% premarket on 2025-07-18; deal closed same day (CNN)","sources":[{"title":"CNN - Chevron's megadeal for Hess gets approval after winning legal battle with Exxon","url":"https://edition.cnn.com/2025/07/18/business/chevron-hess-exxon"},{"title":"Oil & Gas Journal - Arbitrator rules in favor of Chevron, Hess in Guyana dispute with ExxonMobil","url":"https://www.ogj.com/general-interest/companies/article/55304089/arbitrator-rules-in-favor-of-chevron-hess-in-guyana-dispute-with-exxonmobil"}]},{"id":"defense-2025-lockheed-q2-charges","date":"2025-07-22","end_date":null,"sector":"industrials","subindustries":["defense"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Lockheed Martin takes $1.6bn of program charges and falls 11%, its worst day since 2021","summary":"On July 22, 2025 Lockheed Martin disclosed $1.6bn of program losses plus $169m of other charges, mainly on a classified Skunk Works aeronautics program and helicopter programs for Canada and Turkey, after a review by its new CFO; Q2 profit fell about 80% and 2025 EPS guidance was cut to $21.70-22.00 from $27.00-27.30. Shares plunged nearly 11%, the biggest drop since October 2021, and Truist downgraded the stock. The episode revived fixed-price-contract fears across the primes even as F-35 deliveries continued (50 in the quarter).","evidence":"LMT -~11% on 2025-07-22; $1.6bn program losses; 2025 EPS guide cut to $21.70-22.00 from $27.00-27.30.","sources":[{"title":"Lockheed flags $1.6 billion in charges as new CFO digs deep (Bloomberg)","url":"https://www.bloomberg.com/news/articles/2025-07-22/lockheed-cuts-earnings-outlook-after-booking-program-charges"},{"title":"Lockheed Martin sinks after surprise program losses slash Q2 earnings (Seeking Alpha)","url":"https://seekingalpha.com/news/4469862-lockheed-martin-sinks-after-surprise-program-losses-slash-q2-earnings"},{"title":"Lockheed Martin shares fell 8% after company cuts earnings outlook (Invezz)","url":"https://invezz.com/news/2025/07/22/lockheed-martin-shares-fell-8-after-company-cuts-earnings-outlook/"}]},{"id":"utilities-2025-pjm-auction-record-329","date":"2025-07-22","end_date":null,"sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"PJM capacity auction clears at record $329.17/MW-day cap on data-center load","summary":"PJM's 2026/27 Base Residual Auction, released 2025-07-22, cleared at the FERC-approved cap of $329.17/MW-day across the entire footprint, up 22% from $269.92, procuring 134,311 MW at a total cost of $16.1bn; PJM said the price would have been about $389 without the cap and attributed roughly 5,500 MW of peak-load growth mainly to data centers. The result validated the load-growth thesis behind regulated utilities and generators in PJM (Exelon, PSEG, AEP, Dominion, FirstEnergy, PPL) while raising political pressure on retail bills.","evidence":"PJM 2026/27 BRA cleared at $329.17/MW-day on 2025-07-22 (+22% y/y)","sources":[{"title":"PJM news release: auction procures 134,311 MW, supply responds to price signal","url":"https://www.pjm.com/-/media/DotCom/about-pjm/newsroom/2025-releases/20250722-pjm-auction-procures-134311-mw-of-generation-resources-supply-responds-to-price-signal.pdf"},{"title":"Utility Dive: PJM capacity prices set another record with 22% jump","url":"https://www.utilitydive.com/news/pjm-interconnection-capacity-auction-prices/753798/"}]},{"id":"restaurants-2025-low-income-stress","date":"2025-07-23","end_date":"2025-10-30","sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"moderate","driver_type":"macro","title":"Chipotle cuts guidance three times as younger and lower-income diners pull back","summary":"Chipotle reported a 4% same-store sales decline for Q2 2025 (worse than the -2.9% expected) on July 23 and cut its full-year comp outlook to flat, sending the shares down about 9%. On October 29 it cut for a third time, to a low-single-digit decline, citing younger and lower-income consumers cutting back; the stock fell 13% after hours and as much as 19% the next day, dragging Sweetgreen and Cava. The sequence turned the 'K-shaped consumer' from a thesis into reported numbers for fast casual and QSR.","evidence":"Chipotle Q2 2025 same-store sales -4.0% vs -2.9% consensus (reported 2025-07-23).","sources":[{"title":"Chipotle stock tumbles 9% after chain cuts same-store sales forecast (CNBC)","url":"https://www.cnbc.com/2025/07/23/chipotle-mexican-grill-cmg-q2-2025-earnings.html"},{"title":"Chipotle stock plunges 13% as chain lowers sales forecast, says younger diners are cutting back (CNBC)","url":"https://www.cnbc.com/2025/10/29/chipotle-cmg-earnings-q3-2025.html"},{"title":"Chipotle cuts same-store sales forecast as traffic slumps (eMarketer)","url":"https://www.emarketer.com/content/chipotle-cuts-same-store-sales-forecast-traffic-slumps"}]},{"id":"re-2025-0724-digital-realty-q2-record-bookings","date":"2025-07-24","end_date":null,"sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Digital Realty Q2 2025: record $90M 0-1MW bookings, Core FFO +13%, guidance raised $0.10","summary":"On July 24, 2025 Digital Realty reported Q2 Core FFO of $1.87 per share (+13% y/y, a record) and $177 million of gross bookings at 100% share ($135 million at DLR's share), including a record $90 million in the 0-1 MW plus interconnection category, 18% above the previous record, with year-to-date leasing of $575 million. It raised full-year 2025 Core FFO guidance by $0.10 to $7.15-$7.25 and lifted revenue and adjusted EBITDA guidance by $100 million and $75 million. Shares rose about 0.5% after hours to $180.15, a reassuring read-through for the AI leasing cycle a month after Equinix's analyst-day selloff.","evidence":"Record $90M 0-1MW+interconnection bookings and FY2025 Core FFO guidance raised $0.10 to $7.15-$7.25 (2025-07-24).","sources":[{"title":"Digital Realty Q2 2025 results (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/1297996/000155837025009543/dlr-20250724xex99d1.htm"},{"title":"Investing.com: Earnings call transcript: Digital Realty Q2 2025 earnings surpass expectations","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-digital-realty-q2-2025-earnings-surpass-expectations-93CH-4152177"}]},{"id":"en-2025-0728-venture-global-cp2-fid","date":"2025-07-28","end_date":null,"sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"moderate","driver_type":"macro","title":"Venture Global takes FID on CP2 Phase 1 with $15.1B financing; LNG FID wave of 2025","summary":"On July 28, 2025 Venture Global announced final investment decision and financial close on Phase 1 of its 28 mtpa CP2 LNG project in Louisiana, with $15.1 billion of project financing covering the plant and the CP Express pipeline and first LNG targeted for 2027. It capped a run of US export FIDs in mid-2025 (Cheniere's Corpus Christi midscale Trains 8-9 in June 2025 under a ~$2.9B Bechtel EPC, NextDecade's Rio Grande Train 4 in September 2025) that underpinned the gas-pipeline volume thesis for Kinder Morgan, Williams, Energy Transfer and Cheniere (LNG).","evidence":"$15.1 billion CP2 Phase 1 project financing closed 2025-07-28; project peak capacity 28 mtpa","sources":[{"title":"Venture Global - FID and Financial Close for Phase 1 of CP2 LNG","url":"https://ventureglobal.com/2025/07/28/venture-global-announces-final-investment-decision-and-financial-close-for-phase-1-of-cp2-lng/"},{"title":"Cheniere Energy 8-K (June 2025) - Corpus Christi midscale Trains 8 & 9 notice to proceed","url":"https://www.sec.gov/Archives/edgar/data/3570/000000357025000088/lng-20250617.htm"},{"title":"Natural Gas Intelligence - Venture Global poised to take US LNG export crown after FID on second phase of CP2","url":"https://naturalgasintel.com/news/venture-global-poised-to-take-us-lng-export-crown-after-reaching-fid-on-second-phase-of-cp2/"}]},{"id":"re-2025-0728-welltower-q2-2025-shop-surge","date":"2025-07-28","end_date":null,"sector":"real_estate","subindustries":["healthcare_reits"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Welltower Q2 2025: FFO +21.9%, senior housing NOI +23.4%, occupancy +420 bp; guidance raised, shares +3.5%","summary":"Welltower reported Q2 2025 after the close on July 28, 2025: normalized FFO of $1.28 per share (+21.9% y/y), revenue of $2.55 billion versus $2.45 billion expected, senior housing operating (SHOP) same-store NOI growth of 23.4%, a 420 bp y/y occupancy gain (the largest outside the post-COVID recovery) and RevPOR growth of 4.9%. It raised the midpoint of 2025 normalized FFO guidance by $0.13 to $5.10 ($5.06-$5.14) and disclosed $2 billion of equity raised in the quarter. Investing.com reported WELL shares up 3.47% to $160.52 after the print, extending the 80+ demographics / senior housing recovery trade that also lifts Ventas and American Healthcare REIT.","evidence":"Q2 2025 normalized FFO $1.28/share (+21.9%), SHOP SSNOI +23.4%; WELL +3.47% to $160.52 after the 2025-07-28 release.","sources":[{"title":"Welltower Q2 2025 earnings release (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/766704/000076670425000027/a2q25earningsrelease991.htm"},{"title":"Investing.com: Earnings call transcript: Welltower Q2 2025 results show strong revenue growth","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-welltower-q2-2025-results-show-strong-revenue-growth-93CH-4157934"}]},{"id":"hc-2025-novo-guidance-cut","date":"2025-07-29","end_date":"2025-09-10","sector":"healthcare","subindustries":["pharma"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Novo Nordisk guidance cut: the GLP-1 leader loses its crown","summary":"Novo slashed 2025 growth guidance on July 29 2025 as compounded semaglutide and Lilly's Zepbound took US share, and the shares plummeted (WSJ: 'Novo Nordisk shares plummet as competition weighs on sales'). Having been the world's second most valuable drugmaker in late 2024, Novo had slipped to fifth by July 2025; a new CEO took over on August 7 and 9,000 job cuts (about 9% of staff) were announced in September. Capital concentrated further in Lilly.","evidence":"Novo fell from 2nd most valuable drug company (Oct 2024) to 5th by July 2025; 9,000 job cuts announced September 2025","sources":[{"title":"Wikipedia: Novo Nordisk (2025 developments)","url":"https://en.wikipedia.org/wiki/Novo_Nordisk"}]},{"id":"glp1-2025-novo-collapse","date":"2025-07-29","end_date":"2025-11-14","sector":"glp1","subindustries":[],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Novo Nordisk cuts guidance and falls 22% in a day","summary":"Novo Nordisk cut its 2025 sales-growth guidance to 8-14% from 13-21% on 29 July 2025, citing slower US Wegovy growth and compounded copies, and its shares fell 21.7% to DKK 346.9; by 14 November the stock was down 47% for the year, with its GLP-1 share at 49.3% versus 55.7% a year earlier as Lilly's tirzepatide took share. The GLP-1 theme shifted from a duopoly growth trade to a market-share and pricing contest.","evidence":"Novo shares -21.7% to DKK 346.9 on 2025-07-29; 2025 guidance cut to 8-14% sales growth from 13-21%.","sources":[{"title":"Novo Nordisk shares plummet as 2025 guidance is cut (Pharmaceutical Technology)","url":"https://www.pharmaceutical-technology.com/news/novo-nordisk-shares-plummet-as-2025-guidance-is-cut-overshadowing-new-ceo/"},{"title":"Why is everyone talking about Novo Nordisk stock (Motley Fool, 2025-11-14)","url":"https://www.fool.com/investing/2025/11/14/why-is-everyone-talking-about-novo-nordisk-stock"}]},{"id":"transport-2025-union-pacific-norfolk-southern-merger","date":"2025-07-29","end_date":null,"sector":"industrials","subindustries":["transportation"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"Union Pacific agrees to buy Norfolk Southern for $85bn: the first transcontinental railroad","summary":"On July 29, 2025 Union Pacific agreed to acquire Norfolk Southern for one UNP share plus $88.82 in cash per NSC share (about $320 a share, $85bn including debt), creating the first coast-to-coast US railroad. Norfolk Southern fell about 3% to around $277 on announcement because the price was below where it had run on talk reports, Union Pacific slipped about 2% on dilution and regulatory risk, and CSX, which had risen on the July talks reports as the next target, lost 1.4%. UNP holders approved the issuance with 99.5% support in November 2025; the STB lifted its abeyance in August 2026 and set a statutory decision deadline of August 28, 2027.","evidence":"Deal terms: 1.0 UNP share + $88.82 cash per NSC share (~$320); NSC -~3% to $277.40 on 2025-07-29; STB decision deadline 2027-08-28.","sources":[{"title":"Union Pacific to buy Norfolk Southern in $85 billion deal (Transport Topics)","url":"https://www.ttnews.com/articles/ns-up-railroad-merger"},{"title":"Union Pacific to buy rival Norfolk Southern in $320 per share deal (Investing.com)","url":"https://ng.investing.com/news/stock-market-news/union-pacific-to-buy-rival-norfolk-southernin-320-per-share-deal-2031352"},{"title":"STB lifts abeyance in Union Pacific-Norfolk Southern merger and sets procedural schedule (Thompson Hine)","url":"https://www.thompsonhine.com/insights/stb-lifts-abeyance-in-union-pacific-norfolk-southern-merger-and-sets-procedural-schedule/"}]},{"id":"en-2025-0729-baker-hughes-chart-deal","date":"2025-07-29","end_date":null,"sector":"energy","subindustries":["oilfield_services"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Baker Hughes agrees to buy Chart Industries for $13.6B; OFS consolidation accelerates","summary":"On July 29, 2025 Baker Hughes agreed to acquire Chart Industries for $210 per share in cash, a $13.6 billion enterprise value and a 22% premium, ending Chart's pending merger with Flowserve; Chart shares surged about 16.5% to $200 after hours. The deal came two weeks after SLB closed its ~$4.9 billion all-stock ChampionX acquisition on July 16, 2025, marking a shift by the big-three service companies toward production, LNG and industrial equipment as North American drilling activity shrank. Baker Hughes' leverage from the deal (2.5x) later weighed on its stock after Q3 2026 results.","evidence":"$210/share cash, $13.6B EV, 22% premium announced 2025-07-29; Chart +16.5% after hours","sources":[{"title":"Baker Hughes - Baker Hughes to Acquire Chart Industries","url":"https://investors.bakerhughes.com/news/press-releases/news-details/2025/Baker-Hughes-to-Acquire-Chart-Industries-Accelerating-Energy-Industrial-Technology-Strategy-07-29-2025/default.aspx"},{"title":"Bloomberg - Baker Hughes to Acquire Chart Industries in $13.6 Billion Deal","url":"https://www.bloomberg.com/news/articles/2025-07-29/baker-hughes-to-acquire-chart-industries-in-13-6-billion-deal"},{"title":"SLB - SLB Completes Acquisition of ChampionX (July 16, 2025)","url":"https://www.slb.com/newsroom/press-release/2025/slb-completes-acquisition-of-championx"}]},{"id":"re-2025-0729-cbre-q2-beat-raises-guidance","date":"2025-07-29","end_date":null,"sector":"real_estate","subindustries":["real_estate_services"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"CBRE Q2: revenue +16%, core EPS +47%, guidance raised; stock +5% premarket","summary":"On July 29, 2025 CBRE reported Q2 revenue of $9.75B (+16% YoY) and core EPS of $1.19 (+47%), and raised its 2025 core EPS outlook to $6.10-$6.20 from $5.80-$6.10, pointing to a recovery in capital-markets and leasing activity; shares were up 5.47% in premarket trading on the report. The print anchored the 'transaction-volume recovery' trade in commercial real-estate services (CBRE, JLL, CWK, NMRK) through the summer of 2025 as rate-cut expectations built ahead of the September FOMC.","evidence":"CBRE Q2 2025 (reported 2025-07-29): revenue $9.75B (+16%), core EPS $1.19 (+47%), 2025 core EPS guidance raised to $6.10-$6.20.","sources":[{"title":"CBRE Group, Inc. Reports Financial Results for Second-Quarter 2025 (company press release)","url":"https://www.cbre.com/press-releases/cbre-q2-2025-earnings"},{"title":"CBRE Group Soars 5.47% on Strong Q2 Earnings Beat and Raised 2025 Guidance (Tiger Brokers, Jul 29 2025)","url":"https://www.itiger.com/news/1148380612"},{"title":"CBRE Q2 2025 presentation: Revenue jumps 16%, company raises full-year guidance (Investing.com)","url":"https://www.investing.com/news/company-news/cbre-q2-2025-presentation-revenue-jumps-16-company-raises-fullyear-guidance-93CH-4156989"}]},{"id":"cyber-2025-palo-alto-cyberark","date":"2025-07-30","end_date":"2026-02-28","sector":"cybersecurity","subindustries":["infrastructure_software_cyber"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Palo Alto Networks buys CyberArk for $25 billion","summary":"Palo Alto Networks announced a $25 billion acquisition of identity-security vendor CyberArk on 30 July 2025, closing in February 2026, extending the platform-consolidation thesis that has driven security budgets toward a few large vendors. With Google's Wiz purchase, 2025 saw more than $57 billion of cybersecurity M&A, supporting takeover premiums across mid-cap security names.","evidence":"Palo Alto Networks-CyberArk deal announced 2025-07-30 at $25 billion; closed February 2026.","sources":[{"title":"CyberArk (Wikipedia)","url":"https://en.wikipedia.org/wiki/CyberArk"},{"title":"Wiz (Wikipedia)","url":"https://en.wikipedia.org/wiki/Wiz_(company)"}]},{"id":"re-2025-0731-host-park-q2-2025-prints","date":"2025-07-31","end_date":null,"sector":"real_estate","subindustries":["lodging_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"Lodging REIT Q2 2025 prints split: Host raises RevPAR outlook but guides Q3 negative (HST -2.2%); Park cuts RevPAR guidance 150 bp","summary":"Host Hotels reported Q2 2025 comparable RevPAR +3.0% and total RevPAR +4.2%, beat with EPS of $0.32 vs $0.22 expected, and raised its 2025 comparable RevPAR growth range to 1.5%-2.5% with the adjusted EBITDAre midpoint up $60 million to $1.705 billion, but told investors Q3 RevPAR would be negative on soft short-term group volume; Investing.com reported HST fell 2.17% to $16.13 in the regular session around the print. Park Hotels, reporting July 31, 2025, posted comparable RevPAR -1.6% (Hawaii -11.6% on occupancy of 78.6% vs 86.9%) and cut its 2025 comparable RevPAR guidance to -2.0% to 0.0% from -1.0% to +2.0%, a 150 bp midpoint reduction. The pair framed the mid-2025 lodging debate: coastal/luxury resilience versus weakening group, Hawaii and inbound demand.","evidence":"Park Hotels cut 2025 comparable RevPAR guidance to (2.0)%-0.0% from (1.0)%-2.0% on 2025-07-31; HST -2.17% to $16.13 on its Q2 print.","sources":[{"title":"Park Hotels & Resorts Inc. Reports Second Quarter 2025 Results","url":"https://www.pkhotelsandresorts.com/investors/news-and-events/press-releases/2025/07-31-2025-211622886"},{"title":"Investing.com: Earnings call transcript: Host Hotels beats Q2 2025 forecasts, stock dips","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-host-hotels-beats-q2-2025-forecasts-stock-dips-93CH-4164268"},{"title":"Host Hotels & Resorts Q2 2025 results (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/1070750/000107075025000094/hst-ex991.htm"}]},{"id":"software-2025-figma-ipo","date":"2025-07-31","end_date":null,"sector":"technology","subindustries":["application_software"],"direction":"in","magnitude":"moderate","driver_type":"tech_cycle","title":"Figma IPO prices at $33 and closes up ~250%","summary":"Figma priced its NYSE IPO at $33 (above the $30-32 range), raised about $1.2bn, opened at $85 and closed its first session near $115.50, a gain of roughly 250% that valued the design-software company around $68bn. The blowout debut reopened the software IPO window and briefly re-rated growth software sentiment, although the stock fell 27% on its third session and later gave back about half its pop.","evidence":"FIG closed at ~$115.50 on 2025-07-31 vs $33 IPO price (~+250%)","sources":[{"title":"CNBC: Figma's top VCs sitting on $24 billion worth of stock after massive IPO pop","url":"https://www.cnbc.com/2025/07/31/figmas-top-vcs-sitting-on-20-billion-in-stock-after-ipo-pop.html"},{"title":"Crunchbase News: Figma first-day IPO trading triples","url":"https://news.crunchbase.com/public/saas-figma-first-day-ipo-trading-triples/"}]},{"id":"re-2025-0804-elme-cortland-sale-liquidation","date":"2025-08-04","end_date":null,"sector":"real_estate","subindustries":["residential_reits"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"Elme Communities sells 19 apartment assets to Cortland for $1.6B and will liquidate","summary":"On August 4, 2025 Elme Communities concluded its strategic review by agreeing to sell 19 multifamily properties (16 in the DC area, 3 in Atlanta) to Cortland for $1.6 billion in cash and announced a plan of liquidation, marketing its remaining nine apartment assets and the Watergate 600 office building over the following 12 months. The company guided to upfront distributions of roughly $14.68-$15.00 per share plus later residual payouts. The deal was read as a private-market mark for apartment REITs trading at discounts to NAV, supporting the public-to-private arbitrage thesis across the group (AVB, EQR, UDR, CPT, IRT, NXRT).","evidence":"19-property portfolio sale to Cortland for $1.6 billion announced 2025-08-04; estimated upfront distributions $14.68-$15.00 per share (Elme press release).","sources":[{"title":"Elme Communities Concludes Strategic Alternatives Review; Agreement to Sell 19 Properties to Cortland (press release)","url":"https://ir.elmecommunities.com/news-events/press-releases/detail/372/elme-communities-concludes-strategic-alternatives-review"},{"title":"Elme Communities to Dissolve After $1.6B Multifamily Sale to Cortland (Commercial Observer, Aug 4 2025)","url":"https://commercialobserver.com/2025/08/elme-multifamily-dissolve-cortland/"}]},{"id":"re-2025-0804-simon-q2-2025-occupancy-guidance","date":"2025-08-04","end_date":null,"sector":"real_estate","subindustries":["retail_reits"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Simon Property Q2 2025: occupancy 96.0%, Mills at record 99.3%, FFO guidance raised despite 1.8M sq ft of bankruptcy fallout","summary":"Simon Property Group reported Q2 2025 on August 4, 2025 with Real Estate FFO of $3.05 per share (+4.1% y/y), US Malls and Premium Outlets occupancy of 96.0% (+40 bp y/y) and a record 99.3% at The Mills, and raised the midpoint of 2025 Real Estate FFO guidance to $12.45-$12.65. Roughly 1,000 leases for 3.6 million sq ft were signed in the quarter even as management said retailer bankruptcies (Forever 21, Joann, Rite Aid and others earlier in 2025) touched about 1.8 million sq ft of space, underscoring the lack-of-new-supply backfill story for Class A retail.","evidence":"US Malls & Premium Outlets occupancy 96.0% at 2025-06-30 vs 95.6% a year earlier; 2025 Real Estate FFO guidance midpoint raised to $12.45-$12.65 (reported 2025-08-04).","sources":[{"title":"Simon Property Group Q2 2025 results (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/1063761/000110465925073630/tm2521096d2_ex99-1.htm"},{"title":"Commercial Observer: Simon Property Group Raises Guidance After Q2 Earnings, Occupancy Gains","url":"https://commercialobserver.com/2025/08/simon-property-group-q2-earnings-retail/"}]},{"id":"semis-2025-intel-government-stake","date":"2025-08-22","end_date":"2025-09-18","sector":"technology","subindustries":["semiconductors","semicap"],"direction":"in","magnitude":"major","driver_type":"policy","title":"US government takes a 9.9% stake in Intel; Nvidia invests $5 billion","summary":"The US government bought 433.3 million Intel shares at $20.47 (about 9.9%) in August 2025, a week after SoftBank paid $23 a share, with warrants for a further 5% if Intel's foundry ownership falls below 51%; in September 2025 Nvidia invested $5 billion to co-develop data-center and PC chips. State and strategic equity turned Intel from a restructuring story into a policy-backed foundry bet, and Intel became one of the leaders of the 2026 semiconductor rally.","evidence":"US government purchase of 433.3 million Intel shares at $20.47 (about 9.9%) announced August 2025; Nvidia $5 billion investment September 2025.","sources":[{"title":"Intel (Wikipedia)","url":"https://en.wikipedia.org/wiki/Intel"}]},{"id":"en-2025-0822-epa-small-refinery-exemptions","date":"2025-08-22","end_date":null,"sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"EPA clears 175 small-refinery exemption petitions, grants 63 in full and 77 at 50%","summary":"On August 22, 2025 EPA ruled on 175 backlogged RFS small refinery exemption petitions from 38 refineries for 2016-2024, fully granting 63, partially (50%) granting 77 and denying 28, and formalized a partial-relief policy. D6 RINs jumped to $1.15 on the day (+8.2% per Platts) on reallocation fears, while small-refinery-exposed names benefited directly: Delek said the exemptions cut its net RIN obligation by about $280.8 million in Q3 2025. HF Sinclair units sued in October 2025 over denials, and EPA later reallocated 70% of the waived volumes into the 2026-27 standards.","evidence":"63 full and 77 partial exemptions granted 2025-08-22; Platts D6 RIN $1.15 (+8.2%) that day","sources":[{"title":"EPA - August 2025 Decisions on Petitions for RFS Small Refinery Exemptions","url":"https://www.epa.gov/renewable-fuel-standard/august-2025-decisions-petitions-rfs-small-refinery-exemptions"},{"title":"S&P Global - US EPA fully grants 63 petitions from small refiners seeking exemptions from RFS","url":"https://www.spglobal.com/energy/en/news-research/latest-news/agriculture/082225-us-epa-fully-grants-63-petitions-from-small-refiners-seeking-exemptions-from-rfs"},{"title":"Delek US Holdings 10-Q Q3 2025","url":"https://www.sec.gov/Archives/edgar/data/1694426/000162828025050541/dk-20250930.htm"}]},{"id":"cs-2025-kdp-jde-peets","date":"2025-08-25","end_date":"2026-04-07","sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"Keurig Dr Pepper buys JDE Peet's for $18 billion and plans to split","summary":"KDP agreed to buy JDE Peet's for $18 billion (EUR 15.7 billion) and to separate into a global coffee company and a US beverage company; the stock fell 11% on August 25 2025 and S&P put it on CreditWatch negative on leverage and deal complexity. The deal closed in 2026 with 96% of JDE Peet's shares tendered. It was part of a 2025 wave of defensive restructurings in food and beverage (Kraft Heinz split, Kellanova sale) as the group searched for growth.","evidence":"KDP -11% on 2025-08-25 on the $18B JDE Peet's deal; S&P CreditWatch negative","sources":[{"title":"Barchart/AP: Dr Pepper buys Peet's for $18 billion and will split","url":"https://www.barchart.com/story/news/34363048/dr-pepper-buys-peet-s-for-18-billion-and-will-split-into-separate-coffee-and-cold-drink-sellers"},{"title":"JDE Peet's: Keurig Dr Pepper acquires JDE Peet's","url":"https://www.jdepeets.com/news-container/keurig-dr-pepper-acquires-jde-peets-and--announces-rafael-oliveira-as-ceo-of-future-global-coffee-co.-3266395"}]},{"id":"re-2025-0825-public-storage-withdraws-abacus-bid","date":"2025-08-25","end_date":null,"sector":"real_estate","subindustries":["self_storage_reits"],"direction":"mixed","magnitude":"minor","driver_type":"ma","title":"Public Storage and Ki Corp walk away from A$2.2B Abacus Storage King bid","summary":"On August 25, 2025 Public Storage and Ki Corporation withdrew their non-binding offer for ASX-listed Abacus Storage King after due diligence, having raised the bid from A$1.47 to A$1.65 per security (about A$2.2B) in July; CEO Joe Russell said the consortium 'was unable to match their Independent Board Committee's value assessment.' The retreat ended PSA's first major overseas platform attempt and signalled pricing discipline from the sector's largest buyer during a period of flat street rates, ahead of PSA's domestic consolidation push (49 facilities for $511M in Q3 2025 and the 2026 NSA deal). Abacus Group later sold its 19.6% stake, with Ki taking much of it.","evidence":"Offer withdrawn 2025-08-25 after a revised A$1.65 per security proposal in July 2025 (Investing.com; Nasdaq press release).","sources":[{"title":"Public Storage withdraws bid for Abacus Storage King (Investing.com, Aug 25 2025)","url":"https://www.investing.com/news/company-news/public-storage-withdraws-bid-for-abacus-storage-king-93CH-4209972"},{"title":"Ki Corporation and Public Storage Withdraw Offer to Acquire Abacus Storage King (press release via Nasdaq)","url":"https://www.nasdaq.com/press-release/ki-corporation-and-public-storage-withdraw-offer-acquire-abacus-storage-king-2025-08"},{"title":"Ki Corporation and Public Storage scrap $2.2b Abacus Storage King buyout (Capital Brief)","url":"https://www.capitalbrief.com/briefing/ki-corporation-and-public-storage-scrap-22b-abacus-storage-king-buyout-4d0d84f0-785f-4956-92a2-1c0b32342314/"}]},{"id":"telecom-2025-echostar-spectrum-sales","date":"2025-08-26","end_date":"2026-07-28","sector":"technology","subindustries":["telecom"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"EchoStar sells spectrum to AT&T ($23 billion) and SpaceX ($17 billion)","summary":"Under FCC pressure over unmet 5G build-out obligations, EchoStar agreed on 26 August 2025 to sell spectrum licences to AT&T for $23 billion in cash (closed 28 July 2026) and on 8 September to SpaceX for about $17 billion. The sales ended the fourth-carrier experiment, handed AT&T and Verizon mid-band capacity, and left EchoStar's Dish DBS pay-TV unit to file for Chapter 11 in June 2026.","evidence":"AT&T agreed to buy EchoStar spectrum for $23 billion on 2025-08-26; SpaceX deal of about $17 billion announced 2025-09-08.","sources":[{"title":"EchoStar (Wikipedia)","url":"https://en.wikipedia.org/wiki/EchoStar"}]},{"id":"re-2025-0826-att-echostar-spectrum-towers","date":"2025-08-26","end_date":null,"sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"moderate","driver_type":"ma","title":"AT&T buys $23B of EchoStar spectrum, signalling Dish's exit as the fourth tower tenant","summary":"On August 26, 2025 AT&T agreed to buy roughly 30 MHz of nationwide 3.45 GHz and 20 MHz of 600 MHz spectrum from EchoStar for about $23 billion in cash. The deal effectively ended EchoStar/Dish Wireless's standalone network build, the marginal source of new leasing for American Tower, Crown Castle and SBA since 2021; Dish leases represented an estimated 5.1%-7.0% of annual rental revenue across roughly 25,000 macro sites, with more than $9 billion of contracted tower revenue later judged at risk after EchoStar declared its master lease agreements 'excused'. AT&T closed the purchase on July 28, 2026.","evidence":"AT&T-EchoStar ~$23B spectrum purchase announced 2025-08-26; Dish estimated at 5.1%-7.0% of AMT/CCI/SBAC rental revenue.","sources":[{"title":"AT&T: AT&T to Acquire Spectrum Licenses from EchoStar","url":"https://about.att.com/story/2025/echostar.html"},{"title":"Wireless Estimator: The DISH default crisis: How EchoStar's spectrum exit could endanger the wireless tower ecosystem","url":"https://wirelessestimator.com/articles/2026/the-dish-default-crisis-how-echostars-spectrum-exit-could-endanger-the-wireless-tower-ecosystem/"},{"title":"DCD: EchoStar's tower payments dispute could cost industry $9bn","url":"https://www.datacenterdynamics.com/en/news/echostars-tower-payments-dispute-could-cost-industry-9bn-wia-warns-jobs-could-go/"}]},{"id":"en-2025-0828-ferc-reissues-nese-certificate","date":"2025-08-28","end_date":null,"sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"FERC reissues Williams' NESE certificate; Northeast pipeline expansion revived","summary":"On August 28, 2025 FERC reissued the certificate for Transco's Northeast Supply Enhancement project, which Williams had abandoned in 2024 after New York and New Jersey denied water permits, clearing 400,000 Dth/d of new capacity into New York City targeted for Q4 2027. Williams had asked for re-approval in May citing the national energy emergency declaration; New York subsequently reversed itself on the Clean Water Act permits and New Jersey's Tidelands council gave the final license. The order was read as a template for reviving Constitution and other blocked Northeast gas lines, a key permitting-reform catalyst for Williams, Kinder Morgan and Enbridge.","evidence":"FERC reissued the NESE certificate on 2025-08-28 for up to 400,000 Dth/d, in-service targeted Q4 2027","sources":[{"title":"Oil & Gas Journal - FERC re-approves Williams' gas pipeline expansion into New York City","url":"https://www.ogj.com/general-interest/government/news/55313583/ferc-re-approves-williams-gas-pipeline-expansion-into-new-york-city"},{"title":"Natural Gas Intelligence - FERC Reissues NESE Certificate to Boost Transco Natural Gas Volumes","url":"https://www.naturalgasintel.com/news/good-sign-for-constitution-ferc-reissues-nese-certificate-to-boost-transco-natural-gas-volumes/"},{"title":"NJBIA - NESE Pipeline Clears Final Regulatory Hurdle","url":"https://njbia.org/nese-pipeline-clears-final-regulatory-hurdle/"}]},{"id":"internet-retail-2025-de-minimis-ends","date":"2025-08-29","end_date":null,"sector":"consumer_discretionary","subindustries":["internet_retail"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Global de minimis exemption ends: Etsy falls 15% in a week, eBay 7%, as sub-$800 parcels become dutiable","summary":"At 12:01 a.m. on August 29, 2025 the US ended the de minimis exemption for all countries, making every parcel import dutiable regardless of value after the China-specific cutoff on May 2 had already cut Temu's US daily active users by 52% and Shein's by 25%. Cross-border marketplaces took the hit: Etsy fell about 15% over the five sessions into the deadline and eBay 7%, PDD lost about 4% on the week, while Shopify slipped 1%; Cantor called the order the removal of 'a key channel for low value cross-border shipments'. Exempt shipments had been worth about $65bn a year, around 2% of US imports.","evidence":"De minimis ended for all origins at 12:01 a.m. 2025-08-29; ETSY -15% and EBAY -7% over the prior five sessions; Temu US DAU -52% after the May China cutoff.","sources":[{"title":"Etsy, eBay, Shein: de minimis tariff exemption ends, adding charges (Fortune, 2025-08-29)","url":"https://fortune.com/2025/08/29/etsy-ebay-shein-de-minimis-tariff-exemption-ends-adding-charges"},{"title":"When de minimis rules ended, ecommerce changed (Digital Commerce 360)","url":"https://www.digitalcommerce360.com/2025/09/04/when-de-minimis-rules-ended-ecommerce-changed/"},{"title":"Explainer: how the end of de minimis exemption will impact U.S. shoppers and businesses (Reuters via Tiger)","url":"https://www.itiger.com/hans/news/2563979260"}]},{"id":"cs-2025-kraft-heinz-split","date":"2025-09-02","end_date":null,"sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"minor","driver_type":"ma","title":"Kraft Heinz unwinds the 2015 merger","summary":"Kraft Heinz's board approved splitting into a sauces/spreads company (Heinz, Kraft Mac & Cheese) and a North American grocery company (Oscar Mayer, Lunchables) at a cost of up to $300 million, a decade after the 3G/Berkshire merger. The shares had lost about 60% since 2015, and the split was read as an admission that scale without growth no longer earns a premium in packaged food.","evidence":"KHC shares down ~60% since the 2015 merger at the time of the 2025-09-02 split announcement","sources":[{"title":"Al Jazeera: Kraft Heinz to split into two companies as financial struggles mount","url":"https://www.aljazeera.com/economy/2025/9/2/kraft-heinz-to-split-into-two-companies-as-financial-struggles-mount"},{"title":"TODAY: Kraft Heinz splits, separating ketchup from hot dogs","url":"https://www.today.com/food/news/kraft-heinz-split-rcna228512"}]},{"id":"materials-2025-gold-record-3600-fed-cut-bets","date":"2025-09-08","end_date":null,"sector":"materials","subindustries":["gold_miners"],"direction":"in","magnitude":"moderate","driver_type":"rates","title":"Gold tops $3,600 for the first time as weak jobs data cements Fed cut","summary":"Spot gold broke above $3,600/oz for the first time on 2025-09-08, hitting about $3,646 intraday, after weak August US payrolls pushed the market to price an ~88% probability of a September 17 Fed cut and Treasury yields hit five-month lows; gold was up roughly 37% year-to-date. The breakout, which followed Powell's dovish Jackson Hole pivot on August 22, extended the leg higher in gold-mining equities ahead of the October surge past $4,000.","evidence":"Spot gold record ~$3,646/oz on 2025-09-08","sources":[{"title":"CNBC: Gold rallies to record high above $3,600/oz as Fed rate cut bets firm","url":"https://www.cnbc.com/2025/09/08/gold-hovers-near-record-high-on-us-rate-cut-prospects.html"},{"title":"Kitco (Reuters): Gold hits record high above $3,600/oz as traders weigh Fed rate-cut bets","url":"https://www.kitco.com/news/off-the-wire/2025-09-08/gold-hits-record-high-above-3600oz-traders-weigh-fed-rate-cut-bets"}]},{"id":"re-2025-0908-spacex-echostar-spectrum-tower-selloff","date":"2025-09-08","end_date":"2025-09-30","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"major","driver_type":"ma","title":"SpaceX pays $17B for EchoStar's AWS-4/H-block spectrum; tower REITs fall 2-4% in September as S&P rises 4%","summary":"On September 8, 2025 EchoStar agreed to sell its AWS-4 and H-block licenses to SpaceX for about $17 billion (up to $8.5 billion cash plus $8.5 billion of SpaceX stock, with SpaceX also funding ~$2 billion of EchoStar interest), completing EchoStar's exit from terrestrial wireless just two weeks after the AT&T deal and raising fears that direct-to-device satellite service could substitute for macro towers. Wireless Estimator reported that in September, when the sales were announced, American Tower fell 4%, SBA fell 4% and Crown Castle fell 2% while the S&P 500 rose 4%. EchoStar subsequently told the towercos their master leases were 'excused' and stopped paying; American Tower sued in October 2025, Crown Castle later sought more than $3.5 billion, and the FCC approved the ~$40 billion of sales.","evidence":"EchoStar-SpaceX ~$17B spectrum sale announced 2025-09-08; AMT -4%, SBAC -4%, CCI -2% in September 2025 vs S&P 500 +4% (Wireless Estimator).","sources":[{"title":"EchoStar: EchoStar Announces Spectrum Sale and Commercial Agreement with SpaceX","url":"https://ir.echostar.com/news-releases/news-release-details/echostar-announces-spectrum-sale-and-commercial-agreement-spacex"},{"title":"Wireless Estimator: The DISH default crisis: How EchoStar's spectrum exit could endanger the wireless tower ecosystem","url":"https://wirelessestimator.com/articles/2026/the-dish-default-crisis-how-echostars-spectrum-exit-could-endanger-the-wireless-tower-ecosystem/"},{"title":"Fierce Network: EchoStar payment dispute puts $9B tower industry impact in focus","url":"https://www.fierce-network.com/wireless/echostar-payment-dispute-puts-9b-tower-industry-impact-focus"}]},{"id":"infra-2025-oracle-rpo-surge","date":"2025-09-09","end_date":"2025-09-30","sector":"technology","subindustries":["infrastructure_software_cyber","hardware"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Oracle's backlog jumps 359% on the OpenAI deal; stock up nearly 40% intraday","summary":"On its 9 September 2025 earnings call Oracle disclosed remaining performance obligations of $455 billion, up 359% year on year, of which about $317 billion came from a reported $300 billion, five-year OpenAI compute contract starting in 2027; the shares rose nearly 40% the next day before settling at a 24.4% gain for September. The print re-rated Oracle as the fourth hyperscaler but tied its credit profile to a single customer, the source of its 2026 CDS widening.","evidence":"Oracle RPO $455 billion (+359% YoY) disclosed 2025-09-09; shares rose nearly 40% intraday on 2025-09-10 and +24.4% for the month.","sources":[{"title":"Why Oracle rallied in September (Motley Fool)","url":"https://www.fool.com/investing/2025/10/07/why-oracle-rallied-in-september/"},{"title":"Oracle's AI surge boosts stock but $300 billion OpenAI deal raises risk (TipRanks)","url":"https://www.tipranks.com/news/oracles-ai-surge-boosts-stock-but-300-billion-openai-deal-raises-risk"}]},{"id":"fintech-2025-klarna-ipo","date":"2025-09-10","end_date":null,"sector":"technology","subindustries":["fintech_payments"],"direction":"in","magnitude":"minor","driver_type":"positioning","title":"Klarna lists on the NYSE at $40 after an April tariff delay","summary":"Buy-now-pay-later lender Klarna began trading on the NYSE on 10 September 2025 at $40 a share, selling 34.3 million shares, after postponing the deal in April 2025 during the tariff selloff. Together with Circle and Figma, the listing confirmed that the fintech IPO window had reopened for the first time since 2021.","evidence":"Klarna IPO priced at $40.00 with trading from 2025-09-10 under ticker KLAR.","sources":[{"title":"Klarna (Wikipedia)","url":"https://en.wikipedia.org/wiki/Klarna"}]},{"id":"re-2025-0910-opendoor-names-nejatian-ceo","date":"2025-09-10","end_date":null,"sector":"real_estate","subindustries":["real_estate_services"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Opendoor names ex-Shopify COO Kaz Nejatian CEO, Rabois chairman; stock +78% next day","summary":"After the close on September 10, 2025 Opendoor named former Shopify COO Kaz Nejatian CEO and brought co-founders Keith Rabois (as chairman) and Eric Wu back to the board, weeks after CEO Carrie Wheeler resigned under investor pressure; shares jumped about 30% after hours and closed up 78% on September 11, taking the year-to-date gain past 500%. The retail-driven surge, which Rabois insisted was not a 'meme stock' phenomenon, pulled attention and flows toward the whole online-brokerage/iBuying cohort (OPEN, COMP, EXPI, Z) in the weeks before the Compass-Anywhere deal.","evidence":"Opendoor stock closed 78% higher on 2025-09-11 after the Sept 10 CEO announcement (CNBC).","sources":[{"title":"Opendoor stock closes 78% higher after company names new CEO (CNBC, Sep 11 2025)","url":"https://www.cnbc.com/2025/09/11/opendoor-stock-ceo-nejatian-keith-rabois.html"},{"title":"Opendoor taps new CEO and names Keith Rabois chairman, boosting stock 36% (CNBC, Sep 10 2025)","url":"https://www.cnbc.com/2025/09/10/opendoor-stock-jumps-20percent-after-company-taps-ex-shopify-coo-as-new-ceo-.html"},{"title":"Opendoor Names Kaz Nejatian as CEO; Founders Rabois and Wu Rejoin Board (press release via Nasdaq)","url":"https://www.nasdaq.com/press-release/opendoor-names-kaz-nejatian-ceo-founders-rabois-and-wu-rejoin-board-2025-09-10"}]},{"id":"media-2025-wbd-bids-ea-lbo","date":"2025-09-11","end_date":"2025-12-05","sector":"communication_media","subindustries":["media_entertainment"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Media M&A wave: Paramount bids for WBD, EA's $55 billion buyout","summary":"Warner Bros. Discovery shares rose 33% after the 11 September 2025 report that Paramount Skydance was exploring a bid for the whole company, and on 29 September 2025 Electronic Arts agreed to a $55 billion take-private by Saudi Arabia's PIF, Silver Lake and Affinity Partners, the largest leveraged buyout on record. WBD put itself up for sale on 21 October and accepted a Netflix offer for its studios and streaming assets in December 2025 that valued the company at $82.7 billion.","evidence":"WBD shares +33% after the 2025-09-11 Paramount bid report; EA buyout of $55 billion announced 2025-09-29.","sources":[{"title":"Warner Bros. Discovery (Wikipedia)","url":"https://en.wikipedia.org/wiki/Warner_Bros._Discovery"},{"title":"Electronic Arts (Wikipedia)","url":"https://en.wikipedia.org/wiki/Electronic_Arts"}]},{"id":"housing-2025-fed-cut-lennar-miss","date":"2025-09-17","end_date":"2025-09-18","sector":"consumer_discretionary","subindustries":["housing"],"direction":"mixed","magnitude":"moderate","driver_type":"rates","title":"The Fed's first 2025 cut caps a 16% summer homebuilder rally; Lennar misses the next day","summary":"Homebuilders rallied into the Federal Reserve's 25bp cut on September 17, 2025, with the SPDR Homebuilders ETF (XHB) up more than 16% from the end of June as D.R. Horton, Lennar, KB Home, Toll and Pulte priced in lower mortgage rates. On September 18 Lennar reported a fiscal Q3 miss and gave no improvement in outlook despite falling rates, and shares slid about 3.5% after hours, an early sign that incentives rather than demand were driving volume and that the rate cut alone would not fix builder margins.","evidence":"Fed cut 25bp on 2025-09-17; XHB +16% from end-June to mid-September 2025; LEN -~3.5% after hours on 2025-09-18 after a Q3 miss.","sources":[{"title":"Berkshire-backed Lennar slides after weak Q3 earnings (MarketBeat)","url":"https://www.marketbeat.com/articles/berkshire-backed-lennar-slides-after-weak-q3-earnings/"},{"title":"Housing giant Lennar looks to rate cuts to stimulate demand after earnings miss (Yahoo Finance)","url":"https://finance.yahoo.com/news/housing-giant-lennar-looks-rate-143908929.html"},{"title":"As Fed rate cut bets surge, Wednesday's homebuilder rally signals housing market optimism (Benzinga)","url":"https://benzinga.com/trading-ideas/movers/25/08/47104468/as-fed-rate-cut-bets-surge-wednesdays-homebuilder-rally-signals-housing-market-optimism"}]},{"id":"re-2025-0917-rithm-buys-paramount-group","date":"2025-09-17","end_date":null,"sector":"real_estate","subindustries":["office_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Rithm Capital agrees to buy office REIT Paramount Group for $1.6B","summary":"On September 17, 2025 Rithm Capital announced a definitive agreement to acquire Paramount Group (PGRE), owner of 13.1 million sq ft of Class A office in New York and San Francisco (85.4% leased), for $6.60 per share in cash, about $1.6 billion. The price was below PGRE's $7.38 close on Sept 16 but Rithm's CEO framed it as buying at roughly a 30% discount to replacement cost, a signal that credit-focused buyers see value in trophy office. The deal closed December 19, 2025 and the portfolio was later rebranded Elecor Properties with a $250M capex program; it was the first take-private of a listed gateway office REIT in this cycle and a read-across for discounted peers such as SLG, VNO, BXP, KRC and DEI.","evidence":"Rithm agreed on 2025-09-17 to pay $6.60 per share (~$1.6B) for Paramount Group; PGRE had closed at $7.38 on 2025-09-16.","sources":[{"title":"Rithm Capital Agrees to Acquire Paramount Group Office REIT for $1.6B (REBusinessOnline, Sep 17 2025)","url":"https://rebusinessonline.com/rithm-capital-agrees-to-acquire-paramount-group-for-1-6b/"},{"title":"Rithm Capital Completes Acquisition of Paramount Group, Inc. (Business Wire, Dec 19 2025)","url":"https://www.businesswire.com/news/home/20251219150205/en/Rithm-Capital-Completes-Acquisition-of-Paramount-Group-Inc."},{"title":"Paramount Group Gets New Name, $250M Portfolio Revamp Under New Owner (Bisnow)","url":"https://www.bisnow.com/news/national/office/rithm-infusing-250m-into-former-paramount-portfolio-rebranding-company-134320"}]},{"id":"it-services-2025-h1b-fee","date":"2025-09-19","end_date":"2026-06-08","sector":"technology","subindustries":["it_services"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"$100,000 H-1B fee hits the offshore IT-services model","summary":"A 19 September 2025 proclamation imposed a one-time $100,000 fee on new H-1B petitions filed from 21 September 2025, roughly 65 times the prior cost, with national-interest waivers at DHS discretion; Indian and US IT-services firms are the largest H-1B users. A federal judge ruled the fee unlawful on 8 June 2026, but DHS proposed a $103,265 fee by rule in August 2026, keeping labor-cost and delivery-model risk on Cognizant, Infosys and peers. The same week Accenture said it would exit staff it could not reskill for AI.","evidence":"Proclamation of 2025-09-19: $100,000 fee on H-1B petitions filed 2025-09-21 to 2026-09-21; ruled unlawful 2026-06-08.","sources":[{"title":"H-1B visa (Wikipedia)","url":"https://en.wikipedia.org/wiki/H-1B_visa"},{"title":"Accenture (Wikipedia)","url":"https://en.wikipedia.org/wiki/Accenture"}]},{"id":"utilities-2025-california-sb254-wildfire-fund","date":"2025-09-19","end_date":null,"sector":"utilities","subindustries":["regulated_utilities"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"Newsom signs SB 254, adding $18bn wildfire-fund continuation account","summary":"California Governor Gavin Newsom signed SB 254 on 2025-09-19, creating an $18bn Wildfire Fund Continuation Account split between utility shareholders and ratepayers, capping utility reimbursement at 20% of the equity portion of T&D rate base in the ignition year, and lowering PG&E's share of contributions from 64.2% to 47.85%. Shares of Edison International and PG&E rose as the bill advanced through the legislature in September, reducing the wildfire-liability overhang that had weighed on California utilities since the January 2025 Los Angeles fires.","evidence":"SB 254 signed 2025-09-19; $18bn continuation account, PG&E share cut to 47.85%","sources":[{"title":"Transition Economics Institute: California adds $18 billion to its wildfire fund, split between utility shareholders and customers","url":"https://tei-energy.org/news/2025-09-22-california-sb-254-wildfire-fund-continuation"},{"title":"PG&E Corp Form 10-Q (Q1 2026) describing SB 254 provisions","url":"https://www.sec.gov/Archives/edgar/data/0001004980/000100498026000033/pcg-20260331.htm"}]},{"id":"re-2025-compass-anywhere-merger","date":"2025-09-22","end_date":"2026-01-31","sector":"real_estate","subindustries":["real_estate_services"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Compass buys Anywhere: brokerage consolidation after the NAR settlement","summary":"Compass agreed on September 22, 2025 to buy Anywhere Real Estate (Coldwell Banker, Century 21, Sotheby's) for $1.6bn in stock at an 84% premium plus $2.6bn of debt, creating a ~$10bn enterprise with 340,000 agents and $225m of targeted synergies; the deal closed in January 2026 after 99% of Compass holders approved. Lower commissions and depressed existing-home sales (near 30-year lows) made scale the only defensible strategy.","evidence":"Compass-Anywhere all-stock deal $1.6bn equity / ~$10bn EV at $13.01 per Anywhere share (84% premium), announced Sep 22, 2025","sources":[{"title":"GlobeSt: Compass and Anywhere agree to $1.6B all-stock merger","url":"https://www.globest.com/amp/2025/09/22/compass-and-anywhere-real-estate-agree-to-16b-all-stock-merger/"},{"title":"Elite Agent: Compass and Anywhere mega merger to close after shareholder approval","url":"https://eliteagent.com/compass-and-anywhere-mega-merger-to-close-after-overwhelming-shareholder-approval/"}]},{"id":"cs-2025-kenvue-tylenol","date":"2025-09-22","end_date":"2025-10-31","sector":"consumer_staples","subindustries":["household_personal"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Trump links Tylenol to autism; Kenvue sells off","summary":"On September 22 2025 President Trump and HHS announced a claimed link between acetaminophen use in pregnancy and autism, contradicting medical consensus; Kenvue, the Tylenol maker spun out of J&J in May 2023, dropped sharply and stayed depressed on litigation and political risk. The episode showed that under the MAHA agenda even over-the-counter household brands carry regulatory headline risk, and it set up Kenvue as a distressed acquisition target.","evidence":"Kenvue shares 'dropped sharply' after Trump's Tylenol comments and were still depressed when the KMB bid arrived (Al Jazeera, Nov 2025)","sources":[{"title":"Al Jazeera: Kimberly-Clark to buy Tylenol maker Kenvue for $40bn","url":"https://www.aljazeera.com/economy/2025/11/3/kimberly-clark-to-buy-tylenol-maker-kenvue-for-40bn"},{"title":"NBC News: Kimberly-Clark to buy Kenvue in $48.7 billion deal","url":"https://www.nbcnews.com/business/business-news/kimberly-clark-buy-kenvue-487-billion-deal-rcna241548"}]},{"id":"ai-2025-openai-circular-deals","date":"2025-09-22","end_date":"2025-10-31","sector":"ai","subindustries":["semiconductors","infrastructure_software_cyber","hardware","memory"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Nvidia's $100 billion OpenAI pledge, AMD's 6 GW deal and the 'circular financing' debate","summary":"In September 2025 Nvidia and OpenAI announced a plan for at least 10 GW of capacity backed by up to $100 billion of Nvidia investment; in October AMD agreed to supply 6 GW of accelerators with OpenAI receiving warrants on up to 160 million AMD shares (10%), and OpenAI signed letters of intent with Samsung and SK Hynix for up to 900,000 DRAM wafers a month. An employee share sale valued OpenAI at $500 billion. The deals extended the AI rally (Nvidia reached $5 trillion on 29 October 2025) but seeded concerns that suppliers were financing their own demand.","evidence":"Nvidia-OpenAI: at least 10 GW and up to $100 billion of investment (September 2025); AMD-OpenAI: 6 GW with warrants for up to 160 million shares (October 2025); OpenAI valued at $500 billion.","sources":[{"title":"OpenAI (Wikipedia)","url":"https://en.wikipedia.org/wiki/OpenAI"},{"title":"AMD (Wikipedia)","url":"https://en.wikipedia.org/wiki/AMD"},{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"},{"title":"Nvidia (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nvidia"}]},{"id":"hc-2025-pharma-tariff-threat","date":"2025-09-25","end_date":"2025-11-06","sector":"healthcare","subindustries":["pharma"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Trump threatens 100% tariffs on branded drugs unless companies build in the US","summary":"On September 25 2025 Trump announced 100% tariffs on imported branded or patented drugs from October 1 for any company not building US plants, with exemptions for firms with construction under way. The threat was postponed to extract company-specific deals on pricing and onshoring (Pfizer, AstraZeneca and others announced TrumpRx agreements and US capex pledges), which is why the large caps were little changed while European and Japanese exporters bore the uncertainty. A day-of market move was not retrievable.","evidence":"100% tariff on patented drugs announced for 2025-10-01 with exemptions for companies building US plants; later postponed pending negotiated agreements","sources":[{"title":"Fierce Pharma: Trump slaps 100% duties on imported drugs but leaves exceptions","url":"https://www.fiercepharma.com/pharma/trump-slaps-100-duties-imported-drugs-there-are-plenty-exceptions"},{"title":"BioPharma Dive: Trump revives pharma tariffs with 100% levies","url":"https://www.biopharmadive.com/news/trump-revives-pharma-tariffs-100-percent-levies/816584/"},{"title":"Freshfields: Trump's pharma tariff ultimatum","url":"https://www.freshfields.com/en/our-thinking/blogs/a-fresh-take/trumps-pharma-tariff-ultimatum-102mqe9"}]},{"id":"financials-2025-private-credit-scare","date":"2025-09-28","end_date":"2025-10-31","sector":"financials","subindustries":["banks","capital_markets","insurance"],"direction":"out","magnitude":"moderate","driver_type":"macro","title":"First Brands bankruptcy exposes private-credit and trade-finance risk","summary":"Auto-parts maker First Brands filed for Chapter 11 in late September 2025 with liabilities of $10-50 billion funded through opaque off-balance-sheet receivables financing; Jefferies' Leucadia fund disclosed $715 million of linked receivables and its shares fell, UBS reported over $500 million of exposure, and Norinchukin-Mitsui about $1.75 billion. The episode, alongside the Tricolor collapse, triggered a sell-off in lenders with private-credit and asset-backed exposure and a debate over 'cockroaches' in non-bank credit.","evidence":"First Brands Chapter 11 filing in September 2025 with liabilities listed at $10-50 billion; Jefferies disclosed $715 million of linked receivables.","sources":[{"title":"First Brands Group (Wikipedia)","url":"https://en.wikipedia.org/wiki/First_Brands_Group"}]},{"id":"hc-2025-aca-subsidy-cliff","date":"2025-10-01","end_date":"2025-12-31","sector":"healthcare","subindustries":["managed_care","healthcare_facilities_services"],"direction":"out","magnitude":"moderate","driver_type":"policy","title":"Shutdown fight over expiring enhanced ACA subsidies","summary":"The enhanced ACA premium tax credits from the 2021 American Rescue Plan, extended by the IRA, were set to expire at the end of 2025; the dispute drove a federal shutdown that passed 39 days in early November 2025. KFF found insurers proposing a median 18% premium increase for 2026 (versus 7% a year earlier), citing the expiration, with warnings that premiums could more than double for some enrollees and enrollment could fall. Exchange-heavy insurers (Oscar, Centene) and hospitals with high exchange mix carried the risk into 2026.","evidence":"KFF: median proposed 2026 marketplace premium increase 18% vs 7% the prior year, with insurers citing enhanced-subsidy expiration","sources":[{"title":"KFF: How much and why ACA marketplace premiums are going up in 2026","url":"https://www.kff.org/affordable-care-act/issue-brief/how-much-and-why-aca-marketplace-premiums-are-going-up-in-2026/"},{"title":"Wikipedia: Affordable Care Act (2025 shutdown section)","url":"https://en.wikipedia.org/wiki/Affordable_Care_Act"}]},{"id":"memory-2025-price-surge","date":"2025-10-01","end_date":"2025-12-31","sector":"technology","subindustries":["memory","semiconductors","hardware"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"Memory price surge: DRAM up 172% in 2025 as HBM eats capacity","summary":"With fab capacity diverted to HBM for AI accelerators and OpenAI's 1 October 2025 letters of intent with Samsung and SK Hynix for up to 900,000 wafers a month (about 40% of global DRAM output), DRAM prices rose about 172% during 2025 and NAND wafer contracts jumped more than 60% month on month in November; Samsung halted new DDR5 module orders to reprice and Micron announced its exit from the Crucial consumer brand on 3 December. Micron's fiscal 2025 revenue rose to $37.4 billion, and the memory bucket became the best-performing group in semiconductors.","evidence":"DRAM prices up about 172% in 2025; NAND wafer contract prices up more than 60% month-over-month in November 2025.","sources":[{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"},{"title":"RAM shortage 2025: how AI demand is raising DRAM prices (IntuitionLabs)","url":"https://intuitionlabs.ai/articles/ram-shortage-2025-ai-demand"},{"title":"Micron Technology (Wikipedia)","url":"https://en.wikipedia.org/wiki/Micron_Technology"}]},{"id":"materials-2025-gold-4000-miners","date":"2025-10-08","end_date":"2025-12-31","sector":"materials","subindustries":["gold_miners"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Gold passes $4,000 and gold miners more than double in 2025","summary":"Gold broke $4,000 an ounce in October 2025 amid a US government shutdown, China tensions, central-bank buying and Fed cuts, finishing the year near $4,350 (+60%, its best year since at least 1988); the VanEck Gold Miners ETF (GDX) rose from $35.34 to $76.16 (+115%) by October and was reported up roughly 134% at the BofA $5,000 call. Miners' Q4 2025 profits were their best on record, and the gold_miners bucket was the best-performing group in materials.","evidence":"GDX from $35.34 to $76.16 (+115%) year-to-date by October 2025; gold above $4,000 in October 2025 and about $4,350 at year-end.","sources":[{"title":"After gold soars past $4,000, BofA eyes $5,000 in 2026 (Barchart)","url":"https://www.barchart.com/story/news/35478328/after-gold-blast-soars-past-4-000-bofa-eyes-5-000-in-2026"},{"title":"VanEck Gold Miners ETF climbs as gold breaks above $4,300 (Tickeron)","url":"https://tickeron.com/blogs/vaneck-gold-miners-etf-gdx-climbs-14-as-gold-breaks-above-4-300-15416/"},{"title":"Gold in 2025: a new era of structural strength (VanEck)","url":"https://www.vaneck.com/us/en/blogs/gold-investing/gold-in-2025-a-new-era-of-structural-strength-and-enduring-appeal/"},{"title":"Gold doubled to $4,000, mining valuations didn't (Benzinga)","url":"https://www.benzinga.com/Opinion/25/11/48896552/gold-doubled-to-4000-mining-valuations-did-not-3-top-stocks-to-consider"}]},{"id":"re-2025-1015-prologis-q3-record-leasing","date":"2025-10-15","end_date":"2025-10-17","sector":"real_estate","subindustries":["industrial_logistics_reits"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Prologis posts record 62M sq ft of leasing, raises guidance; industrial REITs soar ~11% on the week","summary":"Prologis reported Q3 2025 on October 15, 2025 with a record 62 million sq ft of lease signings, Core FFO of $1.49 per share (+4.2% y/y), revenue of $2.21 billion (+9%) and portfolio occupancy of 95.3%, and raised full-year guidance for Core FFO, same-store NOI and development starts (GAAP EPS guidance to $3.40-$3.50). Management also said it had 5.2 GW of utility-fed power secured or in advanced stages for data-center conversions. The print re-rated the whole group: S&P Global's REIT Replay reported Prologis up 11.55% and Rexford up 11.18% for the week ended October 17, 2025, with industrial REITs the best-performing REIT sector that week.","evidence":"Prologis +11.55% and Rexford +11.18% for the week ended 2025-10-17 after the 62M sq ft record leasing quarter (S&P Global Market Intelligence).","sources":[{"title":"S&P Global: REIT Replay: Industrial REIT stocks soar during week ended Oct. 17","url":"https://www.spglobal.com/market-intelligence/en/news-insights/articles/2025/10/reit-replay-industrial-reit-stocks-soar-during-week-ended-oct-17-94045291"},{"title":"Prologis Reports Third Quarter 2025 Results (Oct 15, 2025)","url":"https://d1io3yog0oux5.cloudfront.net/_98226a95dec5121cd8fa399fa643cbe1/prologis/news/2025-10-15_Prologis_Reports_Third_Quarter_2025_1025.pdf"},{"title":"FreightWaves: Prologis sees 'record leasing' activity in Q3","url":"https://www.freightwaves.com/news/first-look-prologis-sees-record-leasing-activity-in-q3"}]},{"id":"re-2025-1015-sl-green-q3-manhattan-leasing","date":"2025-10-15","end_date":null,"sector":"real_estate","subindustries":["office_reits"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"SL Green Q3: strong Manhattan leasing but shares drop 6% on results","summary":"SL Green reported Q3 2025 after the close on October 15, 2025: FFO of $1.58 per share, 52 Manhattan office leases totalling 657,942 sq ft in the quarter (143 leases, 1.8 million sq ft year-to-date) at $92.81 average rent, and same-store occupancy up to 92.4% from 91.5% with a 93.2% year-end target. Despite the leasing beat, SLG closed down 6.04% at $57.14 on October 16 as investors focused on heavy concessions (9.1 months free rent, $99 TI allowances) and earnings quality, a sell-the-news reaction that set the tone for the BXP/VNO prints that followed and for the 'Manhattan recovery vs. everywhere else' debate in office REITs.","evidence":"SLG closed at $57.14, down 6.04%, on 2025-10-16 after reporting Q3 FFO of $1.58 and 657,942 sq ft of Manhattan leasing.","sources":[{"title":"SL Green Realty Corp. Reports Third Quarter 2025 EPS of $0.34 and FFO of $1.58 Per Share (GlobeNewswire, Oct 15 2025)","url":"https://www.globenewswire.com/news-release/2025/10/15/3167526/0/en/SL-Green-Realty-Corp-Reports-Third-Quarter-2025-EPS-of-0-34-Per-Share-and-FFO-of-1-58-Per-Share.html"},{"title":"SL Green Q3 2025 slides: Manhattan REIT beats expectations amid office challenges (Investing.com, Oct 16 2025)","url":"https://www.investing.com/news/company-news/sl-green-q3-2025-slides-manhattan-reit-beats-expectations-amid-office-challenges-93CH-4293057"}]},{"id":"aero-2025-faa-737-rate-42","date":"2025-10-17","end_date":null,"sector":"industrials","subindustries":["commercial_aerospace"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"FAA lifts Boeing's 737 MAX production cap from 38 to 42 a month","summary":"On October 17, 2025 the FAA approved Boeing's request to raise 737 MAX output from 38 to 42 jets a month, almost two years after the January 2024 Alaska Airlines door-plug blowout froze the rate. The FAA said key performance indicators and a rate-readiness process agreed with Boeing supported the increase and that it would keep oversight in place. Boeing shares ticked up about 1.6% after hours; the decision unlocked the supplier chain (Spirit, Howmet, Hexcel) that had been building to a higher rate than Boeing could ship.","evidence":"FAA approval dated 2025-10-17 raising the 737 MAX cap to 42/month; BA +~1.6% after hours.","sources":[{"title":"FAA raises Boeing 737 Max production cap to 42 a month (CNBC)","url":"https://www.cnbc.com/2025/10/17/boeing-737-max-production.html"},{"title":"Boeing stock rises after FAA reportedly approves production increase (Yahoo Finance)","url":"https://finance.yahoo.com/news/boeing-stock-rises-faa-reportedly-221021060.html"},{"title":"FAA authorizes Boeing to increase 737 MAX production rate (AeroMorning)","url":"https://aeromorning.com/en/faa-authorizes-boeing-to-increase-737-max-production-rate/"}]},{"id":"autos-2025-gm-q3-record-close","date":"2025-10-21","end_date":null,"sector":"consumer_discretionary","subindustries":["autos"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"GM soars 15% to a record close as truck demand dulls tariff pain and guidance is raised","summary":"On October 21, 2025 General Motors raised its 2025 adjusted EBIT outlook to $12-13bn from $10-12.5bn, cut its estimated tariff cost to $3.5-4.5bn from as much as $5bn and reported Q3 operating profit of $3.4bn on $48.6bn of revenue on strong truck and SUV demand. The stock rose $8.62, or 15%, to a record close of $66.62, its biggest gain in five years, and lifted Ford with it; GM was near $70 by the end of the month. Six months after pulling guidance over tariffs, the print marked the moment Detroit's tariff absorption stopped being a 2025 bear case.","evidence":"GM +15% to a record close of $66.62 on 2025-10-21; 2025 EBIT-adjusted guide raised to $12-13bn; tariff cost estimate cut to $3.5-4.5bn.","sources":[{"title":"General Motors third quarter earnings: stock surge, beats expectations (Fortune, 2025-10-21)","url":"https://fortune.com/2025/10/21/general-motors-third-quarter-earnings-stock-surge-beats-expectations/"},{"title":"GM soars most in five years as truck demand spurs outlook boost (Bloomberg Government)","url":"https://news.bgov.com/international-trade/gm-raises-outlook-as-strong-truck-demand-dulls-tariff-pain"},{"title":"Why did GM stock suddenly jump 20% higher (Motley Fool, 2025-10-30)","url":"https://www.fool.com/investing/2025/10/30/why-did-gm-stock-suddenly-jump-20-higher"}]},{"id":"materials-2025-gold-plunge-gdx-worst-since-2020","date":"2025-10-21","end_date":null,"sector":"materials","subindustries":["gold_miners"],"direction":"out","magnitude":"major","driver_type":"commodity","title":"Gold's biggest drop since 2013 sends GDX down 9.5%","summary":"One day after spot gold set a record near $4,381, it fell as much as 6.3% to about $4,082 on 2025-10-21, the largest single-day decline since 2013, as a firmer dollar and profit-taking hit an overcrowded trade; silver fell 8.7%. Gold miners were hit harder: Newmont and Agnico Eagle fell about 9%, Barrick more than 8%, and the VanEck Gold Miners ETF (GDX) dropped 9.5%, its worst session since March 2020.","evidence":"GDX -9.5% on 2025-10-21; spot gold -6.3% intraday","sources":[{"title":"Bloomberg: Gold miners plummet after bullion falls most since 2013","url":"https://www.bloomberg.com/news/articles/2025-10-21/gold-miners-plummet-after-bullion-falls-most-since-2013"},{"title":"Mining.com: Gold price falls by most in over a decade as rally cools","url":"https://www.mining.com/gold-price-falls-by-most-in-four-years-as-rally-cools-off/"},{"title":"FinancialContent: Gold and silver plunge; Barrick and miners face steepest drops in years","url":"https://markets.financialcontent.com/stocks/article/marketminute-2025-10-21-gold-and-silver-plunge-barrick-gold-nyse-gold-and-miners-face-steepest-drops-in-years"}]},{"id":"lstools-2025-thermo-fisher-worst-is-over","date":"2025-10-22","end_date":null,"sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Thermo Fisher's Q3 2025 beat and raise: William Blair says 'the worst is over' for tools","summary":"On October 22, 2025 Thermo Fisher reported Q3 revenue of $11.12bn (+5%, 3% organic) and adjusted EPS of $5.79 (+10%) against a $5.49 consensus and lifted its 2025 revenue outlook to $44.1-44.5bn. With Danaher's report the same week, William Blair argued the prints supported the view that the worst was over for scientific tools after two years of biopharma destocking, NIH cuts and China weakness, while cautioning that the 2026 outlook would set the pace of recovery.","evidence":"Q3 2025 adjusted EPS $5.79 vs $5.49 consensus; revenue $11.12bn (+5%); 2025 revenue guide raised to $44.1-44.5bn.","sources":[{"title":"Thermo Fisher Scientific reports third quarter 2025 results (Thermo Fisher IR)","url":"https://ir.thermofisher.com/investors/news-events/news/news-details/2025/Thermo-Fisher-Scientific-Reports-Third-Quarter-2025-Results/default.aspx"},{"title":"Thermo Fisher's upbeat earnings suggest worst is over for scientific tools sector, analyst says (Sahm Capital, 2025-10-22)","url":"https://www.sahmcapital.com/news/content/thermo-fishers-upbeat-earnings-suggest-worst-is-over-for-scientific-tools-sector-analyst-says-2025-10-22"},{"title":"Thermo Fisher Q3 2025 earnings release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/97745/000009774525000150/q32025earnings8kex99_1.htm"}]},{"id":"en-2025-1022-rosneft-lukoil-sanctions","date":"2025-10-22","end_date":null,"sector":"energy","subindustries":["integrated","exploration_production","refining"],"direction":"in","magnitude":"moderate","driver_type":"geopolitical","title":"US sanctions Rosneft and Lukoil; WTI jumps ~6%, XLE tops all sectors","summary":"On October 22, 2025 the Treasury sanctioned Rosneft and Lukoil, Russia's two largest oil exporters, citing Moscow's lack of commitment to a Ukraine peace process, with full effect from November 21. WTI, which had hit five-month lows days earlier, spiked nearly 6% to above $60 on October 23, and the Energy Select Sector SPDR (XLE) rose 1.9%, the best S&P 500 sector, with Valero up about 6.3% on expectations of tighter Russian product supply. The premium faded in November as the market refocused on the 2026 surplus.","evidence":"WTI +~6% to above $60/bbl on 2025-10-23; XLE +1.9% led all sectors (Benzinga market wrap)","sources":[{"title":"CNBC - Trump's Russia oil sanctions could just be starting as low prices leave room to escalate","url":"https://www.cnbc.com/2025/10/23/trump-russia-ukraine-oil-sanctions-rosneft-lukoil-brent-wti.html"},{"title":"Benzinga - Markets Today: Wall Street, oil crude rally on Trump Russia sanctions on Rosneft, Lukoil","url":"https://www.benzinga.com/markets/market-summary/25/10/48386632/markets-today-thursday-wall-street-oil-crude-rally-wti-trump-russia-sanctions-rosneft-luko"},{"title":"The Moscow Times - What New U.S. Sanctions on Rosneft and Lukoil Mean for Russia's Oil Trade","url":"https://www.themoscowtimes.com/2025/10/28/what-new-us-sanctions-on-rosneft-and-lukoil-mean-for-russias-oil-trade-a90957"}]},{"id":"facilities-2025-hca-q3-record-high","date":"2025-10-24","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"HCA raises 2025 guidance on 18.5% EBITDA growth and hits a 52-week high","summary":"On October 24, 2025 HCA Healthcare reported Q3 EPS of $6.96 (vs $4.88 a year earlier), adjusted EBITDA up 18.5% to $3.87bn, same-facility admissions +2.1% and revenue per equivalent admission +6.6%, and raised 2025 EPS guidance to $27.00-28.00 from $25.50-27.00 (revenue $75.0-76.5bn). Shares rose about 3.9% to a 52-week high near $457 as the company bought back $2.5bn of stock in the quarter. The print showed hospital volumes and Medicaid supplemental payments still strong ahead of the 2026 ACA subsidy expiry that would later hit the group.","evidence":"HCA +3.9% to ~$457 (52-week high) on 2025-10-24; 2025 EPS guide raised to $27.00-28.00; Q3 adjusted EBITDA +18.5% to $3.87bn.","sources":[{"title":"HCA Healthcare shares jump on strong Q3 results, raised guidance (Investing.com)","url":"https://ng.investing.com/news/earnings/hca-healthcare-shares-jump-on-strong-q3-results-raised-guidance-2163080"},{"title":"HCA Healthcare raises 2025 guidance (Nasdaq)","url":"https://www.nasdaq.com/articles/hca-healthcare-raises-2025-guidance"},{"title":"HCA Healthcare reports third quarter 2025 results (Business Wire, 2025-10-24)","url":"https://www.businesswire.com/news/home/20251024490832/en"}]},{"id":"waste-2025-wm-q3-miss-commodity-prices","date":"2025-10-27","end_date":null,"sector":"industrials","subindustries":["waste"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Waste Management misses Q3 2025 and guides revenue to the low end on recycled-commodity prices","summary":"After the close on October 27, 2025 Waste Management reported Q3 adjusted EPS of $2.15 against a $2.18 consensus and said full-year revenue would land at the low end of its range because of falling recycled commodity prices and softer healthcare-solutions (Stericycle) revenue, while holding EBITDA and free cash flow guidance. Shares fell 2.4-3.5% in extended trading. The miss capped a 2025 in which the waste group lagged a risk-on tape despite pricing above CPI.","evidence":"Q3 2025 adjusted EPS $2.15 vs $2.18 Zacks consensus; WM -2.35% to -3.5% after hours on 2025-10-27.","sources":[{"title":"Waste Management falls as quarterly earnings miss estimates, costs rise (Seeking Alpha)","url":"https://seekingalpha.com/news/4658480-waste-management-falls-as-quarterly-earnings-miss-estimates-costs-rise"},{"title":"Earnings call transcript: Waste Management Q3 2025 results miss forecasts (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-waste-management-q3-2025-results-miss-forecasts-93CH-4314254"},{"title":"Waste Management Q3 2025 earnings release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/823768/000110465925102615/tm2529298d1_ex99-1.htm"}]},{"id":"re-2025-1027-welltower-23b-senior-housing-deals","date":"2025-10-27","end_date":null,"sector":"real_estate","subindustries":["healthcare_reits"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Welltower unveils $23B of transactions: $14B of senior housing buys (Barchester £5.2B, HC-One £1.2B) funded by $7.2B medical office sale","summary":"On October 27, 2025 Welltower announced a series of transactions totalling $23 billion, including $14 billion of pro rata senior housing acquisitions closed or under contract covering more than 700 communities and 46,000 units in the UK, US and Canada. The centerpiece is the £5.2 billion purchase of the Barchester-operated UK portfolio (111 RIDEA communities, 152 triple-net, 21 developments), plus taking 100% of the HC-One portfolio for £1.2 billion after converting a pandemic-era loan; another ~$4 billion across ~40 deals and 150+ communities is separately closed or contracted. Funding comes from cash and $9 billion of capital recycling, led by the ~$7.2 billion sale of an 18 million sq ft outpatient medical portfolio (first $2 billion tranche closed in October 2025). The package remakes the largest healthcare REIT into a near-pure senior housing operator and sets a global cap-rate marker for the whole group.","evidence":"$23B of transactions announced 2025-10-27, including £5.2B Barchester portfolio and $14B of senior housing acquisitions across 700+ communities.","sources":[{"title":"Welltower transactions press release, Oct 27 2025 (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/766704/000076670425000037/a3q25transactionspressrele.htm"},{"title":"Senior Housing News: Welltower Announces $14B in Senior Housing Acquisitions Totaling More Than 700 Communities","url":"https://seniorhousingnews.com/2025/10/27/welltower-announces-14b-in-senior-housing-acquisitions-totaling-more-than-700-communities/"}]},{"id":"nuclear-2025-westinghouse-80b","date":"2025-10-28","end_date":"2026-07-31","sector":"nuclear","subindustries":[],"direction":"in","magnitude":"major","driver_type":"policy","title":"Westinghouse and the US government plan $80 billion of new reactors","summary":"Westinghouse, owned 51% by Brookfield and 49% by Cameco, announced on 28 October 2025 an agreement with the Trump administration to begin planning $80 billion of new AP1000 and AP300 reactors in the US. The deal gave the first concrete large-reactor order book since Vogtle, lifted Cameco and the fuel-cycle names, and preceded Westinghouse's confidential IPO filing on 31 July 2026 and X-energy's record $1 billion nuclear IPO in April 2026.","evidence":"Westinghouse-US government agreement for $80 billion of new reactors announced 2025-10-28; Westinghouse draft S-1 submitted 2026-07-31.","sources":[{"title":"Westinghouse Electric Company (Wikipedia)","url":"https://en.wikipedia.org/wiki/Westinghouse_Electric_Company"},{"title":"X-energy (Wikipedia)","url":"https://en.wikipedia.org/wiki/X-energy"}]},{"id":"semis-2025-nvidia-5t-ai-peak-leg","date":"2025-10-29","end_date":"2025-12-31","sector":"technology","subindustries":["semiconductors","apple","internet_platforms","memory"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Nvidia hits $5 trillion, Apple $4 trillion, Nasdaq record 23,958","summary":"Nvidia became the first $5 trillion company on 29 October 2025, a day after Apple crossed $4 trillion, and the Nasdaq set its 2025 closing high of 23,958.47 the same day; Alphabet had passed $3 trillion on 15 September and Lilly $1 trillion on 21 November. Technology returned 24.0% and communication services 33.6% in 2025 against 17.9% for the S&P 500, with the Fed cutting on 17 September, 29 October and 10 December 2025 to 3.5-3.75%.","evidence":"Nvidia first $5 trillion market cap on 2025-10-29; Nasdaq Composite 2025 high close 23,958.47 on 2025-10-29; IT sector 2025 return +24.0% vs S&P 500 +17.9%.","sources":[{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"},{"title":"Nasdaq Composite (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"FOMC statement, 10 December 2025","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20251210a.htm"}]},{"id":"machinery-2025-caterpillar-q3-record-high","date":"2025-10-29","end_date":null,"sector":"industrials","subindustries":["machinery"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Caterpillar jumps 12% to a record on a Q3 2025 beat and $39.9bn backlog despite $686m of tariff costs","summary":"Caterpillar reported Q3 2025 revenue of $17.64bn (+9.5%) and adjusted EPS of $4.95 against a $4.52 consensus, with backlog at an all-time high of about $39.9bn as power-generation demand from data centers offset weaker construction. Shares rose about 12% on October 29, 2025 to a 52-week high of $591.58 even though operating margin contracted to 17.3% from 19.5% on $686m of tariff-driven manufacturing costs. The print reset machinery from a tariff-victim narrative to an AI-power beneficiary.","evidence":"CAT +12.3% intraday to $591.58 on 2025-10-29; Q3 2025 adjusted EPS $4.95 vs ~$4.52 consensus; backlog ~$39.9bn record.","sources":[{"title":"Caterpillar's stock up 12% after impressive Q3 earnings (24/7 Wall St., 2025-10-29)","url":"https://247wallst.com/investing/2025/10/29/caterpillars-stock-up-12-after-impressive-q3-earnings/"},{"title":"Caterpillar soars on Q3 earnings beat and better-than-expected outlook (Sherwood News)","url":"https://sherwood.news/markets/caterpillar-soars-on-q3-earnings-beat-and-better-than-expected-outlook/"},{"title":"Why is Caterpillar (CAT) stock rocketing higher today (Yahoo Finance)","url":"https://finance.yahoo.com/news/why-caterpillar-cat-stock-rocketing-171100909.html"}]},{"id":"re-2025-1029-fed-cut-ends-qt","date":"2025-10-29","end_date":null,"sector":"real_estate","subindustries":["mortgage_reits"],"direction":"in","magnitude":"moderate","driver_type":"rates","title":"Fed cuts to 3.75-4.00% and announces end of balance-sheet runoff on Dec 1","summary":"At the October 29, 2025 FOMC the Fed cut the funds target by 25 bp to 3.75%-4.00% and stated it 'decided to conclude the reduction of its aggregate securities holdings on December 1.' Ending QT removes a steady source of agency-MBS supply pressure and lowers repo funding costs, the two core levers for agency mortgage REITs (NLY, AGNC, DX, TWO, ARR, ORC) and for REM. The Fed continues to let MBS paydowns roll into Treasury bills rather than new MBS, so the direct bid for mortgages still rests with private balance sheets.","evidence":"FOMC statement 2025-10-29: target range lowered to 3.75-4.00%; securities-holdings reduction concludes December 1, 2025.","sources":[{"title":"Federal Reserve FOMC statement, October 29 2025","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20251029a.htm"},{"title":"The Fed Ends QT: What it Means for Markets (MFS)","url":"https://www.mfs.com/en-us/investment-professional/insights/market-insights/fed-ends-qt-what-it-means-markets.html"}]},{"id":"re-2025-1029-public-storage-q3-raises-outlook","date":"2025-10-29","end_date":null,"sector":"real_estate","subindustries":["self_storage_reits"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Public Storage raises 2025 outlook for second straight quarter as storage bottoms","summary":"Public Storage's Q3 2025 report on October 29, 2025 showed core FFO of $4.31 per share (+2.6% YoY) and lifted same-store revenue guidance to -0.3% to +0.3% from -1.3% to +0.8%, while narrowing expense growth to 1.8%-2.8%; CEO Joe Russell said 'we are raising our 2025 outlook for the second consecutive quarter,' and the company bought 49 facilities for $511M in the quarter. Coming after a Q2 in which same-store revenue was flat at EXR, down 0.5% at CUBE and down 3% at NSA, the raise was the clearest signal yet that street-rate declines had bottomed, supporting the troughing thesis for PSA, EXR, CUBE and NSA.","evidence":"PSA Q3 2025 core FFO $4.31/share (+2.6% YoY); 2025 same-store revenue guidance raised to -0.3% to +0.3% from -1.3% to +0.8% (release 2025-10-29).","sources":[{"title":"Public Storage Reports Results for the Three and Nine Months Ended September 30, 2025 (press release)","url":"https://investors.publicstorage.com/news-events/press-releases/news-details/2025/Public-Storage-Reports-Results-for-the-Three-and-Nine-Months-Ended-September-30-2025/default.aspx"},{"title":"Public Storage Form 8-K exhibit 99.1, Q3 2025 (SEC)","url":"https://www.sec.gov/Archives/edgar/data/1393311/000162828025047143/psa-102925xex99_1.htm"},{"title":"Self-Storage REITs Release Financial Results for Second-Quarter 2025 (Inside Self-Storage)","url":"https://www.insideselfstorage.com/facility-operators/self-storage-reits-release-financial-results-for-second-quarter-2025"}]},{"id":"hyperscalers-2025-q3-capex-amazon","date":"2025-10-30","end_date":"2025-10-31","sector":"hyperscalers","subindustries":["internet_platforms","infrastructure_software_cyber","semiconductors"],"direction":"mixed","magnitude":"major","driver_type":"earnings","title":"Q3 2025 earnings: Amazon rewarded for AWS re-acceleration, capex guides rise again","summary":"Amazon reported AWS growth of 20.2% to $33 billion on 30 October 2025, its fastest since 2022, raised 2025 capex guidance to $125 billion and said it would rise again in 2026; the shares jumped more than 13% after hours. The same week Meta and Microsoft guided capex higher and were treated more harshly, and combined five-company capex reached $140.6 billion in Q4 2025, the start of the 'reward only monetised capex' pattern that dominated 2026.","evidence":"AWS revenue +20.2% to $33 billion in Q3 2025; Amazon 2025 capex guidance raised to $125 billion from $118 billion; shares +13% after hours on 2025-10-30.","sources":[{"title":"Amazon Q3 2025 earnings (CNBC, 2025-10-30)","url":"https://www.cnbc.com/2025/10/30/amazon-amzn-q3-earnings-report-2025.html"},{"title":"Hyperscaler capex has quadrupled since GPT-4's release (Epoch AI)","url":"https://epoch.ai/data-insights/hyperscaler-capex-trend"}]},{"id":"internet-2025-meta-capex-day","date":"2025-10-30","end_date":null,"sector":"technology","subindustries":["internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Meta's capex day: -11%, the worst session since 2022, on 'notably larger' 2026 spending","summary":"Meta reported 26% revenue growth for Q3 2025 but took a one-time $15.93bn non-cash tax charge tied to the One Big Beautiful Bill Act, raised 2025 capex to $70-72bn and said 2026 capex growth would be 'notably larger'. The stock fell more than 11% on October 30, 2025, its biggest one-day loss since October 2022, while Alphabet rose the same week after lifting its own capex to $91-93bn with cloud growth to show for it. The split marked the start of the 'reward only monetised capex' regime that dominated internet platforms through 2026.","evidence":"Meta 2025 capex guidance raised to $70-72bn (from $66-72bn); shares -11% on 2025-10-30.","sources":[{"title":"Meta stock has worst day in 3 years, dropping 11% on higher AI spend (CNBC)","url":"https://www.cnbc.com/2025/10/30/meta-stock-earnings-ai-spend.html"},{"title":"Meta shares drop 9% despite earnings beat as company takes one-time tax charge (CNBC)","url":"https://www.cnbc.com/2025/10/29/meta-q3-earnings-report-2025.html"},{"title":"Meta plans 'notably larger' capex spend on AI data centers in 2026 (DCD)","url":"https://www.datacenterdynamics.com/en/news/meta-plans-notably-larger-capex-spend-on-ai-data-centers-in-2026-compute-expectations-already-higher-than-last-quarter-prediction/"}]},{"id":"re-2025-1030-avalonbay-q3-guidance-cut","date":"2025-10-30","end_date":null,"sector":"real_estate","subindustries":["residential_reits"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"AvalonBay misses and cuts 2025 outlook as apartment demand softens; MAA also trims","summary":"AvalonBay's Q3 2025 results (released Oct 29 after the close, presented Oct 30) showed core FFO of $2.75 versus its own $2.80 midpoint, and the company cut full-year core FFO guidance by $0.14 to an $11.25 midpoint (2.2% growth vs 3.5% prior), lowered same-store revenue growth to 2.5% from 2.8% and NOI growth to 2.0% from 2.7%, blaming weaker job growth, lower consumer confidence and rate softness that began late in Q3 and continued into October. AVB was down 2.7% premarket on Oct 30 and touched a 52-week low intraday; Mid-America Apartment (MAA) also lowered its core FFO guidance in the same earnings cycle, and Bisnow described the big apartment owners turning bearish on rents.","evidence":"AvalonBay lowered 2025 core FFO guidance by $0.14 to $11.25 per share midpoint (2.2% growth) in its Q3 2025 report of 2025-10-29/30.","sources":[{"title":"AvalonBay Q3 2025 slides: results miss expectations, full-year outlook reduced (Investing.com, Oct 30 2025)","url":"https://www.investing.com/news/company-news/avalonbay-q3-2025-slides-results-miss-expectations-fullyear-outlook-reduced-93CH-4321268"},{"title":"AvalonBay Q3 FFO & Revenues Miss Estimates, '25 Outlook Lowered (Zacks via Yahoo)","url":"https://finance.yahoo.com/news/avalonbay-q3-ffo-revenues-miss-164700387.html"},{"title":"Major Apartment Owners Turn Bearish On Rents As Economy Falters (Bisnow)","url":"https://www.bisnow.com/news/national/multifamily/avalonbay-equity-residential-multifamily-reit-earnings-131657"}]},{"id":"en-2025-1102-opec-pauses-q1-2026-hikes","date":"2025-11-02","end_date":"2025-11-30","sector":"energy","subindustries":["exploration_production","integrated"],"direction":"in","magnitude":"minor","driver_type":"commodity","title":"OPEC+ adds 137,000 b/d for December, then pauses hikes for Q1 2026","summary":"On November 2, 2025 the eight OPEC+ voluntary cutters raised December targets by 137,000 b/d but announced no increases for January-March 2026, the first pause since the April 2025 unwinding began, citing seasonal refinery maintenance. The move came with Brent near $63, down about 15% year to date, and after the IEA's October 2025 report projected a 2026 surplus approaching 4 mb/d; Rystad still saw a ~3.5 mb/d Q1 surplus. The full OPEC+ group confirmed the pause on November 30 and approved a capacity-assessment mechanism for 2027 quotas, putting a floor under sentiment for E&Ps heading into year-end.","evidence":"137,000 b/d December increase and Jan-Mar 2026 pause agreed 2025-11-02 (OGJ)","sources":[{"title":"Oil & Gas Journal - OPEC+ to pause oil production hikes for first-quarter 2026","url":"https://www.ogj.com/general-interest/economics-markets/news/55327719/opec-to-pause-oil-production-hikes-for-first-quarter-2026"},{"title":"CNBC - OPEC+ holds 2026 group-wide oil output steady, agrees capacity mechanism","url":"https://www.cnbc.com/2025/11/30/opec-holds-2026-group-wide-oil-output-steady-agrees-capacity-mechanism.html"},{"title":"IEA - Oil Market Report October 2025","url":"https://www.iea.org/reports/oil-market-report-october-2025"}]},{"id":"cs-2025-kimberly-clark-kenvue","date":"2025-11-03","end_date":"2026-11-02","sector":"consumer_staples","subindustries":["household_personal"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"Kimberly-Clark buys Kenvue for $48.7 billion","summary":"Kimberly-Clark agreed to acquire Kenvue for $3.50 cash plus 0.14625 KMB shares per share ($21.01, a 46% premium, $48.7 billion enterprise value). Kenvue rose about 18% and Kimberly-Clark fell 12.5% on November 3 2025 as shareholders questioned the premium and Tylenol litigation; the deal closed on November 2 2026 and Kenvue left the S&P 500. It is the largest household-products deal since P&G-Gillette and a bet that scale in OTC and personal care can reignite growth.","evidence":"KVUE +18% and KMB -12.5% on 2025-11-03; $48.7B enterprise value, closed 2026-11-02","sources":[{"title":"CBS News: Kimberly-Clark to acquire Tylenol maker Kenvue in $48.7 billion deal","url":"https://www.cbsnews.com/news/kenvue-kimberly-clark-acquisition-tylenol/"},{"title":"Kimberly-Clark: Completes acquisition of Kenvue (Nov 2026)","url":"https://www.investor.kimberly-clark.com/news-releases/news-release-details/kimberly-clark-completes-acquisition-kenvue-creating-preeminent"}]},{"id":"re-2025-1103-simon-q3-2025-record-occupancy","date":"2025-11-03","end_date":null,"sector":"real_estate","subindustries":["retail_reits"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Simon Q3 2025: occupancy climbs to 96.4%, FFO +5.6%, guidance raised again","summary":"On November 3, 2025 Simon Property Group reported Q3 Real Estate FFO of $3.22 per diluted share (+5.6% y/y), US Malls and Premium Outlets occupancy of 96.4% (vs 96.2% a year earlier) with The Mills at 99.4%, base minimum rent of $59.14 per sq ft (+2.5%) and trailing-12-month retailer sales of $742 per sq ft. It raised full-year 2025 Real Estate FFO guidance to $12.60-$12.70, the second raise of the year, reinforcing the thesis that store closures by weak retailers were being absorbed by Class A landlords with pricing power.","evidence":"Q3 2025 Real Estate FFO $3.22/share (+5.6%); occupancy 96.4%; FY guidance raised to $12.60-$12.70 (2025-11-03).","sources":[{"title":"Simon Property Group Q3 2025 results (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/1063761/000110465925105545/tm2528944d2_ex99-1.htm"}]},{"id":"hc-2025-glp1-price-deal","date":"2025-11-06","end_date":"2026-02-28","sector":"healthcare","subindustries":["pharma","healthcare_technology"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Lilly and Novo cut GLP-1 prices for Medicare and TrumpRx; Lilly hits $1 trillion","summary":"On November 6 2025 the White House announced deals under which Medicare and Medicaid pay $245 a month for GLP-1s, Medicare covers obesity for about 10% of beneficiaries at a $50 copay, and cash prices on TrumpRx (launched February 2026) start at or below $350 falling to $245, with oral starter doses at $149; the companies received tariff relief. Novo fell about 3.6% on the day; Lilly's volume story was reinforced and it reached a $1 trillion market cap on November 21 2025. Cheaper branded supply is a direct threat to compounded-GLP-1 telehealth models.","evidence":"Medicare/Medicaid GLP-1 price $245/month and $50 copay announced 2025-11-06; NVO -3.6% intraday; LLY reached $1T market cap on 2025-11-21","sources":[{"title":"CNBC: Trump announces deals with Eli Lilly, Novo Nordisk to slash weight loss drug prices","url":"https://www.cnbc.com/2025/11/06/trump-eli-lilly-novo-nordisk-deal-obesity-drug-prices.html"},{"title":"Al Jazeera: Weight-loss drug makers announce pricing agreement with Trump","url":"https://www.aljazeera.com/economy/2025/11/6/weight-loss-drug-makers-announce-pricing-agreement-with-trump"},{"title":"Wikipedia: Eli Lilly and Company ($1T market value)","url":"https://en.wikipedia.org/wiki/Eli_Lilly_and_Company"}]},{"id":"cs-2025-glp1-price-cuts-food","date":"2025-11-06","end_date":"2026-02-28","sector":"consumer_staples","subindustries":["food_beverage_tobacco"],"direction":"out","magnitude":"minor","driver_type":"policy","title":"GLP-1 price cuts and Medicare obesity coverage revive the food scare","summary":"The November 6 2025 Lilly/Novo agreements cut GLP-1 prices to $245 a month for government programs, added Medicare obesity coverage for about 10% of beneficiaries and launched sub-$350 cash prices on TrumpRx (February 2026), with oral starter doses at $149. Wider affordability re-opened the 2023 question of structural volume loss for snacks, confectionery and beer, which had already de-rated after the 2023 scare and fell again in 2025.","evidence":"Government GLP-1 price $245/month, Medicare coverage for ~10% of beneficiaries, TrumpRx cash prices at or below $350 announced 2025-11-06","sources":[{"title":"CNBC: Trump announces deals with Eli Lilly, Novo Nordisk to slash weight loss drug prices","url":"https://www.cnbc.com/2025/11/06/trump-eli-lilly-novo-nordisk-deal-obesity-drug-prices.html"},{"title":"Manhattan Institute: Will GLP-1 drugs transform the food business?","url":"https://manhattan.institute/article/will-glp-1-drugs-transform-the-food-business"}]},{"id":"glp1-2025-trumprx-lilly-1t","date":"2025-11-06","end_date":"2025-11-21","sector":"glp1","subindustries":[],"direction":"in","magnitude":"major","driver_type":"policy","title":"TrumpRx pricing deal and Lilly's $1 trillion market cap","summary":"In November 2025 the administration announced GLP-1 pricing deals with Lilly and Novo (about $245 a month for Medicaid and TrumpRx users, $50 for Medicare, with a three-year tariff exemption), removing the most-favoured-nation overhang in exchange for volume; Lilly became the first health-care company worth $1 trillion on 21 November 2025. Novo later cut Wegovy's list price to $675 a month from January 2027. The theme re-centred on Lilly, oral GLP-1s and telehealth channels.","evidence":"Eli Lilly reached a $1 trillion market capitalisation on 2025-11-21; TrumpRx GLP-1 prices of about $245 per month (Medicaid) and $50 (Medicare).","sources":[{"title":"Semaglutide (Wikipedia)","url":"https://en.wikipedia.org/wiki/Semaglutide"},{"title":"Eli Lilly and Company (Wikipedia)","url":"https://en.wikipedia.org/wiki/Eli_Lilly_and_Company"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"id":"media-2025-gta-vi-second-delay","date":"2025-11-06","end_date":null,"sector":"communication_media","subindustries":["media_entertainment"],"direction":"out","magnitude":"moderate","driver_type":"tech_cycle","title":"Rockstar delays GTA VI again to Nov 19 2026; Take-Two sinks","summary":"On 2025-11-06 Rockstar Games pushed Grand Theft Auto VI from May 26, 2026 to November 19, 2026, the second delay after the original fall-2025 target, saying the extra months were needed for polish. Take-Two shares fell about 7% in after-hours trading (some reports cited a drop of more than 10% from $252.50 to as low as $219.87), pushing the single most important video-game cycle catalyst for the group into the final weeks of 2026.","evidence":"TTWO about -7% after hours on 2025-11-06; GTA VI moved to 2026-11-19","sources":[{"title":"CNBC: Take-Two stock sinks 7% on delay of Grand Theft Auto VI to November 2026","url":"https://www.cnbc.com/2025/11/06/take-two-gta-vi-delay.html"},{"title":"Forbes: 'Grand Theft Auto VI' delayed again, Take-Two stock plummets","url":"https://www.forbes.com/sites/antoniopequenoiv/2025/11/06/rockstar-delays-grand-theft-auto-vi-release-until-november-2026/"}]},{"id":"biotech-smid-2025-pfizer-metsera-bidding-war","date":"2025-11-07","end_date":"2025-11-08","sector":"healthcare","subindustries":["biotech_smid"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Pfizer wins the $10bn Metsera bidding war against Novo Nordisk","summary":"On Friday November 7, 2025 Metsera accepted a sweetened Pfizer offer of up to $86.25 a share ($65.60 cash plus a CVR worth up to $20.65), about $10bn, citing US antitrust risk in Novo Nordisk's rival bid of up to $86.20, and Novo withdrew the next day after FTC pressure and a Pfizer lawsuit. Metsera stock rose about 8% after hours to above $77, and the first open bidding war between two large pharmas for a pre-revenue obesity biotech showed how aggressively big pharma would pay for SMID-cap assets ahead of the 2026-2030 patent cliff, a signal the XBI rallied on into 2026.","evidence":"Pfizer final offer up to $86.25 per Metsera share (cash $65.60 + CVR $20.65) accepted 2025-11-07; Novo exited 2025-11-08.","sources":[{"title":"Pfizer wins $10 billion bidding war for Metsera as Novo Nordisk exits (PharmaLive)","url":"https://www.pharmalive.com/pfizer-wins-10-billion-bidding-war-for-metsera-as-novo-nordisk-exits/"},{"title":"Pfizer wins Metsera bidding war over Novo with final $10B price tag (BioSpace)","url":"https://www.biospace.com/business/pfizer-wins-metsera-bidding-war-over-novo-with-final-9b-price-tag"},{"title":"Pfizer-Novo Nordisk bidding war escalates: 5 updates (Becker's)","url":"https://www.beckershospitalreview.com/pharmacy/pfizer-novo-nordisk-bidding-war-escalates-5-updates/"}]},{"id":"hardware-2025-memory-cost-squeeze","date":"2025-11-17","end_date":"2026-02-26","sector":"technology","subindustries":["hardware","apple"],"direction":"out","magnitude":"moderate","driver_type":"tech_cycle","title":"Memory inflation squeezes PC and server OEMs","summary":"Morgan Stanley downgraded Dell to Underweight on 17 November 2025 over server memory costs, Dell's COO said on 26 November he had never seen component costs rise so fast, and by 26 February 2026 HP said memory made up 35% of a PC's bill of materials after roughly doubling in a quarter; Gartner warned sub-$500 laptops could become unviable and forecast 2026 PC shipments down 10-11%. The squeeze moved capital from hardware assemblers to the memory makers themselves.","evidence":"Morgan Stanley downgraded Dell to Underweight on 2025-11-17; HP said memory was 35% of PC bill of materials on 2026-02-26.","sources":[{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"}]},{"id":"re-2025-1201-barclays-downgrades-amt-cci","date":"2025-12-01","end_date":null,"sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Barclays downgrades American Tower and Crown Castle to Equal Weight on EchoStar collection risk","summary":"On December 1, 2025 Barclays cut American Tower (PT $200, 17x 2027 AFFO) and Crown Castle (PT $101, 19x 2027 AFFO) to Equal Weight while keeping SBA at Overweight ($212) for its smaller headline exposure. The broker argued the towercos have strong contract claims against EchoStar but that collecting cash is the problem, modelled a 50% payout on the contracts' NPV versus the 75% many investors assumed, and stripped EchoStar revenue out of its models from Q1 2026, projecting 2% 2026 AFFO/share growth for AMT versus 6.1% consensus. The note crystallised the 'Dish churn' overhang that weighed on towers into early 2026.","evidence":"Barclays cut AMT (PT $200) and CCI (PT $101) to Equal Weight on 2025-12-01, modelling a 50% NPV payout on EchoStar contracts.","sources":[{"title":"Yahoo Finance / Investing.com: American Tower, Crown Castle downgraded as EchoStar disputes cloud tower leasing","url":"https://finance.yahoo.com/news/american-tower-crown-castle-downgraded-161659007.html"}]},{"id":"re-2025-1203-alexandria-dividend-cut","date":"2025-12-03","end_date":null,"sector":"real_estate","subindustries":["office_reits"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Alexandria slashes dividend 45% as life-science demand craters; ARE -10%","summary":"On Wednesday December 3, 2025 Alexandria Real Estate Equities cut its quarterly dividend to $0.72 from $1.32 (a 45% reduction and the first payout under $1 since 2019), citing weak life-science leasing, federal research-funding cuts and a venture-funding drought; the REIT had posted a Q3 loss of nearly $235M and seen occupancy fall to 90.6%. ARE shares fell more than $5, about 10%, by 3 p.m. ET on the day. The cut freed roughly $410M a year for the balance sheet and buybacks and crystallised the lab-office distress narrative that has weighed on ARE, BXP's and KRC's life-science exposure.","evidence":"ARE dividend cut to $0.72 from $1.32 per share announced 2025-12-03; shares down about 10% intraday (Bisnow).","sources":[{"title":"Alexandria Slashes Dividend, Shares Drop Sharply (Bisnow, Dec 3 2025)","url":"https://www.bisnow.com/news/national/life-sciences/alexandria-cuts-dividend-amid-life-sciences-turbulence-132136"},{"title":"Dividend Cut Slams Alexandria Amid Life Sciences Slowdown (CRE Daily)","url":"https://www.credaily.com/briefs/dividend-cut-slams-alexandria-amid-life-sciences-slowdown/"},{"title":"Alexandria Cuts Dividend Amid Deepening Life Science Strains (Zacks via Yahoo)","url":"https://finance.yahoo.com/news/alexandria-cuts-dividend-amid-deepening-153600370.html"}]},{"id":"financials-2026-jan-renewals-rates-down-12","date":"2026-01-01","end_date":null,"sector":"financials","subindustries":["insurance"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"Jan 1 2026 renewals: global property-cat rates fall 12% in 'accelerated softening'","summary":"Guy Carpenter's Global Property Catastrophe Rate-on-Line Index fell 12% at the January 1, 2026 renewals, with US rates also down 12% and Continental Europe down 15%, which the broker attributed to 'accelerated softening' from excess capital and high attachment points. The data confirmed the reinsurance cycle had turned, pressuring reinsurer margins (RenaissanceRe, Arch) while lowering ceded costs for primary P&C carriers; declines deepened to 16% after the mid-year 2026 renewals.","evidence":"Guy Carpenter global property-cat ROL index -12% at 2026-01-01","sources":[{"title":"Artemis: Property catastrophe rates fall 12% globally, in the US and APAC, 15% in Europe - Guy Carpenter","url":"https://www.artemis.bm/news/property-catastrophe-rates-fall-12-globally-in-the-us-and-apac-15-in-europe-guy-carpenter/"},{"title":"Reinsurance News: Global property cat ROL down 12% at Jan 1 renewals - Guy Carpenter","url":"https://www.reinsurancene.ws/global-property-cat-rol-down-12-at-jan-1-reinsurance-renewals-guy-carpenter/"}]},{"id":"ind-2026-commodity-rotation","date":"2026-01-02","end_date":"2026-02-27","sector":"industrials","subindustries":["machinery"],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"January 2026 rotation out of tech into materials, energy and industrials","summary":"Hedge funds that moved billions from tech into cyclicals and defensives in Q4 2025 kept rotating in January 2026: materials and energy were up 7.5% and industrials 5.9% by January 14 against 1.2% for the S&P 500. Ag and construction machinery was a major beneficiary, with Deere up 44% year to date by November 5, 2026 after two down years in farm income.","evidence":"XLI +5.9% YTD vs SPY +1.2% at Jan 14, 2026; DE +43.6% YTD at Nov 5, 2026","sources":[{"title":"Investing.com: Materials and energy stocks take early lead in 2026","url":"https://www.investing.com/analysis/materials-and-energy-stocks-take-early-lead-in-2026-200673302"},{"title":"ChartRow DE calendar-year returns","url":"https://chartrow.com/quote/de/returns"}]},{"id":"en-2026-ipp-affordability-reversal","date":"2026-01-02","end_date":"2026-11-06","sector":"energy","subindustries":["new_energy_power"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Power-price backlash: IPPs give back the AI premium","summary":"After three record PJM auctions turned capacity costs into a political affordability issue (PJM's price cap, state pushback, local opposition to data centers that Bernstein says touches 56% of the 433 GW pipeline), the merchant generators that led 2024-25 sold off: Constellation is down 32% and Vistra 30% year to date in 2026 even as oil-driven inflation lifted power prices. Higher rates and the Democratic midterm sweep added to regulatory risk.","evidence":"CEG -31.9% and VST -29.7% YTD at Nov 5, 2026; PJM Dec 2025 auction cleared at the $333.44/MW-day cap, the third straight record","sources":[{"title":"Energy Connects: Pressure mounts to fix key US grid as costs hit new highs (Dec 2025)","url":"https://www.energyconnects.com/news/gas-lng/2025/december/pressure-mounts-to-fix-key-us-grid-as-costs-hit-new-highs"},{"title":"24/7 Wall St: Bernstein on election-day data center fears (Nov 3, 2026)","url":"https://247wallst.com/investing/2026/11/03/ge-vernova-rallies-7-as-bernstein-calls-election-day-data-center-fears-overblown-eaton-climbs-6-vertiv-gains-5/"},{"title":"ChartRow CEG calendar-year returns","url":"https://chartrow.com/quote/ceg/returns"}]},{"id":"re-2026-data-center-rebound","date":"2026-01-02","end_date":"2026-11-05","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"in","magnitude":"major","driver_type":"tech_cycle","title":"2026: data-center REITs lead again on record 340 MW quarter","summary":"Digital Realty signed a record 340 MW of leases in Q1 2026 at 12-year terms and Equinix's same-store revenue grew 11%; data-center REITs were up 22% by mid-March and 28% by September 30 (33% in the first half), the best REIT sector for a third year in four, with Equinix up 32% year to date. Valuations are back to 25-30x forward FFO versus 15-18x for traditional REITs.","evidence":"Data Center REITs +28.0% YTD at Sep 30, 2026 and +33.2% in 1H 2026; DLR record 340 MW of new leases in Q1 2026; EQIX +32.2% YTD at Nov 5, 2026","sources":[{"title":"Datacentres.com: Data centre REITs outperform broader market with 22% YTD returns (Mar 2026)","url":"https://www.datacentres.com/news/data-centre-reit-performance-q1-2026"},{"title":"Nareit property sector returns Sep 30, 2026","url":"https://www.reit.com/sites/default/files/returns/prop.pdf"},{"title":"ChartRow EQIX calendar-year returns","url":"https://chartrow.com/quote/eqix/returns"}]},{"id":"re-2026-lodging-boom","date":"2026-01-02","end_date":"2026-10-31","sector":"real_estate","subindustries":["lodging_reits"],"direction":"in","magnitude":"major","driver_type":"macro","title":"Lodging REITs return 57% as travel demand outruns the oil shock","summary":"Strong leisure, group and business travel plus no new hotel supply made lodging the top REIT sector of 2026: +42.8% in the first half, +37.6% through September and +57.3% through October after a 14.3% October gain, with Host Hotels up 47% year to date. The group had lagged for five years (-5.1% in 2025), so much of the move is multiple recovery as RevPAR and group bookings reached records despite higher airfares.","evidence":"Lodging/Resorts REITs +57.3% YTD through Oct 2026 (+14.3% in October) and +42.8% in 1H 2026; HST +47.1% YTD at Nov 5, 2026","sources":[{"title":"WealthManagement/Nareit: REIT returns climb 4.7% as telecom surges in October","url":"https://www.wealthmanagement.com/alternative-investments/q-a-reits-bounce-back-in-october"},{"title":"Nareit 2026 mid-year update","url":"https://www.reit.com/news/blog/market-commentary/2026-mid-year-update-reits-rebound-poised-future-gains-and-growth"},{"title":"ChartRow HST calendar-year returns","url":"https://chartrow.com/quote/hst/returns"}]},{"id":"re-2026-storage-and-malls-recover","date":"2026-01-02","end_date":"2026-11-05","sector":"real_estate","subindustries":["self_storage_reits","retail_reits"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Storage and malls rebound: Public Storage +35%, Simon's best rent growth in a decade","summary":"Two of 2025's laggards led the non-digital REITs in 2026: self storage returned 10% through September (Public Storage +35% year to date as street rates stabilized and consolidation continued) and regional malls 13.4% through September and 28.9% on 2nd Market Capital's measure, with Simon posting its highest rent growth in a decade and up 26% year to date. Both groups are seen as late-cycle beneficiaries of zero new supply.","evidence":"Self Storage REITs +10.0% and Regional Malls +13.4% YTD at Sep 30, 2026; PSA +35.2% and SPG +26.5% YTD at Nov 5, 2026","sources":[{"title":"Nareit property sector returns Sep 30, 2026","url":"https://www.reit.com/sites/default/files/returns/prop.pdf"},{"title":"Morningstar: Are REITs still a buy after their 2026 runup?","url":"https://indexes.morningstar.com/insights/perspective/bltb73e23968a7c3ab1/are-reits-still-a-buy-after-their-2026-runup"},{"title":"ChartRow PSA calendar-year returns","url":"https://chartrow.com/quote/psa/returns"}]},{"id":"hc-2026-biotech-leads","date":"2026-01-02","end_date":"2026-11-03","sector":"healthcare","subindustries":["biotech_smid","biotech_large"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Biotech leads health care in 2026 as devices lag","summary":"After four years of underperformance, biotech became the sector's leader in 2026: XBI was up about 24.8% and IBB 26.8% year-to-date as of November 3 2026, versus roughly 20% for the broad sector funds and about 12% for the S&P 500 at mid-year readings, helped by lower policy uncertainty after the pricing deals, M&A and falling rates. XBI cooled about 1.5% over the past month. IHI (medical devices) was the only major health-care ETF in negative territory for the year.","evidence":"XBI +24.82% YTD and IBB +26.79% YTD as of 2026-11-03 (etf.com); IHI the only major healthcare ETF in the red","sources":[{"title":"etf.com: Healthcare ETFs 2026, biotech leads, medical devices lag","url":"https://www.etf.com/sections/news/healthcare-etfs-2026-biotech-leads-medical-devices-lag"},{"title":"Yahoo Finance: Biotech ETFs put up strong show in 1H 2026","url":"https://finance.yahoo.com/healthcare/articles/biotech-etfs-put-strong-show-160000067.html"}]},{"id":"hc-2026-devices-lag","date":"2026-01-02","end_date":"2026-11-03","sector":"healthcare","subindustries":["medical_devices"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Medical devices are 2026's healthcare laggard","summary":"Having been the sector's quality-growth refuge in 2024-2025, device makers lost leadership in 2026: IHI was the only major health-care ETF with a negative year-to-date return as of early November 2026 while biotech and the broad sector gained 20%+. Drivers cited in sector commentary were rotation out of crowded quality names into beaten-down biotech, tariff exposure on imported components, and renewed GLP-1 volume worries for diabetes and sleep devices.","evidence":"IHI negative YTD as of 2026-11-03 while XBI +24.8% and XLV ~+20% (etf.com)","sources":[{"title":"etf.com: Healthcare ETFs 2026, biotech leads, medical devices lag","url":"https://www.etf.com/sections/news/healthcare-etfs-2026-biotech-leads-medical-devices-lag"}]},{"id":"cs-2026-staples-record","date":"2026-01-02","end_date":"2026-11-04","sector":"consumer_staples","subindustries":["staples_retail","food_beverage_tobacco","household_personal"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Staples' best year since the 1998 launch: XLP +17% and at records","summary":"Staples had their best start to a year since XLP launched in 1998 (up about 13% by late February 2026) and reached a record high on November 4 2026, up roughly 17% year-to-date while consumer discretionary was flat, as investors rotated into Walmart, Costco, Coca-Cola and P&G on consumer-stress, tariff and AI-capex worries. By February the sector traded at its most expensive relative valuation in about 25 years despite flat 2025 earnings, so the move is positioning-driven rather than earnings-driven.","evidence":"XLP record high on 2026-11-04, ~+17% YTD (GuruFocus); +13% by late February 2026, best start since 1998 launch (Motley Fool)","sources":[{"title":"GuruFocus: Consumer Staples ETF XLP hits record high","url":"https://www.gurufocus.com/news/9170125/consumer-staples-etf-xlp-hits-record-high-driven-by-major-stocks"},{"title":"Motley Fool: Consumer staples just got expensive in a way not seen in 25 years","url":"https://www.fool.com/investing/2026/02/24/consumer-staples-got-expensive-in-a-way-warning/"},{"title":"MarketBeat: Why consumer staples are winning 2026","url":"https://www.marketbeat.com/articles/consumer-staples-are-massively-outperforming-the-marketheres-why/"}]},{"id":"media-2026-worst-sector","date":"2026-01-02","end_date":null,"sector":"communication_media","subindustries":["media_entertainment","internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Communication services goes from best sector (2024-25) to worst (2026)","summary":"After returning 40.2% in 2024 and 33.6% in 2025 (best sector both years), communication services was the worst S&P 500 sector in October 2026 and is down 10.6% year-to-date through 5 November 2026 versus +12.8% for the index: Alphabet's July and October capex shocks, Meta's AI-spending scrutiny, Paramount Skydance's debt-laden WBD takeover and the loss of EA to a buyout drained the sector, while energy (+40.6%) led. The 2018 reclassification that made the sector a growth proxy now makes it the first casualty of AI-capex doubt.","evidence":"XLC -10.6% year-to-date as of 2026-11-05 (worst sector) after +40.2% in 2024 and +33.6% in 2025.","sources":[{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Paramount Skydance (Wikipedia)","url":"https://en.wikipedia.org/wiki/Paramount_Skydance"}]},{"id":"media-2026-versant-spin-debut","date":"2026-01-05","end_date":null,"sector":"communication_media","subindustries":["media_entertainment"],"direction":"out","magnitude":"minor","driver_type":"ma","title":"Versant cable spin-off from Comcast falls more than 10% on Nasdaq debut","summary":"Comcast completed the spin-off of Versant (CNBC, MS NOW, USA Network, Golf Channel, Fandango, Rotten Tomatoes) after the close on 2026-01-02, distributing one VSNT share per 25 CMCSA shares, and Versant began trading on Nasdaq on 2026-01-05. Reuters reported the new stock fell more than 10% on its first day on doubts about the linear-TV business while Comcast rose about 1%, a read-through for the cable-network carve-outs at WBD and for Paramount and Fox's linear exposure.","evidence":"VSNT fell more than 10% in its 2026-01-05 debut; 1-for-25 distribution","sources":[{"title":"Versant press release (Business Wire): Versant begins trading on Nasdaq as independent company","url":"https://www.businesswire.com/news/home/20260104224814/en/VERSANT-Begins-Trading-on-Nasdaq-Today-as-Independent-Company-Following-Completion-of-Comcast-Spin-Off"},{"title":"Investing.com: Versant completes spin-off from Comcast, begins trading on Nasdaq","url":"https://uk.investing.com/news/company-news/versant-completes-spinoff-from-comcast-begins-trading-on-nasdaq-93CH-4437143"}]},{"id":"re-2026-0107-trump-institutional-sfr-ban","date":"2026-01-07","end_date":null,"sector":"real_estate","subindustries":["residential_reits"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Trump vows ban on large investors buying single-family homes; INVH, AMH plunge","summary":"On Wednesday January 7, 2026 President Trump posted on Truth Social that he was 'immediately taking steps' to ban large institutional investors from buying more single-family homes and would ask Congress to codify it, without defining 'large' or a mechanism. Invitation Homes (INVH) tumbled about 6% and American Homes 4 Rent (AMH) fell to a three-year low (reports cited drops of roughly 6%, with a volatility halt), while Blackstone and Apollo each fell more than 5%. Mizuho downgraded both INVH and AMH to neutral the next day; analysts noted institutions own only about 1% of single-family homes, limiting the policy's effect on prices.","evidence":"Invitation Homes fell 6% on 2026-01-07 after the Truth Social post (CNBC).","sources":[{"title":"Trump says U.S. to ban large investors from buying homes (CNBC, Jan 7 2026)","url":"https://www.cnbc.com/2026/01/07/trump-housing-affordability.html"},{"title":"Investors, analysts react to Trump's single-family home buying ban (Multifamily Dive, Jan 8 2026)","url":"https://www.multifamilydive.com/news/investors-analysts-react-to-trumps-single-family-home-buying-ban/809152/"},{"title":"Trump wants ban on large institutional investors buying homes (HousingWire)","url":"https://www.housingwire.com/articles/trump-institutional-home-ban/"}]},{"id":"re-2026-0108-trump-200b-mbs-purchase-order","date":"2026-01-08","end_date":null,"sector":"real_estate","subindustries":["mortgage_reits"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"Trump orders $200B of GSE mortgage-bond purchases; MBS spreads compress 20 bp","summary":"On Thursday January 8, 2026 President Trump posted on Truth Social that he was instructing his representatives to buy $200 billion of mortgage-backed securities to push mortgage rates down; FHFA Director Bill Pulte confirmed Fannie Mae and Freddie Mac would make the purchases. Agency MBS spreads to Treasuries compressed roughly 20 bp within 24 hours and Lender Price's 30-year rate fell to 6.03% on Jan 9 from 6.32% a day earlier. Agency mortgage REITs were flagged as the immediate beneficiaries: AGNC rose about 2% to $11.41 on Friday Jan 9 with NLY, MFA and PMT also higher, and BTIG named Dynex (DX) its top pick for the move. Analysts (KBW, Cato) doubted the lasting rate impact given the GSEs' limited cash and $225B-per-entity portfolio caps.","evidence":"Lender Price 30-year fixed rate fell to 6.03% on 2026-01-09 from 6.32% a day earlier; MBS spreads compressed ~20 bp in 24 hours (National Mortgage News).","sources":[{"title":"Trump's MBS buying plan sparks rally, long-term doubts (National Mortgage News, Jan 9 2026)","url":"https://www.nationalmortgagenews.com/news/trumps-mbs-buying-plan-sparks-rally-long-term-doubts"},{"title":"Pulte confirms Fannie and Freddie will buy $200 billion of mortgage bonds (Scotsman Guide, Jan 8 2026)","url":"https://www.scotsmanguide.com/news/pulte-confirms-fannie-and-freddie-will-buy-200-billion-of-mortgage-bonds/"},{"title":"AGNC stock rises with mortgage REITs after Trump's $200B MBS order","url":"https://ts2.tech/en/agnc-stock-rises-with-mortgage-reits-after-trumps-200b-mbs-order-what-to-watch-next-week/"}]},{"id":"re-2026-0109-compass-closes-anywhere-deal","date":"2026-01-09","end_date":null,"sector":"real_estate","subindustries":["real_estate_services"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Compass closes $1.6B Anywhere takeover months early after DOJ clears it","summary":"On Friday January 9, 2026 Compass completed its all-stock acquisition of Anywhere Real Estate (Coldwell Banker, Century 21, Sotheby's International Realty), paying 1.436 Compass shares per Anywhere share in a deal valued at about $1.6B, after the transaction cleared the HSR waiting period without a second request; Bloomberg reported DOJ staff had recommended an in-depth probe but were overruled by senior officials, and the close came well ahead of the original second-half-2026 guidance. Anywhere CEO Ryan Schneider departed and Robert Reffkin leads the combined company, now the largest US residential brokerage by agents and volume, raising the scale stakes for EXPI, RMAX and Redfin/Rocket and reshaping the private-listing fight with Zillow.","evidence":"Compass-Anywhere merger completed 2026-01-09 at 1.436 Compass shares per Anywhere share (~$1.6B), per SEC/NYSE notification and HousingWire.","sources":[{"title":"Compass closes $1.6B Anywhere merger, forms industry giant (HousingWire, Jan 9 2026)","url":"https://www.housingwire.com/articles/compass-closes-1-6b-anywhere-merger-forms-industry-giant/"},{"title":"Compass Completes Acquisition and Privatization of Anywhere Real Estate (TipRanks)","url":"https://www.tipranks.com/news/company-announcements/compass-completes-acquisition-and-privatization-of-anywhere-real-estate"},{"title":"Compass closes acquisition of Anywhere Real Estate after DOJ approval - Bloomberg (Investing.com)","url":"https://www.investing.com/news/stock-market-news/compass-closes-acquisition-of-anywhere-real-estate-after-doj-approval--bloomberg-93CH-4440001"}]},{"id":"cd-2026-xly-stall","date":"2026-01-12","end_date":"2026-10-31","sector":"consumer_discretionary","subindustries":["internet_retail","autos"],"direction":"out","magnitude":"moderate","driver_type":"positioning","title":"Consumer discretionary stalls in 2026 while staples make records","summary":"XLY set an all-time closing high of 123.75 on January 12 2026 and then went nowhere: the sector index was down about 2.7% year-to-date at October 31 2026 (roughly flat to +3% by early November after a 6% October bounce) while consumer staples rose about 17% and biotech 25%. With Amazon and Tesla dominating the fund, the stall reflected scepticism about AI capex returns at Amazon, the EV demand cliff after the credit expiry, and a defensive rotation as the low-income consumer weakened.","evidence":"XLY all-time high close 123.75 on 2026-01-12; sector index -2.72% YTD at 2026-10-31 (SSGA) vs XLP ~+17% YTD","sources":[{"title":"Macrotrends: XLY stock price history","url":"https://www.macrotrends.net/stocks/charts/XLY/state-street-consumer-discretionary-select-sector-spdr-etf/stock-price-history"},{"title":"SSGA: Consumer Discretionary Select Sector SPDR (XLY)","url":"https://www.ssga.com/us/en/intermediary/etfs/state-street-consumer-discretionary-select-sector-spdr-etf-xly"},{"title":"GuruFocus: Consumer Staples ETF XLP hits record high","url":"https://www.gurufocus.com/news/9170125/consumer-staples-etf-xlp-hits-record-high-driven-by-major-stocks"}]},{"id":"semis-2026-section-232-chip-tariff","date":"2026-01-14","end_date":"2026-01-15","sector":"technology","subindustries":["semiconductors","semicap","hardware"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Section 232 chip tariff: 25% on advanced accelerators, exemptions for US data centers","summary":"Proclamation 11002 of 14 January 2026 imposed a 25% tariff from 15 January on a narrow set of advanced logic chips (Nvidia H200 and AMD MI325X class) with exemptions for US data-center, R&D, startup and public-sector use, and flagged 'significant' future tariffs paired with an offset program for firms building US capacity; Commerce Secretary Lutnick threatened up to 100% for Korean and Taiwanese chipmakers that do not invest. A BIS rule the next day moved H200-class exports to China to case-by-case review tied to US testing (the mechanism for the 25% revenue-share arrangement), and Taiwan pledged $250 billion of US chip investment plus $250 billion of credit guarantees.","evidence":"25% Section 232 tariff on specified advanced semiconductors effective 2026-01-15 (Proclamation 11002); US-Taiwan deal of 2026-01-15 with at least $250 billion of direct investment.","sources":[{"title":"A month in semiconductor policy: Section 232 measures, BIS rule and Taiwan deal (Global Policy Watch)","url":"https://www.globalpolicywatch.com/2026/02/a-month-in-semiconductor-policy-section-232-measures-bis-rule-and-taiwan-deal-signal-strategic-push/"},{"title":"US imposes 25% tariff on semiconductors under Section 232 (GHY)","url":"https://www.ghy.com/trade-compliance/us-25-percent-tariff-semiconductors-section-232/"},{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"}]},{"id":"meddev-2026-boston-scientific-penumbra","date":"2026-01-15","end_date":null,"sector":"healthcare","subindustries":["medical_devices"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Boston Scientific buys Penumbra for $14.5bn, a 19% premium, and its shares fall about 4%","summary":"On January 15, 2026 Boston Scientific agreed to acquire thrombectomy specialist Penumbra at $374 a share in cash or 3.8721 BSX shares (about 73% cash), an enterprise value of roughly $14.5bn and a 19% premium to Penumbra's prior close, funding the $11bn cash portion with cash and new debt. Boston Scientific shares fell nearly 4% premarket and about 6% over the following days as investors questioned the price for a decelerating vascular franchise, while Penumbra rose toward the offer. The deal turned out to be the start of a difficult year for the acquirer, which cut 2026 guidance three times.","evidence":"Deal announced 2026-01-15 at $374 per Penumbra share (~$14.5bn EV, 19% premium); BSX -~4% premarket.","sources":[{"title":"Boston Scientific to acquire Penumbra for $14.5B (MedTech Dive)","url":"https://www.medtechdive.com/news/boston-scientific-acquire-penumbra/809734/"},{"title":"Boston Scientific to snap up thrombectomy specialist Penumbra in deal valued at $14.5B (Fierce Biotech)","url":"https://www.fiercebiotech.com/medtech/boston-scientific-snap-thrombectomy-specialist-penumbra-deal-valued-145b"},{"title":"Boston Scientific announces agreement to acquire Penumbra (SEC 8-K exhibit)","url":"https://www.sec.gov/Archives/edgar/data/885725/000094787126000034/ss5822817_ex9901.htm"}]},{"id":"en-2026-0121-winter-storm-fern-gas-spike","date":"2026-01-21","end_date":"2026-01-23","sector":"energy","subindustries":["exploration_production"],"direction":"in","magnitude":"moderate","driver_type":"commodity","title":"Winter Storm Fern: Henry Hub futures post record 70% weekly gain, gas E&Ps rally","summary":"Ahead of Winter Storm Fern, front-month Henry Hub futures rose roughly 70% in the week to January 23, 2026, settling at $5.275/MMBtu on Friday for the largest weekly percentage gain in records back to 1990, and the Henry Hub spot price printed a record $30.72 on January 23. Gas-weighted producers led: EQT rose 6% and Antero 4% on Wednesday January 21, and Expand Energy, Comstock and Antero gained mid-single digits to low teens on the week. The spike reversed quickly as record production and milder weather returned in February, with UNG giving back nearly all its storm gains.","evidence":"February Henry Hub futures +70% on the week, settled $5.275/MMBtu on 2026-01-23 (Bloomberg)","sources":[{"title":"Bloomberg - US Natural Gas Hits Record Weekly Gain Ahead of Arctic Blast","url":"https://www.bloomberg.com/news/articles/2026-01-23/us-natural-gas-falls-after-record-breaking-three-day-rally"},{"title":"Yahoo Finance - Natural gas prices soar with massive winter storm, arctic blast set to impact almost half the country","url":"https://finance.yahoo.com/news/natural-gas-prices-soar-with-massive-winter-storm-arctic-blast-set-to-impact-almost-half-the-country-134413249.html"},{"title":"Natural Gas Intelligence - Henry Hub Prices Smash All-Time Records as Winter Storm Fern, LNG Tag-Team to Tighten Balances","url":"https://naturalgasintel.com/news/henry-hub-prices-smash-all-time-records-as-winter-storm-fern-lng-tag-team-to-tighten-balances/"}]},{"id":"hc-2026-ma-advance-notice","date":"2026-01-26","end_date":"2026-01-27","sector":"healthcare","subindustries":["managed_care"],"direction":"out","magnitude":"major","driver_type":"policy","title":"Near-flat 2027 Medicare Advantage proposal: UNH and Humana lose a fifth of their value","summary":"CMS's advance notice proposed a 0.09% average payment change for 2027 Medicare Advantage plans, far below the increases insurers had assumed for margin recovery. UnitedHealth fell 20.7% and Humana 22% between the release and the following afternoon, with CVS and Elevance also down sharply, in the worst single policy shock to the group since the 2019 Medicare for All scare.","evidence":"UNH -20.7% and HUM -22% from the 2026-01-26 advance notice to the next afternoon","sources":[{"title":"CNBC: Humana, UnitedHealth plunge 20% after Trump administration proposes keeping MA rates flat","url":"https://www.cnbc.com/2026/01/26/health-insurers-tumble-after-trump-proposes-keeping-medicare-rates-flat.html"},{"title":"Morningstar: Managed care stocks plunge following almost-flat Medicare rate proposal","url":"https://www.morningstar.com/markets/healthcare-managed-care-stocks-plunge-following-almost-flat-medicare-rate-proposal"}]},{"id":"en-2026-0202-devon-coterra-merger","date":"2026-02-02","end_date":"2026-05-08","sector":"energy","subindustries":["exploration_production"],"direction":"mixed","magnitude":"moderate","driver_type":"ma","title":"Devon and Coterra agree $58B all-stock merger, largest shale deal of 2026","summary":"On February 2, 2026 Devon Energy and Coterra Energy announced an all-stock combination at 0.70 Devon shares per Coterra share, a ~$58 billion enterprise value, targeting $1.0 billion of annual synergies by end-2027 and pro forma output above 1.6 MMboe/d. Coterra shares had already risen about 14% since talks were reported in January. Shareholders approved on May 4 and the deal closed May 7-8, 2026 with Devon unveiling an $8 billion buyback; Enverus counted Q1 2026 US upstream M&A at a two-year-high $36 billion, reinforcing the consolidation premium for mid-cap E&Ps.","evidence":"0.70 exchange ratio and ~$58B enterprise value announced 2026-02-02; closed 2026-05-08","sources":[{"title":"Devon Energy - Devon Energy and Coterra Energy to Combine, Creating a Premier Shale Operator","url":"https://investors.devonenergy.com/investors/press-releases/press-release-details/2026/Devon-Energy-and-Coterra-Energy-to-Combine-Creating-a-Premier-Shale-Operator/"},{"title":"CNBC - Devon, Coterra will merge to create $58 billion U.S. shale giant","url":"https://www.cnbc.com/2026/02/02/us-shale-producers-devon-and-coterra-to-merge-in-a-58-billion-deal.html"},{"title":"Rigzone - Devon, Coterra Complete $58B Merger","url":"https://www.rigzone.com/news/devon_coterra_complete_58b_merger-08-may-2026-183649-article/"}]},{"id":"software-2026-claude-crash","date":"2026-02-03","end_date":"2026-03-31","sector":"technology","subindustries":["application_software","it_services","infrastructure_software_cyber"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"'SaaS-pocalypse': Anthropic's Claude Cowork plug-ins and Opus 4.6 trigger a $300 billion software selloff","summary":"Anthropic's release of Claude Cowork plug-ins in the week of 2 February 2026, followed by Claude Opus 4.6 with agent teams on 5 February, triggered what traders called the 'SaaS-pocalypse': roughly $300 billion of software market value was lost in a single session, enterprise software, legal-services and real-estate data names fell, and financial-data providers were hit on 6 February (FactSet -10%, with S&P Global, Moody's and Nasdaq lower). Investors feared AI agents would shrink seat-based licence counts; IGV, which had peaked in September 2025, was down about 30% from that peak by the spring and was reported to have fallen 24% in Q1 2026, its worst quarter since Q4 2008.","evidence":"Roughly $300 billion of software market-cap losses in one day after the Claude Cowork plug-in release (week of 2026-02-02); FactSet -10% on 2026-02-06.","sources":[{"title":"Anthropic's Claude Opus 4.6 and the software stock selloff (Fortune, 2026-02-06)","url":"https://fortune.com/2026/02/06/anthropic-claude-opus-4-6-stock-selloff-new-upgrade/"},{"title":"The Claude Crash: how AI triggered a historic selloff in software stocks (StockCharts)","url":"https://articles.stockcharts.com/article/the-claude-crash-how-ai-triggered-a-historic-selloff-in-software-stocks/"},{"title":"Anthropic just triggered another SaaS sell-off (24/7 Wall St., 2026-04-11)","url":"https://247wallst.com/investing/2026/04/11/anthropics-just-triggered-another-saas-sell-off-are-software-stocks-uninvestable/"},{"title":"AI crushed software stocks; IGV is betting the SaaSpocalypse is overblown (AOL)","url":"https://www.aol.com/articles/ai-crushed-software-stocks-igv-194541000.html"},{"title":"AI agents just erased $2T in SaaS value (Tech Insider blog; Q1 2026 IGV figure, unverified)","url":"https://tech-insider.org/saas-stock-crash-ai-agents-2-trillion-2026/"}]},{"id":"re-2026-0205-digital-realty-q4-2025-record-backlog","date":"2026-02-05","end_date":null,"sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"Digital Realty Q4 2025: record $1.4B backlog and $1.2B full-year bookings, 2026 Core FFO guidance +8%, but EPS miss","summary":"On February 5, 2026 Digital Realty reported Q4 2025 bookings of $400 million at 100% share, full-year 2025 bookings of $1.2 billion, a record $339 million (+35% y/y) in the 0-1 MW plus interconnection category and a record $1.4 billion backlog equal to 20% of in-place rent. 2025 Core FFO was $7.39 per share and 2026 guidance was set at $7.90-$8.00 (about +8%), with cash renewal spreads of 6%-8% and occupancy up 50-100 bp from 84.7%. GAAP EPS of $0.24 missed the $0.29 consensus; shares slipped 1.12% in the regular session and were flat (+0.13% to ~$167) after hours, a muted reaction given the AI-driven bookings record.","evidence":"Record $1.4B backlog and 2026 Core FFO guidance of $7.90-$8.00/share (~+8%) reported 2026-02-05; DLR -1.12% in the regular session.","sources":[{"title":"Investing.com: Digital Realty Q4 2025 slides: Record bookings and backlog despite EPS miss","url":"https://www.investing.com/news/company-news/digital-realty-q4-2025-slides-record-bookings-and-backlog-despite-eps-miss-93CH-4489275"},{"title":"Digital Realty Reports Fourth Quarter 2025 Results (Feb 5, 2026)","url":"https://investor.digitalrealty.com/node/20001/pdf"}]},{"id":"cd-2026-scotus-ieepa","date":"2026-02-20","end_date":"2026-04-20","sector":"consumer_discretionary","subindustries":["internet_retail","apparel_luxury","specialty_retail"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Supreme Court strikes down IEEPA tariffs; importers rally","summary":"On February 20 2026 the Supreme Court held that IEEPA does not authorise tariffs, voiding the 'Liberation Day' reciprocal and fentanyl tariffs (Section 232 and 301 duties were untouched). Consumer discretionary rose about 1% on the day with Amazon, Etsy, Tapestry and Williams-Sonoma up, and apparel names popped because roughly 60% of applied apparel/footwear tariffs were IEEPA-based (Morgan Stanley). The administration replaced them with a 10% Section 122 global tariff from February 24, and the Court of International Trade ordered refunds on April 20 2026, a cash windfall for importers like G-III.","evidence":"IEEPA tariffs invalidated 2026-02-20; S&P 500 consumer discretionary +~1% intraday; Section 122 10% tariff from 2026-02-24; CIT refund order 2026-04-20","sources":[{"title":"CNBC: Amazon, Etsy, other e-commerce stocks pop after Supreme Court rules against Trump's tariffs","url":"https://www.cnbc.com/2026/02/20/supreme-court-decision-amazon-etsy-stocks-tariffs-trump.html"},{"title":"CNBC: How the Supreme Court's ruling on Trump's tariffs could impact consumer stocks","url":"https://www.cnbc.com/2026/02/19/how-the-supreme-courts-ruling-on-tariffs-could-impact-consumer-stocks.html"},{"title":"G-III Apparel 10-Q (July 2026) on tariff refunds","url":"https://www.sec.gov/Archives/edgar/data/0000821002/000110465926105950/giii-20260731x10q.htm"}]},{"id":"tech-2026-supreme-court-tariff-ruling","date":"2026-02-20","end_date":"2026-07-24","sector":"technology","subindustries":["hardware","apple","semiconductors","fintech_payments"],"direction":"in","magnitude":"major","driver_type":"regulatory","title":"Supreme Court strikes down IEEPA tariffs; Section 122 and 301 duties replace them","summary":"In Learning Resources v. Trump (6-3, 20 February 2026) the Supreme Court held that IEEPA does not authorise tariffs, voiding the Liberation Day and Canada/Mexico duties; collection stopped on 24 February and about $166 billion owed to more than 330,000 importers became refundable (about $81 billion refunded by July). The administration replaced them with a 10%, then 15%, Section 122 global tariff for 150 days to 24 July 2026 and Section 301 tariffs of 10-12.5% on 60 countries thereafter, leaving the average effective rate at 12.1% in July 2026 versus about 27% in April 2025. Import-heavy hardware and Apple benefited; Section 232 metal and chip tariffs were untouched.","evidence":"Supreme Court decision 2026-02-20 (6-3); IEEPA tariff collection ended 2026-02-24 with about $166 billion in refunds owed; average effective tariff rate 12.1% on 2026-07-21.","sources":[{"title":"Learning Resources, Inc. v. Trump (Wikipedia)","url":"https://en.wikipedia.org/wiki/Learning_Resources,_Inc._v._Trump"},{"title":"Supreme Court opinion, 24-1287 (2026-02-20)","url":"https://www.supremecourt.gov/opinions/25pdf/24-1287_4gcj.pdf"},{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"}]},{"id":"re-2026-0220-scotus-strikes-ieepa-tariffs","date":"2026-02-20","end_date":null,"sector":"real_estate","subindustries":["industrial_logistics_reits","retail_reits"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Supreme Court strikes down IEEPA tariffs 6-3; administration pivots to 10% Section 122 global tariff","summary":"In Learning Resources v. Trump, decided February 20, 2026, the Supreme Court ruled 6-3 that IEEPA does not authorize the president to impose tariffs, voiding the Liberation Day 'reciprocal' tariffs (Section 232 and 301 tariffs were untouched). The administration revoked the IEEPA orders and imposed a replacement 10% global tariff under Section 122 of the Trade Act, which expires in late July absent Congress, leaving import-volume visibility for warehouse landlords muddled rather than resolved. The equity reaction was positive but muted: the S&P 500 rose, the Dow gained about 200 points and the retail ETF XRT hit a session high of +1.8%.","evidence":"Supreme Court 6-3 ruling on 2026-02-20 invalidating IEEPA tariffs; replacement 10% Section 122 tariff imposed.","sources":[{"title":"SCOTUSblog: Supreme Court strikes down tariffs","url":"https://www.scotusblog.com/2026/02/supreme-court-strikes-down-tariffs/"},{"title":"Commercial Observer: The Supreme Court Tariffs Ruling and Commercial Real Estate Investment","url":"https://commercialobserver.com/2026/02/trump-supreme-court-tariffs-commercial-real-estate-investment-strategy/"},{"title":"CNBC: S&P 500 rises, Dow gains 200 points after Supreme Court strikes down Trump emergency tariffs","url":"https://www.cnbc.com/2026/02/19/stock-market-today-live-updates.html"}]},{"id":"media-2026-paramount-wins-wbd","date":"2026-02-27","end_date":"2026-10-06","sector":"communication_media","subindustries":["media_entertainment"],"direction":"in","magnitude":"major","driver_type":"ma","title":"Paramount Skydance outbids Netflix for Warner Bros. Discovery at $110 billion","summary":"After WBD's board ruled Paramount's $31-a-share all-cash offer superior on 26 February 2026, Netflix withdrew and Paramount signed a definitive agreement on 27 February valued at about $81 billion in equity and $110 billion in enterprise value; shareholders approved it on 23 April, the DOJ on 12 June, twelve states settled in September and the deal closed on 6 October 2026, creating Skydance Corporation (NYSE: SKYD). Paramount's own shares were about 25% below their year-start price by late September, reflecting the debt load.","evidence":"Definitive Paramount-WBD agreement signed 2026-02-27 at about $110 billion enterprise value; closed 2026-10-06.","sources":[{"title":"Warner Bros. Discovery (Wikipedia)","url":"https://en.wikipedia.org/wiki/Warner_Bros._Discovery"},{"title":"Paramount Skydance (Wikipedia)","url":"https://en.wikipedia.org/wiki/Paramount_Skydance"}]},{"id":"ind-2026-iran-war-airlines-fuel","date":"2026-02-28","end_date":"2026-06-04","sector":"industrials","subindustries":["transportation"],"direction":"mixed","magnitude":"major","driver_type":"geopolitical","title":"Iran war doubles jet fuel; airlines cut capacity then rally on fares","summary":"The Israel-US-Iran war that began February 28, 2026 pushed crude from about $60 to the $90-110 range and jet fuel to roughly double its early-2026 level ('an unprecedented spike', per Delta's CEO). Airlines cut capacity and 2026 EPS estimates were slashed (United $13.33 to $9.46, Delta $7.19 to $5.54), but fare increases and robust premium demand produced a rebound from June, with Delta up 17% year to date by June 4; JETS is roughly flat for 2026.","evidence":"United 2026 EPS consensus cut from $13.33 to $9.46 and Delta from $7.19 to $5.54 within three months; JETS +1.0% YTD at Nov 5, 2026","sources":[{"title":"Motley Fool: The surprising reason airline stocks are soaring (Jun 4, 2026)","url":"https://www.fool.com/investing/2026/06/04/surprising-reason-airline-stocks-soar-dal-ual/"},{"title":"Al Jazeera: Oil prices surge as US-Iran strikes intensify (Sep 7, 2026)","url":"https://www.aljazeera.com/economy/2026/9/7/oil-prices-surge-as-us-iran-strikes-intensify-in-strait-of-hormuz"},{"title":"ChartRow JETS calendar-year returns","url":"https://chartrow.com/quote/jets/returns"}]},{"id":"ind-2026-iran-war-defense-budget","date":"2026-02-28","end_date":"2026-11-03","sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"Operation Epic Fury, a $200bn supplemental and a $1.5 trillion FY2027 request","summary":"The US launched Operation Epic Fury against Iran on February 28, 2026; Hegseth sought ~$200bn in supplemental funding and on April 21 the Pentagon unveiled a $1.5 trillion FY2027 request (42% above the $901bn baseline) centered on Golden Dome, drones and AI. Munitions and missile-defense names led: Lockheed is up 21% year to date, although ITA is slightly negative because Boeing/GE Aerospace weigh on the ETF and CBO's May estimate that Golden Dome would cost $1.2 trillion raised doubts about affordability.","evidence":"FY2027 request $1.5T (+42% y/y) unveiled Apr 21, 2026; CBO Golden Dome estimate $1.2T (May 12, 2026); LMT +21.3% YTD at Nov 5, 2026","sources":[{"title":"Defense News: Pentagon seeks funds for Golden Dome, drones, AI in largest-ever budget request","url":"https://www.defensenews.com/pentagon/2026/04/21/pentagon-seeks-funds-for-golden-dome-drones-ai-in-largest-ever-budget-request/"},{"title":"Defense One: Golden Dome plan would cost $1.2 trillion, CBO finds","url":"https://www.defenseone.com/defense-systems/2026/05/golden-dome-cost-trillion-cbo/413485/"},{"title":"ChartRow LMT calendar-year returns","url":"https://chartrow.com/quote/lmt/returns"}]},{"id":"en-2026-iran-war-hormuz-upstream","date":"2026-02-28","end_date":"2026-11-06","sector":"energy","subindustries":["integrated","exploration_production","oilfield_services"],"direction":"in","magnitude":"major","driver_type":"geopolitical","title":"Iran war closes the Strait of Hormuz: the 2026 oil shock","summary":"Israel struck Iran on February 28, 2026 and the US launched Operation Epic Fury; drones hit Saudi Arabia's Ras Tanura refinery and Qatar's Ras Laffan LNG plant, insurers cancelled Hormuz war-risk cover and transits collapsed from a baseline of 85 a day to near zero. Brent went from the $60s in January to $84 on March 3, $109 on March 9 and $115 in late October before easing toward $98-100 in early November; XLE is up 41% and XOP 40% year to date versus 8% for the S&P 500, Exxon up 40% and SLB 32% as Middle East service work and non-Gulf barrels re-priced.","evidence":"Brent $109.4 on Mar 9, 2026; Hormuz transits 2/day (Oct 25, 2026) vs 85/day pre-crisis; XLE +40.6% and XOM +40.1% YTD at Nov 5, 2026 vs SPY +8.3%","sources":[{"title":"Oilprice/Yahoo: 24-hour energy shock (Mar 3, 2026)","url":"https://finance.yahoo.com/news/24-hour-energy-shock-world-160000254.html"},{"title":"Gulf News: Brent crude oil price spikes to $109 amid Iran-US-Israel war","url":"https://gulfnews.com/business/energy/brent-crude-oil-price-spikes-to-1071-amid-iran-us-israel-war-1.500467933"},{"title":"Straits Daily Brief Nov 6, 2026","url":"https://www.straits.live/briefs/2026-11-06"},{"title":"Fortune: Current price of oil as of October 27, 2026","url":"https://fortune.com/article/price-of-oil-10-27-2026/"},{"title":"ChartRow XLE calendar-year returns","url":"https://chartrow.com/quote/xle/returns"}]},{"id":"en-2026-refiners-diesel-squeeze","date":"2026-02-28","end_date":"2026-11-06","sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"major","driver_type":"commodity","title":"Diesel at $5.90 and record crack spreads: refiners double","summary":"With Gulf refineries hit, Asian naphtha cracks at highs not seen since 2022 and US diesel reaching an all-time high of $5.85-5.90 a gallon in September 2026, US refiners captured the product shortage: Valero is up 119% and the CRAK ETF 51% year to date, with Marathon and Phillips 66 at records. The group is the best-performing energy sub-industry of the war.","evidence":"VLO +119.0% and CRAK +50.9% YTD at Nov 5, 2026; US diesel record $5.85/gal (early Sept 2026)","sources":[{"title":"Al Jazeera: Oil prices surge as US-Iran strikes intensify (Sep 7, 2026)","url":"https://www.aljazeera.com/economy/2026/9/7/oil-prices-surge-as-us-iran-strikes-intensify-in-strait-of-hormuz"},{"title":"ChartRow VLO calendar-year returns","url":"https://chartrow.com/quote/vlo/returns"},{"title":"ChartRow CRAK calendar-year returns","url":"https://chartrow.com/quote/crak/returns"}]},{"id":"materials-2026-iran-war-oil-gold","date":"2026-02-28","end_date":"2026-03-23","sector":"materials","subindustries":["gold_miners","chemicals","metals_mining"],"direction":"mixed","magnitude":"major","driver_type":"geopolitical","title":"Iran war: Brent spikes to $119.50, gold to about $5,400, energy becomes 2026's leading sector","summary":"US and Israeli strikes on Iran on 28 February 2026 killed Supreme Leader Khamenei and Iran effectively closed the Strait of Hormuz; Brent hit an intraday $119.50 on 9 March 2026 (+29%) before easing toward $100 on talk of coordinated reserve releases, and gold reached an all-time high near $5,400 in March. Energy became the best S&P 500 sector of 2026 (about +40% year-to-date by early November) while gold miners spiked then gave back 21% in Q2 as gold fell below $4,700; chemical producers faced higher feedstock costs and refined-product prices stayed 35-70% above pre-war levels into June.","evidence":"Brent intraday high $119.50 on 2026-03-09; gold all-time high near $5,400 in March 2026; S&P 500 Energy +40.3% year-to-date (Novel Investor 2026 YTD table).","sources":[{"title":"2026 in the United States (Wikipedia)","url":"https://en.wikipedia.org/wiki/2026_in_the_United_States"},{"title":"Price of oil (Wikipedia)","url":"https://en.wikipedia.org/wiki/Price_of_oil"},{"title":"Gold just hit $4,400 and the miners are finally catching up (24/7 Wall St., 2026-08-16)","url":"https://247wallst.com/investing/etf/2026/08/16/gold-just-hit-4400-and-the-miners-are-finally-catching-up/"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"ind-2026-staffing-rebound","date":"2026-03-01","end_date":"2026-08-18","sector":"industrials","subindustries":["professional_services"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Staffing stocks 'defy gravity' after the AI-demise call","summary":"From their February-March 2026 lows the staffing group staged one of the year's biggest short squeezes: by August 18, 2026 ManpowerGroup was up about 120% and Robert Half 94% as hiring data stayed firm and Goldman argued the valuation collapse priced a 'worst-case disruption scenario' rather than actual customer behavior. Robert Half is up 68% and ADP 22% year to date through November 5, 2026.","evidence":"ManpowerGroup +~120% from its March 2026 low and Robert Half +~94% from its February low by Aug 18, 2026; RHI +68.1% YTD at Nov 5, 2026","sources":[{"title":"Bloomberg Government: Staffing stocks defy gravity after analysts warned of AI demise","url":"https://news.bgov.com/daily-labor-report/staffing-stocks-defy-gravity-after-analysts-warned-of-ai-demise"},{"title":"Barron's via Tiger: 8 services stocks are AI winners, Goldman says","url":"https://www.itiger.com/news/2631587290"},{"title":"ChartRow RHI calendar-year returns","url":"https://chartrow.com/quote/rhi/returns"}]},{"id":"en-2026-lng-hormuz-premium","date":"2026-03-02","end_date":"2026-11-06","sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"moderate","driver_type":"geopolitical","title":"Qatar's Ras Laffan halt makes US LNG and gas pipelines strategic assets","summary":"Qatar halted production at Ras Laffan after Iranian drone attacks in early March 2026 and LNG prices jumped about $15/MMBtu, sending buyers to US Gulf Coast exporters (Trafigura signed a five-year deal with Venture Global). Cheniere is up 45% year to date, Kinder Morgan 14% and AMLP 13%, lagging the upstream rally because fee-based pipelines have little direct oil exposure but benefiting from LNG feedgas growth.","evidence":"LNG prices +$15/MMBtu after Ras Laffan halt (Mar 2026); LNG (Cheniere) +44.8%, KMI +14.0%, AMLP +12.7% YTD at Nov 5, 2026","sources":[{"title":"Oilprice/Yahoo: 24-hour energy shock (Mar 3, 2026)","url":"https://finance.yahoo.com/news/24-hour-energy-shock-world-160000254.html"},{"title":"ChartRow LNG calendar-year returns","url":"https://chartrow.com/quote/lng/returns"},{"title":"ChartRow AMLP calendar-year returns","url":"https://chartrow.com/quote/amlp/returns"}]},{"id":"housing-2026-lennar-q1-margin-collapse","date":"2026-03-12","end_date":"2026-03-31","sector":"consumer_discretionary","subindustries":["housing"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Lennar's gross margin falls to 15.2% on 14% incentives; the stock loses 24% in March 2026","summary":"Lennar's fiscal Q1 2026 (reported March 12, 2026) showed net earnings of $229m, or $0.93 a share, versus $1.96 a year earlier, revenue down 13% to about $6.6bn, deliveries down to 16,863 and a home-sales gross margin of 15.2% against 18.7%, as incentives of roughly 14% of sales price and an average selling price of $374,000 were needed to hold orders up 1%. Shares fell 2% after hours and management called 15.2% the low point, but the stock lost 24.1% over March as the Iran-war rate spike and the geopolitical shock hit affordability; builders would not recover until the November midterm rally.","evidence":"Fiscal Q1 2026 EPS $0.93 vs $1.96 y/y; gross margin 15.2% vs 18.7%; LEN -24.1% in March 2026 (S&P Global Market Intelligence).","sources":[{"title":"Lennar reports first quarter 2026 results (Lennar newsroom, 2026-03-12)","url":"https://newsroom.lennar.com/2026-03-12-Lennar-Reports-First-Quarter-2026-Results"},{"title":"Why Lennar Corporation stock fell 24.1% in March (Motley Fool, 2026-04-06)","url":"https://www.fool.com/investing/2026/04/06/why-lennar-corporation-stock-fell-241-in-march/"},{"title":"Lennar Q1: revenue falls 13% as deliveries dip and shares slip after earnings (Alpha Spread)","url":"https://www.alphaspread.com/market-news/earnings/lennar-q1-revenue-falls-13-as-deliveries-dip-and-shares-slip-after-earnings"}]},{"id":"self-storage-2026-psa-nsa-merger","date":"2026-03-16","end_date":"2026-07-22","sector":"real_estate","subindustries":["self_storage_reits"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Public Storage buys National Storage Affiliates for $10.5bn: storage consolidates into the housing freeze","summary":"Public Storage agreed on March 16, 2026 to acquire National Storage Affiliates in an all-stock deal at 0.14 PSA shares per NSA share ($41.68, about $10.5bn including debt), backed by $2bn of bridge financing from Goldman Sachs and Wells Fargo plus a $2bn joint-venture bridge. NSA holders approved on July 14 and the deal closed July 22, giving PSA more than 4,500 properties, 327m square feet and about 14% of U.S. storage space; PSA raised its 2026 core FFO guidance twice afterwards. With move-in demand frozen by the locked-up housing market, scale and longer-staying 'can't let go' tenants, not street rates, became the sector's growth story.","evidence":"Exchange ratio 0.14 Public Storage shares per NSA share, implying $41.68 per share (announced 2026-03-16; closed 2026-07-22).","sources":[{"title":"Public Storage to buy National Storage Affiliates for $10.5B (Multi-Housing News)","url":"https://www.multihousingnews.com/public-storage-to-buy-national-storage-affiliates-for-10-5b/"},{"title":"Public Storage announces anticipated closing date of pending acquisition of NSA (Public Storage IR)","url":"https://investors.publicstorage.com/news-events/press-releases/news-details/2026/Public-Storage-Announces-Anticipated-Closing-Date-of-Pending-Acquisition-of-National-Storage-Affiliates-Following-Approval-by-NSA-Shareholders/default.aspx"},{"title":"Self-storage REITs are collecting rent from Americans who cannot let go (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/10/05/self-storage-reits-are-collecting-rent-from-americans-who-cannot-let-go/"}]},{"id":"financials-2026-basel-reproposal","date":"2026-03-19","end_date":"2026-06-18","sector":"financials","subindustries":["banks","capital_markets"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"Basel III endgame re-proposed with lower capital requirements","summary":"On 19 March 2026 the banking agencies issued three proposals to 'modernize' the capital framework, estimated to modestly reduce requirements for large banks and moderately for smaller ones, reversing the 2023 proposal's increases; comments closed 18 June and no final rule had been issued by September. Despite deregulation, higher rates and an inverted-curve scare, financials lagged in 2026 (XLF +6.3% year-to-date on 5 November versus +40.6% for energy) as private-credit losses and AI-related credit stress weighed on capital-markets names.","evidence":"Three capital proposals issued 2026-03-19 with comments due 2026-06-18; XLF total return +6.3% year-to-date as of 2026-11-05.","sources":[{"title":"Basel III endgame: where the US rule stands in 2026","url":"https://governancedocs.com/basel-iii-endgame/"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"}]},{"id":"memory-2026-turboquant-dip","date":"2026-03-24","end_date":"2026-04-10","sector":"technology","subindustries":["memory","hardware"],"direction":"out","magnitude":"moderate","driver_type":"tech_cycle","title":"Google's TurboQuant compression knocks memory stocks; DDR5 prices drop 30%","summary":"Google's 24 March 2026 announcement of TurboQuant, a model-compression technique that cuts memory requirements for inference, sent Sandisk, Micron, Western Digital and Seagate lower over the following days, and retail DDR5 prices dropped nearly 30% by 10 April (though remaining far above 2024 levels). The dip proved temporary: Micron reached a $1 trillion market cap on 26 May 2026 and its CEO said in June the shortage would last through 2027.","evidence":"TurboQuant announced 2026-03-24; DDR5 prices down nearly 30% by 2026-04-10; Micron $1 trillion market cap on 2026-05-26.","sources":[{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"},{"title":"Micron Technology (Wikipedia)","url":"https://en.wikipedia.org/wiki/Micron_Technology"}]},{"id":"biotech-smid-2026-biogen-apellis","date":"2026-03-31","end_date":null,"sector":"healthcare","subindustries":["biotech_smid"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Biogen pays a 140% premium for Apellis: $5.6bn deal marks the floor of the spring 2026 biotech selloff","summary":"On March 31, 2026 Biogen agreed to buy Apellis for $41 a share in cash plus a CVR of up to $4 tied to Syfovre sales, about $5.6bn, an 86% premium to the 90-day VWAP and 35% above the 52-week high; Apellis jumped roughly 135-140% and Biogen fell 3-7%. The deal landed near the XBI's March low and was one of the takeouts that drove the ETF up about 34% from March to August, as large-caps with cash paid record premiums (median public-target premium 37.8% in 2026) for commercial-stage SMID assets.","evidence":"Apellis +135.4% on 2026-03-31 on a $41 cash + $4 CVR offer (~$5.6bn); Biogen -3% to -7%.","sources":[{"title":"Biogen to acquire immunology biotech Apellis for $5.6 billion (STAT)","url":"https://www.statnews.com/2026/03/31/biogen-acquisition-apellis-immunology/"},{"title":"Biogen to buy Apellis Pharmaceuticals for $5.6 billion in rare disease push (CNBC)","url":"https://www.cnbc.com/2026/03/31/biogen-to-buy-apellis-pharmaceuticals.html"},{"title":"APLS stock soars 140% today (Stocktwits)","url":"https://stocktwits.com/news-articles/markets/equity/apls-stock-soars-after-biogen-acquire-5-6b-deal/cZEPMW3RIVe"}]},{"id":"apparel-2026-nike-q3-china-warning","date":"2026-03-31","end_date":null,"sector":"consumer_discretionary","subindustries":["apparel_luxury"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Nike guides fiscal Q4 sales down 2-4% and China down 20%; shares fall 8-9% after hours","summary":"Nike beat on fiscal Q3 2026 (revenue $11.28bn flat, EPS $0.35 vs $0.28) on March 31, 2026 but said Q4 sales would fall 2-4% against expectations of a 1.9% rise, that Greater China sales would drop about 20% in the current quarter and that sales would decline by a low-single-digit rate through the end of calendar 2026, with gross margin down 130bp to 40.2% on North American tariffs. Shares fell more than 8% in extended trading (8.7% at the Frankfurt open), resetting the turnaround timeline that the June 2025 rally had priced.","evidence":"Fiscal Q3 2026 EPS $0.35 vs $0.28; Q4 sales guided -2% to -4% vs +1.9% consensus; NKE -8% to -9% after hours on 2026-03-31.","sources":[{"title":"Nike (NKE) earnings Q3 2026 (CNBC, 2026-03-31)","url":"https://www.cnbc.com/2026/03/31/nike-nke-earnings-q3-2026.html"},{"title":"The Swoosh seeks support: Nike investors eye rebound after 2026 earnings turbulence (FinancialContent, 2026-04-01)","url":"https://markets.financialcontent.com/stocks/article/marketminute-2026-4-1-the-swoosh-seeks-support-nike-investors-eye-rebound-after-2026-earnings-turbulence"}]},{"id":"semis-2026-q2-melt-up","date":"2026-04-01","end_date":"2026-06-30","sector":"technology","subindustries":["semiconductors","memory","semicap","hardware"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Q2 2026 semiconductor melt-up: SMH +71%, SOX +106% year-to-date, Micron $1 trillion","summary":"Betting that AI infrastructure needs more memory and CPUs, not just GPUs, investors drove the VanEck Semiconductor ETF (SMH) up 71% from early April to the end of June 2026, its best quarter ever; Micron, Intel and AMD added about $2 trillion of market value, Lam, KLA and Applied Materials each more than doubled, Micron's quarterly revenue more than quadrupled with gross margin at 84.9%, Micron crossed $1 trillion on 26 May and Broadcom $2 trillion on 22 April, and the Nasdaq closed above 27,000 on 1 June. The Philadelphia semiconductor index was up 106% year-to-date at its late-June record.","evidence":"SMH +71% from early April through end-June 2026 (best quarter ever); SOX +106% year-to-date at its late-June 2026 record.","sources":[{"title":"Chip stocks that notched record rallies in Q2 start Q3 with a dud (CNBC, 2026-07-01)","url":"https://www.cnbc.com/2026/07/01/chip-stocks-notched-record-rallies-in-second-quarter-start-q3-with-dud.html"},{"title":"The 2026 semiconductor selloff creates an opportunity (Leverage Shares)","url":"https://leverageshares.com/en-eu/insights/the-2026-semiconductor-selloff-creates-an-opportunity/"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"},{"title":"Nasdaq Composite (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"}]},{"id":"materials-2026-gold-q2-drawdown-rebound","date":"2026-04-01","end_date":"2026-08-11","sector":"materials","subindustries":["gold_miners"],"direction":"mixed","magnitude":"major","driver_type":"rates","title":"Gold miners fall 21% in Q2 2026, then recover as gold retakes $4,400","summary":"After the March war spike, gold slipped below $4,700 in April and posted its worst quarter in 13 years as the 10-year yield climbed about a point from its February low toward 4.7%; GDX fell about 21% from roughly $96 in early April to $75 by 30 June 2026. Gold moved back above $4,400 on 11 August, GDX hit a decade high near $88 (+53% over 12 months) and Newmont reported record Q2 free cash flow of $2.2 billion at a realized price of $4,414 an ounce; gold then fell to a two-month low in October on Fed-hike signals.","evidence":"GDX about -21% in Q2 2026 (about $96 to $75); gold above $4,400 on 2026-08-11; Newmont Q2 2026 realized gold price $4,414/oz and record $2.2 billion free cash flow.","sources":[{"title":"Gold just hit $4,400 and the miners are finally catching up (24/7 Wall St., 2026-08-16)","url":"https://247wallst.com/investing/etf/2026/08/16/gold-just-hit-4400-and-the-miners-are-finally-catching-up/"}]},{"id":"en-2026-0401-epa-rfs-set2-final-rule","date":"2026-04-01","end_date":null,"sector":"energy","subindustries":["refining"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"EPA finalizes record 2026-27 RFS volumes with 70% SRE reallocation","summary":"EPA's final 'Set 2' Renewable Fuel Standard rule, published in the Federal Register on April 1, 2026 after being finalized in late March, set total obligations of 25.82 billion RINs for 2026 and 25.98 billion for 2027 (26.81 and 27.02 billion including SRE reallocation), the highest in program history, with biomass-based diesel at 9.07 and 9.20 billion RINs. It reallocated 70% of 2023-25 small-refinery exemption volumes onto obligated parties, deferred the half-RIN for imported feedstocks to 2028 and removed eRINs. Merchant refiners without blending (PBF, Delek, CVR, Par) face higher RIN costs while integrated marketers like Valero and Marathon are better hedged; AFPM petitioned the D.C. Circuit in June 2026.","evidence":"Final rule published in Federal Register 2026-04-01: 25.82B RINs (2026), 25.98B (2027), 70% SRE reallocation","sources":[{"title":"Beveridge & Diamond - EPA Finalizes Record-High 2026-2027 Renewable Fuel Standard Volume Obligations","url":"https://www.bdlaw.com/publications/epa-finalizes-record-high-2026-2027-renewable-fuel-standard-volume-obligations/"},{"title":"DieselNet - US EPA finalizes renewable fuels volumes for 2026-2027","url":"https://dieselnet.com/news/2026/04epa.php"},{"title":"Holland & Knight - EPA Boosts Biofuel Mandates in Final RFS Rule for 2026-2027","url":"https://www.hklaw.com/en/insights/publications/2026/04/epa-boosts-biofuel-mandates-in-final-renewable-fuel-standard-rule"}]},{"id":"hc-2026-pharma-s232-tariffs","date":"2026-04-02","end_date":"2026-09-29","sector":"healthcare","subindustries":["pharma","biotech_large"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Section 232 proclamation: 100% tariffs on patented drugs, with deal exemptions","summary":"A Section 232 proclamation imposed 100% tariffs on patented (Orange/Purple Book) drugs and their APIs, with 15% for the EU, Japan, Korea and Switzerland, 10% or less for the UK, 20% for companies with approved onshoring plans, and exemptions for companies that signed pricing/manufacturing agreements; duties start July 31 2026 for 17 named companies and September 29 for others, and generics are exempt for now. Because the February 2026 Supreme Court ruling voided IEEPA tariffs but not Section 232, this became the binding tariff regime for pharma; companies with deals (Lilly, J&J, Pfizer) are largely shielded, European and Japanese names less so.","evidence":"Proclamation of 2026-04-02: 100% on patented drugs/APIs, 15% for EU/Japan/Korea/Switzerland, effective 2026-07-31 (Annex III companies) and 2026-09-29 (others)","sources":[{"title":"White House: Adjusting imports of pharmaceuticals and pharmaceutical ingredients (April 2026)","url":"https://www.whitehouse.gov/presidential-actions/2026/04/adjusting-imports-of-pharmaceuticals-and-pharmaceutical-ingredients-into-the-united-states/"},{"title":"EY: Section 232 proclamation imposes up to 100% tariffs on patented pharmaceuticals","url":"https://taxnews.ey.com/news/2026-0787-us-section-232-proclamation-imposes-up-to-100-percent-tariffs-on-patented-pharmaceuticals-and-active-pharmaceutical-ingredients"},{"title":"Arnold & Porter: Trade winds shift for pharma","url":"https://www.arnoldporter.com/en/perspectives/advisories/2026/04/trade-winds-shift-for-pharma"}]},{"id":"materials-2026-section-232-metals-overhaul","date":"2026-04-02","end_date":"2026-04-06","sector":"materials","subindustries":["metals_mining","chemicals"],"direction":"mixed","magnitude":"moderate","driver_type":"policy","title":"Section 232 metals tariffs restructured on full value: 50% metal, 25% derivatives","summary":"A 2 April 2026 proclamation (effective 6 April) assessed steel, aluminum and copper tariffs on full customs value: 50% on articles made almost entirely of the metals, 25% on derivative products, 15% on certain industrial and grid equipment through 2027, 10% on goods made with US metal, and an exemption for products with 15% or less metal content. The change narrowed the tariff base after the Supreme Court ruling while preserving protection for domestic steel, aluminum and copper producers.","evidence":"Proclamation signed 2026-04-02: 50% on metal articles, 25% on derivatives, 15% on grid and industrial equipment through 2027, exemption below 15% metal content.","sources":[{"title":"White House fact sheet: strengthening tariffs on steel, aluminum and copper (April 2026)","url":"https://www.whitehouse.gov/fact-sheets/2026/04/fact-sheet-president-donald-j-trump-strengthens-tariffs-on-steel-aluminum-and-copper-imports/"},{"title":"Tariffs in the second Trump administration (Wikipedia)","url":"https://en.wikipedia.org/wiki/Tariffs_in_the_second_Trump_administration"}]},{"id":"hc-2026-ma-final-notice","date":"2026-04-06","end_date":null,"sector":"healthcare","subindustries":["managed_care"],"direction":"in","magnitude":"major","driver_type":"policy","title":"CMS finalises a 2.48% 2027 MA rate increase; insurers soar","summary":"The final 2027 Medicare Advantage notice raised average payments 2.48% (more than $13 billion), versus the 0.09% proposed in January. UnitedHealth jumped as much as 10-11% (its best intraday move since August), Humana 9-11%, and CVS and Elevance about 7%, recovering most of the January losses. UnitedHealth and Humana still announced exits from MA plans covering more than one million members for 2027, so the rally was about margin, not growth.","evidence":"Final 2027 MA rate +2.48% (>$13B) on 2026-04-06; UNH up as much as 10%, HUM up as much as 11%","sources":[{"title":"Bloomberg: Humana, UnitedHealth stocks soar as US raises Medicare Advantage rates","url":"https://www.bloomberg.com/news/articles/2026-04-06/medicare-finalizes-2-48-rate-hike-for-private-insurers-in-2027"},{"title":"TipRanks: UNH, HUM stocks soar after CMS finalizes 2027 MA rate hike","url":"https://www.tipranks.com/news/unitedhealth-unh-humana-hum-stocks-soar-after-cms-finalizes-2027-medicare-advantage-rate-hike"},{"title":"24/7 Wall St: UnitedHealth rockets 11%, Humana climbs 9%","url":"https://247wallst.com/investing/2026/04/07/unitedhealth-rockets-11-humana-climbs-9-as-medicare-advantage-rate-decision-crushes-regulatory-fears/"}]},{"id":"software-2026-managed-agents-selloff","date":"2026-04-08","end_date":"2026-04-13","sector":"technology","subindustries":["application_software","infrastructure_software_cyber"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"Claude Managed Agents hits infrastructure software: Akamai -17%, Cloudflare -14%","summary":"Anthropic's launch of Claude Managed Agents in public beta on 8 April 2026, a hosted stack with sandboxed execution, credentials and tracing, triggered a second AI selloff on 10 April focused on infrastructure and edge names: Akamai fell 16.6%, Cloudflare 13.5% and DigitalOcean 13.4%. The software ETF IGV bottomed around 13 April 2026, the low from which it rallied 41% into October.","evidence":"On 2026-04-10 Akamai -16.6%, Cloudflare -13.5%, DigitalOcean -13.4% after the 2026-04-08 Managed Agents launch.","sources":[{"title":"Anthropic just triggered another SaaS sell-off (24/7 Wall St., 2026-04-11)","url":"https://247wallst.com/investing/2026/04/11/anthropics-just-triggered-another-saas-sell-off-are-software-stocks-uninvestable/"},{"title":"Everyone declared software dead in April; this ETF is up 41% since (24/7 Wall St., 2026-10-13)","url":"https://247wallst.com/investing/2026/10/13/everyone-declared-software-dead-in-april-this-etf-is-up-41-since-then/"}]},{"id":"en-2026-0408-us-iran-ceasefire-oil-plunge","date":"2026-04-08","end_date":null,"sector":"energy","subindustries":["integrated","exploration_production","oilfield_services","refining"],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"Two-week US-Iran ceasefire: Brent -13%, WTI -16% in a day, energy sells off","summary":"On April 8, 2026 the US and Iran agreed a two-week ceasefire with safe passage through the Strait of Hormuz, roughly six weeks after the February 28 closure. Brent fell 13.3% to $94.75 and WTI 16.4% to $94.41 by late US trading, the sharpest one-day drop of the war, and shares of oil producers fell sharply while airlines and broad indices rallied; Shell and BP dropped in tandem with crude in London. The ceasefire proved fragile, with Iran stopping tankers again within days, but it marked the top of the first war-premium leg for the energy sector.","evidence":"Brent -13.3% to $94.75 and WTI -16.4% to $94.41 on 2026-04-08 (Gulf News/AFP)","sources":[{"title":"Gulf News - Oil prices plunge, stocks surge on US-Iran ceasefire","url":"https://gulfnews.com/business/energy/oil-prices-plunge-stocks-surge-on-us-iran-ceasefire-1.500499658"},{"title":"Hargreaves Lansdown - Iran ceasefire relief sends shares soaring and energy prices sharply down","url":"https://www.hl.co.uk/news/iran-ceasefire-relief-sends-shares-soaring-and-energy-prices-sharply-down"},{"title":"Euronews - Iran ceasefire pushes oil prices down as markets remain cautious","url":"https://euronews.com/2026/04/08/iran-ceasefire-pushes-oil-prices-down-as-markets-remain-cautious"}]},{"id":"software-2026-rebound","date":"2026-04-13","end_date":"2026-10-12","sector":"technology","subindustries":["application_software","infrastructure_software_cyber"],"direction":"in","magnitude":"major","driver_type":"positioning","title":"Software rebounds 41% from the April 'SaaS-pocalypse' low","summary":"IGV rose 41.46% from 13 April to 12 October 2026, closing at $111.31, as incumbents demonstrated AI upsell within existing contracts, takeover interest resurfaced (PayPal drew Stripe/Advent interest; Figma and others were targets) and vendors shifted toward consumption pricing; the ETF was nonetheless still down 0.68% over one year and up only 5.3% year-to-date, with QQQ +20.8% over the same six months. Analysts characterised the rally as multiple expansion rather than earnings acceleration, leaving it exposed to the October-November tech selloff.","evidence":"IGV +41.46% from 2026-04-13 to 2026-10-12 (close $111.31), but -0.68% over one year.","sources":[{"title":"Everyone declared software dead in April; this ETF is up 41% since (24/7 Wall St., 2026-10-13)","url":"https://247wallst.com/investing/2026/10/13/everyone-declared-software-dead-in-april-this-etf-is-up-41-since-then/"},{"title":"iShares Expanded Tech-Software Sector ETF (StockAnalysis)","url":"https://stockanalysis.com/etf/igv/"},{"title":"PayPal (Wikipedia)","url":"https://en.wikipedia.org/wiki/PayPal"}]},{"id":"lstools-2026-danaher-bioprocessing-orders","date":"2026-04-21","end_date":null,"sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Danaher's bioprocessing equipment orders rise 30%, the first growth in nearly two years","summary":"On April 21, 2026 Danaher reported Q1 revenue of about $6.0bn with core growth of just 0.5%, but said bioprocessing equipment orders rose more than 30% year over year, the first year-over-year increase in almost two years, and raised the top end of 2026 adjusted EPS guidance to $8.35-8.55 from $8.35-8.50 while keeping core growth at 3-6%. The order inflection was the data point the tools group had waited for since the post-COVID destocking began, and it preceded Thermo Fisher's 10% growth quarter in July.","evidence":"Q1 2026 bioprocessing equipment orders +30% y/y (first growth in ~2 years); 2026 adjusted EPS guide top end raised to $8.55.","sources":[{"title":"Danaher Q1 2026 earnings call: lifts 2026 EPS guidance on 30% bioprocessing orders surge (BigGo Finance)","url":"https://finance.biggo.com/news/US_DHR_2026-04-21"},{"title":"Thermo Fisher (TMO) vs Danaher (DHR): which life sciences stock looks better positioned? (Yahoo Finance)","url":"https://finance.yahoo.com/healthcare/articles/thermo-fisher-tmo-vs-danaher-000131616.html"}]},{"id":"ind-2026-ai-power-backlog-election-risk","date":"2026-04-22","end_date":"2026-11-03","sector":"industrials","subindustries":["electrical_equipment","building_products_construction"],"direction":"mixed","magnitude":"major","driver_type":"tech_cycle","title":"AI power trade year three: record backlogs, higher rates and data-center politics","summary":"GE Vernova's Q3 2026 orders hit $29.3bn (+96% organic) with backlog heading above $200bn and Eaton posted record $8.9bn sales (+28%), but the group traded sideways for much of 2026 as rates rose and local opposition to data centers became a midterm issue; the GRID ETF is flat and EMCOR slightly down year to date while GE Vernova is up 18-41% depending on the date. On November 3 Bernstein called election-day data-center fears overblown and GEV rose 7%, Eaton 6% and Vertiv 5%.","evidence":"GE Vernova Q3 2026 orders $29.3bn (+96% organic); GEV +7%, ETN +6%, VRT +5% on Nov 3, 2026; GRID ETF 0.0% YTD at Nov 5, 2026","sources":[{"title":"24/7 Wall St: GE Vernova rallies 7% as Bernstein calls election-day data center fears overblown","url":"https://247wallst.com/investing/2026/11/03/ge-vernova-rallies-7-as-bernstein-calls-election-day-data-center-fears-overblown-eaton-climbs-6-vertiv-gains-5/"},{"title":"GE Vernova Q3 2026 press release (8-K)","url":"https://www.sec.gov/Archives/edgar/data/0001996810/000199681026000162/gevpressrelease3q26.htm"},{"title":"ChartRow GRID calendar-year returns","url":"https://chartrow.com/quote/grid/returns"}]},{"id":"elec-2026-ge-vernova-q1-backlog-pull-forward","date":"2026-04-22","end_date":null,"sector":"industrials","subindustries":["electrical_equipment"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"GE Vernova jumps about 14% on 59% order growth and pulls its $200bn backlog target forward to 2027; Vertiv slips on 'only' a raise","summary":"On April 22, 2026 GE Vernova reported Q1 revenue of $9.3bn (+16%), orders of $10bn (+59% organic) and a $163bn backlog, raised 2026 guidance for revenue ($44.5-45.5bn), EBITDA margin and free cash flow, pulled its $200bn total-backlog target forward from 2028 to 2027 and said gas-turbine backlog and slot reservations would reach at least 110 GW by year-end; the stock rose nearly 14%. Vertiv the same day grew sales 30% to $2.65bn with a 20.8% adjusted margin and raised its 2026 net sales guide to $13.5-14.0bn, yet fell about 2.3-2.5% because its Q2 guide trailed the most bullish estimates after a 300% twelve-month run.","evidence":"GEV +~14% on 2026-04-22; Q1 orders $10bn (+59% organic), backlog $163bn, 2026 revenue guide $44.5-45.5bn; VRT -2.3% despite raising 2026 sales guide to $13.5-14.0bn.","sources":[{"title":"Vertiv, GE Vernova earnings: how AI data centers are bypassing America's grid (Yahoo Finance video)","url":"https://finance.yahoo.com/video/vertiv-ge-vernova-earnings-how-ai-data-centers-are-bypassing-americas-grid-135827662.html"},{"title":"Inside the AIPO ETF: what GE Vernova and Vertiv's Q1 earnings just revealed about the AI power trade (TipRanks)","url":"https://www.tipranks.com/news/inside-the-aipo-etf-what-ge-vernova-and-vertivs-q1-earnings-just-revealed-about-the-ai-power-trade"},{"title":"Vertiv Q1 2026 earnings release (SEC 8-K, 2026-04-22)","url":"https://www.sec.gov/Archives/edgar/data/0001674101/000162828026026379/q12026exhibit991vrt04222026.htm"}]},{"id":"meddev-2026-boston-scientific-q1-guidance-cut","date":"2026-04-22","end_date":null,"sector":"healthcare","subindustries":["medical_devices"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Boston Scientific cuts 2026 organic growth to 6.5-8% from 10-11% on electrophysiology competition; stock drops about 12% to a 52-week low","summary":"With Q1 2026 results on April 22, 2026 (sales $5.203bn, +9.4% organic, adjusted EPS $0.80), Boston Scientific slashed full-year organic growth guidance to 6.5-8% from 10-11%, citing competitive erosion in electrophysiology (Medtronic's pulsed-field ablation), slower stand-alone Watchman procedures and urology underperformance. Shares fell as much as 11-12% to a 52-week low. The cut broke the med-tech sector's highest-multiple growth story and anchored a 2026 in which devices became health care's laggard group, with BSX down more than 50% year to date by the autumn.","evidence":"2026 organic growth guide cut to 6.5-8% from 10-11% on 2026-04-22; BSX -11% to -12% intraday to a 52-week low.","sources":[{"title":"Boston Scientific Q1 2026 earnings release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0000885725/000088572526000031/q12026earningsrelease.htm"},{"title":"Boston Scientific cuts 2026 organic growth guidance, shares fall 12% (Rallies.ai)","url":"https://rallies.ai/news/boston-scientific-cuts-2026-organic-growth-guidance-shares-fall-12"},{"title":"BSX Q1 2026 earnings transcript (Motley Fool, 2026-04-22)","url":"https://www.fool.com/earnings/call-transcripts/2026/04/22/bsx-q1-2026-earnings-transcript/"}]},{"id":"autos-2026-tesla-q1-capex-shock","date":"2026-04-22","end_date":"2026-04-23","sector":"consumer_discretionary","subindustries":["autos"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Tesla beats on Q1 2026 but a $25bn-plus capex plan and near-zero auto profit send the stock down about 4%","summary":"Tesla reported Q1 2026 revenue of $22.39bn (+16%) and non-GAAP EPS of $0.41 (+52%) after the close on April 22, 2026, with margins at a five-quarter high but deliveries still falling (US sales -8.4%) and almost nothing earned on cars; the CFO guided 2026 capex to 'over $25 billion', up from $20bn, with free cash flow expected to be negative for the rest of the year. Shares fell about 3.6% to $373.60 on April 23. The reaction showed the robotaxi/AI narrative being asked to fund itself while the auto business stalled.","evidence":"Q1 2026 revenue $22.39bn, non-GAAP EPS $0.41; 2026 capex guide raised to >$25bn; TSLA -3.56% to $373.60 on 2026-04-23.","sources":[{"title":"Tesla stock dives on news that it earned next to nothing on cars in Q1, and plans to spend $25 billion in capex anyway (Fortune, 2026-04-23)","url":"https://fortune.com/2026/04/23/tesla-stock-price-earnings-call-outlook/"},{"title":"Tesla Q1 2026 earnings beat so why did the stock fall 3.56%? (TIKR)","url":"https://www.tikr.com/blog/tesla-q1-2026-earnings-beat-so-why-did-the-stock-fall-3-56"},{"title":"Tesla Q1 2026 update (SEC 8-K, 2026-04-22)","url":"https://www.sec.gov/Archives/edgar/data/0001318605/000162828026026551/tsla-20260422.htm"}]},{"id":"en-2026-0422-golden-pass-first-cargo","date":"2026-04-22","end_date":null,"sector":"energy","subindustries":["midstream"],"direction":"in","magnitude":"moderate","driver_type":"macro","title":"Golden Pass ships first LNG cargo as US feedgas hits record 18.8 Bcf/d","summary":"QatarEnergy (70%) and ExxonMobil (30%) announced on April 22, 2026 that Golden Pass LNG in Sabine Pass, Texas had shipped its first export cargo, about three weeks after Train 1's first production in late March, with Train 2 due in H2 2026 and Train 3 in H1 2027 toward 18 mtpa. US LNG feedgas hit a monthly record of 18.8 Bcf/d in April per LSEG, with Qatar's Ras Laffan still constrained by the Hormuz war, cementing the volume case for Gulf Coast gas pipelines (Kinder Morgan, Williams, Energy Transfer, Enbridge) and Cheniere. By October Golden Pass was shipping four cargoes a month and feedgas was tracking ~18.9 Bcf/d.","evidence":"First Golden Pass export cargo announced 2026-04-22; US LNG feedgas monthly record 18.8 Bcf/d in April 2026 (LSEG)","sources":[{"title":"Oil & Gas Journal - Golden Pass LNG ships first LNG export cargo","url":"https://www.ogj.com/pipelines-transportation/lng/news/55372854/golden-pass-lng-ships-first-lng-export-cargo"},{"title":"Euronews - QatarEnergy launches first LNG exports from $10bn Golden Pass project in Texas","url":"https://www.euronews.com/2026/04/23/qatarenergy-launches-first-lng-exports-from-10bn-golden-pass-project-in-texas"},{"title":"Natural Gas Intelligence - Henry Hub Price Volatility in 2026 Seen Rising With LNG Feed Gas Demand","url":"https://naturalgasintel.com/news/henry-hub-price-volatility-in-2026-seen-rising-with-lng-feed-gas-demand-the-offtake/"}]},{"id":"defense-2026-lockheed-q1-miss","date":"2026-04-23","end_date":null,"sector":"industrials","subindustries":["defense"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Lockheed misses on Q1 2026 as F-16 and C-130 problems drag Aeronautics; shares fall 3-5% from the war-rally high","summary":"Lockheed Martin's Q1 2026 sales of $18.0bn missed forecasts and EPS fell to $6.44 from $7.28 a year earlier (consensus about $6.73) as Aeronautics operating profit dropped 14% on F-16 and C-130 program issues and free cash flow swung to -$291m. Shares fell 4.8-6.3% premarket and closed down about 3-5% on April 23, 2026, extending a slide of roughly 25% from the March 2026 high reached during the Iran-war defense rally even though full-year guidance ($77.5-80.0bn sales, $29.35-30.25 EPS) was reaffirmed.","evidence":"Q1 2026 EPS $6.44 vs ~$6.73 consensus; FCF -$291m; LMT -3.1% close (up to -6.3% premarket) on 2026-04-23.","sources":[{"title":"Earnings call transcript: Lockheed Martin misses Q1 2026 EPS and revenue forecasts (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-lockheed-martin-misses-q1-2026-eps-and-revenue-forecasts-93CH-4632962"},{"title":"Why Lockheed Martin (LMT) shares are falling today (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/why-lockheed-martin-lmt-shares-114923507.html"},{"title":"Lockheed Martin has fallen nearly 25% from its 2026 high (TIKR)","url":"https://www.tikr.com/blog/lockheed-martin-has-fallen-nearly-25-from-its-2026-high-is-it-finally-time-to-buy"}]},{"id":"nuclear-2026-x-energy-ipo","date":"2026-04-24","end_date":"2026-07-31","sector":"nuclear","subindustries":[],"direction":"in","magnitude":"moderate","driver_type":"positioning","title":"X-energy's $1 billion IPO and Westinghouse's S-1: nuclear goes public","summary":"X-energy listed on Nasdaq on 24 April 2026 raising over $1 billion, the largest nuclear IPO on record, weeks after the NRC's first Category II fuel-facility licence for its TX-1 plant; Westinghouse confidentially filed for an IPO on 31 July 2026, and Oklo's Groves test reactor reached criticality on 5 August. The listings monetised the 2024-2025 re-rating and supplied the public market with pure-play SMR and large-reactor equity for the first time.","evidence":"X-energy Nasdaq IPO on 2026-04-24 raising more than $1 billion; Westinghouse draft S-1 submitted 2026-07-31.","sources":[{"title":"X-energy (Wikipedia)","url":"https://en.wikipedia.org/wiki/X-energy"},{"title":"Westinghouse Electric Company (Wikipedia)","url":"https://en.wikipedia.org/wiki/Westinghouse_Electric_Company"},{"title":"Oklo Inc. (Wikipedia)","url":"https://en.wikipedia.org/wiki/Oklo_Inc."}]},{"id":"semicap-2026-hua-hong-halt","date":"2026-04-28","end_date":null,"sector":"technology","subindustries":["semicap","semiconductors"],"direction":"out","magnitude":"moderate","driver_type":"geopolitical","title":"Commerce orders tool shipments to Hua Hong halted","summary":"On 28 April 2026 the Commerce Department ordered Applied Materials, Lam Research and KLA to halt certain tool shipments to Hua Hong, China's second-largest foundry, and its Huali subsidiary; the shares were already down 5-6% that day on an OpenAI-related report and came under further pressure. With Lam drawing roughly 35% of recent quarterly revenue from China, the order revived the China-exposure discount on equipment makers at the peak of their 2026 rally.","evidence":"Commerce halt order on Hua Hong tool shipments reported 2026-04-28; Lam Research about 35% of recent quarterly revenue from China.","sources":[{"title":"US orders chip equipment companies to stop shipments to China's second-largest chipmaker (InvestingLive, 2026-04-28)","url":"https://investinglive.com/stocks/us-orders-chip-equipment-companies-to-stop-shipments-to-chinas-second-largest-chipmaker-20260428/"}]},{"id":"autos-2026-gm-ford-ieepa-refunds","date":"2026-04-28","end_date":"2026-04-29","sector":"consumer_discretionary","subindustries":["autos"],"direction":"in","magnitude":"moderate","driver_type":"policy","title":"IEEPA tariff refunds flow to Detroit: GM and Ford each raise 2026 guidance by about $500m","summary":"On April 28, 2026 GM beat Q1 estimates and raised 2026 guidance, including a favorable adjustment of about $0.5bn from refunds of IEEPA tariffs struck down by the Supreme Court in February; shares closed up 1.3% at $78.95. Ford followed on April 29 with its own $500m guidance increase, which its CFO attributed to underlying performance with further refunds excluded, though the stock fell 1.3% and another 2% after hours to about $12. The refunds quantified the February ruling for autos, the sector most exposed to the Mexico/Canada/Japan/EU vehicle tariffs, while Section 232 auto tariffs remained in place.","evidence":"GM 2026 guidance raised incl. ~$0.5bn IEEPA tariff refund adjustment on 2026-04-28 (GM +1.3% to $78.95); Ford guidance +$500m on 2026-04-29.","sources":[{"title":"GM raises 2026 guidance amid $500 million tariff refund, topping Wall Street's earnings expectations (CNBC, 2026-04-28)","url":"https://www.cnbc.com/2026/04/28/general-motors-gm-earnings-q1-2026.html"},{"title":"Ford's guidance hike reflects more than tariff refund, CFO says (Detroit News, 2026-04-29)","url":"https://www.detroitnews.com/story/business/autos/ford/2026/04/29/ford-first-quarter-earnings-tariff-refund-trump-guidance-wall-street/89856352007/"},{"title":"GM raises 2026 outlook after tariff ruling (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/gm-raises-2026-outlook-tariff-160824281.html"}]},{"id":"en-2026-0428-uae-exits-opec","date":"2026-04-28","end_date":"2026-05-01","sector":"energy","subindustries":["exploration_production","integrated"],"direction":"mixed","magnitude":"moderate","driver_type":"geopolitical","title":"UAE announces exit from OPEC and OPEC+ effective May 1","summary":"On April 28, 2026 the UAE said it would leave OPEC and OPEC+ after almost 60 years, effective May 1, removing the holder of the group's second-largest spare capacity (targeting 5 mb/d by 2027). Oil futures barely reacted on the day because Hormuz disruption dominated pricing, with deferred contracts down 2-3% before recovering, but analysts at Rystad and Again Capital called the cartel 'structurally weaker' and longer-term bearish for crude once the strait reopens. OPEC+ trimmed its June hike to 188,000 b/d to account for the exit, and President Trump welcomed the move as likely to lower prices.","evidence":"UAE announced OPEC exit 2026-04-28, effective 2026-05-01 (CNBC)","sources":[{"title":"CNBC - UAE's shock OPEC exit: What it means for the oil cartel's future and for crude prices","url":"https://www.cnbc.com/2026/04/28/oil-uae-opec-saudi-arabia.html"},{"title":"Euronews - Oil prices rise despite UAE exit from OPEC as Iran war ceasefire hangs in balance","url":"https://www.euronews.com/2026/04/29/oil-prices-rise-despite-uae-exit-from-opec-as-iran-war-ceasefire-hangs-in-balance"},{"title":"CNBC - OPEC+ approves fourth oil output quota hike since Hormuz closure","url":"https://www.cnbc.com/2026/06/07/opec-set-for-fourth-oil-quota-hike-since-strait-of-hormuz-closure.html"}]},{"id":"hctech-2026-hims-q1-loss","date":"2026-05-11","end_date":"2026-05-12","sector":"healthcare","subindustries":["healthcare_technology"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Hims & Hers swings to a $92m loss as the weight-loss pivot crushes margins; stock falls 12-14%","summary":"Hims & Hers reported Q1 2026 revenue of $608.1m (+3.8%, vs $616.8m expected) and a net loss of $92.1m, or -$0.40 a share against a $0.04 profit expected, with gross margin down to 65% from 73% and adjusted EBITDA halved to $44.3m, as it pivoted its US weight-loss business away from compounded GLP-1s after the Novo breakup. Shares fell 12-14% to about $25 on May 12 even though 2026 revenue guidance was raised to $2.8-3.0bn; total liabilities had grown 431% to $1.82bn on about $1bn of converts, and the CEO had sold 436,000 shares before the print.","evidence":"Q1 2026 EPS -$0.40 vs +$0.04 consensus; revenue $608.1m vs $616.8m; HIMS -14.1% to $25.03 on 2026-05-12.","sources":[{"title":"Hims & Hers Health falls as Q1 results miss on both lines (Seeking Alpha)","url":"https://seekingalpha.com/news/4590895-hims-and-hers-health-falls-q1-results-miss-both-lines"},{"title":"Why Hims & Hers Health stock just crashed (Motley Fool, 2026-05-12)","url":"https://www.fool.com/investing/2026/05/12/why-hims-hers-health-stock-just-crashed/"},{"title":"Hims & Hers shares plummet on first quarter earnings miss (Proactive)","url":"https://www.proactiveinvestors.com/companies/news/1092145/hims-hers-shares-plummet-on-first-quarter-earnings-miss-1092145.html"}]},{"id":"materials-2026-equinox-orla-consolidation","date":"2026-05-13","end_date":null,"sector":"materials","subindustries":["gold_miners"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"Equinox Gold buys Orla Mining for $5.1bn as gold M&A wave builds","summary":"Equinox Gold agreed on 2026-05-13 to acquire Orla Mining in a $5.1bn all-stock deal (one Equinox share per Orla share), creating a 1.1Moz/yr North American producer backed by Pierre Lassonde and Fairfax, with about $1.4bn of projected 2026 free cash flow. It followed Coeur's ~$7bn all-stock takeover of New Gold (announced 2025-11-03, closed 2026-03-20) and Agnico Eagle's roughly $2.1bn purchase of Rupert Resources in April 2026, taking 2026 gold M&A past $7.9bn and underscoring record-price cash flows being recycled into consolidation.","evidence":"Equinox-Orla deal value $5.1bn announced 2026-05-13","sources":[{"title":"Kitco: Equinox Gold acquires Orla Mining in $5.1 billion consolidation, backed by Pierre Lassonde","url":"https://www.kitco.com/news/article/2026-05-13/equinox-gold-acquires-orla-mining-51-billion-consolidation-backed-pierre"},{"title":"The Oregon Group: Gold mining M&A is back","url":"https://theoregongroup.com/commodities/gold/gold-mining-ma-is-back/"},{"title":"Startup Fortune: Coeur Mining's $7 billion gold megadeal","url":"https://startupfortune.com/coeur-minings-7-billion-gold-megadeal-is-already-missing-its-own-targets/"}]},{"id":"utilities-2026-nextera-dominion-67bn","date":"2026-05-18","end_date":null,"sector":"utilities","subindustries":["regulated_utilities"],"direction":"mixed","magnitude":"major","driver_type":"ma","title":"NextEra agrees to buy Dominion for $67bn, largest utility deal this century","summary":"NextEra Energy announced an all-stock acquisition of Dominion Energy on 2026-05-18 at 0.8138 NEE shares per D share, valuing Dominion at about $67bn (a 23% premium to its May 15 market cap) and creating the world's largest regulated electric utility with a ~130 GW large-load pipeline and $59bn of annual capex. NEE fell almost 5% on concerns it was overpaying while Dominion rose 9%; the deal, which includes $2.25bn of customer bill credits and needs five regulatory approvals, kicked off an AI-era wave of utility mega-merger speculation across the group.","evidence":"NEE -5% and D +9% on 2026-05-18; exchange ratio 0.8138","sources":[{"title":"Fortune: NextEra's $67 billion Dominion takeover creates world's largest utility","url":"https://fortune.com/2026/05/18/nextera-dominion-67-billion-acquisition-ai-data-centers-largest-utility/"},{"title":"NextEra Energy press release: NextEra Energy and Dominion Energy to combine","url":"https://www.investor.nexteraenergy.com/news-and-events/news-releases/2026/05-18-2026-123054903"},{"title":"Bloomberg: NextEra to buy Dominion for $67 billion to form power giant","url":"https://www.bloomberg.com/news/articles/2026-05-18/nextera-to-buy-dominion-for-67-billion-to-form-utility-colossus"}]},{"id":"specialty-retail-2026-tjx-q1-raise","date":"2026-05-20","end_date":null,"sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"TJX posts 6% comps and raises its fiscal 2027 outlook as off-price takes share from tariff-hit full-price retail","summary":"TJX reported fiscal Q1 2027 (quarter to early May 2026) comparable sales up 6% and diluted EPS of $1.19 on May 20, 2026 and raised its full-year outlook, confirming that the trade-down and the flood of excess inventory from tariff-disrupted brands were accruing to off-price. Ross Stores followed a day later with 17% comps. The pair's results set up the year's clearest specialty-retail divergence: off-price and auto parts compounding while mall apparel and department stores fell.","evidence":"TJX fiscal Q1 2027 comparable sales +6%, diluted EPS $1.19, full-year FY27 outlook raised (release 2026-05-20).","sources":[{"title":"TJX Q1 fiscal 2027 earnings press release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0000109198/000010919826000023/tjxq1fy27earningspressrele.htm"},{"title":"TJX (TJX) Q1 earnings and revenues surpass estimates (Yahoo Finance / Zacks)","url":"https://finance.yahoo.com/markets/stocks/articles/tjx-tjx-q1-earnings-revenues-124002275.html"},{"title":"TJX Companies: the retail stock that actually benefits from tariffs and inflation (Motley Fool, 2026-01-15)","url":"https://www.fool.com/investing/2026/01/15/tjx-the-retail-stock-that-benefits-from-tariffs/"}]},{"id":"specialty-retail-2026-ross-record-comps","date":"2026-05-21","end_date":null,"sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Ross Stores' comps jump 17%, EPS beats guidance by 25% and the full-year comp outlook doubles","summary":"On May 21, 2026 Ross Stores reported fiscal Q1 comparable-store sales up 17% (flat a year earlier), total sales up 21% to $6.01bn and EPS of $2.02 (+37%) against guidance of $1.60-1.67 and a $1.73 consensus, and raised its fiscal 2026 comp outlook to 6-7% from 3-4% and EPS to $7.50-7.74; shares rose about 6% after hours. Tax refunds, BNPL and tariff-driven excess inventory from full-price retailers combined into the strongest off-price quarter on record, and Ross raised again in August ($8.61-8.77) even as the stock dipped 2.4% on that print.","evidence":"Fiscal Q1 2026 comparable sales +17%, EPS $2.02 vs $1.60-1.67 guidance; ROST +~6% after hours on 2026-05-21; FY26 comp guide raised to 6-7%.","sources":[{"title":"Ross Stores reports robust first quarter sales and earnings results, significantly exceeding guidance (Ross IR)","url":"https://investors.rossstores.com/news-releases/news-release-details/ross-stores-reports-robust-first-quarter-sales-and-earnings"},{"title":"Ross Stores Q1 2026 earnings beat guidance, stock rises (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/ross-stores-q1-2026-earnings-120825086.html"},{"title":"Earnings call transcript: Ross Stores tops Q2 2026 estimates, shares jump after hours (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-ross-stores-tops-q2-2026-estimates-shares-jump-after-hours-93CH-4870582"}]},{"id":"en-2026-0615-hormuz-reopening-mou","date":"2026-06-15","end_date":"2026-07-08","sector":"energy","subindustries":["integrated","refining","exploration_production"],"direction":"out","magnitude":"major","driver_type":"geopolitical","title":"US-Iran MoU to reopen Hormuz: WTI under $80, Exxon -4%, Marathon -5%","summary":"Late on June 14, 2026 the US and Iran announced a memorandum of understanding to reopen the Strait of Hormuz after more than 100 days of closure, with a 60-day ceasefire allowing Iranian exports to resume pending a signing in Switzerland. WTI fell about 5% to below $80, its lowest since March (Brent -3.95% to $83.88 in early Asian trade), and energy stocks followed: ExxonMobil fell roughly 4.1%, Chevron 3.6%, Valero 3.7% and Marathon Petroleum about 5%. Brent was back near its pre-war $72 by July 3 even though Trump declared the MoU 'over' on July 8 after Iran struck ships in the strait.","evidence":"WTI below $80/bbl (lowest since March) in the first session after the 2026-06-14 announcement; Brent $83.88 (-3.95%) early 2026-06-15","sources":[{"title":"Oilprice.com - Oil Prices Plunge as U.S. and Iran Reach Deal to Reopen Strait of Hormuz","url":"https://oilprice.com/Latest-Energy-News/World-News/Oil-Prices-Plunge-as-US-and-Iran-Reach-Deal-to-Reopen-Strait-of-Hormuz.html"},{"title":"MarketWise - US-Iran Strait of Hormuz Deal: What It Means for Oil Stocks","url":"https://marketwise.com/investing/us-iran-deal-strait-of-hormuz-oil-stocks/"},{"title":"Sherwood News - Energy stocks follow oil lower as Strait of Hormuz set to reopen","url":"https://sherwood.news/markets/energy-stocks-follow-oil-lower-as-strait-of-hormuz-set-to-reopen/"},{"title":"CNBC - OPEC+ approves further oil output increase as Hormuz exports start to recover","url":"https://www.cnbc.com/2026/07/05/opec-set-to-approve-another-oil-output-increase.html"}]},{"id":"it-services-2026-accenture-record-drop","date":"2026-06-18","end_date":null,"sector":"technology","subindustries":["it_services"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Accenture's worst day on record: -18% on guidance cut and AI fears","summary":"Accenture reported fiscal Q3 2026 revenue of $18.7 billion (+6%, slightly below consensus), cut full-year growth guidance to 3-4% from 3-5%, disclosed a 2% fall in bookings and about $100 million of Middle East war revenue loss; the stock fell about 18% on 18 June 2026, its worst day ever, with Cognizant -10% to a 52-week low, EPAM -9% (down two-thirds from its January high and dropped from the S&P 500), Capgemini -8.4% and IBM -5%. Investors priced AI coding and agent tools as a structural threat to billable-hour models, leaving Accenture at about 10x earnings.","evidence":"Accenture -18% on 2026-06-18 (record one-day drop); FY2026 local-currency growth guidance cut to 3-4% from 3-5%; bookings -2%.","sources":[{"title":"Wall Street just sold off these IT-services stocks on AI fears (Motley Fool, 2026-06-21)","url":"https://www.fool.com/investing/2026/06/21/wall-street-just-sold-off-these-it-services-stocks/"},{"title":"IT services stocks fall after Accenture cuts guidance, Capgemini drops 8% (Investing.com, 2026-06-18)","url":"https://www.investing.com/news/stock-market-news/it-services-stocks-fall-after-accenture-cuts-guidance-capgemini-drops-8-4749447"},{"title":"Lowering moat ratings for IT services firms due to AI's disruption (Morningstar)","url":"https://www.morningstar.com/stocks/lowering-moat-ratings-it-services-firms-due-ais-disruption-knowledge-based-work"}]},{"id":"apple-2026-price-hikes-5t","date":"2026-06-25","end_date":"2026-07-28","sector":"technology","subindustries":["apple","hardware"],"direction":"mixed","magnitude":"moderate","driver_type":"tech_cycle","title":"Apple raises prices on memory costs (-6%), then becomes a $5 trillion company","summary":"Apple raised prices on several products on 25 June 2026 as memory costs surged and its shares fell more than 6% that day; a month later, on 28 July 2026, Apple became the second company to reach a $5 trillion market capitalisation, helped by the tariff relief after the Supreme Court ruling and the Broadcom partnership extension to 2031. Apple ended Q3 2026 as the second-largest company at about $4.86 trillion behind Nvidia.","evidence":"Apple shares fell more than 6% on 2026-06-25 after price increases; first $5 trillion close on 2026-07-28.","sources":[{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"},{"title":"Broadcom (Wikipedia)","url":"https://en.wikipedia.org/wiki/Broadcom"}]},{"id":"re-2026-0625-nyc-rgb-two-year-rent-freeze","date":"2026-06-25","end_date":null,"sector":"real_estate","subindustries":["residential_reits"],"direction":"out","magnitude":"moderate","driver_type":"regulatory","title":"NYC Rent Guidelines Board approves first-ever two-year rent freeze","summary":"On June 25, 2026 New York City's Rent Guidelines Board voted 7-1 to set 0% increases on both one- and two-year leases for roughly 1 million rent-stabilized apartments (leases starting Oct 1, 2026 through Sep 30, 2027), the first two-year freeze in the board's history and the fulfilment of Mayor Zohran Mamdani's campaign pledge; the landlord-side member resigned the morning of the vote and owner groups signalled litigation. The vote is the highest-profile rent-control action of the cycle and a negative read-across for coastal apartment landlords with New York exposure (AVB, EQR, UDR) and for regulatory risk across residential REITs generally.","evidence":"RGB vote on 2026-06-25: 0% for one-year and two-year leases on ~1 million rent-stabilized units, 7-1 tally.","sources":[{"title":"Rent Guidelines Board freezes rents, marking win for Mamdani (NY1, Jun 25 2026)","url":"https://ny1.com/nyc/all-boroughs/news/2026/06/25/nyc-rent-guidelines-board-final-vote"},{"title":"Mamdani's Promised Rent Freeze Approved in New York (TIME, Jun 26 2026)","url":"https://time.com/article/2026/06/26/new-york-rent-freeze-stabilized-apartments-zohran-mamdani-housing-promise/"},{"title":"NYC Rent Guidelines Board votes to freeze rent on 1 million apartments (Reason, Jun 26 2026)","url":"https://reason.com/2026/06/26/mamdani-got-his-rent-freeze-wish-dont-expect-new-york-city-housing-to-become-more-affordable/"}]},{"id":"telecom-2026-dish-chapter-11","date":"2026-06-29","end_date":"2026-08-02","sector":"technology","subindustries":["telecom"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Dish DBS, Sling and Boost file for Chapter 11; Hughes follows","summary":"EchoStar said on 29 June 2026 that Dish DBS, Sling TV and Boost Mobile would file for Chapter 11 by 30 June, citing debt, subscriber losses and spectrum obligations, and Hughes Network Systems filed on 2 August 2026 after a debt maturity; the $23 billion AT&T spectrum sale closed on 28 July. The bankruptcies closed out the satellite pay-TV era and confirmed the three-carrier structure in US wireless.","evidence":"EchoStar announced the Dish DBS/Sling/Boost Chapter 11 filing on 2026-06-29; AT&T spectrum purchase completed 2026-07-28.","sources":[{"title":"EchoStar (Wikipedia)","url":"https://en.wikipedia.org/wiki/EchoStar"}]},{"id":"semis-2026-july-reversal","date":"2026-07-01","end_date":"2026-08-24","sector":"technology","subindustries":["semiconductors","memory","semicap","hardware"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Semis reverse: Micron -11%, SOX falls as much as 29% from its June peak","summary":"On 1 July 2026 a report that Meta might rent out excess compute raised fears that AI processing supply was catching up with demand: Micron fell 11% (about $138 billion), Intel 9%, AMD 7%, SMH more than 5%, and Lam, KLA and Applied Materials at least 10%, while Meta rose 9%. Broadcom's AI-revenue guidance of about $16 billion versus $17.2 billion expected, Brent above $84 on Hormuz tensions and reports of a Chinese DUV lithography tool and CXMT's oversubscribed listing extended the drawdown to as much as 29% before a double-digit rebound in early August.","evidence":"Micron -11% (about $138 billion) on 2026-07-01; Philadelphia semiconductor index down as much as 29% from its June 2026 peak.","sources":[{"title":"Chip stocks that notched record rallies in Q2 start Q3 with a dud (CNBC, 2026-07-01)","url":"https://www.cnbc.com/2026/07/01/chip-stocks-notched-record-rallies-in-second-quarter-start-q3-with-dud.html"},{"title":"The 2026 semiconductor selloff creates an opportunity (Leverage Shares, 2026-08-24)","url":"https://leverageshares.com/en-eu/insights/the-2026-semiconductor-selloff-creates-an-opportunity/"}]},{"id":"utilities-2026-data-center-backlash","date":"2026-07-14","end_date":"2026-08-27","sector":"utilities","subindustries":["regulated_utilities"],"direction":"out","magnitude":"major","driver_type":"regulatory","title":"Data-center backlash: New York's one-year moratorium and a wave of state restrictions","summary":"Governor Hochul's 14 July 2026 executive order suspended permits for data centers of 50 MW or more for a year; Chicago's mayor called for a moratorium on 11 August, Pennsylvania imposed GRID requirements on 18 August and New Jersey mandated water and power reporting on 27 August, with at least 47 large projects delayed or denied in 2026 and Gallup finding 71% of Americans opposed to local data centers. Rising electricity bills turned the AI-power trade political: utilities were up only 3.5% year-to-date by 5 November 2026 and Goldman estimated moratoria could affect 45% of planned US capacity after the midterms.","evidence":"New York executive order of 2026-07-14 suspending large data-center construction for one year; XLU +3.5% year-to-date as of 2026-11-05.","sources":[{"title":"AI credit fears deepen as data centers face nationwide backlash (Seoul Economic Daily, 2026-10-21)","url":"https://en.sedaily.com/international/2026/10/21/ai-credit-fears-deepen-as-data-centers-face-nationwide"},{"title":"CoreWeave bond yield tops 16% as AI credit stress rises (CNBC, 2026-11-06)","url":"https://www.cnbc.com/2026/11/06/coreweave-bond-yield-tops-16percent-as-ai-credit-stress-rises.html"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"}]},{"id":"facilities-2026-hca-exchange-coverage-cut","date":"2026-07-14","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"out","magnitude":"major","driver_type":"policy","title":"HCA pre-announces a 2026 guidance cut as ACA exchange losses turn patients uninsured one-for-one; hospitals sell off","summary":"On July 14, 2026 HCA previewed Q2 results and cut 2026 guidance (EPS to $28.70-30.50 from $29.10-31.50; adjusted EBITDA to $15.4-16.1bn from $15.55-16.45bn), saying a payer-mix shift cost about $400m of pre-tax income in the quarter: patients losing exchange coverage after the enhanced subsidies expired were becoming uninsured roughly one-for-one rather than the 80-85% assumed, lifting the full-year exchange headwind to $1.0-1.2bn from $600-900m. Shares fell about 7% (nearly 10% premarket) and dragged Tenet, Universal Health and Community Health lower; Yahoo tallied a 14% decline over the following days. When HCA printed the full quarter on July 24 the stock rose 3.6%.","evidence":"HCA 2026 EPS guide cut to $28.70-30.50 from $29.10-31.50 on 2026-07-14; $400m Q2 payer-mix hit; HCA -6.7% to -10% on the day.","sources":[{"title":"HCA Healthcare previews second quarter 2026 results (HCA IR)","url":"https://investor.hcahealthcare.com/news/news-details/2026/HCA-Healthcare-Previews-Second-Quarter-2026-Results/default.aspx"},{"title":"HCA cuts 2026 earnings forecast on insurance coverage losses (Healthcare Dive)","url":"https://www.healthcaredive.com/news/hca-cuts-2026-earnings-ACA-coverage-losses/825147/"},{"title":"HCA stock falls on uninsured warning despite earnings beat (TheStreet)","url":"https://www.thestreet.com/investing/stocks/hca-healthcare-stock-earnings-coverage-loss-guidance-cut"}]},{"id":"financials-2026-progressive-june-growth-slowdown","date":"2026-07-15","end_date":null,"sector":"financials","subindustries":["insurance"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Progressive drops ~9% as June results show slowing growth and pricing pressure","summary":"Progressive's June and Q2 2026 release on 2026-07-15 showed Q2 EPS of $5.67 (above the $5.30 estimate) but net premiums written of $21.08bn missed, June premium growth slowed to 3%, and the combined ratio of 87.3% was worse than last year's 86.2%. The stock fell about 9% on the day as investors read the numbers as the end of the auto-insurance margin peak, with Reuters citing weaker pricing and renewed competition from GEICO; the drop reverberated across personal-lines peers.","evidence":"PGR about -9% on 2026-07-15; June net premiums written +3%","sources":[{"title":"Yahoo Finance / Motley Fool: Why Progressive Insurance fell today","url":"https://finance.yahoo.com/markets/stocks/articles/why-progressive-insurance-fell-today-195901091.html"},{"title":"The Insurer (Reuters): Progressive shares fall 9% as June results signal slowing growth, pricing pressure","url":"https://www.theinsurer.com/ti/news/progressive-shares-fall-9-as-june-results-signal-slowing-growth-pricing-pressure-2026-07-16/"}]},{"id":"re-2026-0716-prologis-q2-2026-record-leasing","date":"2026-07-16","end_date":null,"sector":"real_estate","subindustries":["industrial_logistics_reits"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Prologis Q2 2026: record 67M sq ft leased, second guidance raise of the year, shares +3.2%","summary":"On July 16, 2026 Prologis reported Q2 Core FFO of $1.63 per share (vs $1.46 a year earlier), a record 67 million sq ft of leases signed and owned-and-managed occupancy of 95.5% (+20 bp q/q). It raised 2026 Core FFO guidance to $6.22-$6.30 from $6.07-$6.23 and net-earnings guidance to $4.40-$4.55 from $3.80-$4.05, its second raise of 2026. Quiver Quantitative reported PLD shares up 3.2% on the day.","evidence":"PLD +3.2% on 2026-07-16; 2026 Core FFO guidance raised to $6.22-$6.30 from $6.07-$6.23.","sources":[{"title":"Prologis Reports Second Quarter 2026 Results","url":"https://ir.prologis.com/news-events/press-releases/detail/1044/prologis-reports-second-quarter-2026-results"},{"title":"Quiver Quantitative: Prologis Shares Rise After Q2 Results and Higher 2026 Outlook","url":"https://www.quiverquant.com/news/Prologis+Shares+Rise+After+Q2+Results+and+Higher+2026+Outlook"}]},{"id":"hyperscalers-2026-alphabet-capex-shock","date":"2026-07-22","end_date":"2026-07-23","sector":"hyperscalers","subindustries":["internet_platforms","infrastructure_software_cyber"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Alphabet falls 7% as 2026 capex rises to $205 billion and cash flow turns negative","summary":"Alphabet's Q2 2026 report on 22 July raised the top of its 2026 capex range to $205 billion and showed Google Cloud growing 82%, but the company turned cash-flow negative for the first time and its long-term debt had risen 111% to $98 billion in six months; the shares fell 7% on 23 July and Amazon, Meta and Microsoft fell in sympathy ahead of their own reports (Microsoft guiding about $190 billion including finance leases, Amazon about $200-207 billion, Meta up to $145 billion). 'AI fatigue' and debt-funded build-outs became the market's framing for the rest of 2026.","evidence":"Alphabet -7% on 2026-07-23 after lifting 2026 capex guidance to $205 billion; long-term debt +111% to $98 billion in H1 2026.","sources":[{"title":"Amazon, Meta and Microsoft face skeptical investors after Google report sparked sell-off (CNBC, 2026-07-28)","url":"https://www.cnbc.com/2026/07/28/hyperscalers-face-higher-capex-scrutiny-after-alphabet-report-panned.html"}]},{"id":"defense-2026-lockheed-rtx-q2-record-backlogs","date":"2026-07-23","end_date":null,"sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Lockheed rockets 10% and RTX 7% on beat-and-raise quarters; a $35bn THAAD award lifts Lockheed's backlog to $230bn","summary":"Lockheed Martin reported Q2 2026 sales of $20.1bn (vs $19.37bn expected) and EPS of $7.94 (vs $7.23) on July 23, 2026, with $65bn of new orders including a $35bn multi-year Missile Defense Agency THAAD contract taking backlog to a record $230bn; it raised full-year guidance and the stock rose about 10% to $567.71. RTX, which had also beaten and raised its 2026 EPS outlook to $7.65-7.75 on rearmament demand, gained 7% to $208.48. The quarter marked the turn from the spring drawdown as the Iran-war supplemental and European rearmament converted into booked orders.","evidence":"LMT +10% to $567.71 and RTX +7% to $208.48 around 2026-07-23; LMT Q2 EPS $7.94 vs $7.23 consensus; backlog $230bn incl. $35bn THAAD award.","sources":[{"title":"Lockheed Martin rockets 10%, RTX jumps 7% on beat-and-raise quarters and record backlogs (24/7 Wall St., 2026-07-23)","url":"https://247wallst.com/investing/2026/07/23/lockheed-martin-rockets-10-rtx-jumps-7-on-beat-and-raise-quarters-and-record-backlogs/"},{"title":"Lockheed Martin reports second quarter 2026 financial results (Lockheed Martin IR)","url":"https://investors.lockheedmartin.com/news-releases/news-release-details/lockheed-martin-reports-second-quarter-2026-financial-results/"},{"title":"RTX and Northrop Grumman raise 2026 profit outlooks on military rearmament demand (Yahoo Finance)","url":"https://finance.yahoo.com/markets/article/rtx-and-northrop-grumman-raise-2026-profit-outlooks-on-military-rearmament-demand-170122722.html"}]},{"id":"lstools-2026-thermo-fisher-q2-surge","date":"2026-07-23","end_date":null,"sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Thermo Fisher jumps about 9% as pharma spending lifts growth to 10% and 2026 guidance rises","summary":"Thermo Fisher reported Q2 2026 revenue of $11.99bn (+10%, 5% organic) and adjusted EPS of $6.03 against a $5.71 consensus on July 23, 2026, and raised 2026 guidance to $47.4-48.1bn of revenue and $24.93-25.33 of adjusted EPS (9-11% growth). Shares rose about 9% premarket and closed up 8.7% at $572.32, the largest earnings-day move for the tools bellwether in years, confirming the bioprocessing and pharma-services recovery flagged by Danaher's April order inflection.","evidence":"TMO +8.71% to $572.32 on 2026-07-23; Q2 adjusted EPS $6.03 vs $5.71 consensus; 2026 adjusted EPS guide $24.93-25.33.","sources":[{"title":"Thermo Fisher Scientific reports second quarter 2026 results (Nasdaq, 2026-07-23)","url":"https://www.nasdaq.com/press-release/thermo-fisher-scientific-reports-second-quarter-2026-results-2026-07-23"},{"title":"Thermo Fisher raises 2026 outlook after 10% growth in Q2 (Medical Device Network)","url":"https://www.medicaldevice-network.com/news/thermo-fisher-raises-2026-outlook-after-10-growth-in-q2/"},{"title":"Earnings call transcript: Thermo Fisher tops Q2 2026 estimates and lifts outlook (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-thermo-fisher-tops-q2-2026-estimates-and-lifts-outlook-93CH-4809188"}]},{"id":"facilities-2026-tenet-q2-blowout","date":"2026-07-23","end_date":"2026-07-24","sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Tenet's ambulatory-led Q2 beat by 44% and $2bn buyback send the stock up about 15%","summary":"Tenet Healthcare reported Q2 2026 adjusted EPS of $6.12 against a $4.26 consensus on revenue of $5.63bn ($5.43bn expected) after the close on July 23, 2026, raised its 2026 adjusted EBITDA outlook to $4.83-5.03bn and added $2.0bn to its buyback authorization. Shares jumped 14.6% premarket on July 24. Nine days after HCA's exchange-driven guidance cut, Tenet's USPI surgery-center mix showed the provider group was splitting between acute-care operators exposed to uninsured volumes and ambulatory platforms that were not.","evidence":"Tenet Q2 2026 adjusted EPS $6.12 vs $4.26 consensus; THC +14.6% premarket on 2026-07-24; 2026 adjusted EBITDA guide $4.83-5.03bn.","sources":[{"title":"Tenet reports strong second quarter 2026 results; raises 2026 financial outlook (Tenet IR)","url":"https://investor.tenethealth.com/press-releases/press-release-details/2026/Tenet-Reports-Strong-Second-Quarter-2026-Results-Raises-2026-Financial-Outlook/default.aspx"},{"title":"Tenet Healthcare shares jump after second-quarter earnings and guidance top forecasts (Yahoo Finance)","url":"https://finance.yahoo.com/healthcare/articles/tenet-healthcare-shares-jump-second-103508861.html"},{"title":"Tenet Healthcare tops Q2 earnings estimates, raises 2026 outlook (Yahoo Finance)","url":"https://finance.yahoo.com/healthcare/articles/tenet-healthcare-tops-q2-earnings-191100509.html"}]},{"id":"aero-2026-boeing-q2-cash-flow-positive","date":"2026-07-28","end_date":null,"sector":"industrials","subindustries":["commercial_aerospace"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Boeing turns free cash flow positive on 171 deliveries; stock rises 4% despite a VC-25B charge","summary":"Boeing's Q2 2026 revenue rose 8% to $24.6bn on 171 commercial deliveries and free cash flow was +$631m versus -$200m a year earlier, while a $280m charge on the VC-25B (Air Force One) program pushed the core loss to $0.76 a share against a $0.34 loss expected. Shares closed up about 4% at $219.92 on July 28, 2026 as investors focused on the record $715bn backlog, the start of the 737 transition to 47 a month and the low-rate start of the North Line in July. The full-year free cash flow outlook was held at $1-3bn.","evidence":"BA +3.98% to $219.92 on 2026-07-28; Q2 FCF +$631m; 171 deliveries; core loss $0.76/share incl. $280m VC-25B charge.","sources":[{"title":"Earnings call transcript: Boeing Q2 2026 revenue beats as loss widens (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-boeing-q2-2026-revenue-beats-as-loss-widens-93CH-4817578"},{"title":"Boeing stock rises 2% as cash flow turns positive (ScanX)","url":"https://scanx.trade/stock-market-news/companies/boeing-q2-results-revenue-rises-8-to-24-56b-cash-flow-turns-positive/46797369"},{"title":"Boeing Q2 earnings: $24.6B revenue, $0.67 loss/share (StockTitan)","url":"https://www.stocktitan.net/news/BA/boeing-reports-second-quarter-iajg461ldaeq.html"}]},{"id":"transport-2026-ups-q2-amazon-glide-down","date":"2026-07-28","end_date":null,"sector":"industrials","subindustries":["transportation"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"UPS falls about 6% as the Amazon volume glide-down and flat Q3 domestic revenue overshadow a beat-and-raise","summary":"UPS beat Q2 2026 estimates (adjusted EPS $1.76; GAAP $0.71 after transformation charges) and raised its full-year outlook on July 28, 2026, but guided to flat US domestic revenue in Q3 and a mid-single-digit decline in domestic average daily volume as the planned Amazon glide-down took hold; Q2 ADV was down 3.3% and revenue fell 2.7%. Shares closed down roughly 6% after surging premarket. Amazon had been more than 13% of UPS revenue at the peak and 8.8% by the end of Q1; Bank of America later cut its target saying Amazon volumes fell faster than expected.","evidence":"UPS closed down ~6% on 2026-07-28 (CNBC); Q2 2026 average daily volume -3.3%, revenue -2.7%, Q3 domestic revenue guided flat.","sources":[{"title":"UPS expects third-quarter domestic revenue to be flat (CNBC, 2026-07-28)","url":"https://www.cnbc.com/2026/07/28/ups-ups-q2-2026-earnings.html"},{"title":"Earnings call transcript: UPS beats Q2 2026 estimates but shares fall (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-ups-beats-q2-2026-estimates-but-shares-fall-93CH-4817084"},{"title":"UPS Q2 revenue falls 2.7% amid economic uncertainty, Amazon volume glide down takes hold (Logistics Management)","url":"https://www.logisticsmgmt.com/article/ups_q2_revenue_falls_2.7_amid_economic_uncertainty_amazon_volume_glide_down_takes_hold"}]},{"id":"hctech-2026-tempus-first-profit-personalis","date":"2026-07-30","end_date":null,"sector":"healthcare","subindustries":["healthcare_technology"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Tempus AI posts its first GAAP profit and raises guidance after agreeing to buy the rest of Personalis","summary":"On July 30, 2026 Tempus AI reported Q2 revenue of $382.5m (+22%), oncology volume +31%, data-licensing revenue +36% and net income of $5.6m, its first quarterly GAAP profit, and raised 2026 revenue guidance to $1.595-1.605bn; the stock rose 6.6% to $44.28 in the session near the low end of its 52-week range before giving back about 3% after hours on dilution worries over the July 20 agreement to buy the Personalis shares it did not own at $16.25 a share (about $1.5bn net). The print started a rerating that took TEM above $70 by November.","evidence":"Q2 2026 revenue $382.5m (+22%), net income $5.6m (first GAAP profit); TEM +6.57% to $44.28 on 2026-07-30; 2026 revenue guide $1.595-1.605bn.","sources":[{"title":"Tempus reports second quarter 2026 results (Tempus IR, 2026-07-30)","url":"https://investors.tempus.com/files/doc_news/2026/07/Tempus-Reports-Second-Quarter-2026-Results.pdf"},{"title":"Tempus Q2 2026 slides: first profit, FDA win drive growth outlook (Investing.com)","url":"https://www.investing.com/news/company-news/tempus-q2-2026-slides-first-profit-fda-win-drive-growth-outlook-93CH-4826329"},{"title":"Tempus AI Personalis agreement (SEC 8-K, 2026-07-20)","url":"https://www.sec.gov/Archives/edgar/data/0001717115/000119312526308469/d124162dex991.htm"}]},{"id":"internet-retail-2026-amazon-q2-aws-reacceleration","date":"2026-07-30","end_date":null,"sector":"consumer_discretionary","subindustries":["internet_retail"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Amazon jumps about 9% after hours on AWS strength in Q2 2026","summary":"Amazon's Q2 2026 report on July 30, 2026 sent the stock up roughly 9% in extended trading as AWS growth re-accelerated and the cloud business carried results, although EPS was flattered by a gain on its Anthropic stake. The move was the biggest post-earnings pop for the internet-retail bellwether since 2024 and masked a retail and advertising business that was growing more slowly; three months later the same AI capex that powered AWS would produce the first back-to-back negative free-cash-flow quarters and a sharp reversal.","evidence":"AMZN +~9% after hours on 2026-07-30 on AWS strength; EPS included an Anthropic-related gain.","sources":[{"title":"Amazon (AMZN) Q2 earnings report 2026 (CNBC, 2026-07-30)","url":"https://www.cnbc.com/2026/07/30/amazon-amzn-q2-earnings-report-2026.html"},{"title":"Amazon (AMZN) Q2 2026 earnings: +9% after-hours jump on AWS strength (Tickeron)","url":"https://tickeron.com/blogs/amazon-amzn-q2-2026-earnings-9-after-hours-jump-on-aws-strength-15172/"}]},{"id":"en-2026-0730-valero-record-q2-2026","date":"2026-07-30","end_date":null,"sector":"energy","subindustries":["refining"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Valero posts record Q2 profit of $12.54/share on $23.62/bbl margins","summary":"On July 30, 2026 Valero reported $12.54 per share for the second quarter against a $10.12 consensus, its highest Q2 profit on record, as refining margin per barrel of throughput nearly doubled year over year to $23.62 and refining adjusted operating earnings more than tripled to $4.4 billion. Hormuz-driven product tightness lifted gasoline and diesel prices faster than feedstock costs; Valero shares rose more than 2% in midday trading. The print confirmed the war-era crack-spread windfall for US Gulf Coast refiners (Marathon, Phillips 66) a year after Valero's Q2 2025 beat ($2.28 vs $1.74 on $12.35/bbl margins) had shown margins merely normalizing.","evidence":"Valero Q2 2026 EPS $12.54 vs $10.12 estimate; refining margin $23.62/bbl, reported 2026-07-30","sources":[{"title":"BNN Bloomberg/Reuters - U.S. refiner Valero Energy posts record Q2 profit, shares jump 2%","url":"https://www.bnnbloomberg.ca/business/company-news/2026/07/30/us-refiner-valero-energy-posts-record-q2-profit-shares-jump-2/"},{"title":"EnergyNow - US Refiner Valero Energy Posts Record Second-Quarter Profit, Shares Jump 2%","url":"https://energynow.com/2026/07/us-refiner-valero-energy-posts-record-second-quarter-profit-shares-jump-2/"},{"title":"Hydrocarbon Processing - Valero Energy beats Q2 2025 profit estimates as refining margins improve","url":"https://www.hydrocarbonprocessing.com/news/2025/07/valero-energy-beats-q2-profit-estimates-as-refining-margins-improve/"}]},{"id":"re-2026-fed-hike-reit-selloff","date":"2026-08-03","end_date":"2026-09-30","sector":"real_estate","subindustries":["net_lease_specialty_reits","mortgage_reits","residential_reits","office_reits","self_storage_reits"],"direction":"out","magnitude":"major","driver_type":"rates","title":"Fed hikes to 3.75-4% and the 10-year hits 5.1%: REITs fall 5.7% in September","summary":"Oil-driven inflation pushed the Fed to its first hike since 2023 on September 16, 2026 and the 10-year yield to 5.10% on September 23 (5.36% in early October), the highest since 2007; every REIT property type fell in September, with free-standing net lease -10.6%, mortgage REITs -13.7%, office -8.2% and apartments -6.9%, and the 30-year mortgage reached 7.19%. Mortgage REITs are down 12.4% for 2026 (REM -16.6%); REITs rebounded 4.7% in October once the Fed paused.","evidence":"All Equity REITs -5.7% in Sep 2026; Free Standing -10.6%, Mortgage REITs -13.7%, Office -8.2% in September; 10-year yield 5.104% on Sep 23, 2026","sources":[{"title":"Nareit property sector returns Sep 30, 2026","url":"https://www.reit.com/sites/default/files/returns/prop.pdf"},{"title":"CNBC: 10-year Treasury yield rockets to 19-year high (Sep 23, 2026)","url":"https://www.cnbc.com/2026/09/23/treasury-yields-oil-inflation-fed.html"},{"title":"CNBC: Fed approves interest rate hike (Sep 16, 2026)","url":"https://www.cnbc.com/2026/09/16/fed-rate-decision-september-2026.html"},{"title":"ChartRow REM calendar-year returns","url":"https://chartrow.com/quote/rem/returns"}]},{"id":"machinery-2026-caterpillar-q2-tariff-relief","date":"2026-08-04","end_date":null,"sector":"industrials","subindustries":["machinery"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Caterpillar Q2 2026: sales +24% to $20.5bn, tariff costs lower than feared, shares jump about 9%","summary":"On August 4, 2026 Caterpillar reported Q2 sales and revenues up 24% to $20.5bn and adjusted EPS of $8.17, well ahead of forecasts, and said tariff costs came in below the April estimate because of favorable adjustments to tariffs previously incurred (management had projected roughly $700m for the quarter and $2.2-2.4bn for the year in April). Shares rose nearly 9% in premarket trading. Management cautioned that the tariff favorability was not expected to persist.","evidence":"Q2 2026 sales and revenues $20.5bn (+24%), adjusted EPS $8.17; CAT shares +~9% premarket on 2026-08-04.","sources":[{"title":"Earnings call transcript: Caterpillar Q2 2026 beats forecasts, shares jump 9% (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-caterpillar-q2-2026-beats-forecasts-shares-jump-9-93CH-4834724"},{"title":"Caterpillar Q2 2026 earnings release (SEC 8-K exhibit 99.1)","url":"https://www.sec.gov/Archives/edgar/data/0000018230/000001823026000040/ex991toformcat2q2026earnin.htm"},{"title":"Caterpillar Q1 2026 earnings: revenue beats but tariffs hit margins (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/caterpillar-q1-2026-earnings-revenue-112145516.html"}]},{"id":"hctech-2026-hims-q2-margin-miss","date":"2026-08-10","end_date":null,"sector":"healthcare","subindustries":["healthcare_technology"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Hims & Hers grows revenue 38% to $753m but misses on EPS; shares fall 6% after hours","summary":"Hims & Hers reported Q2 2026 revenue of about $753m, up roughly 38-40% and ahead of estimates, and raised full-year revenue guidance on August 10, 2026, but missed on EPS as margins stayed compressed by the weight-loss transition; shares fell 6.3% after hours to $29.77. The telehealth leader had become a revenue-growth story without the profitability investors had paid for in 2025, with the stock still down more than 50% from its 52-week high of $44.","evidence":"Q2 2026 revenue ~$753m (+38-40%), EPS miss; HIMS -6.3% after hours to $29.77 on 2026-08-10.","sources":[{"title":"Earnings call transcript: Hims & Hers Q2 2026 revenue beats, EPS misses (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-hims--hers-q2-2026-revenue-beats-eps-misses-93CH-4850552"},{"title":"Hims & Hers Q2 2026 earnings release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0001773751/000177375126000161/hims-20260630x8xkearningsr.htm"}]},{"id":"biotech-smid-2026-xbi-peak-and-fade","date":"2026-08-19","end_date":"2026-10-31","sector":"healthcare","subindustries":["biotech_smid"],"direction":"mixed","magnitude":"major","driver_type":"positioning","title":"XBI peaks near $170, more than double a year earlier, then fades on readouts, rates and midterm risk","summary":"The SPDR S&P Biotech ETF closed at $169.55 on August 19, 2026 (52-week high $169.89), having more than doubled in twelve months and risen about 34% from March on a record M&A wave (biopharma deal value about $199bn for 2026, SMID takeouts roughly $143bn over a year) and lower rates. The gains then stalled: XBI lost about 3.5% in September and traded in the mid-140s to high-150s in October as a run of disappointing clinical readouts, rising interest rates after the Fed's September hike, a slowdown in public-company acquisitions and apprehension about the midterms weighed; it closed at $159.10 on November 4. Removal of acquired winners from the index also changed its composition.","evidence":"XBI closed $169.55 on 2026-08-19 (52-week high $169.89, low $106.30); September 2026 -3.5%; close $159.10 on 2026-11-04.","sources":[{"title":"XBI historical stock price data (StockAnalysis)","url":"https://stockanalysis.com/etf/xbi/history/"},{"title":"This week in charts: what's driving biotech's recent pullback? (BioPharma Dive)","url":"https://www.biopharmadive.com/news/biotech-charts-xbi-private-public-merger-acquisition-deals/832398/"},{"title":"Blockbusters lift 2026 biopharma deal value to record $199B (BioWorld)","url":"https://www.bioworld.com/articles/734411-blockbusters-lift-2026-biopharma-deal-value-to-record-199b"}]},{"id":"staples-retail-2026-target-q2-tariff-refund-turnaround","date":"2026-08-19","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"Target's traffic turns positive (+3.6%) and a $994m tariff refund lifts guidance, but the stock slides after a 60%-plus year","summary":"On August 19, 2026 Target reported Q2 comparable sales up 3.8% against a 2.4% estimate with traffic up 3.6% after multiple quarters of declines, digital comps up 8.7% and a $994m pre-tax benefit from IEEPA tariff refunds, and raised full-year adjusted EPS guidance to $9.90-10.90 (about $1.65 of it refund-related) and sales growth to about 5%. The stock slid despite the beat because the turnaround under CEO Michael Fiddelke had already driven a 60-78% year-to-date rally, and Guggenheim said the contrarian stage of the story had run its course. Target's rotation gain came at Walmart's expense, with WMT down 5% year to date at the time.","evidence":"Q2 2026 comparable sales +3.8% vs +2.4% consensus; traffic +3.6%; $994m tariff refund benefit; FY adjusted EPS guide raised to $9.90-10.90; TGT fell on the day after a ~60%+ YTD run.","sources":[{"title":"Target (TGT) Q2 2026 earnings (CNBC, 2026-08-19)","url":"https://www.cnbc.com/2026/08/19/target-tgt-q2-2026-earnings.html"},{"title":"Target Q2 2026 earnings beat: sales up 5.3%, guidance raised (Quartz)","url":"https://qz.com/target-earnings-sales-beat-full-year-guidance-raised-081926"},{"title":"Target has surged in 2026, Wall Street may be ready to hit pause (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/target-surged-2026-wall-street-111800019.html"}]},{"id":"machinery-2026-deere-ag-cycle-low","date":"2026-08-20","end_date":null,"sector":"industrials","subindustries":["machinery"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Deere calls fiscal 2026 the bottom of the ag cycle; construction carries a beat and the stock rises about 8%","summary":"Deere's fiscal Q3 2026 (quarter to August 2) delivered EPS of $5.10 on revenue of $12.61bn against expectations of $4.69 and $10.81bn, the first year-over-year profit gain in roughly three years. Construction and forestry sales rose 18% to $3.62bn with operating profit up 84%, offsetting still-weak large farm equipment; Deere raised the low end of its fiscal 2026 net income range to $4.75bn (top $5.0bn), lifted equipment cash flow guidance to $5.0-5.5bn and reaffirmed that 2026 marks the trough of the ag equipment cycle. Shares rose about 7.7% premarket toward a 12-month high.","evidence":"Fiscal Q3 2026 EPS $5.10 vs $4.69 consensus; FY26 net income guide low end raised to $4.75bn; DE +~7.7% premarket on 2026-08-20.","sources":[{"title":"Earnings call transcript: Deere beats Q3 2026 estimates, raises outlook (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-deere-beats-q3-2026-estimates-raises-outlook-93CH-4870160"},{"title":"Deere Q3 2026 earnings: profit rises as construction offsets farm weakness (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/deere-q3-2026-earnings-profit-120751377.html"},{"title":"Deere stock climbs after strong Q3 earnings and higher 2026 guidance (ad-hoc-news)","url":"https://www.ad-hoc-news.de/boerse/news/corporate-news/deere-stock-climbs-after-strong-q3-earnings-and-higher-2026-guidance/69985958"}]},{"id":"staples-retail-2026-walmart-q2-9pct-drop","date":"2026-08-20","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Walmart falls 9% on a beat as comps and a below-consensus fiscal 2027 EPS raise disappoint","summary":"Walmart reported fiscal Q2 2027 adjusted EPS of $0.81 against $0.74 and revenue up 5.9% to $187.94bn on August 20, 2026, and raised fiscal 2027 guidance to $2.80-2.87 of adjusted EPS (from $2.75-2.85) and 4-5% sales growth, but the new EPS range sat below the $2.89 consensus and comparable sales and Q3 guidance (sales +3-3.75%, EPS $0.62-0.64) disappointed; CFO John David Rainey said Q2 tariff refunds were being reinvested. Shares closed about 9% lower, the worst earnings day for the staples-retail leader in years and a sharp contrast with Target's turnaround print the day before.","evidence":"WMT closed ~-9% on 2026-08-20; adjusted EPS $0.81 vs $0.74; FY27 adjusted EPS guide $2.80-2.87 vs $2.89 consensus.","sources":[{"title":"Walmart (WMT) Q2 2027 earnings (CNBC, 2026-08-20)","url":"https://www.cnbc.com/2026/08/20/walmart-wmt-q2-2027-earnings.html"},{"title":"Walmart Q2 2027 earnings call transcript (MarketBeat)","url":"https://www.marketbeat.com/earnings/reports/2026-8-20-walmart-inc-stock/"},{"title":"Walmart fiscal 2027 Q2 earnings release (SEC 8-K, 2026-08-20)","url":"https://www.sec.gov/Archives/edgar/data/0000104169/000010416926000145/earningsreleasefy27q2.htm"}]},{"id":"ind-2026-fed-hike-building-products","date":"2026-08-21","end_date":"2026-10-15","sector":"industrials","subindustries":["building_products_construction","industrial_distribution"],"direction":"out","magnitude":"moderate","driver_type":"rates","title":"Fed hikes for the first time since 2023; mortgage rates back above 7%","summary":"Oil-driven inflation (headline PCE projected at 3.7% for 2026) led the Fed to raise rates to 3.75-4.00% on September 16, 2026, with the 10-year yield reaching 5.10% on September 23 (highest since 2007) and 5.36% in early October; the 30-year mortgage rate hit 7.19%. Rate-sensitive building products, HVAC and housing-linked distributors fell with homebuilders, while non-residential/data-center construction names held up better.","evidence":"Fed funds raised 25bp to 3.75%-4.00% on Sep 16, 2026; 10-year Treasury 5.104% on Sep 23, 2026; 30-year mortgage 7.19%","sources":[{"title":"CNBC: Fed approves interest rate hike, signals one more (Sep 16, 2026)","url":"https://www.cnbc.com/2026/09/16/fed-rate-decision-september-2026.html"},{"title":"CNBC: 10-year Treasury yield rockets to 19-year high (Sep 23, 2026)","url":"https://www.cnbc.com/2026/09/23/treasury-yields-oil-inflation-fed.html"}]},{"id":"specialty-retail-2026-burlington-q2-slip","date":"2026-08-27","end_date":null,"sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"Burlington beats on EPS but comps slow to 2% and shares slip; off-price passes tariff refunds to prices","summary":"Burlington reported fiscal Q2 2026 adjusted EPS of $2.37 against $2.17 expected on August 27, 2026, but revenue of about $3.0bn missed slightly and comparable sales slowed to 2% from 5% a year earlier; shares fell about 2.2% to $307.22 and the stock had lost nearly 40% over three months by late summer. Management said it would use IEEPA tariff refunds to lower prices, a reminder that the off-price share gains of the spring were partly a one-off inventory windfall rather than a permanent margin step-up.","evidence":"Fiscal Q2 2026 adjusted EPS $2.37 vs $2.17 consensus; comparable sales +2% vs +5% y/y; BURL -2.16% to $307.22 on 2026-08-27.","sources":[{"title":"Earnings call transcript: Burlington tops Q2 2026 profit forecasts, shares slip (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-burlington-tops-q2-2026-profit-forecasts-shares-slip-93CH-4879615"},{"title":"Burlington Stores Q2 2026 earnings: tariff refunds to lower prices (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/burlington-stores-q2-2026-earnings-123742994.html"},{"title":"Bear of the day: Burlington Stores (Zacks via TradingView)","url":"https://www.tradingview.com/news/zacks:be242e5fd094b:0-bear-of-the-day-burlington-stores-burl/"}]},{"id":"staples-retail-2026-dollar-general-q2-raise","date":"2026-08-27","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Dollar General raises fiscal 2026 EPS to $7.80-8.00 on 5.2% sales growth; shares up 2.5%","summary":"On August 27, 2026 Dollar General reported Q2 net sales up 5.2% to $11.3bn and raised fiscal 2026 EPS guidance to $7.80-8.00; shares rose about 2.5%. A week after Walmart's 9% drop, the dollar-store print showed low-income trade-down still supporting discount volumes even as SNAP cuts from the 2025 budget law began to phase in, and the group held its 2026 outperformance as a defensive, domestic-sourcing alternative to general-merchandise retail.","evidence":"Q2 2026 net sales +5.2% to $11.3bn; FY26 EPS guide raised to $7.80-8.00; DG +2.5% on 2026-08-27.","sources":[{"title":"Can Dollar General keep expanding earnings in fiscal 2026? (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/dollar-general-keep-expanding-earnings-130600251.html"},{"title":"Dollar General's quarterly earnings preview: what you need to know (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/dollar-generals-quarterly-earnings-preview-143220999.html"}]},{"id":"software-2026-salesforce-q2-fy27-rally","date":"2026-08-27","end_date":null,"sector":"technology","subindustries":["application_software"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Salesforce jumps 18% on Q2 FY27 beat and Agentforce ARR above $1.5bn","summary":"Salesforce reported fiscal Q2 2027 results on 2026-08-26 with revenue of $11.35bn (+11% y/y) and adjusted EPS of $5.90 (boosted by an Anthropic investment gain) versus $3.27 expected; Agentforce ARR topped $1.5bn, up 240% y/y, and full-year revenue guidance was raised to $46.1-46.4bn. CRM rose 18% on 2026-08-27 after being down 22% year-to-date going into the print, with CEO Marc Benioff declaring 'This is not the SaaSpocalypse', a relief signal for seat-based application software.","evidence":"CRM +18% on 2026-08-27; Agentforce ARR >$1.5bn (+240% y/y)","sources":[{"title":"CNBC: Salesforce (CRM) Q2 earnings report fiscal 2027","url":"https://www.cnbc.com/2026/08/26/salesforce-crm-q2-earnings-report-2027.html"},{"title":"Salesforce 8-K exhibit 99.1, Q2 FY27 results","url":"https://www.sec.gov/Archives/edgar/data/0001108524/000110852426000187/crm-q2fy27xexhibit991.htm"}]},{"id":"financials-2026-aon-usi-17bn","date":"2026-08-31","end_date":null,"sector":"financials","subindustries":["insurance"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Aon agrees to buy USI for $17bn, biggest broker deal of 2026","summary":"On 2026-08-31 Aon confirmed a $17bn all-debt-funded acquisition of USI Insurance Services from KKR (net price $16.7bn, about 14.5x synergized EBITDA), doubling down on the US middle market and pausing buybacks to protect its Baa2/A- ratings. Aon shares rose on the announcement while KKR slipped, and the deal extended a wave of broker consolidation that includes Brown & Brown's $9.8bn Accession purchase (June 2025) and the $7.7bn Baldwin Group take-private (September 2026), supporting broker valuations (MMC, AJG, WTW).","evidence":"Aon-USI deal value $17bn announced 2026-08-31","sources":[{"title":"Insurance Business: Aon strikes $17 billion deal for USI, doubling down on the middle market","url":"https://www.insurancebusinessmag.com/us/news/benefits/aon-strikes-17-billion-deal-for-usi-doubling-down-on-the-middle-market-587920.aspx"},{"title":"Bloomberg: Brown & Brown to buy Accession Risk Management for $9.8 billion","url":"https://www.bloomberg.com/news/articles/2025-06-10/brown-brown-to-buy-accession-risk-management-for-9-8-billion"}]},{"id":"apparel-2026-lululemon-q2-plunge","date":"2026-09-03","end_date":null,"sector":"consumer_discretionary","subindustries":["apparel_luxury"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Lululemon plunges 20% as comps fall 9% and a $134.5m tariff refund masks margin pressure","summary":"Lululemon's fiscal Q2 2026 results on September 3, 2026 showed revenue down 4% and comparable sales down 9%, with diluted EPS of $2.92 (vs $3.10 a year earlier) including $0.86 from a $134.5m refund of IEEPA tariffs; full-year EPS guidance was cut to $9.48-9.73. Shares fell about 20% in premarket trading, leaving the stock down roughly 48% for 2026 at an 8x multiple. Nike's own fiscal Q1 miss four weeks later confirmed that brand heat, not tariffs, had become the apparel group's problem.","evidence":"LULU -20% premarket on 2026-09-03; Q2 comparable sales -9%; FY26 EPS guide cut to $9.48-9.73; $134.5m tariff refund added $0.86 to EPS.","sources":[{"title":"Lululemon stock plunges 20% on disappointing earnings and outlook (CNBC, 2026-09-03)","url":"https://www.cnbc.com/2026/09/03/lululemon-lulu-q2-2026-earnings.html"},{"title":"lululemon athletica inc. announces second quarter fiscal 2026 results (lululemon)","url":"https://corporate.lululemon.com/newsroom/press-releases/2026/09-03-2026-210528733"},{"title":"LULU Q2 earnings show tariff refunds but demand remains under pressure (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/lulu-q2-earnings-show-tariff-153000058.html"}]},{"id":"financials-2026-fed-hike","date":"2026-09-16","end_date":"2026-10-28","sector":"financials","subindustries":["banks","insurance","capital_markets"],"direction":"mixed","magnitude":"major","driver_type":"rates","title":"Fed hikes to 3.75-4% under Warsh, the first increase since July 2023","summary":"With inflation 'elevated' (2026 headline PCE projected at 3.7%) after the Iran-war energy shock and lingering tariff effects, the FOMC under Chair Kevin Warsh (sworn in 22 May 2026) raised rates 25 bp to 3.75-4% on 16 September 2026 by a 12-0 vote and held on 28 October with two dissents for a further hike; futures priced another increase in December. Higher short rates help bank margins but the 'recent rise in longer-term borrowing costs' and AI-credit stress kept financials (XLF +6.3% year-to-date on 5 November) well behind energy and health care.","evidence":"FOMC raised the target range to 3.75-4% on 2026-09-16 (12-0), the first hike since July 2023; held 10-2 on 2026-10-28.","sources":[{"title":"FOMC statement, 16 September 2026","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm"},{"title":"Fed rate decision September 2026 (CNBC)","url":"https://www.cnbc.com/2026/09/16/fed-rate-decision-september-2026.html"},{"title":"Fed holds rates steady, October 2026 (CNBC)","url":"https://www.cnbc.com/2026/10/28/fed-interest-rate-decision-october-2026.html"},{"title":"Kevin Warsh (Wikipedia)","url":"https://en.wikipedia.org/wiki/Kevin_Warsh"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"}]},{"id":"media-2026-paramount-wbd-state-ag-settlement","date":"2026-09-21","end_date":"2026-10-06","sector":"communication_media","subindustries":["media_entertainment"],"direction":"mixed","magnitude":"moderate","driver_type":"regulatory","title":"Paramount settles state AG antitrust suit, clearing WBD deal to close Oct 6","summary":"On 2026-09-21 Paramount settled the antitrust suit brought by a dozen state attorneys general led by California's Rob Bonta, agreeing to lift US production spending by at least $300m a year, release 30 theatrical films in two years, keep the Paramount and Warner lots in Los Angeles, and create an independent oversight board for CBS News and CNN, with Miramax or a suite of cable channels to be divested if targets are missed. Paramount shares rose early then fell 3% after Bonta's press conference; the ~$110bn Warner Bros. Discovery acquisition, already cleared by the DOJ (June 12) and EU (July 22), closed on 2026-10-06.","evidence":"Settlement 2026-09-21; Paramount-WBD deal closed 2026-10-06","sources":[{"title":"CNBC: Paramount and state AGs settle lawsuit, allowing Warner Bros. merger to proceed","url":"https://www.cnbc.com/2026/09/21/paramount-reaches-settlement-over-warner-bros-merger.html"},{"title":"CNBC: Paramount's hard-fought takeover of Warner Bros. Discovery closed Tuesday","url":"https://www.cnbc.com/2026/10/06/paramount-wbd-deal-timeline.html"}]},{"id":"specialty-retail-2026-autozone-fq4-tariff-refund","date":"2026-09-22","end_date":"2026-09-23","sector":"consumer_discretionary","subindustries":["specialty_retail"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"AutoZone's EPS rises 15% to $56.05 with $100m of tariff refunds in gross margin; stock up 3%","summary":"AutoZone reported fiscal Q4 2026 EPS of $56.05 (+15.1%, vs $53.84 expected) on September 22, 2026 with same-store sales up 1.5% in constant currency; tariff refunds added about 145bp (roughly $100m) to gross margin, so underlying growth was far smaller. Shares rose more than 3% the next day after a 12-month stretch in which the stock had lost about 22%, as the aging-fleet auto-parts trade re-rated on cheaper multiples while O'Reilly and AutoZone's DIY customers stayed under affordability pressure.","evidence":"Fiscal Q4 2026 EPS $56.05 vs $53.84 consensus; same-store sales +1.5% (constant currency); AZO +~3% on 2026-09-23.","sources":[{"title":"Is AutoZone a buy after its latest earnings report? (Motley Fool, 2026-09-23)","url":"https://www.fool.com/investing/2026/09/23/is-autozone-a-buy-after-its-latest-earnings-report/"},{"title":"What could lift AutoZone stock after its fall? (Trefis, 2026-10-21)","url":"https://www.trefis.com/stock/azo/articles/619671/what-could-lift-autozone-stock-after-its-fall/2026-10-21"}]},{"id":"proserv-2026-paychex-guidance-disappointment","date":"2026-09-23","end_date":null,"sector":"industrials","subindustries":["professional_services"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Paychex drops 7-9% on a beat: reaffirmed guidance and slower Q2 growth punish a premium multiple","summary":"Paychex reported fiscal Q1 2027 adjusted EPS of $1.34 (vs $1.32) on $1.63bn of revenue on September 23, 2026, but only reaffirmed full-year guidance and flagged lower Q2 revenue growth with a key segment 'slightly below expectations'. The stock fell 7-9% on the day (TradingKey -7.07%; Seeking Alpha almost -9%), with a 24/7 Wall St. follow-up citing a double-digit multi-day decline. The reaction showed how little room the payroll processors' premium valuations leave for in-line results as employment growth cools.","evidence":"PAYX -7.07% on 2026-09-23 per TradingKey (Seeking Alpha: almost -9%); fiscal Q1 adjusted EPS $1.34 vs $1.32.","sources":[{"title":"Why is Paychex stock falling Wednesday? (Benzinga)","url":"https://www.benzinga.com/markets/earnings/26/09/61954978/paychex-says-key-segment-was-slightly-below-expectations-stock-sinks"},{"title":"Paychex falls 9% after earnings (Seeking Alpha)","url":"https://seekingalpha.com/news/4646307-paychex-falls-9-after-earnings"},{"title":"Paychex (PAYX) moved down by 7.07% on Sep 23 (TradingKey)","url":"https://www.tradingkey.com/news/market-movers/262183139-market-movers-payx-20260923"}]},{"id":"travel-2026-mcdonalds-investor-day","date":"2026-09-23","end_date":null,"sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"McDonald's NEXT: an $8.5bn franchisee rescue plan sends the stock down 4.8%, its worst day since March 2020","summary":"At its September 23, 2026 investor day McDonald's unveiled 'McDonald's NEXT', about $8.5bn of rent relief and capital support to franchisees through 2036 (roughly $5bn by 2030), pushed its 50,000-restaurant target from 2027 to 2028 and warned of flat traffic after Q2 US comps of just 0.8% with negative guest counts. Shares closed down 4.81% at $238.32 on three times normal volume, the worst session since March 2020, taking the stock to its lowest since 2022 and about 29% below its March high. The plan confirmed that low-income traffic erosion had reached the largest QSR, not just Chipotle and casual dining.","evidence":"MCD -4.81% to $238.32 on 2026-09-23 (worst day since March 2020); $8.5bn franchisee support through 2036; 50,000-unit target moved to 2028.","sources":[{"title":"McDonald's shares fall as $8.5 billion franchisee plan raises spending concerns (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/mcdonald-shares-fall-8-5-150000011.html"},{"title":"McDonald's stock hits lowest level since 2022 as CEO warns of flat traffic at investor day (TIKR)","url":"https://www.tikr.com/blog/mcdonalds-stock-lowest-since-2022-investor-day-next-plan"},{"title":"McDonald's stock is down 29%, its comeback plan could make things worse (Forbes, 2026-09-25)","url":"https://www.forbes.com/sites/jimosman/2026/09/25/mcdonalds-stock-fell-29-its-turnaround-plan-could-make-things-worse/"}]},{"id":"re-2026-tower-spacex-reversal","date":"2026-10-01","end_date":"2026-10-31","sector":"real_estate","subindustries":["data_center_tower_reits"],"direction":"in","magnitude":"moderate","driver_type":"tech_cycle","title":"SpaceX cellular fears reverse: telecom REITs jump 18% in October","summary":"Tower REITs had lagged all year (-10.6% through September) after SpaceX announced plans for its own cellular network; in October analysts concluded a full network still needs terrestrial towers and the group gained 18.4%, the best property type of the month, with American Tower up 14% for the year. Towers remain below their 2021 highs on carrier-capex and leverage concerns.","evidence":"Telecommunications REITs +18.4% in Oct 2026 after -10.6% YTD through Sep 30; AMT +13.9% YTD at Nov 5, 2026","sources":[{"title":"WealthManagement/Nareit: REIT returns climb 4.7% as telecom surges in October","url":"https://www.wealthmanagement.com/alternative-investments/q-a-reits-bounce-back-in-october"},{"title":"Nareit property sector returns Sep 30, 2026","url":"https://www.reit.com/sites/default/files/returns/prop.pdf"},{"title":"ChartRow AMT calendar-year returns","url":"https://chartrow.com/quote/amt/returns"}]},{"id":"it-services-2026-accenture-rebound","date":"2026-10-01","end_date":null,"sector":"technology","subindustries":["it_services"],"direction":"in","magnitude":"major","driver_type":"earnings","title":"Accenture jumps 22% on fiscal 2027 guidance; IT services snap back","summary":"On 1 October 2026 Accenture guided fiscal 2027 revenue growth of 3-6% (midpoint above the 3.9% consensus) with Q4 bookings up 4% to $22.17 billion; the shares surged 22%, on track for their best day ever, lifting Cognizant about 8%, Infosys and Wipro 6-7% and IBM 3%. The move reversed part of the June derating and reframed AI as a services tailwind (systems integration, data work) rather than purely a substitution risk, although the group still trades at single-digit to low-teens multiples.","evidence":"Accenture +22% on 2026-10-01 after guiding FY2027 revenue growth of 3-6%; Q4 bookings $22.17 billion (+4%).","sources":[{"title":"Accenture's forecast eases AI disruption fears, lifts battered IT services stocks (Reuters via AOL, 2026-10-01)","url":"https://www.aol.com/articles/accenture-forecasts-annual-revenue-growth-104422000.html"}]},{"id":"apparel-2026-nike-13-year-low","date":"2026-10-01","end_date":null,"sector":"consumer_discretionary","subindustries":["apparel_luxury"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Nike hits a 13-year low after guiding fiscal 2027 revenue down high-single digits and starting a cost overhaul","summary":"On October 1, 2026 Nike reported fiscal Q1 2027 EPS of $0.48, ahead of estimates, but revenue of about $11.2bn fell short and the company said fiscal 2027 revenue would decline by a high-single-digit percentage as it cut guidance and launched a cost overhaul. Shares fell 6.2% after hours to $32.96 (as much as 9% by some accounts), the lowest since September 2013, after a roughly 43% year-to-date decline. The print, after Lululemon's 20% drop in September, cemented apparel and footwear as 2026's worst consumer group even after the Supreme Court tariff ruling had removed the IEEPA cost.","evidence":"NKE -6.24% after hours to $32.96 on 2026-10-01, lowest since September 2013; fiscal 2027 revenue guided down high-single digits.","sources":[{"title":"Nike earnings: stock sinks nearly 4% to 13-year low as revenue falls short (Forbes, 2026-10-01)","url":"https://www.forbes.com/sites/antoniopequenoiv/2026/10/01/nike-shares-hit-new-13-year-low-after-q1-revenue-falls-short-of-expectations/"},{"title":"Nike cuts guidance as sales slide and a cost overhaul begins (Forbes, 2026-10-01)","url":"https://www.forbes.com/sites/jimosman/2026/10/01/nike-stocks-turnaround-just-became-a-25-billion-retreat/"},{"title":"Earnings call transcript: Nike posts Q1 2026 EPS beat, shares sink on weak sales (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-nike-posts-q1-2026-eps-beat-shares-sink-on-weak-sales-93CH-4928594"}]},{"id":"utilities-2026-bond-selloff-xlu-oversold","date":"2026-10-02","end_date":null,"sector":"utilities","subindustries":["regulated_utilities"],"direction":"out","magnitude":"moderate","driver_type":"rates","title":"Bond selloff pushes XLU down 6% in a month, most oversold since 2023","summary":"By 2026-10-02 the Utilities Select Sector SPDR (XLU) had fallen about 6% over the prior month while the S&P 500 rose, its sharpest selloff since October 2023, sitting 17% below its 52-week high as the 10-year Treasury yield pushed above 5% in what CNBC's Mike Khouw called the fastest rise in yields since 1994. Regulated names led by NextEra (13% of XLU) lagged while IPPs Constellation and Vistra held up on data-center demand; XLU had given back all of its Q1 2026 outperformance.","evidence":"XLU about -6% over the month to 2026-10-02, 17% below 52-week high","sources":[{"title":"24/7 Wall St: Utility stocks are the most oversold since 2023","url":"https://247wallst.com/investing/etf/2026/10/02/utility-stocks-are-the-most-oversold-since-2023/"},{"title":"CNBC: The sector in the cross hairs of the bond sell-off looks poised for a bounce, says Mike Khouw","url":"https://www.cnbc.com/2026/10/02/the-sector-in-the-cross-hairs-of-the-bond-sell-off-looks-poised-for-a-bounce-says-mike-khouw.html"}]},{"id":"telecom-2026-spacex-starlink-mobile","date":"2026-10-09","end_date":"2026-10-23","sector":"technology","subindustries":["telecom"],"direction":"out","magnitude":"major","driver_type":"tech_cycle","title":"Starlink Mobile: SpaceX's spectrum deal knocks 10-14% off AT&T, Verizon and T-Mobile in a day","summary":"On October 9, 2026 SpaceX announced a nationwide low-band spectrum deal for a 'Starlink Mobile' service combining its satellites with terrestrial sites, building on the EchoStar spectrum it bought in 2025. AT&T closed down 11.0% at $22.13, Verizon 10.4% at $41.52 and T-Mobile 13.6% at $148.02, a rare same-day double-digit sweep; on October 23 reports that SpaceX wanted access to 80,000 cell sites took another 7-8% off AT&T and T-Mobile, and AT&T's October 21 earnings beat was overshadowed by a $2.6bn Mexico impairment (-6.1%). The threat to the three-player oligopoly reversed telecom's defensive bid while tower REITs, which would host the new sites, jumped 18% in October.","evidence":"T-Mobile -13.6% to $148.02, Verizon -10.4% to $41.52 and AT&T -11.0% to $22.13 on 2026-10-09.","sources":[{"title":"AT&T, Verizon and T-Mobile stocks slump as SpaceX announces key 'Starlink Mobile' deal (Forbes)","url":"https://www.forbes.com/sites/siladityaray/2026/10/09/att-verizon-and-t-mobile-stocks-slump-as-spacex-announces-key-starlink-mobile-deal/"},{"title":"Telecom stocks fall as SpaceX eyes 80,000 cell sites (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/10/23/telecom-stocks-fall-as-spacex-eyes-80000-cell-sites-t-mobile-sinks-5-att-drops-4-verizon-slides-3/"},{"title":"AT&T Q3 2026 earnings: six straight beats and a raised outlook (24/7 Wall St.)","url":"https://247wallst.com/cards/at-t-q3-2026-earnings-t-01m5f0j31psck1tt7c1qcf4a0f"},{"title":"Elon Musk's growing SpaceX empire sends AT&T, Verizon and T-Mobile shares plunging (NBC News)","url":"https://www.nbcnews.com/business/corporations/elon-musk-spacex-verizon-tmobile-att-rcna602525"}]},{"id":"transport-2026-delta-fuel-guidance-cut","date":"2026-10-09","end_date":null,"sector":"industrials","subindustries":["transportation"],"direction":"out","magnitude":"moderate","driver_type":"commodity","title":"Delta's first miss in two years: fuel bill +62% forces a cut in 2026 EPS guidance to $5.10-5.60","summary":"On October 9, 2026 Delta reported Q3 adjusted EPS of about $1.72-1.76 against roughly $1.77 expected, its first miss in two years, as adjusted fuel expense surged 62% to $4.14bn with the average price up 60% to $3.61 a gallon after the Iran war. Delta cut full-year adjusted EPS guidance to $5.10-5.60 from the $6.50-7.50 set in July and guided Q4 to $1.15-1.65 on $4.25 fuel, while CEO Ed Bastian said demand remained strong and fares were rising. Shares fell 3-4% in early trading; reports on United and American conflicted, with 24/7 Wall St. saying they slipped under 1%.","evidence":"Delta 2026 adjusted EPS guide cut to $5.10-5.60 from $6.50-7.50 on 2026-10-09; Q3 fuel expense +62% to $4.143bn ($3.61/gal); DAL -3% to -4.4% early.","sources":[{"title":"Delta falls 3% on cut full-year profit outlook as fuel costs jump 62% (24/7 Wall St., 2026-10-09)","url":"https://247wallst.com/investing/2026/10/09/delta-falls-3-on-cut-full-year-profit-outlook-as-fuel-costs-jump-62-united-and-american-airlines-slip/"},{"title":"Delta Air Lines (DAL) Q3 2026 earnings (CNBC)","url":"https://www.cnbc.com/2026/10/09/delta-air-lines-dal-q3-2026-earnings.html"},{"title":"Delta Air Lines announces September quarter 2026 financial results (Delta IR)","url":"https://ir.delta.com/news/news-details/2026/Delta-Air-Lines-Announces-September-Quarter-2026-Financial-Results/default.aspx"}]},{"id":"ai-2026-credit-stress","date":"2026-10-14","end_date":null,"sector":"ai","subindustries":["infrastructure_software_cyber","semiconductors","hardware","internet_platforms"],"direction":"out","magnitude":"major","driver_type":"macro","title":"AI credit stress: CoreWeave bonds distressed, CDS above 1,000 bp, hyperscaler spreads at 2021 highs","summary":"CoreWeave fell 15.5% on 14 October 2026 as its 2032 bonds dropped to 78 cents (yield 14.8%), 34% between 6 and 21 October and to a record low of $49.92 on 2 November (-44% for the month); its five-year CDS passed 1,000 bp (1,087.8 on 30 October, above 1,289 on 5 November), implying more than 60% five-year default probability on $72 billion of debt, while Oracle's CDS reached about 296-322 bp versus 144 at the start of 2026 and hyperscaler CDS hit their highest since 2021. Gartner (14 October) estimated more than $4 trillion of data-center asset value at write-down risk and BofA (16 October) called AI a classic capital cycle; hyperscalers issued $296 billion of debt in 2026 and reported negative free cash flow in Q3, and OpenAI pushed its IPO to 2027.","evidence":"CoreWeave five-year CDS 1,087.8 bp on 2026-10-30 and above 1,289 bp on 2026-11-05; Oracle CDS about 296 bp vs 144 bp in early 2026.","sources":[{"title":"CoreWeave bond yield tops 16% as AI credit stress rises (CNBC, 2026-11-06)","url":"https://www.cnbc.com/2026/11/06/coreweave-bond-yield-tops-16percent-as-ai-credit-stress-rises.html"},{"title":"AI credit fears deepen as data centers face nationwide backlash (Seoul Economic Daily, 2026-10-21)","url":"https://en.sedaily.com/international/2026/10/21/ai-credit-fears-deepen-as-data-centers-face-nationwide"},{"title":"Wall Street debates whether the latest AI bubble warnings are real (Fortune, 2026-10-17)","url":"https://fortune.com/2026/10/17/ai-boom-vs-bust-bubble-warning-hyperscaler-spending-debt-coreweave-nvidia/"},{"title":"CoreWeave stock sinks to record low as AI debt fears mount (BigGo Finance, 2026-11-02)","url":"https://finance.biggo.com/news/42d1c106-28b1-4e61-8ddb-2d3b27feecac"},{"title":"AI debt fears surge as tech default insurance hits record highs (ROIC.ai, 2026-10-15)","url":"https://www.roic.ai/news/ai-debt-fears-surge-as-tech-default-insurance-hits-record-highs-10-15-2026"},{"title":"OpenAI (Wikipedia)","url":"https://en.wikipedia.org/wiki/OpenAI"}]},{"id":"staples-retail-2026-walmart-inflation-defensive-bid","date":"2026-10-14","end_date":null,"sector":"consumer_staples","subindustries":["staples_retail"],"direction":"in","magnitude":"minor","driver_type":"macro","title":"Hot inflation print sends money into defensives: Walmart +3%, Costco and Target edge higher","summary":"On October 14, 2026 a hotter-than-expected US inflation reading revived worries about borrowing costs after the Fed's September hike and pushed investors into defensive retailers, with Walmart rising about 3% and Costco and Target edging higher while AI-power and semiconductor names fell. The session was part of the October rotation that also lifted Procter & Gamble and Waste Connections, as staples retail recovered from Walmart's August earnings drop; Costco was up about 20% for the year by early November after its fiscal Q4 beat ($6.75 vs $6.53).","evidence":"WMT +~3% on 2026-10-14 on an inflation-driven move into defensives; COST and TGT higher the same session.","sources":[{"title":"Walmart advances 3% as inflation data sends money into defensives; Costco and Target edge higher (24/7 Wall St., 2026-10-14)","url":"https://247wallst.com/investing/2026/10/14/walmart-advances-3-as-inflation-data-sends-money-into-defensives-costco-and-target-edge-higher/"},{"title":"Costco stock: earnings growth could shape the next big move (24/7 Wall St., 2026-11-06)","url":"https://247wallst.com/investing/2026/11/06/costco-stock-earnings-growth-could-shape-the-next-big-move/"}]},{"id":"proserv-2026-equifax-q3-beat","date":"2026-10-20","end_date":null,"sector":"industrials","subindustries":["professional_services"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Equifax jumps about 10% on Q3 2026 as non-mortgage growth offsets a frozen mortgage market","summary":"Equifax reported Q3 2026 revenue of $1.693bn (+10%) and adjusted EPS of $2.26 (+11%, vs $2.20 expected) on October 20, 2026, with 8% growth in diversified markets offsetting flat Workforce Solutions mortgage revenue after 30-year mortgage rates rose about 75bp from July. Shares rose about 10% in premarket trading. Rival TransUnion beat a week later but slipped about 2% premarket on declining mortgage inquiry volumes, so the bid was for the diversified data story, not the credit-bureau group as a whole.","evidence":"EFX +10.44% premarket on 2026-10-20; Q3 revenue $1.693bn (+10%), adjusted EPS $2.26 vs $2.20 consensus.","sources":[{"title":"Equifax delivers strong 10% revenue growth in third quarter 2026 (Equifax IR)","url":"https://investor.equifax.com/news-events/press-releases/detail/1427/equifax-delivers-strong-10-revenue-growth-in-third-quarter"},{"title":"Earnings call transcript: Equifax tops Q3 2026 profit view, shares jump 10% (Investing.com)","url":"https://za.investing.com/news/stock-market-news/earnings-call-transcript-equifax-tops-q3-2026-profit-view-shares-jump-10-93CH-4514595"},{"title":"Earnings call transcript: TransUnion tops Q3 2026 EPS forecast, shares slip (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-transunion-tops-q3-2026-eps-forecast-shares-slip-93CH-4976283"}]},{"id":"aero-2026-ge-aerospace-q3-raise-sell-the-news","date":"2026-10-20","end_date":null,"sector":"industrials","subindustries":["commercial_aerospace"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"GE Aerospace raises 2026 guidance again on 49% order growth; shares slip 3% on shop-visit timing","summary":"GE Aerospace's Q3 2026 orders jumped 49% to $19.0bn and adjusted EPS of $2.25 beat consensus for a sixth straight quarter; the company lifted 2026 adjusted EPS guidance to $8.00-8.10 (from $7.65-7.85, above the $7.92 consensus), operating profit to $10.9-11.0bn and free cash flow to $9.1-9.4bn, with commercial services now expected to grow in the low-20% range on a backlog above $170bn. Shares nevertheless fell about 3% on October 20, 2026 as analysts flagged a modest hit to 2026 services from shop-visit timing. The aftermarket engine story remained the healthiest part of commercial aerospace while Boeing's ramp slipped a week later.","evidence":"GE -~3% on 2026-10-20 despite 2026 adjusted EPS guide raised to $8.00-8.10 (consensus $7.92); Q3 orders +49% to $19.0bn.","sources":[{"title":"GE Aerospace raises 2026 guidance as orders surge (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/ge-aerospace-raises-2026-guidance-125500735.html"},{"title":"GE Aerospace Q3 2026 earnings release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0000040545/000004054526000063/ge3q2026earningsrelease.htm"},{"title":"GE Aerospace raises profit outlook in Q3 2026 earnings report (Quartz)","url":"https://qz.com/ge-aerospace-raises-2026-profit-forecast-engine-demand-102026"}]},{"id":"aero-2026-faa-certifies-737-10","date":"2026-10-20","end_date":null,"sector":"industrials","subindustries":["commercial_aerospace"],"direction":"in","magnitude":"moderate","driver_type":"regulatory","title":"FAA certifies the 737-10, the largest MAX and more than 30% of the 737 order book","summary":"On October 20, 2026 the FAA issued an amended type certificate and production approval for the Boeing 737-10 after a program of nearly 1,000 test flights, clearing deliveries 'in the coming months' (Safran's release points to 2027). The 737-10 accounts for more than 30% of the 737 MAX backlog and its certification removes a multi-year overhang for Boeing, CFM/Safran and the 40-odd built-but-undelivered 737-7/-10 airframes in inventory; the enhanced angle-of-attack system will become standard across the MAX family. The relief was short-lived: a week later Boeing pushed the 737 rate ramp out a year.","evidence":"FAA amended type certificate for the 737-10 issued 2026-10-20; 737-10 is >30% of the 737 MAX order book per Boeing.","sources":[{"title":"FAA certifies Boeing 737-10 (Boeing)","url":"https://www.boeing.com/features/2026/10/faa-certifies-boeing-737-10"},{"title":"U.S. FAA certifies Boeing 737-10, largest member of 737 MAX family (PR Newswire)","url":"https://www.prnewswire.com/news-releases/us-faa-certifies-boeing-737-10-largest-member-of-737-max-family-302914559.html"},{"title":"Boeing 737 MAX 10 receives FAA certification (Aviation Week)","url":"https://aviationweek.com/air-transport/safety-ops-regulation/boeing-737-max-10-receives-faa-certification"}]},{"id":"meddev-2026-intuitive-q3-us-slowdown","date":"2026-10-20","end_date":null,"sector":"healthcare","subindustries":["medical_devices"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"Intuitive Surgical grows revenue 22% and places 546 systems, but US da Vinci procedure growth slows to 10%","summary":"Intuitive Surgical's Q3 2026 revenue rose 22% to $3.05bn with worldwide procedures up about 15% and 546 da Vinci placements (427 a year earlier), and non-GAAP EPS of $3.00 versus $2.40, while GAAP EPS fell to $1.49 on a proposed $450m antitrust settlement. US da Vinci procedure growth decelerated to 10% from 12% the prior quarter and management narrowed 2026 procedure growth guidance to 14-15%. The quarter kept the robotics leader as the relative winner in a device group where Boston Scientific was cutting guidance for a third time.","evidence":"Q3 2026 revenue $3.05bn (+22%); US da Vinci procedure growth 10% vs 20% outside the US; 2026 procedure growth guide 14-15%.","sources":[{"title":"Intuitive announces third quarter earnings (Intuitive IR)","url":"https://isrg.intuitive.com/news-releases/news-release-details/intuitive-announces-third-quarter-earnings-6"},{"title":"Intuitive Surgical (ISRG) Q3 2026 earnings call transcript (Motley Fool, 2026-10-21)","url":"https://www.fool.com/earnings/call-transcripts/2026/10/21/intuitive-surgical-isrg-q3-2026-earnings-call-transcript/"},{"title":"Intuitive Surgical reports strong Q3 growth as $450 million settlement adds pressure (MedReps)","url":"https://medreps.com/news/intuitive-surgical-q3-2026-growth-settlement/"}]},{"id":"en-2026-1020-ofs-q3-2026-earnings","date":"2026-10-20","end_date":"2026-10-28","sector":"energy","subindustries":["oilfield_services"],"direction":"mixed","magnitude":"moderate","driver_type":"earnings","title":"Q3 2026 OFS prints: Halliburton and SLB beat on international, Baker Hughes drops 6% on leverage","summary":"Halliburton opened the Q3 2026 oilfield-services season on October 20 with adjusted EPS of $0.60 vs $0.58 and revenue of $5.7 billion, but North America revenue fell 9% year over year to $2.2 billion on weaker US pressure pumping, offset by Latin America (+12.6%) and Europe/Africa (+22.7%); it took a $107 million severance charge, guided 2027 to mid-single-digit growth and ~15% margins assuming flat North America, and shares rose (up ~2% premarket, with intraday gains reported as high as 5.8%). SLB reported revenue of $9.45 billion (+5.8%) and EPS $0.64 vs ~$0.61 with Middle East revenue +13% sequentially. Baker Hughes on October 28 beat ($0.70 vs $0.60) but fell more than 6% after hours to about $55 as 2.5x post-Chart leverage and ~$200 million of integration costs overshadowed the quarter.","evidence":"Halliburton Q3 2026 adjusted EPS $0.60 vs $0.58, North America revenue -9% y/y, reported 2026-10-20; Baker Hughes -6% after hours 2026-10-28","sources":[{"title":"Halliburton - Halliburton Announces Third Quarter 2026 Results","url":"https://ir.halliburton.com/news-releases/news-release-details/halliburton-announces-third-quarter-2026-results"},{"title":"Investing.com - Earnings call transcript: Halliburton tops Q3 2026 estimates as shares rise","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-halliburton-tops-q3-2026-estimates-as-shares-rise-93CH-4960442"},{"title":"Investing.com - Baker Hughes Q3 2026 slides: earnings beat, stock falls on leverage","url":"https://ca.investing.com/news/stock-market-news/baker-hughes-q3-2026-slides-earnings-beat-stock-falls-on-leverage-93CH-4910171"},{"title":"EnergyNow - Halliburton Tops Estimates as Latin America, Europe Cushion North American Weakness","url":"https://energynow.com/2026/10/halliburton-tops-estimates-as-latin-america-europe-cushion-north-american-weakness/"},{"title":"Yahoo Finance - SLB's (NYSE:SLB) Q3 2026: beats on revenue","url":"https://finance.yahoo.com/markets/stocks/articles/slb-nyse-slb-q3-2026-110655686.html"}]},{"id":"lstools-2026-danaher-q3-new-ceo","date":"2026-10-21","end_date":null,"sector":"healthcare","subindustries":["life_sciences_tools"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"Danaher beats Q3 2026 with 5.5% core growth and raises EPS guidance; shares dip then bounce","summary":"On October 21, 2026 Danaher reported Q3 adjusted EPS of $2.11 against a $1.91 FactSet mean on revenue of $6.6bn, with core growth accelerating to 5.5%, and raised 2026 adjusted EPS guidance to $8.57-8.62 from $8.45-8.60 while keeping core growth at 4-5%; its new CEO pledged 'unambiguous share gain'. Shares fell about 3.7% premarket on a respiratory-testing headwind before bouncing higher during the session, a muted reaction for a tools group that had already re-rated on the bioprocessing recovery.","evidence":"Q3 2026 adjusted EPS $2.11 vs $1.91 FactSet mean; 2026 adjusted EPS guide raised to $8.57-8.62; DHR -3.67% premarket on 2026-10-21 before recovering.","sources":[{"title":"Earnings call transcript: Danaher tops Q3 2026 estimates but shares fall premarket (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-danaher-tops-q3-2026-estimates-but-shares-fall-premarket-93CH-4963206"},{"title":"Why Danaher stock bounced higher today (Motley Fool, 2026-10-21)","url":"https://www.fool.com/investing/2026/10/21/why-danaher-stock-bounced-higher-today/"},{"title":"Danaher 3Q net up sharply as company boosts 2026 adjusted EPS view (MarketScreener)","url":"https://www.marketscreener.com/news/danaher-3q-net-up-sharply-as-company-boosts-2026-adjusted-eps-view-ce785cd8d08eff24"}]},{"id":"autos-2026-tesla-q3-robotaxi-pushout","date":"2026-10-21","end_date":"2026-10-22","sector":"consumer_discretionary","subindustries":["autos"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Tesla trims capex to $20bn and pushes robotaxi and Optimus monetization to 2027; GM narrows guidance","summary":"Tesla's Q3 2026 results beat on EPS but the stock fell 3.1% on October 22, 2026 after management cut the 2026 capex plan to $20bn from $25bn, pushed profit contribution from robotaxi and Optimus to the second half of 2027 and beyond (cumulative unsupervised robotaxi miles rose eightfold to nearly 2 million), disclosed more than $400m of quarterly tariff costs on imported parts and flagged about $2bn of commodity, memory and logistics headwinds for 2027 at a forward multiple above 200x. GM the previous day narrowed 2026 EBIT-adjusted guidance to $14.5-15.5bn with tariff costs at the low end of $2.5-3.5bn, while analysts questioned 2027 pricing.","evidence":"TSLA -3.08% on 2026-10-22; 2026 capex cut to $20bn from $25bn; robotaxi/Optimus monetization pushed to 2H27+; GM 2026 EBIT-adjusted guide narrowed to $14.5-15.5bn on 2026-10-20.","sources":[{"title":"Tesla shares slip despite solid Q3 results as robot monetization pushed to 2027 (BigGo Finance)","url":"https://finance.biggo.com/news/a2d5a057-fc9c-4267-9f38-c4969f9e5819"},{"title":"Tesla vs. Ford: which stock has an edge after Q3 earnings? (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/tesla-vs-ford-stock-edge-143900506.html"},{"title":"General Motors (GM) earnings Q3 2026 (CNBC, 2026-10-20)","url":"https://www.cnbc.com/2026/10/20/general-motors-gm-earnings-q3-2026.html"}]},{"id":"household-2026-pg-defensive-bid","date":"2026-10-22","end_date":null,"sector":"consumer_staples","subindustries":["household_personal"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"P&G jumps 6% on an earnings beat as the AI selloff sends buyers into household staples","summary":"Procter & Gamble rose about 6% on October 22, 2026 after its September-quarter beat, with Johnson & Johnson up 3% and Coca-Cola higher the same day, as investors rotated out of the AI complex into defensive cash generators. The move came after a year in which P&G had guided fiscal 2026 core EPS to $6.83-7.09 and then toward the low end, and in which Colgate (+23% over the trailing year to late October) had outrun P&G (+10%) on gross-margin expansion. Household products, the least-loved staples group of 2023-25, became part of the 2026 record run in XLP.","evidence":"Procter & Gamble +6% on 2026-10-22 after its fiscal Q1 2027 earnings beat.","sources":[{"title":"Procter & Gamble jumps 6% as earnings beat draws defensive buyers (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/10/22/procter-gamble-jumps-6-as-earnings-beat-draws-defensive-buyers-johnson-johnson-rises-3-coca-cola-ticks-up/"},{"title":"PG vs. CL: which household giant deserves your retirement dollars? (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/10/26/pg-vs-cl-which-household-giant-deserves-your-retirement-dollars/"},{"title":"Procter & Gamble fiscal 2026 Q3 earnings release (SEC 8-K exhibit 99.1)","url":"https://www.sec.gov/Archives/edgar/data/0000080424/000008042426000056/fy2526q3jfm8-kexhibit991.htm"}]},{"id":"elec-2026-meta-capex-ai-power-selloff","date":"2026-10-22","end_date":null,"sector":"industrials","subindustries":["electrical_equipment"],"direction":"out","magnitude":"major","driver_type":"positioning","title":"Meta's negative free cash flow and 'no financing plans' hit AI power: GE Vernova -11%, Vertiv -7%, Eaton -6%","summary":"After Meta raised its AI spending outlook on October 21, 2026, reported negative quarterly free cash flow and said it had 'no specific financing plans to announce', electrical-equipment names sold off on October 22: GE Vernova fell 11% to $826.01, Vertiv 7% to $196.42, Eaton 6% to $369.80 and the GRID ETF 4% against a 1.4% drop in SPY. Investors worried that hyperscaler financing strain would slow the long-lead gas-turbine, switchgear and cooling orders that the group's backlogs depend on; over the week through the following Tuesday GE Vernova was down about 11%, Vertiv 14% and Bloom Energy 15%, with hot inflation data and CoreWeave credit stress adding to the pressure.","evidence":"On 2026-10-22: GEV -11% to $826.01, VRT -7% to $196.42, ETN -6% to $369.80, GRID -4% vs SPY -1.43%.","sources":[{"title":"GE Vernova slumps 11% as Meta's spending outlook stokes AI financing worries; Vertiv drops 7%, Eaton slides 6% (24/7 Wall St., 2026-10-22)","url":"https://247wallst.com/investing/2026/10/22/ge-vernova-slumps-11-as-metas-spending-outlook-stokes-ai-financing-worries-vertiv-holdings-drops-7-eaton-slides-6/"},{"title":"GE Vernova sinks 11%, Vertiv 14%, Bloom Energy 15% in a week as AI power stocks slide (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/ge-vernova-sinks-11-vertiv-134456087.html"},{"title":"Ranking 4 AI power stocks by balance sheet after the sell-off (Motley Fool, 2026-10-27)","url":"https://www.fool.com/investing/2026/10/27/ranking-4-ai-power-stocks-by-balance-sheet-after-t/"}]},{"id":"defense-2026-q3-rebound-into-midterms","date":"2026-10-22","end_date":null,"sector":"industrials","subindustries":["defense"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Lockheed's $292bn backlog and second straight guidance raise lift the primes 9% into the midterms","summary":"On October 22, 2026 Lockheed Martin reported Q3 sales of $20.7bn, EPS of $7.97 (+14%), free cash flow of $3.0bn and a record $292bn backlog (+27% in a quarter, including $52.5bn for the PAC-3 MSE interceptor award), and raised 2026 guidance for the second consecutive quarter; 24/7 Wall St. recorded the stock up 9% with RTX +2% and Northrop +3%. Benzinga put Lockheed up about 26% and Northrop 15% for October as strong Q3 prints reversed a two-month election-jitters slump, while drone makers lagged. The rally set up the November 4 reversal when Democrats swept Congress.","evidence":"LMT backlog $292.0bn at 2026-09-30 (+27% q/q); LMT +9%, RTX +2%, NOC +3% on 2026-10-22 per 24/7 Wall St.","sources":[{"title":"Lockheed Martin rises 9% as record backlog lifts outlook; RTX gains 2%, Northrop Grumman advances 3% (24/7 Wall St., 2026-10-22)","url":"https://247wallst.com/investing/2026/10/22/lockheed-martin-rises-9-as-record-backlog-lifts-outlook-rtx-gains-2-northrop-grumman-advances-3/"},{"title":"Lockheed Martin reports third quarter 2026 financial results (Lockheed Martin IR)","url":"https://investors.lockheedmartin.com/news-releases/news-release-details/lockheed-martin-reports-third-quarter-2026-financial-results"},{"title":"Defense stocks rebound into midterms as drone makers lag (Benzinga)","url":"https://www.benzinga.com/markets/equities/26/10/62763999/defense-stocks-rebound-into-midterms-as-drone-makers-lag"}]},{"id":"waste-2026-waste-connections-q3-second-raise","date":"2026-10-22","end_date":null,"sector":"industrials","subindustries":["waste"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Waste Connections soars about 10% on a 'top to bottom beat' and its second 2026 guidance raise","summary":"On October 22, 2026 Waste Connections reported Q3 revenue of $2.638bn and adjusted EPS of $1.58 (vs $1.52 expected, $1.44 a year earlier) with a 34% adjusted EBITDA margin and 5.5% core pricing, raised its 2026 outlook for the second time to about $10.09bn of revenue, $3.345bn of EBITDA and at least $1.4bn of free cash flow, and lifted its payout. The stock rose about 10% in the afternoon session toward a 52-week high as investors rotated into defensive compounders during the AI-power selloff.","evidence":"WCN +~10% on 2026-10-22; Q3 adjusted EPS $1.58 vs $1.52 consensus; 2026 revenue outlook raised to ~$10.09bn.","sources":[{"title":"Waste Connections soars 10% on raised 2026 outlook after 'another top to bottom beat' (TIKR)","url":"https://www.tikr.com/blog/waste-connections-soars-10-on-raised-2026-outlook-after-another-top-to-bottom-beat"},{"title":"Waste Connections reports third quarter 2026 results and raises full year outlook (Nasdaq)","url":"https://www.nasdaq.com/press-release/waste-connections-reports-third-quarter-2026-results-and-raises-full-year-outlook"},{"title":"Why Waste Connections stock is up today (Motley Fool, 2026-10-22)","url":"https://www.fool.com/investing/2026/10/22/why-waste-connections-stock-is-up-today/"}]},{"id":"ind-2026-boeing-737-ramp-delay","date":"2026-10-27","end_date":"2026-11-06","sector":"industrials","subindustries":["commercial_aerospace"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Boeing pushes the 737 ramp out a year; stock drops 10% to a 52-week low","summary":"With Q3 2026 results Boeing said it will miss its ~500-jet 2026 737 delivery target, that stabilizing at 47 a month will slip into 2027 (52/month in 2H27), and guided free cash flow to just $2bn in 2026 and $3bn in 2027 versus consensus above $5bn; the stock fell 10-11% on October 27 and is down about 21% for 2026 against an S&P 500 up 8%. 777X certification is still targeted for mid-2027.","evidence":"BA -10.7% on Oct 27, 2026; FCF guide $2bn (2026) / $3bn (2027) vs Visible Alpha consensus $5.3bn for 2027; BA -20.6% YTD at Nov 5, 2026","sources":[{"title":"Motley Fool: Boeing stock slumps again (Oct 31, 2026)","url":"https://www.fool.com/investing/2026/10/31/boeing-stock-slumps-again-time-to-buy-or-throw-in/"},{"title":"Stocktwits: BA drops over 5% after CEO says 737 production still not stable","url":"https://stocktwits.com/news-articles/markets/equity/boeing-stock-drops-over-5-percent-after-ceo-says-737-production-is-still-not-stable-777x-deliveries-still-on-track-for-2027/cZtYt70RBPY"},{"title":"ChartRow BA calendar-year returns","url":"https://chartrow.com/quote/ba/returns"}]},{"id":"net-lease-2026-realty-income-five-percent-tens","date":"2026-10-27","end_date":null,"sector":"real_estate","subindustries":["net_lease_specialty_reits"],"direction":"out","magnitude":"minor","driver_type":"rates","title":"Net lease vs a 5% ten-year: Realty Income's dividend yield converges on Treasuries","summary":"Into its Q3 2026 report Realty Income yielded about 5.9% at $55 with the 10-year Treasury between 5.0% and 5.2% after the Fed's September hike, leaving almost no spread for the 'bond proxy' trade. The company kept buying (Q2 acquisitions at a 7.3% initial cash yield, 2026 volume target raised to $10bn from $9.5bn, and a push into private capital), but with its own cost of capital rising the 150bp target spread was thinning and the stock lagged the REIT index through the autumn. Net lease was the clearest casualty of the 2026 term-premium shock after mortgage REITs.","evidence":"Realty Income 2026 investment-volume target raised to $10.0bn from $9.5bn; Q2 2026 acquisitions at a 7.3% initial cash yield.","sources":[{"title":"Realty Income Q3 earnings: will rising Treasury yields break 'The Monthly Dividend Company'? (24/7 Wall St.)","url":"https://247wallst.com/investing/2026/10/27/realty-income-q3-earnings-will-rising-treasury-yields-break-the-monthly-dividend-company/"},{"title":"Realty Income Q2 2026 slides: $89B REIT eyes $15T market via private capital (Investing.com)","url":"https://ng.investing.com/news/company-news/realty-income-q2-2026-slides-89b-reit-eyes-15t-market-via-private-capital-93CH-2641529"},{"title":"Realty Income Form 10-Q for the quarter ended June 30, 2026 (SEC)","url":"https://www.sec.gov/Archives/edgar/data/0000726728/000072672826000048/o-20260630.htm"}]},{"id":"transport-2026-ups-q3-beat-raise","date":"2026-10-27","end_date":null,"sector":"industrials","subindustries":["transportation"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"UPS rises 5.8% on a Q3 2026 beat and raised full-year outlook; FedEx inches higher","summary":"UPS reported Q3 2026 adjusted EPS of $1.69 against $1.62 expected on revenue of $22.9bn ($22.3bn expected) on October 27, 2026 and raised its full-year outlook to about $92.6bn of revenue, $8.75bn of adjusted operating profit and $7.28 of adjusted EPS. Shares rose 5.8% against a 0.6% gain for the S&P 500, their largest move since the 6.6% drop after Q2, and FedEx gained about 2% ahead of its own report. The print suggested the Amazon glide-down and network reconfiguration were finally showing up in margins rather than just volume losses.","evidence":"UPS +5.8% on 2026-10-27; Q3 adjusted EPS $1.69 vs $1.62 consensus; FY26 adjusted EPS guide ~$7.28.","sources":[{"title":"UPS rises 5% as Q3 beat lifts full-year outlook; FedEx inches higher (24/7 Wall St., 2026-10-27)","url":"https://247wallst.com/investing/2026/10/27/ups-rises-5-as-q3-beat-lifts-full-year-outlook-fedex-inches-higher/"},{"title":"What sent UPS stock higher? (Trefis, 2026-10-28)","url":"https://www.trefis.com/stock/ups/articles/621061/what-sent-ups-stock-higher/2026-10-28"},{"title":"UPS Q3 2026 earnings press release (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0001090727/000162828026067381/exhibit991-earningspressre.htm"}]},{"id":"waste-2026-wm-q3-miss-ceo-transition","date":"2026-10-27","end_date":null,"sector":"industrials","subindustries":["waste"],"direction":"out","magnitude":"minor","driver_type":"earnings","title":"Waste Management slips 3% on a Q3 2026 EPS miss as Republic and Waste Connections raise","summary":"Waste Management reported Q3 2026 revenue of $6.846bn and adjusted EPS of $2.15, a cent or so short of consensus, and merely affirmed 2026 guidance (revenue and free cash flow at the high end of $26.275-26.475bn and $3.75-3.85bn, EBITDA within $8.15-8.25bn) on October 27, 2026; the stock fell about 3.2% to $228.36 the next session. The muted print contrasted with Waste Connections' raise five days earlier and Republic's guidance raise and $5bn buyback two days later, and came as CEO Jim Fish prepared to hand over to John Morris in January.","evidence":"Q3 2026 revenue $6,846m, adjusted EPS $2.15 (GAAP $2.05) per 2026-10-27 release; WM -3.16% to $228.36 on 2026-10-28.","sources":[{"title":"Waste Management Q3 2026 earnings release (SEC 8-K, 2026-10-27)","url":"https://www.sec.gov/Archives/edgar/data/0000823768/000110465926119188/tm2628322d1_ex99-1.htm"},{"title":"Waste Management earnings analysis: questions answered and next catalysts (Investing.com)","url":"https://www.investing.com/news/stock-market-news/waste-management-earnings-analysis-questions-answered-and-next-catalysts-93CH-4980282"},{"title":"Waste Management's Q3 2026: beats on revenue (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/waste-management-nyse-wm-q3-205241569.html"}]},{"id":"facilities-2026-hca-q3-upper-half","date":"2026-10-27","end_date":null,"sector":"healthcare","subindustries":["healthcare_facilities_services"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"HCA beats Q3 2026 and points to the upper half of its cut guidance; Tenet slips 2.6%","summary":"On October 27, 2026 HCA reported Q3 EPS of $7.22 against a $6.65 consensus on revenue of $19.85bn (+3.6%) and said full-year results would land in the upper half of the ranges set on July 14, stabilising the hospital group after the summer's exchange-coverage shock. Tenet closed down 2.6% at $262.05 the same day, so the relief was HCA-specific rather than a group re-rating, with investors still weighing uninsured volumes and 2027 site-neutral and Medicaid policy under a Democratic Congress.","evidence":"HCA Q3 2026 EPS $7.22 vs $6.65 consensus; revenue $19.85bn; THC -2.57% to $262.05 on 2026-10-27.","sources":[{"title":"HCA Healthcare Q3 2026 results (SEC 8-K, 2026-10-27)","url":"https://www.sec.gov/Archives/edgar/data/0000860730/000119312526432665/hca-ex99_1.htm"},{"title":"HCA Healthcare (HCA) earnings date and reports (MarketBeat)","url":"https://www.marketbeat.com/stocks/NYSE/HCA/earnings/"},{"title":"Tenet Healthcare (THC) stock price: Oct 27 close $262.05 (HeyGoTrade)","url":"https://www.heygotrade.com/en/us-stock/thc/"}]},{"id":"travel-2026-royal-caribbean-q3-raise","date":"2026-10-27","end_date":null,"sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Royal Caribbean rises about 6% on a Q3 beat and a 2026 EPS outlook of $17.85-17.95","summary":"On October 27, 2026 Royal Caribbean reported Q3 adjusted EPS of $6.57 against a $6.38 consensus on revenue of $5.6bn (+9%) and raised full-year adjusted EPS guidance to $17.85-17.95, and the stock rose about 6.3% in early trading (up to 7.5% intraday) despite Q4 guidance that trailed estimates. With Carnival having also beaten ($1.43 vs $1.35) but carrying a $150m unhedged fuel hit, the print showed cruise demand absorbing the 2026 oil shock far better than airlines, which were cutting guidance on the same jet-fuel costs.","evidence":"RCL +6.3% early on 2026-10-27; Q3 adjusted EPS $6.57 vs $6.38 consensus; 2026 adjusted EPS guide $17.85-17.95.","sources":[{"title":"Royal Caribbean shares rise 6.3% as Q3 earnings beat estimates and 2026 profit guidance increases (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/royal-caribbean-shares-rise-6-142904290.html"},{"title":"Royal Caribbean Group reports third quarter results above expectations and raises full year guidance (PR Newswire)","url":"https://www.prnewswire.com/news-releases/royal-caribbean-group-reports-third-quarter-results-above-expectations-and-raises-full-year-guidance-302920572.html"},{"title":"Earnings call transcript: Royal Caribbean tops profit view in Q3 2026, shares jump (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-royal-caribbean-tops-profit-view-in-q3-2026-shares-jump-93CH-4976286"}]},{"id":"elec-2026-vertiv-ge-vernova-q3-split","date":"2026-10-28","end_date":null,"sector":"industrials","subindustries":["electrical_equipment"],"direction":"mixed","magnitude":"major","driver_type":"earnings","title":"Q3 2026 AI-power earnings split: Vertiv +13% on 61% sales growth, GE Vernova -6% on a $9bn Trench deal","summary":"On October 28, 2026 Vertiv reported Q3 net sales of $4.313bn (+61%), orders more than doubled, and raised full-year sales guidance by $650m; the stock rose about 13% to $236. GE Vernova the same day beat with adjusted EPS of $4.81, raised guidance, reported a $197bn backlog and doubled its buyback authorization, but fell about 6% (as much as 11% intraday before recovering) as investors balked at the roughly $9bn half-cash, half-debt acquisition of Trench Group that will not close until late 2027. Eaton and Quanta ticked up, showing the trade had become selective about which AI-power balance sheets to own after the previous week's selloff.","evidence":"VRT +~13% on 2026-10-28 with Q3 net sales $4,313m (+61%) and FY sales guide raised $650m; GEV -6% despite adjusted EPS $4.81 and $197bn backlog.","sources":[{"title":"GE Vernova falls 6% despite beat, raise and $9B Trench deal; Vertiv soars 13%, Eaton and Quanta tick up (24/7 Wall St., 2026-10-28)","url":"https://247wallst.com/investing/2026/10/28/ge-vernova-falls-6-despite-beat-raise-and-9b-trench-deal-vertiv-holdings-soars-13-eaton-and-quanta-services-tick-up/"},{"title":"Vertiv Q3 2026 earnings release (SEC 8-K, 2026-10-28)","url":"https://www.sec.gov/Archives/edgar/data/0001674101/000162828026067707/q32026exhibit991vrt10282026.htm"},{"title":"GE Vernova stock rebounds, AI sell-off gives way to earnings focus (Benzinga)","url":"https://www.benzinga.com/trading-ideas/movers/26/10/62557401/ge-vernova-stock-rebounds-ai-sell-off-gives-way-to-earnings-focus"}]},{"id":"meddev-2026-boston-scientific-third-cut-cyberattack","date":"2026-10-28","end_date":null,"sector":"healthcare","subindustries":["medical_devices"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Boston Scientific's third 2026 guidance cut: an August cyberattack costs $150m and Q4 sales are guided down","summary":"On October 28, 2026 Boston Scientific reported Q3 revenue of $5.14bn (+1.5%) after a cyberattack that began on August 25 shut down ordering, manufacturing and shipping and cost an estimated $150m of sales, and cut 2026 guidance for the third time this year: reported revenue growth to 4.25% (from 5.5-6.5%), adjusted EPS to $3.16-3.18 (from $3.28-3.32), with Q4 sales guided to decline 1-3%. Shares fell nearly 7% to $42.02 at the open (as much as 12% intraday by other accounts). The company had already cut in April and July on electrophysiology and Watchman weakness, so the business was slowing before the attack.","evidence":"2026 adjusted EPS guide cut to $3.16-3.18 from $3.28-3.32 on 2026-10-28; Q3 revenue $5.14bn (+1.5%); BSX -~7% to $42.02 at the open.","sources":[{"title":"Boston Scientific cuts 2026 guidance for third time this year (MedTech Dive, 2026-10-28)","url":"https://www.medtechdive.com/news/boston-scientific-cuts-2026-guidance-for-third-time-this-year/873037/"},{"title":"Boston Scientific sinks 12% as cyberattack forces guidance cut (TIKR)","url":"https://www.tikr.com/blog/boston-scientific-sinks-12-as-cyberattack-forces-guidance-cut-a-challenging-year"},{"title":"BSX Q3 results reset growth expectations as 2027 outlook stays weak (Yahoo Finance)","url":"https://finance.yahoo.com/healthcare/articles/bsx-q3-results-reset-growth-135500158.html"}]},{"id":"internet-2026-alphabet-fcf-plunge","date":"2026-10-29","end_date":null,"sector":"technology","subindustries":["internet_platforms"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Alphabet -13% ($490 billion) on a second quarter of negative free cash flow","summary":"Alphabet fell about 13% on 29 October 2026, erasing roughly $490 billion, after Q3 capex of $51.4 billion exceeded operating cash flow of $42.3 billion for a second straight quarter of negative free cash flow, search advertising missed and a one-off fine hit results, even though cloud revenue nearly doubled. Communication services, the best sector of 2024 and 2025, became the worst of 2026 (XLC -10.6% year-to-date on 5 November, the worst October performer).","evidence":"Alphabet -13% on 2026-10-29 (about $490 billion); Q3 2026 capex $51.4 billion vs operating cash generation $42.3 billion; XLC -10.6% year-to-date as of 2026-11-05.","sources":[{"title":"The 'shadow of credit' creeping into the AI trade: Alphabet's plunge and CoreWeave's woes (BigGo Finance, 2026-11-05)","url":"https://finance.biggo.com/news/d47a9f4c-786a-452e-b8c3-0b0d6e8b9ade"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"id":"waste-2026-republic-guidance-raise","date":"2026-10-29","end_date":null,"sector":"industrials","subindustries":["waste"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Republic Services raises 2026 guidance and authorises a $5bn buyback as waste reclaims its defensive bid","summary":"Republic Services reported Q3 2026 adjusted EPS of $1.94 (vs $1.90 a year earlier) on October 29, 2026, raised full-year revenue guidance to $17.425-17.475bn and adjusted EBITDA to $5.55-5.575bn, and approved a $5bn repurchase authorisation starting January 1, 2027. Waste Management reaffirmed its guidance with revenue at the high end of $26.275-26.475bn and $2bn of 2026 buybacks. With the 10-year above 5% and the AI complex selling off into the midterms, pricing-led haulers regained the low-volatility bid they had lost during the 2025 risk-on summer.","evidence":"Republic Services 2026 adjusted EBITDA guidance raised to $5.550-5.575bn; $5bn buyback authorised from 2027-01-01.","sources":[{"title":"Republic Services reports third quarter 2026 results (Republic Services IR)","url":"https://investor.republicservices.com/news-releases/news-release-details/republic-services-inc-reports-third-quarter-2026-results"},{"title":"Waste Management Q3 2026 earnings release (SEC 8-K exhibit 99.1)","url":"https://www.sec.gov/Archives/edgar/data/0000823768/000110465926119188/tm2628322d1_ex99-1.htm"},{"title":"Republic Services raises fiscal 2026 revenue guidance on Oct. 29 (GuruFocus)","url":"https://www.gurufocus.com/news/9158490/republic-services-raises-fiscal-2026-revenue-guidance-on-oct-29"}]},{"id":"machinery-2026-caterpillar-q3-capacity-selloff","date":"2026-10-29","end_date":null,"sector":"industrials","subindustries":["machinery"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"Caterpillar falls about 8% on a Q3 2026 beat as capacity limits and a cautious Q4 outlook cap the AI-power story","summary":"Caterpillar's Q3 2026 sales rose 17% to $20.7bn with adjusted EPS of $7.20 (vs about $7.05 expected) and a record $78.1bn backlog, but the stock fell roughly 8% on October 29, 2026 (about -7.7% premarket to $658.84). Management said Power & Energy capacity is still limiting growth, that full-year guidance was unchanged, and that margins ex tariff recoveries would sit near the bottom of the target range; it plans to triple large-engine output by 2030. A Zacks note later put the post-earnings drawdown at roughly 17%.","evidence":"CAT -~8% on 2026-10-29 despite adjusted EPS $7.20 and record $78.1bn backlog; adjusted operating margin 20.6%.","sources":[{"title":"Earnings call transcript: Caterpillar tops Q3 2026 estimates, shares drop (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-caterpillar-tops-q3-2026-estimates-shares-drop-93CH-4984633"},{"title":"Caterpillar sales up 17%, margin hits 20.4%: rapid earnings reaction (Motley Fool, 2026-10-29)","url":"https://www.fool.com/investing/2026/10/29/caterpillar-sales-up-17-margin-hits-20-4-rapid-earnings-reaction/"},{"title":"CAT shares fall despite Q3 earnings beat (Zacks via TradingView)","url":"https://www.tradingview.com/news/zacks:b4c459939094b:0-cat-shares-fall-despite-q3-earnings-beat-how-to-play-the-stock/"}]},{"id":"housing-2026-dr-horton-fq4-orders-down","date":"2026-10-29","end_date":null,"sector":"consumer_discretionary","subindustries":["housing"],"direction":"out","magnitude":"moderate","driver_type":"earnings","title":"D.R. Horton misses as orders fall 7% and guides fiscal Q1 revenue well below consensus; Raymond James downgrades","summary":"D.R. Horton reported fiscal Q4 2026 EPS of $2.67 against about $3.01-3.03 expected on October 29, 2026 (revenue $9.4bn beat), with net income down 18% to $741.8m including $91.4m of rental-segment impairments, net sales orders down 7% to 18,619 homes (-9% in value) and fiscal Q1 revenue guided to $5.9-6.4bn versus a $6.96bn consensus as mortgage rates above 7% after the Fed's September hike squeezed affordability. Shares fell about 4.2% despite an 11% dividend increase and a $3bn buyback plan, and Raymond James cut the stock to Underperform.","evidence":"Fiscal Q4 2026 EPS $2.67 vs ~$3.01 consensus; net orders -7% to 18,619; DHI -4.2% on 2026-10-29.","sources":[{"title":"D.R. Horton reports Q4 earnings below estimates despite $9.4 billion revenue, shares fall 4.2% (Yahoo Finance)","url":"https://finance.yahoo.com/real-estate/articles/d-r-horton-reports-q4-145619903.html"},{"title":"D.R. Horton reports fourth quarter and fiscal 2026 earnings (Business Wire, 2026-10-28)","url":"https://www.businesswire.com/news/home/20261028498589/en/D.R.-Horton-Inc.-Americas-Builder-Reports-Fourth-Quarter-and-Fiscal-2026-Earnings-and-Increases-Quarterly-Dividend-to-$0.50-Per-Share"},{"title":"Raymond James downgrades D.R. Horton stock rating on valuation concerns (Investing.com)","url":"https://investing.com/news/analyst-ratings/raymond-james-downgrades-dr-horton-stock-rating-on-valuation-concerns-93CH-4993860"}]},{"id":"internet-retail-2026-amazon-q3-negative-fcf","date":"2026-10-29","end_date":"2026-10-30","sector":"consumer_discretionary","subindustries":["internet_retail"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Amazon posts $42bn of negative trailing free cash flow and misses on EPS; shares drop 6-7%","summary":"Amazon's Q3 2026 revenue of $201.9bn and EPS of $1.89 (vs $1.96 expected) came in slightly short on October 29, 2026 even as operating income rose 61% and AWS grew 39.3% to $46bn; trailing-twelve-month free cash flow was -$42.4bn, the second straight negative quarter, as 2026 capex was held at $220bn. Shares fell 4.25% in the regular session to $243.79 and another 6-7% in extended and premarket trading toward $226, with the retail and advertising units flagged as weak spots. The print, a week after Alphabet's own cash-flow shock, made AI capex the dominant driver for the internet-retail bucket.","evidence":"Q3 2026 EPS $1.89 vs $1.96 consensus; TTM free cash flow -$42.4bn; AMZN -6% to -7% in extended/premarket trading after 2026-10-29.","sources":[{"title":"Amazon posts negative free cash flow of $42.4 billion, holds 2026 capex unchanged (CNBC, 2026-10-29)","url":"https://www.cnbc.com/2026/10/29/amazon-amzn-q3-earnings-report-2026.html"},{"title":"Earnings call transcript: Amazon Q3 2026 misses EPS as shares fall after hours (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-amazon-q3-2026-misses-eps-as-shares-fall-after-hours-93CH-4985489"},{"title":"Amazon stock fell after earnings. Should investors be worried? (Motley Fool, 2026-11-04)","url":"https://www.fool.com/investing/2026/11/04/amazon-stock-fell-after-earnings-should-investors/"}]},{"id":"re-2026-1029-cubesmart-heitman-jv-q3","date":"2026-10-29","end_date":null,"sector":"real_estate","subindustries":["self_storage_reits"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"CubeSmart forms $197M Heitman venture to recycle capital into buybacks; Q3 occupancy up","summary":"With its Q3 2026 results on October 29, 2026 CubeSmart announced it would contribute 15 stores (about 900,000 sq ft) to a $197M joint venture with Heitman, retaining 20%, to free capital for share repurchases (it had already bought back 2.1M shares for $83.9M in the quarter) rather than buy stabilized assets at private-market prices. Same-store NOI rose 2.1% and revenue 1.9% with occupancy at 89.9% vs 89.0% a year earlier, and 2026 adjusted FFO guidance was set at $2.58-$2.60. The transaction extends the 2026 self-storage consolidation/capital-recycling theme (PSA-NSA in March, CUBE's $250M CBRE IM venture in February) and underlines that public storage REITs see their own shares as cheaper than private deals.","evidence":"CubeSmart Q3 2026 release of 2026-10-29: $197M 15-property Heitman JV (CubeSmart keeps 20%); same-store NOI +2.1%, occupancy 89.9% vs 89.0%.","sources":[{"title":"CubeSmart Plans $197M Storage Venture With Heitman (WRE News, Oct 30 2026)","url":"https://wrenews.com/cubesmart-q3-2026-197-million-storage-joint-venture-heitman/"},{"title":"CubeSmart taps Heitman venture to unlock cash, fund stock buybacks (CoStar)","url":"https://www.costar.com/article/1767870154/cubesmart-taps-heitman-venture-to-unlock-cash-fund-stock-buybacks"}]},{"id":"software-2026-servicenow-q3-record-drop","date":"2026-10-29","end_date":null,"sector":"technology","subindustries":["application_software"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"ServiceNow falls 27%, its worst day ever, on Q3 2026 print","summary":"ServiceNow reported Q3 2026 revenue of $4.11bn (+20.5% y/y, in line) but adjusted EPS of $1.00 missed the $1.02 consensus, and the stock fell 27% on 2026-10-29, its largest single-day drop on record. Citi's Tyler Radke cited 'the lack of upside' as uncharacteristic, and the print revived SaaSpocalypse fears that AI agents are eroding seat-based enterprise software economics, weighing on application-software peers into the November selloff.","evidence":"NOW -27% on 2026-10-29; adjusted EPS $1.00 vs $1.02 est.","sources":[{"title":"CNBC: ServiceNow (NOW) earnings Q3 2026","url":"https://www.cnbc.com/2026/10/29/servicenow-now-earnings-q3-2026.html"},{"title":"Investing.com: ServiceNow Q3 2026 revenue beats, shares sink after hours","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-servicenow-q3-2026-revenue-beats-shares-sink-after-hours-93CH-4981127"}]},{"id":"semis-2026-intel-pc-shock","date":"2026-10-30","end_date":null,"sector":"technology","subindustries":["semiconductors","hardware","memory"],"direction":"out","magnitude":"major","driver_type":"earnings","title":"Intel's PC warning drops the semiconductor index 7% in a day","summary":"On Friday 30 October 2026 Intel guided well below expectations because of a declining PC market (memory inflation had pushed Gartner and IDC to forecast 2026 PC shipments down 10-11%), and the Philadelphia semiconductor index fell 7% in one session with Nvidia down more than 4% and Broadcom and Micron also lower. The print showed the consumer side of the chip market deteriorating even as AI revenue kept compounding (Nvidia fiscal 2027 revenue expected near $412 billion, +90%).","evidence":"Philadelphia Semiconductor Index -7% on 2026-10-30 after Intel's guidance; Nvidia -4% that day.","sources":[{"title":"Semiconductor sell-off: the best chip stocks to buy right now (Motley Fool, 2026-11-04)","url":"https://www.fool.com/investing/2026/11/04/semiconductor-sell-off-the-best-chip-stocks-to-buy-right-now-before-they-skyrocket-once-again/"},{"title":"2025-present global memory supply shortage (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025%E2%80%93present_global_memory_supply_shortage"}]},{"id":"hctech-2026-tempus-q3-ebitda-positive","date":"2026-11-02","end_date":null,"sector":"healthcare","subindustries":["healthcare_technology"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Tempus turns adjusted-EBITDA positive and clears the Personalis deal; stock holds near $71 after a 22% year","summary":"On November 2, 2026 Tempus AI reported Q3 revenue of $411.5m (+23%), adjusted EPS of $0.07 against $0.01 expected and its first quarter of positive adjusted EBITDA ($25.6m), raised full-year revenue guidance and said regulators had cleared the Personalis acquisition ahead of a November 30 shareholder vote. Shares edged down 1.35% to $71.25 after a 31% six-month run that left the stock up 22% for 2026. The report confirmed that AI-enabled diagnostics, not telehealth, had become the profitable end of health-care technology.","evidence":"Q3 2026 revenue $411.5m (+23%), adjusted EBITDA +$25.6m (first positive quarter); TEM -1.35% to $71.25 on 2026-11-02.","sources":[{"title":"Earnings call transcript: Tempus AI beats Q3 2026 EPS forecast, lifts outlook (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-tempus-ai-beats-q3-2026-eps-forecast-lifts-outlook-93CH-4992054"},{"title":"Tempus AI Q3 2026 results (SEC 8-K)","url":"https://www.sec.gov/Archives/edgar/data/0001717115/000119312526442619/tem-ex99_1.htm"}]},{"id":"travel-2026-cruise-oil-drop-rally","date":"2026-11-02","end_date":null,"sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"in","magnitude":"minor","driver_type":"commodity","title":"Cruise lines rally 4-5% as oil prices drop; Carnival's unhedged fuel bill makes it the high-beta play","summary":"On November 2, 2026 Carnival and Royal Caribbean rose about 5% and Norwegian 4% as crude fell, repeating an October 20 session in which the three gained about 3% while energy shares slipped. Carnival does not hedge fuel and had built a $150m fuel impact into guidance, so it trades as the most direct beneficiary of any retreat in the 2026 oil shock; RCL was up about 17% year to date at $321.77 while CCL was roughly flat near $30, showing how fuel sensitivity had split the group.","evidence":"On 2026-11-02: CCL +~5%, RCL +~5%, NCLH +~4% as oil prices fell; CCL ~+0.7% YTD vs RCL +17% YTD.","sources":[{"title":"Carnival and Royal Caribbean climb 5%, Norwegian Cruise Line rises 4% as oil prices drop (24/7 Wall St., 2026-11-02)","url":"https://247wallst.com/investing/2026/11/02/carnival-and-royal-caribbean-climb-5-norwegian-cruise-line-rises-4-as-oil-prices-drop/"},{"title":"Cruise stocks rally while energy shares slip: Norwegian, Royal Caribbean and Carnival rise 3% (24/7 Wall St., 2026-10-20)","url":"https://247wallst.com/investing/2026/10/20/cruise-stocks-rally-while-energy-shares-slip-norwegian-royal-caribbean-and-carnival-rise-3/"}]},{"id":"re-2026-1102-kimco-louisville-acquisition-guidance","date":"2026-11-02","end_date":null,"sector":"real_estate","subindustries":["retail_reits"],"direction":"in","magnitude":"minor","driver_type":"ma","title":"Kimco buys two grocery-anchored Louisville centers for $295M alongside higher guidance and a dividend raise","summary":"On November 2, 2026 Kimco Realty announced the $295 million acquisition of Paddock Shops and Shelbyville Road Plaza, two Trader Joe's/Fresh Market-anchored open-air centers totalling more than 741,000 sq ft in Louisville's East End, funded primarily with 1031 exchange proceeds from 2026 dispositions (self-funded and leverage-neutral), with NOI underwritten to grow ~4% a year. Coverage on November 3 tied the deal to Kimco's raised full-year earnings guidance and a larger common dividend; Simply Wall St noted KIM shares up 6.0% over the prior seven days and about 25% year-to-date, consistent with the grocery-anchored resilience trade.","evidence":"$295M purchase of 741,000+ sq ft of grocery-anchored centers announced 2026-11-02; KIM +6.0% over the prior seven days per Simply Wall St (2026-11-03).","sources":[{"title":"GlobeNewswire via Manila Times: Kimco Realty Acquires Two Dominant Grocery-Anchored Centers in Louisville","url":"https://www.manilatimes.net/2026/11/03/tmt-newswire/globenewswire/kimco-realty-acquires-two-dominant-grocery-anchored-centers-in-louisville/2460136"},{"title":"Simply Wall St: Is Kimco Realty (KIM) A Bargain On Its Acquisition, Higher Guidance, And Dividend Raise?","url":"https://simplywall.st/stocks/us/real-estate/nyse-kim/kimco-realty/news/is-kimco-realty-kim-a-bargain-on-its-acquisition-higher-guid"},{"title":"Connect CRE: Kimco Realty Completes $295M Acquisition of Louisville Retail Centers","url":"https://www.connectcre.com/stories/kimco-realty-completes-295m-acquisition-of-louisville-retail-centers/"}]},{"id":"tech-2026-midterm-selloff","date":"2026-11-03","end_date":null,"sector":"technology","subindustries":["semiconductors","internet_platforms","infrastructure_software_cyber","hardware","memory"],"direction":"out","magnitude":"major","driver_type":"election","title":"Midterm 'blue tsunami' and data-center moratorium risk deepen the tech selloff","summary":"Democrats won the House and Senate on 3 November 2026, flipping seven Republican Senate seats, and journalists read the result partly as a rebuke of further AI build-out; Goldman Sachs estimated possible moratoria could affect 45% of planned US data-center capacity (Texas, Ohio, Georgia), Nvidia's CDS rose 76% in a month to about 139 bp and Nvidia was reported down about 9% (more than $400 billion) in a single post-election session. XLK was down 19.2% over the month to 5 November 2026 while staples (+12.6%) and health care (+10.5%) absorbed the rotation; the Nasdaq's record close of 27,599.89 on 6 October 2026 marks the top.","evidence":"XLK total return -19.2% over the one month to 2026-11-05 (ChartRow); Nvidia five-year CDS up 76% in a month to about 139 bp (CNBC, 2026-11-06).","sources":[{"title":"CoreWeave bond yield tops 16% as AI credit stress rises (CNBC, 2026-11-06)","url":"https://www.cnbc.com/2026/11/06/coreweave-bond-yield-tops-16percent-as-ai-credit-stress-rises.html"},{"title":"2026 United States elections (Wikipedia)","url":"https://en.wikipedia.org/wiki/2026_United_States_elections"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"},{"title":"AI bubble about to burst? Top tech investor warns most neocloud players could go to zero (Benzinga, Nov 2026)","url":"https://www.benzinga.com/markets/tech/26/11/62968934/ai-bubble-about-to-burst-top-tech-investor-warns-most-neocloud-players-could-go-to-zero"},{"title":"Nasdaq Composite (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"}]},{"id":"ind-2026-midterm-defense-selloff","date":"2026-11-04","end_date":"2026-11-05","sector":"industrials","subindustries":["defense"],"direction":"out","magnitude":"moderate","driver_type":"election","title":"Democratic sweep of Congress sinks defense primes","summary":"Democrats won both chambers on November 3, 2026 and the $1.5 trillion FY2027 request was immediately judged dead; on November 4 Lockheed fell 6.9% (worst day since July 2025), L3Harris 6.5%, Northrop 4.5% and RTX 2.6%, while ITA fell only about 2% because commercial-aerospace holdings cushioned it. Jefferies expects the final number to land near the House's $1.15 trillion; TD Cowen called Golden Dome effectively dead.","evidence":"LMT -6.88%, LHX -6.46%, NOC -4.53%, RTX -2.64% on Nov 4, 2026; ITA -1.5% to -2%","sources":[{"title":"24/7 Wall St: Defense stocks sank as Democrats took Congress","url":"https://247wallst.com/investing/2026/11/05/defense-stocks-sank-as-democrats-took-congress-and-the-1-5-trillion-budget-looks-doomed/"},{"title":"US News: Defense firms fall as Democratic victory stokes fears of tighter Pentagon budget","url":"https://www.usnews.com/news/top-news/articles/2026-11-04/defense-firms-fall-as-democratic-victory-stokes-fears-of-tighter-pentagon-budget"}]},{"id":"en-2026-midterm-clean-energy-rally","date":"2026-11-04","end_date":"2026-11-06","sector":"energy","subindustries":["new_energy_power"],"direction":"in","magnitude":"moderate","driver_type":"election","title":"Democratic sweep revives clean-energy hopes","summary":"The November 3, 2026 midterms gave Democrats both chambers and traders bet on restoration of the solar credits curbed by the 2025 tax law: First Solar and Enphase rose 9% and Sunrun 8% on November 4. The rebound is from a low base (First Solar -23% and Sunrun -49% year to date) and a presidential veto remains the obstacle, with Kalshi pricing only a 28% chance of a veto override before 2028.","evidence":"FSLR +9%, ENPH +9%, RUN +8% on Nov 4, 2026; FSLR -23% and RUN -49% YTD","sources":[{"title":"24/7 Wall St: First Solar jumps 9% as Democratic sweep revives clean-energy hopes","url":"https://247wallst.com/investing/2026/11/04/first-solar-jumps-9-as-democratic-sweep-revives-clean-energy-hopes-enphase-surges-9-solaredge-sinks-8/"},{"title":"ChartRow FSLR calendar-year returns","url":"https://chartrow.com/quote/fslr/returns"}]},{"id":"distribution-2026-q3-earnings-dispersion","date":"2026-11-04","end_date":null,"sector":"industrials","subindustries":["industrial_distribution"],"direction":"mixed","magnitude":"minor","driver_type":"earnings","title":"Q3 2026 distribution earnings: Grainger +8% on a guidance raise while United Rentals and Fastenal slip on beats","summary":"W.W. Grainger rose about 7.8% on November 4, 2026 after reporting adjusted EPS of $12.54 (+22.8%) and lifting full-year guidance, a rare rally in an industrial tape dominated by the post-midterm tech selloff. United Rentals fell about 1.4% despite record Q3 results and higher guidance as investors questioned margin durability and elevated fleet capex, and Fastenal slipped 2% on 15.5% revenue growth after losing nearly 7% on its Q1 report. The dispersion shows the market rewarding self-help pricing and share gains in MRO while discounting capital-intensive rental growth at premium multiples.","evidence":"Grainger Q3 2026 adjusted EPS $12.54, +22.8% y/y; shares +7.8% intraday on 2026-11-04.","sources":[{"title":"Grainger earnings rally raises the valuation hurdle (FinChannel)","url":"https://finchannel.com/grainger-earnings-rally-raises-the-valuation-hurdle/140540/american-business-trends/2026/11/"},{"title":"Earnings call transcript: W.W. Grainger tops Q3 2026 estimates, lifts outlook (Investing.com)","url":"https://uk.investing.com/news/stock-market-news/earnings-call-transcript-ww-grainger-tops-q3-2026-estimates-lifts-outlook-93CH-4957972"},{"title":"Earnings call transcript: United Rentals tops Q3 2026 forecasts but shares slip (Investing.com)","url":"https://www.investing.com/news/transcripts/earnings-call-transcript-united-rentals-tops-q3-2026-forecasts-but-shares-slip-93CH-4966497"}]},{"id":"biotech-smid-2026-astrazeneca-rhythm-bid","date":"2026-11-04","end_date":null,"sector":"healthcare","subindustries":["biotech_smid"],"direction":"in","magnitude":"moderate","driver_type":"ma","title":"Rhythm Pharmaceuticals jumps 28% on reports of a $10bn AstraZeneca approach","summary":"On November 4, 2026 Rhythm Pharmaceuticals closed up 28% at $110.68 (market value about $7.64bn), its best day in nearly 16 months, after reports that AstraZeneca had made a non-binding roughly $10bn approach worth up to $134 a share including milestones, following a $124-a-share bid the Wall Street Journal said was made in October. Neither company confirmed the talks and at least three analyst teams suggested a bidding war could follow. The move showed big-pharma appetite for commercial-stage obesity and rare-disease SMID names was intact even as XBI faded from its August peak and the midterm result rattled the broader tape.","evidence":"RYTM +28% to $110.68 on 2026-11-04 on reports of an AstraZeneca proposal of up to $134/share incl. milestones ($124 upfront per WSJ).","sources":[{"title":"AstraZeneca weighs roughly $10 billion takeover of Rhythm Pharmaceuticals, sending shares up 28% (BigGo Finance, 2026-11-04)","url":"https://finance.biggo.com/news/66633248-fdcc-42d9-ad4f-0cdc834e6943"},{"title":"AstraZeneca said to offer $10B to acquire Rhythm, analysts whisper of a bidding war (Fierce Pharma)","url":"https://www.fiercepharma.com/pharma/astrazeneca-offers-10b-acquire-rhythm-analysts-whisper-bidding-war"},{"title":"Coveted metabolic gem Rhythm reportedly gets $10B offer from AstraZeneca (BioSpace)","url":"https://www.biospace.com/business/coveted-metabolic-gem-rhythm-reportedly-gets-10b-offer-from-astrazeneca"}]},{"id":"housing-2026-midterm-affordability-rally","date":"2026-11-04","end_date":null,"sector":"consumer_discretionary","subindustries":["housing"],"direction":"in","magnitude":"moderate","driver_type":"election","title":"Democratic sweep sparks an affordability trade: Lennar +8%, Home Depot up as much as 17% intraday, yields dip","summary":"On November 4, 2026, the day after Democrats took both chambers, housing stocks rallied on bets that federal affordability measures and lower rates were coming: Lennar rose more than 8% and D.R. Horton and PulteGroup about 8% at midday, Home Depot jumped as much as 17% before closing up about 3-5%, Lowe's rose 7%, and Treasury yields fell. By the close D.R. Horton was up 4.9% and Pulte 4.4%. Analysts doubted new housing legislation would pass and fundamentals were still weak (Horton's orders -7%, Lennar's margin 15.8%), making this a positioning reversal in the year's most-shorted consumer group rather than a demand signal.","evidence":"On 2026-11-04: LEN +8% intraday, DHI +4.9% and PHM +4.4% at the close, HD up to +17% intraday (closing ~+3-5%), LOW +7%.","sources":[{"title":"Home Depot soars 7% as housing stocks rally on midterm election results (TIKR)","url":"https://www.tikr.com/blog/home-depot-soars-7-as-housing-stocks-rally-on-midterm-election-results"},{"title":"Housing stocks rally following midterm elections, Treasury yields dip lower (AOL)","url":"https://www.aol.com/articles/housing-stocks-rally-following-midterm-171937000.html"},{"title":"Homebuilder stocks jump after midterms: Lennar, D.R. Horton, PulteGroup gain (IndexBox)","url":"https://www.indexbox.io/blog/homebuilder-and-housing-supplier-shares-surge-after-midterm-elections-on-affordability-hopes/"}]},{"id":"travel-2026-mcdonalds-q3-relief-rally","date":"2026-11-04","end_date":null,"sector":"consumer_discretionary","subindustries":["travel_leisure_restaurants"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"McDonald's rises 5.6% on an EPS beat despite its first US comp decline in over a year; Chipotle +4%, Starbucks +3%","summary":"On November 4, 2026 McDonald's reported Q3 adjusted EPS of $3.57 against $3.38 expected (+11%) even as US same-store sales fell for the first time in more than a year; shares jumped 5.6% as the beat and the post-investor-day washout outweighed the traffic data, and restaurants rallied as a group with Chipotle up 4% and Starbucks 3% to $107.69. The rotation into consumer names on the day after the midterms, with yields falling, added a macro bid; Starbucks was up about 25% for 2026 on its turnaround while McDonald's was still down.","evidence":"MCD +5.6% on 2026-11-04; Q3 adjusted EPS $3.57 vs $3.38 consensus; CMG +4%, SBUX +3% to $107.69.","sources":[{"title":"McDonald's rises 5% as earnings beat outweighs U.S. sales dip; Chipotle climbs 4%, Starbucks gains 3% (24/7 Wall St., 2026-11-04)","url":"https://247wallst.com/investing/2026/11/04/mcdonalds-rises-5-as-earnings-beat-outweighs-u-s-sales-dip-chipotle-climbs-4-starbucks-gains-3/"},{"title":"McDonald's (MCD) shares skyrocket, what you need to know (StockStory via FinancialContent, 2026-11-04)","url":"https://markets.financialcontent.com/stocks/article/stockstory-2026-11-4-mcdonalds-mcd-shares-skyrocket-what-you-need-to-know"},{"title":"McDonald's is down 4% and Starbucks is up 25% in 2026 (Barchart)","url":"https://www.barchart.com/story/news/1657472/mcdonalds-is-down-4-and-starbucks-is-up-25-in-2026-the-better-dividend-stock-might-surprise-you"}]},{"id":"proserv-2026-verisk-q3","date":"2026-11-05","end_date":null,"sector":"industrials","subindustries":["professional_services"],"direction":"in","magnitude":"minor","driver_type":"earnings","title":"Verisk rises 4.5% on in-line Q3 2026 revenue and 14% adjusted EPS growth","summary":"Verisk reported Q3 2026 revenue of $809m (+5.3%) and diluted adjusted EPS of $1.96 (+14%) on November 5, 2026 and executed a $100m accelerated share repurchase; shares rose 4.5% to $208.26 immediately after the report. In a week when the midterm result was sinking AI and defense names, the steady subscription-data compounder drew a defensive bid.","evidence":"VRSK +4.5% to $208.26 on 2026-11-05; Q3 revenue $809m (+5.3%), adjusted EPS $1.96 (+14%).","sources":[{"title":"Verisk reports third quarter 2026 financial results (GlobeNewswire, 2026-11-05)","url":"https://www.globenewswire.com/news-release/2026/11/05/3396290/0/en/verisk-reports-third-quarter-2026-financial-results.html"},{"title":"Verisk's Q3 2026 earnings results: revenue in line with expectations (Yahoo Finance)","url":"https://finance.yahoo.com/markets/stocks/articles/verisk-nasdaq-vrsk-q3-2026-131133034.html"}]},{"id":"elec-2026-bloom-midterm-moratorium-fears","date":"2026-11-05","end_date":null,"sector":"industrials","subindustries":["electrical_equipment"],"direction":"out","magnitude":"moderate","driver_type":"election","title":"Bloom Energy drops 15-16% despite a 900 MW NTT DATA deal as a Democratic Congress and a Texas data-center moratorium pledge hit AI power","summary":"On Thursday November 5, 2026, two days after Democrats took Congress, Bloom Energy fell about 15-16% even as it announced its largest international deal, a 900 MW agreement with NTT DATA, and behind-the-meter power names sold off on fears that the data-center build-out could stall under new federal scrutiny and state restrictions, with Texas's incoming governor promising a moratorium on new data-center approvals. The move extended the group's post-earnings slide and showed that political risk to siting and interconnection had overtaken order books as the marginal driver.","evidence":"BE -15% to -16.4% on 2026-11-05 despite a 900 MW NTT DATA agreement.","sources":[{"title":"Bloom Energy sinks 16% despite 900 MW NTT DATA deal as midterm fears hit AI power stocks (TIKR)","url":"https://www.tikr.com/blog/bloom-energy-sinks-16-despite-900-mw-ntt-data-deal-as-midterm-fears-hit-ai-power-stocks"},{"title":"Bloom Energy slides 15% amid AI data center concerns (Seeking Alpha)","url":"https://seekingalpha.com/news/4667142-bloom-energy-slides-15-amid-ai-data-center-concerns"},{"title":"GE Vernova has something Nvidia needs under a Democratic Congress (24/7 Wall St., 2026-11-06)","url":"https://247wallst.com/investing/2026/11/06/ge-vernova-has-something-nvidia-needs-under-a-democratic-congress/"}]},{"id":"re-2026-1105-host-q3-2026-world-cup-revpar","date":"2026-11-05","end_date":null,"sector":"real_estate","subindustries":["lodging_reits"],"direction":"in","magnitude":"moderate","driver_type":"earnings","title":"Host Hotels Q3 2026: total RevPAR +7.3% on World Cup and business travel; full-year RevPAR outlook raised to +6%","summary":"Host Hotels' Q3 2026 results (call held November 5, 2026) showed comparable-hotel total RevPAR up 7.3% to $348.19, driven by a 5.6% rise in average rate and a 2.1% increase in occupancy, with transient demand 'aided by the World Cup and increased business travel' and stronger group bookings. Host raised its full-year outlook to comparable total RevPAR growth of 6% (about $392) from 5% and adjusted FFO per share to $2.21, a $0.05 increase. The Motley Fool noted HST shares had risen more than 60% over the prior year, capping a lodging-REIT re-rating from the 2025 trough.","evidence":"Q3 2026 comparable total RevPAR +7.3% to $348.19; FY2026 total RevPAR growth guidance raised to 6% from 5% (call 2026-11-05).","sources":[{"title":"Motley Fool: Is Host Hotels & Resorts a Buy After Its Latest Earnings Report? (Nov 5, 2026)","url":"https://www.fool.com/investing/2026/11/05/is-host-hotels-resorts-a-buy-after-its-latest-earnings-report/"}]},{"id":"software-2026-midterm-ai-trade-unwind","date":"2026-11-05","end_date":null,"sector":"technology","subindustries":["application_software"],"direction":"out","magnitude":"major","driver_type":"election","title":"Post-midterm AI unwind: Nasdaq -5%, IGV -4%, Palantir -10%","summary":"Two days after Democrats won both chambers in the 2026-11-03 midterms on platforms that targeted AI data-center buildout, the Nasdaq fell about 5.2% intraday (biggest drop since April 2025) and the Philadelphia Semiconductor index had its worst day since March 2020. The retreat spread from chips to software: IGV fell about 4%, Palantir and Okta dropped about 10%, CrowdStrike 9%, Snowflake 6.4%, Salesforce 3.6% and Figma 17% despite a revenue beat.","evidence":"IGV -4% and PLTR -10% on 2026-11-05; Nasdaq -5.2% midday","sources":[{"title":"Fortune: Tech stocks suffering biggest selloff since Covid as investors see premature end to AI datacenter boom","url":"https://fortune.com/2026/11/05/tech-stocks-are-suffering-the-biggest-selloff-since-covid-as-investors-see-premature-end-to-ai-datacenter-boom"},{"title":"TheStreet Pro: AI rout sends the tech sector to its worst day since the Covid crash","url":"https://pro.thestreet.com/market-commentary/ai-rout-sends-the-tech-sector-to-its-worst-day-since-the-covid-crash"},{"title":"Yahoo Finance: Palantir tumbles 10%, CrowdStrike sinks 9% as Wall Street dumps software's AI winners","url":"https://finance.yahoo.com/markets/stocks/articles/palantir-tumbles-10-crowdstrike-sinks-181136741.html"}]}],"regimes":[{"start":"1999-01-01","end":"2000-03-10","name":"Dot-com melt-up","fed_policy":"Tightening: fed funds raised from 4.75% to 6.0% by March 2000 (final hike to 6.5% in May 2000).","ten_year_yield_range":"approx. 4.7% to 6.5% (rising)","dominant_factor":"momentum","leading_sectors":["technology","communication_media"],"lagging_sectors":["utilities","materials","financials"],"summary":"Internet, telecom-equipment and software stocks absorbed capital at any price while the Fed tightened into the top. The Nasdaq rose 85.6% in 1999 versus 21.0% for the S&P 500 and peaked on 10 March 2000 at 5,048.62. Old-economy value, utilities and materials were starved of flows.","sources":[{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"},{"title":"Dot-com bubble (Wikipedia)","url":"https://en.wikipedia.org/wiki/Dot-com_bubble"}]},{"start":"2000-03-11","end":"2002-10-09","name":"Dot-com bust","fed_policy":"Aggressive easing: surprise 50 bp cut to 6.0% on 3 January 2001, then down to 1.25% by November 2002.","ten_year_yield_range":"approx. 6.5% down to 3.6%","dominant_factor":"value","leading_sectors":["consumer_staples","healthcare","financials"],"lagging_sectors":["technology","communication_media","utilities"],"summary":"Technology fell 82.4% and telecom 74.1% peak-to-trough against 49.2% for the S&P 500, while staples gained 24%. Accounting scandals (Enron, WorldCom) and the 9/11 shock extended the bear; rate cuts could not revive capex, and capital rotated to defensives, small-cap value and housing-linked financials.","sources":[{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"FOMC statement, 3 January 2001","url":"https://www.federalreserve.gov/boarddocs/press/general/2001/20010103/default.htm"}]},{"start":"2002-10-10","end":"2007-10-09","name":"Reflation and credit boom","fed_policy":"1% floor (June 2003) then 17 'measured pace' hikes from 1.25% (30 June 2004) to 5.25% (29 June 2006); on hold until September 2007.","ten_year_yield_range":"approx. 3.3% to 5.2%","dominant_factor":"value","leading_sectors":["energy","materials","financials","utilities"],"lagging_sectors":["technology","healthcare"],"summary":"A 2003 tech bounce (Nasdaq +50%) gave way to a commodity, emerging-market and housing-credit boom in which energy, materials, banks and utilities led and large-cap tech lagged (Nasdaq +1.4% in 2005). The iPhone launch in June 2007 arrived just as mortgage credit cracked.","sources":[{"title":"FOMC statement, 30 June 2004","url":"https://www.federalreserve.gov/boarddocs/press/monetary/2004/20040630/default.htm"},{"title":"FOMC statement, 29 June 2006","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20060629a.htm"},{"title":"Nasdaq Composite annual returns (Wikipedia)","url":"https://en.wikipedia.org/wiki/Nasdaq_Composite"}]},{"start":"2007-10-10","end":"2009-03-09","name":"Global financial crisis","fed_policy":"Emergency easing from 5.25% to 0-0.25% (16 December 2008); QE1 agency/MBS purchases announced 25 November 2008.","ten_year_yield_range":"approx. 4.7% down to 2.1%","dominant_factor":"quality","leading_sectors":["consumer_staples","healthcare","technology"],"lagging_sectors":["financials","materials","industrials"],"summary":"Financials fell 82.6% and materials 59.6% peak-to-trough against 56.8% for the S&P 500; tech (-53%) outperformed on cash-rich balance sheets and overtook financials as the largest sector in May 2008. Oil collapsed from $147 to $30 in five months. Only cash, Treasuries and quality balance sheets preserved capital.","sources":[{"title":"Comparing sector performance during the last two bear markets","url":"https://fortunefinancialadvisors.com/blog/comparing-sector-performance-during-the-last-two-bear-markets/"},{"title":"FOMC statement, 16 December 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081216b.htm"},{"title":"Fed announces agency debt and MBS purchases, 25 November 2008","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20081125b.htm"}]},{"start":"2009-03-10","end":"2013-05-21","name":"QE recovery (QE1-QE3)","fed_policy":"Zero rates throughout; QE2 ($600 billion, 3 November 2010), Operation Twist (2011), QE3 ($40 billion a month MBS, 13 September 2012).","ten_year_yield_range":"approx. 1.4% to 4.0%","dominant_factor":"growth","leading_sectors":["technology","consumer_discretionary","financials","utilities"],"lagging_sectors":["energy","materials"],"summary":"Stress tests (May 2009) ended the bank panic and the smartphone and cloud build-out led growth (Nasdaq +43.9% in 2009). The 2011 US downgrade and Eurozone crisis produced a mid-cycle defensive rotation (utilities +19.9%, financials -17.1% in 2011) before QE3 drove financials to the best sector in 2012 (+28.8%).","sources":[{"title":"FOMC statement, 3 November 2010 (QE2)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20101103a.htm"},{"title":"FOMC statement, 13 September 2012 (QE3)","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20120913a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2013-05-22","end":"2014-12-31","name":"Taper tantrum and taper","fed_policy":"Taper signalled 22 May 2013, purchases cut from $85 billion a month starting January 2014 (announced 18 December 2013), QE3 ended October 2014; rates still 0-0.25%.","ten_year_yield_range":"approx. 1.6% to 3.0%, then back to 2.2%","dominant_factor":"growth","leading_sectors":["technology","healthcare","consumer_discretionary","utilities"],"lagging_sectors":["telecom","energy","materials"],"summary":"Bond proxies (utilities, REITs, telecom) were hit hard in mid-2013 as yields jumped, then recovered in 2014 as yields fell again (utilities +29.0% in 2014). Energy began its collapse in H2 2014 (-7.8%) while tech and health care led a 32.4% S&P 500 year in 2013.","sources":[{"title":"FOMC statement, 18 December 2013","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20131218a.htm"},{"title":"Friday's sell-off reminiscent of 2013 (SmartTrust)","url":"https://www.smarttrustuit.com/wcmu/fridays-sell-off-reminiscent-of-2013/"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2015-01-01","end":"2016-02-11","name":"Industrial recession and oil crash","fed_policy":"Liftoff to 0.25-0.5% on 16 December 2015 after a year of delay; one hike only.","ten_year_yield_range":"approx. 1.6% to 2.5%","dominant_factor":"quality","leading_sectors":["consumer_discretionary","healthcare","technology"],"lagging_sectors":["energy","materials","financials","utilities"],"summary":"China's August 2015 devaluation, oil below $30 and the Glencore scare drove a global industrial recession without a US one. Energy (-21.1%) and materials (-8.4%) lagged in 2015; large-cap growth and 'FANG' concentration began. Semiconductor M&A hit records as unit growth slowed.","sources":[{"title":"FOMC statement, 16 December 2015","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20151216a.htm"},{"title":"2015-2016 stock market selloff (Wikipedia)","url":"https://en.wikipedia.org/wiki/2015%E2%80%932016_stock_market_selloff"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2016-02-12","end":"2018-01-26","name":"Reflation, election and synchronized growth","fed_policy":"Gradual hikes: three in 2017 to 1.25-1.5%; balance-sheet runoff began October 2017.","ten_year_yield_range":"approx. 1.4% to 2.7%","dominant_factor":"momentum","leading_sectors":["technology","financials","materials","energy"],"lagging_sectors":["telecom","utilities","consumer_staples"],"summary":"Cyclicals led off the February 2016 low (energy +27.4%, materials +16.7% in 2016), the Trump election produced the best bank month on record (KBE +18.7% in November 2016) with tech lagging, and 2017's synchronized global growth and tax cut delivered a tech melt-up (+38.8%, FAANG +46.5%) with record-low volatility.","sources":[{"title":"Bank stocks on pace for best month in history (CNBC, 2016-11-30)","url":"https://www.cnbc.com/2016/11/30/bank-stocks-rise-nearly-19-percent-on-pace-for-their-best-month-in-history.html"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2018-01-27","end":"2018-12-24","name":"Hiking cycle and trade war","fed_policy":"Four hikes to 2.25-2.5% (final on 19 December 2018) plus QT at $50 billion a month.","ten_year_yield_range":"approx. 2.6% to 3.2%","dominant_factor":"quality","leading_sectors":["healthcare","utilities","technology"],"lagging_sectors":["energy","materials","financials","communication_media"],"summary":"Steel tariffs (March), Section 301 tariffs on China and four Fed hikes ended the low-volatility regime. Materials (-14.7%), financials (-13.0%) and energy (-18.1%) lagged; the GICS Communication Services sector was created in September; Q4 brought the worst December since 1931 (Nasdaq -17.5% for the quarter) and a Nasdaq-100 bear market.","sources":[{"title":"FOMC statement, 19 December 2018","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20181219a.htm"},{"title":"US stocks post worst year in a decade (CNBC, 2018-12-31)","url":"https://www.cnbc.com/amp/2018/12/31/stock-market-wall-street-stocks-eye-us-china-trade-talks.html"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2018-12-25","end":"2020-02-19","name":"Fed pivot and late-cycle growth","fed_policy":"Pause in January 2019, three cuts to 1.5-1.75% (31 July, 18 September, 30 October 2019); QT ended August 2019; repo/bill purchases from October 2019.","ten_year_yield_range":"approx. 1.5% to 2.8% (falling)","dominant_factor":"growth","leading_sectors":["technology","communication_media","financials","utilities"],"lagging_sectors":["energy","materials"],"summary":"The Fed's reversal re-rated long-duration growth: technology returned 50.3% in 2019 (best sector) against 31.5% for the S&P 500, semiconductors led despite the May 2019 Huawei shock, and the Phase One trade deal (15 January 2020) removed the tariff overhang just before COVID.","sources":[{"title":"FOMC statement, 31 July 2019","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20190731a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2020-02-20","end":"2020-03-23","name":"COVID crash","fed_policy":"Emergency cuts to 0-0.25% (3 and 15 March 2020), $700 billion QE announced 15 March, unlimited QE and credit facilities from 23 March.","ten_year_yield_range":"approx. 1.5% down to 0.5%","dominant_factor":"quality","leading_sectors":["consumer_staples","healthcare","technology"],"lagging_sectors":["energy","financials","industrials","real_estate"],"summary":"The fastest bear market on record: the Dow fell 12.93% on 16 March alone. Energy, airlines, banks and REITs were hit hardest; digital, staples and health care held up. The crash ended on 23 March once the Fed backstopped credit markets and Congress passed the CARES Act.","sources":[{"title":"FOMC statement, 15 March 2020","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20200315a.htm"},{"title":"2020 stock market crash (Wikipedia)","url":"https://en.wikipedia.org/wiki/2020_stock_market_crash"}]},{"start":"2020-03-24","end":"2021-12-31","name":"Reopening, reflation and the everything rally","fed_policy":"Zero rates and $120 billion a month QE; taper announced November 2021 and accelerated December 2021.","ten_year_yield_range":"approx. 0.5% to 1.7%","dominant_factor":"growth","leading_sectors":["technology","consumer_discretionary","energy","materials","financials"],"lagging_sectors":["utilities","consumer_staples","healthcare"],"summary":"2020 belonged to work-from-home tech (IT +43.9%, Nasdaq +43.6%); 2021 to reflation (energy +54.6%, financials +35.0%, materials +27.3%) as vaccines, fiscal stimulus and the chip shortage lifted cyclicals, while SPACs, fintech and crypto (Coinbase listing April 2021) marked the speculative peak. Utilities (+17.7%) were the 2021 laggard.","sources":[{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"Coinbase (Wikipedia)","url":"https://en.wikipedia.org/wiki/Coinbase"}]},{"start":"2022-01-03","end":"2022-10-12","name":"2022 tightening bear market","fed_policy":"Liftoff 16 March 2022 (0.25-0.5%), four 75 bp hikes, 3.0-3.25% by September and 4.25-4.5% by December; QT from June 2022.","ten_year_yield_range":"approx. 1.5% to 4.2%","dominant_factor":"value","leading_sectors":["energy","utilities","consumer_staples","healthcare"],"lagging_sectors":["communication_media","technology","consumer_discretionary","real_estate"],"summary":"The fastest hiking cycle in four decades repriced duration: the S&P 500 fell about 25% to its October low and -18.1% for the year, with communication services -39.9% and technology -28.2% against energy +65.7% and utilities +1.6%. Software and fintech halved; Meta and Netflix posted record one-day losses; the growth-to-value rotation was the largest since 2000.","sources":[{"title":"FOMC statement, 16 March 2022","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20220316a.htm"},{"title":"2022 stock market decline (Wikipedia)","url":"https://en.wikipedia.org/wiki/2022_stock_market_decline"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2022-10-13","end":"2024-09-17","name":"AI trade and soft landing, higher for longer","fed_policy":"Final hikes to 5.25-5.5% (26 July 2023), then a 14-month hold; QT continuing.","ten_year_yield_range":"approx. 3.3% to 5.0%","dominant_factor":"growth","leading_sectors":["technology","communication_media","consumer_discretionary"],"lagging_sectors":["utilities","energy","real_estate","consumer_staples"],"summary":"ChatGPT (30 November 2022) and Nvidia's May 2023 guidance ignited the AI trade: technology returned 57.8% and communication services 55.8% in 2023 versus 26.3% for the S&P 500, while utilities (-7.1%) were the worst sector as yields hit cycle highs. The March 2023 regional-bank crisis was contained by the BTFP; hyperscaler capex began its quadrupling.","sources":[{"title":"FOMC statement, 26 July 2023","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20230726a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"2023 United States banking crisis (Wikipedia)","url":"https://en.wikipedia.org/wiki/2023_United_States_banking_crisis"}]},{"start":"2024-09-18","end":"2025-04-08","name":"Fed cuts, election and tariff shock","fed_policy":"50 bp cut on 18 September 2024, 25 bp in November and December 2024 to 4.25-4.5%, then on hold.","ten_year_yield_range":"approx. 3.6% to 4.8%","dominant_factor":"momentum","leading_sectors":["communication_media","financials","utilities","technology"],"lagging_sectors":["materials","healthcare","energy"],"summary":"Rate cuts and the AI-power narrative made utilities (+23.4%) and communication services (+40.2%) leaders in 2024, financials rallied on the election and deregulation hopes, and materials (0.0%) lagged. DeepSeek (27 January 2025) and then Liberation Day tariffs (2 April 2025) produced a 12% S&P 500 drawdown in four sessions, ending the regime at the 8 April low.","sources":[{"title":"FOMC statement, 18 September 2024","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20240918a.htm"},{"title":"2025 stock market crash (Wikipedia)","url":"https://en.wikipedia.org/wiki/2025_stock_market_crash"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"}]},{"start":"2025-04-09","end":"2026-02-27","name":"Tariff pause rally, AI capex and stablecoins","fed_policy":"Hold until September 2025, then three cuts (17 September, 29 October, 10 December 2025) to 3.5-3.75%; QT ended with reserve-management bill purchases.","ten_year_yield_range":"approx. 3.7% to 4.6%","dominant_factor":"growth","leading_sectors":["communication_media","technology","materials","utilities"],"lagging_sectors":["real_estate","energy","healthcare"],"summary":"The 9 April 2025 pause (S&P +9.52%) and chip exemptions drove a V-shaped recovery to a record on 27 June 2025 and a narrow AI leadership (Nvidia $5 trillion on 29 October). Gold more than doubled miners' value, the GENIUS Act and bank deregulation lifted fintech and banks, while software and IT services derated on AI-substitution fears. Communication services (+33.6%) led 2025; the S&P 500 returned 17.9%.","sources":[{"title":"FOMC statement, 10 December 2025","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20251210a.htm"},{"title":"Annual S&P sector returns (Novel Investor)","url":"https://novelinvestor.com/sector-performance/"},{"title":"List of public corporations by market capitalization (Wikipedia)","url":"https://en.wikipedia.org/wiki/List_of_public_corporations_by_market_capitalization"}]},{"start":"2026-02-28","end":"2026-06-30","name":"Iran war oil shock and the semiconductor melt-up","fed_policy":"On hold at 3.5-3.75%; Powell under investigation, Kevin Warsh confirmed 13 May and sworn in 22 May 2026; first Warsh FOMC in June with no change.","ten_year_yield_range":"approx. 3.7% (February low) rising toward 4.7%","dominant_factor":"momentum","leading_sectors":["energy","technology","materials"],"lagging_sectors":["communication_media","consumer_discretionary","financials","utilities"],"summary":"US-Israeli strikes on Iran (28 February), the closure of Hormuz and Brent at $119.50 (9 March) made energy the 2026 leader and gold spiked to about $5,400, while the Supreme Court's 20 February tariff ruling and replacement Section 122/301 duties cut the effective tariff rate. Semiconductors had their best quarter ever in Q2 (SMH +71%, SOX +106% year-to-date) on memory and CPU demand, even as software suffered the 'SaaS-pocalypse' and IT services derated.","sources":[{"title":"2026 in the United States (Wikipedia)","url":"https://en.wikipedia.org/wiki/2026_in_the_United_States"},{"title":"Price of oil (Wikipedia)","url":"https://en.wikipedia.org/wiki/Price_of_oil"},{"title":"Kevin Warsh (Wikipedia)","url":"https://en.wikipedia.org/wiki/Kevin_Warsh"},{"title":"Chip stocks that notched record rallies in Q2 (CNBC, 2026-07-01)","url":"https://www.cnbc.com/2026/07/01/chip-stocks-notched-record-rallies-in-second-quarter-start-q3-with-dud.html"}]},{"start":"2026-07-01","end":null,"name":"AI credit stress, Fed hike and the midterm rotation","fed_policy":"25 bp hike to 3.75-4% on 16 September 2026 (first since July 2023), hold on 28 October with two dissents for a hike; markets price another hike in December.","ten_year_yield_range":"approx. 4.5% to 4.9% (highest in years; some reports cite multi-decade highs in long yields)","dominant_factor":"low_vol","leading_sectors":["energy","healthcare","consumer_staples","materials"],"lagging_sectors":["technology","communication_media","industrials","utilities"],"summary":"The 1 July semiconductor reversal, Alphabet's capex and free-cash-flow shocks (July and 29 October), CoreWeave's distressed bonds and CDS above 1,000 bp, state data-center moratoria and the 3 November Democratic sweep turned AI capex from growth story to credit question: XLK fell 19.2% in the month to 5 November 2026 while staples, health care and energy absorbed flows. Energy leads 2026 (+40.6%), communication services lags (-10.6%); the Nasdaq's 6 October record of 27,599.89 stands as the cycle high for now.","sources":[{"title":"FOMC statement, 16 September 2026","url":"https://www.federalreserve.gov/newsevents/pressreleases/monetary20260916a.htm"},{"title":"Fed holds rates steady, October 2026 (CNBC)","url":"https://www.cnbc.com/2026/10/28/fed-interest-rate-decision-october-2026.html"},{"title":"CoreWeave bond yield tops 16% as AI credit stress rises (CNBC, 2026-11-06)","url":"https://www.cnbc.com/2026/11/06/coreweave-bond-yield-tops-16percent-as-ai-credit-stress-rises.html"},{"title":"S&P 500 sector performance YTD 2026 (ChartRow)","url":"https://chartrow.com/sp500/sector-performance"},{"title":"2026 United States elections (Wikipedia)","url":"https://en.wikipedia.org/wiki/2026_United_States_elections"}]}]};